g/operationPolicy.ts","../../packages/account-core/src/core/billing/operationPointer.ts","../../packages/account-core/src/core/billing/presentation.ts","../../packages/account-core/src/core/billing/paymentFriction.ts","../../packages/account-core/src/core/billing/operationLifecycle.ts","../../packages/account-core/src/core/billing/telemetry/operationLifecycleEvent.ts","../../packages/account-core/src/core/billing/telemetry/topupEvent.ts","../../packages/account-core/src/core/billing/challengeDriver.ts","../../packages/account-core/src/core/billing/subscriptionCommands.ts","../../packages/account-core/src/core/billing/paymentCopy.ts","../../packages/account-core/src/core/billing/topup.ts","../../src/platform/workspace/billing/customerAttention.ts","../../src/platform/workspace/billing/stripePublishableKey.ts","../../src/platform/serverFacts/serverFact.ts","../../src/platform/workspace/telemetry/workspaceTelemetryContext.ts","../../src/platform/workspace/composables/useBillingCapabilities.ts","../../packages/billing-contract/src/contract.ts","../../packages/billing-contract/src/entryFields.ts","../../packages/billing-contract/src/identifiers.ts","../../packages/billing-contract/src/url.ts","../../packages/billing-contract/src/returnTargets.ts","../../packages/billing-contract/src/entryUrl.ts","../../src/platform/telemetry/utils/paymentIntentSource.ts","../../src/platform/workspace/utils/checkoutJourney.ts","../../src/platform/workspace/billing/sdk/billingCapabilitiesView.ts","../../src/platform/workspace/billing/sdk/safeInt64.ts","../../src/platform/workspace/billing/sdk/billingPlansView.ts","../../src/platform/workspace/billing/sdk/billingStatusView.ts","../../src/platform/workspace/billing/sdk/createBillingSdk.ts","../../src/platform/workspace/billing/sdk/topupOperationView.ts","../../src/platform/workspace/billing/sdk/operationRecordView.ts","../../src/platform/workspace/billing/sdk/subscriptionOperationView.ts","../../src/platform/workspace/billing/sdk/webSessionBillingSession.ts","../../src/platform/workspace/billing/sdk/billingSdkStore.ts","../../src/platform/workspace/composables/useBillingReadRail.ts","../../packages/account-core/src/workspaceLink.ts","../../src/platform/workspace/utils/platformLink.ts","../../src/components/dialog/content/TopUpCreditsDialogContentLegacy.vue","../../src/platform/workspace/components/InsufficientCreditsMemberDialog.vue","../../src/platform/workspace/billing/hostedBillingRoutes.ts","../../src/platform/workspace/billing/topupCheckoutReturnUrl.ts","../../src/platform/workspace/stores/billingOperationStore.ts","../../src/platform/workspace/composables/useTopupOperation.ts","../../src/platform/workspace/utils/checkoutJourneyTelemetry.ts","../../src/platform/workspace/components/TopUpCreditsDialogContentWorkspace.vue","../../src/composables/billing/useBillingDialogs.ts","../../src/platform/cloud/subscription/utils/subscriptionCheckoutTracker.ts","../../src/platform/cloud/subscription/utils/subscriptionCheckoutUtil.ts","../../src/platform/cloud/subscription/composables/useSubscriptionCancellationWatcher.ts","../../src/platform/cloud/subscription/composables/useSubscription.ts","../../src/composables/billing/useLegacyBilling.ts","../../src/platform/cloud/subscription/composables/useBillingPlans.ts","../../src/platform/workspace/composables/useWorkspaceDialogs.ts","../../src/platform/workspace/composables/useWorkspaceUI.ts","../../src/platform/cloud/subscription/utils/billingPlanTelemetry.ts","../../src/platform/workspace/utils/pendingSubscriptionCheckout.ts","../../src/platform/cloud/subscription/composables/useSubscriptionDialog.ts","../../src/platform/workspace/billing/openHostedBillingTab.ts","../../src/platform/workspace/composables/useSubscriptionRail.ts","../../src/platform/workspace/billing/subscribeInput.ts","../../src/platform/workspace/composables/useWorkspaceBilling.ts","../../src/composables/billing/useBillingContext.ts"],"sourcesContent":["/**\n * The self-serve tiers' list prices (USD per month, billed monthly or\n * yearly) and monthly credit grants. The cloud app's pricing table and both\n * checkout hosts read this one table, so a plan cannot price or grant\n * differently between the app and billing-web.\n */\nexport const TIER_CATALOG = {\n  standard: { monthly: 20, yearly: 16, credits: 4200 },\n  creator: { monthly: 35, yearly: 28, credits: 7400 },\n  pro: { monthly: 100, yearly: 80, credits: 21100 }\n} as const satisfies Record<\n  string,\n  { monthly: number; yearly: number; credits: number }\n>\n\nexport type CatalogTierKey = keyof typeof TIER_CATALOG\n\n/** The catalog key for a server tier (`'CREATOR'`), if it is a self-serve one. */\nexport function toCatalogTierKey(tier: string): CatalogTierKey | undefined {\n  const key = tier.toLowerCase()\n  return Object.hasOwn(TIER_CATALOG, key) ? (key as CatalogTierKey) : undefined\n}\n\n/** A team credit stop's list price and grant, as the pricing table shows it. */\nexport interface TeamCreditStopPrice {\n  readonly id: string\n  /** Monthly list price in USD, before the yearly-commitment discount. */\n  readonly usd: number\n  readonly credits: number\n  /** The yearly discount as a whole percent; monthly billing halves it. */\n  readonly discountPercentYearly: number\n}\n\n/**\n * Reads the server's `team_credit_stops`: the yearly list price is the\n * monthly list price, and the discount is the struck vs charged yearly price.\n */\nexport function mapApiTeamCreditStops(\n  stops: readonly {\n    id: string\n    credits: number\n    yearly: { list_price_cents: number; price_cents: number }\n  }[]\n): TeamCreditStopPrice[] {\n  return stops.map((stop) => {\n    const listCents = stop.yearly.list_price_cents\n    const discountPercentYearly =\n      listCents > 0\n        ? Math.round(((listCents - stop.yearly.price_cents) / listCents) * 100)\n        : 0\n    return {\n      id: stop.id,\n      usd: Math.round(listCents / 100),\n      credits: stop.credits,\n      discountPercentYearly\n    }\n  })\n}\n\n/**\n * The discounted monthly price of a credit stop for a billing cycle. The\n * pricing table and both checkout hosts price a team stop through this, so\n * the slider and the confirm never drift.\n */\nexport function getStopDiscountedMonthlyUsd(\n  stop: Pick<TeamCreditStopPrice, 'usd' | 'discountPercentYearly'>,\n  cycle: 'monthly' | 'yearly'\n): number {\n  const percent =\n    cycle === 'monthly'\n      ? stop.discountPercentYearly / 2\n      : stop.discountPercentYearly\n  return Math.round(stop.usd * (1 - percent / 100))\n}\n","import type { BillingTierKey } from '@comfyorg/account-core/billing'\nimport { TIER_CATALOG } from '@comfyorg/account-ui/billing/catalog'\nimport type { SubscriptionTier as IngestSubscriptionTier } from '@comfyorg/ingest-types'\n\nimport { remoteConfig } from '@/platform/remoteConfig/remoteConfig'\nimport type { components } from '@/types/comfyRegistryTypes'\n\nexport type { IngestSubscriptionTier }\n\nexport type RegistrySubscriptionTier = components['schemas']['SubscriptionTier']\n\nexport type TierKey = BillingTierKey\n\n// Self-serve personal-plan tiers only. TEAM and ENTERPRISE are workspace-level\n// and sales-managed respectively, and intentionally have no catalog key (see\n// toTierKey/isSalesManagedTier below).\ntype CatalogTier = Exclude<RegistrySubscriptionTier, 'TEAM' | 'ENTERPRISE'>\n\nconst TIER_TO_KEY: Record<CatalogTier, TierKey> = {\n  FREE: 'free',\n  STANDARD: 'standard',\n  CREATOR: 'creator',\n  PRO: 'pro',\n  FOUNDERS_EDITION: 'founder'\n}\n\nexport const KEY_TO_TIER: Record<TierKey, RegistrySubscriptionTier> = {\n  free: 'FREE',\n  standard: 'STANDARD',\n  creator: 'CREATOR',\n  pro: 'PRO',\n  founder: 'FOUNDERS_EDITION'\n}\n\nexport interface TierPricing {\n  monthly: number\n  yearly: number\n  credits: number\n  videoEstimate: number\n}\n\nexport const TIER_PRICING: Record<\n  Exclude<TierKey, 'free' | 'founder'>,\n  TierPricing\n> = {\n  standard: { ...TIER_CATALOG.standard, videoEstimate: 380 },\n  creator: { ...TIER_CATALOG.creator, videoEstimate: 670 },\n  pro: { ...TIER_CATALOG.pro, videoEstimate: 1915 }\n}\n\nconst MONTHS_PER_YEAR = 12\n\n// Annual plans grant the whole year up front (catalog `*-annual` credit_grant\n// is 12x the monthly grant), so a yearly cycle shows the year's total.\nexport function amountForBillingCycle(\n  monthlyAmount: number,\n  isYearly: boolean\n): number {\n  return isYearly ? monthlyAmount * MONTHS_PER_YEAR : monthlyAmount\n}\n\ninterface TierFeatures {\n  customLoRAs: boolean\n  maxMembers: number\n}\n\nconst TIER_FEATURES: Record<TierKey, TierFeatures> = {\n  free: { customLoRAs: false, maxMembers: 1 },\n  standard: { customLoRAs: false, maxMembers: 1 },\n  creator: { customLoRAs: true, maxMembers: 5 },\n  pro: { customLoRAs: true, maxMembers: 20 },\n  founder: { customLoRAs: false, maxMembers: 1 }\n}\n\nexport const DEFAULT_TIER_KEY: TierKey = 'standard'\n\n// Membership is tested rather than listing the exclusions, so a tier added to\n// the ingest enum narrows to false and returns null instead of failing the\n// build. Two details are load-bearing:\n//   - `typeof`, because tier is unvalidated backend JSON and need not be a\n//     string; hasOwnProperty coerces its argument to a property key, so\n//     ['FREE'] would be accepted as FREE and a null toString would throw.\n//   - own-property rather than `in`, which walks the prototype chain and would\n//     return an inherited function for 'constructor' or 'toString'.\nfunction isRegistrySubscriptionTier(tier: unknown): tier is CatalogTier {\n  return (\n    typeof tier === 'string' &&\n    Object.prototype.hasOwnProperty.call(TIER_TO_KEY, tier)\n  )\n}\n\n// Workspace-level tiers (TEAM, and any added later) map to no key in this\n// personal plan catalog.\nexport function toTierKey(tier: IngestSubscriptionTier): TierKey | null {\n  return isRegistrySubscriptionTier(tier) ? TIER_TO_KEY[tier] : null\n}\n\n// Enterprise plans are intentionally absent from the self-serve catalog, so a\n// scheduled change to one cannot be resolved through `plans` and carries no\n// tier to read. The slug is the only signal on that path; everywhere a tier\n// exists, compare it to 'ENTERPRISE' directly.\nexport function isEnterprisePlanSlug(slug: string | null | undefined): boolean {\n  return slug?.toLowerCase().startsWith('enterprise') === true\n}\n\n// A tier the frontend cannot map to its catalog and that is not one of the\n// workspace-level tiers it knows about. Price and feature claims must never be\n// borrowed for a plan we cannot identify (FE-1662 story 6).\nexport function isUnknownTier(\n  tier: IngestSubscriptionTier | null | undefined\n): boolean {\n  if (tier == null || tier === 'TEAM' || tier === 'ENTERPRISE') return false\n  return toTierKey(tier) === null\n}\n\n// Enterprise and unrecognized tiers share one presentation: no catalog price,\n// benefits, or pricing surfaces. The server hides their lifecycle capabilities\n// (billing-api hideLifecycleCapabilities); this helper only drives rendering.\n// Where a sales conversation starts. Shared by the pricing table's footnote\n// and the ended-plan Contact sales actions so the destination cannot drift.\nexport const ENTERPRISE_URL = 'https://comfy.org/cloud/enterprise/'\n\nexport function isSalesManagedTier(\n  tier: IngestSubscriptionTier | null | undefined\n): boolean {\n  return tier === 'ENTERPRISE' || isUnknownTier(tier)\n}\n\n// An Enterprise end date is an agreed ending — an operator pilot term or a\n// sales-mediated cancellation, deliberately not distinguished (FE-2035) —\n// often set months before the plan lapses. It is not self-serve news, so the\n// workspace keeps its plainly-active presentation until the end date is this\n// close; only then does the muted ending notice appear. Strictly ENTERPRISE:\n// self-serve plans never consult this window, and neither do unrecognized\n// tiers — sales-managed contracts are Enterprise-only today, and per\n// isUnknownTier's contract an unidentifiable plan must not borrow claims.\nexport const ENTERPRISE_ENDING_NOTICE_DAYS = 14\n\nconst MS_PER_DAY = 24 * 60 * 60 * 1000\n\n// Wall-clock comparison; callers feed `now` from a coarse reactive clock so a\n// long-lived session still crosses into the window without a data refresh.\n// The window is deliberately unbounded below — a passed end date counts as\n// \"within\" — because the backend reconciles on read: cloud's\n// common/repository/billing/subscription.go:55 transitions a canceled row\n// whose cancel_at has passed into ended on first load and returns no active\n// subscription, so canAccessSubscriptionFeatures gates every caller first.\nexport function isWithinEnterpriseEndingNotice(\n  endDate: string | null | undefined,\n  now: number = Date.now()\n): boolean {\n  if (!endDate) return false\n  const end = new Date(endDate).getTime()\n  if (Number.isNaN(end)) return false\n  return end - now <= ENTERPRISE_ENDING_NOTICE_DAYS * MS_PER_DAY\n}\n\n// Includes the workspace-level TEAM, which toTierKey maps to null: a catalog\n// key is not a usable test for \"is on a paid plan\".\nexport function hasActivePaidPlan(\n  tier: IngestSubscriptionTier | null | undefined\n): boolean {\n  return tier != null && tier !== 'FREE'\n}\n\nconst FOUNDER_MONTHLY_PRICE = 20\nconst FOUNDER_MONTHLY_CREDITS = 5461\n\nexport function getTierPrice(tierKey: TierKey, isYearly = false): number {\n  if (tierKey === 'free') return 0\n  if (tierKey === 'founder') return FOUNDER_MONTHLY_PRICE\n  const pricing = TIER_PRICING[tierKey]\n  return isYearly ? pricing.yearly : pricing.monthly\n}\n\nexport function getTierCredits(tierKey: TierKey): number | null {\n  if (tierKey === 'free') return remoteConfig.value.free_tier_credits ?? null\n  if (tierKey === 'founder') return FOUNDER_MONTHLY_CREDITS\n  return TIER_PRICING[tierKey]?.credits\n}\n\nexport function getTierFeatures(tierKey: TierKey): TierFeatures {\n  return TIER_FEATURES[tierKey]\n}\n","import type {\n  ComfyNodeDef,\n  PriceBadge,\n  WidgetDependency\n} from '@comfyorg/object-info-parser'\nimport { memoize } from 'es-toolkit'\nimport type { Expression } from 'jsonata'\nimport jsonata from 'jsonata'\n\nimport { CREDITS_PER_USD, formatCredits } from './creditsUtil'\n\n/**\n * Determine if a number should display 1 decimal place.\n * Shows decimal only when the first decimal digit is non-zero.\n */\nconst shouldShowDecimal = (value: number): boolean => {\n  const rounded = Math.round(value * 10) / 10\n  return rounded % 1 !== 0\n}\n\nconst getNumberOptions = (credits: number): Intl.NumberFormatOptions => ({\n  minimumFractionDigits: 0,\n  maximumFractionDigits: shouldShowDecimal(credits) ? 1 : 0\n})\n\ntype CreditFormatOptions = {\n  suffix?: string\n  note?: string\n  approximate?: boolean\n  separator?: string\n}\n\nexport const formatCreditsValue = (usd: number): string => {\n  // Use raw credits value (before rounding) to determine decimal display\n  const rawCredits = usd * CREDITS_PER_USD\n  return formatCredits({\n    value: rawCredits,\n    numberOptions: getNumberOptions(rawCredits)\n  })\n}\n\nconst makePrefix = (approximate?: boolean) => (approximate ? '~' : '')\n\nconst makeSuffix = (suffix?: string) => suffix ?? '/Run'\n\nconst appendNote = (note?: string) => (note ? ` ${note}` : '')\n\nconst formatCreditsLabel = (\n  usd: number,\n  { suffix, note, approximate }: CreditFormatOptions = {}\n): string =>\n  `${makePrefix(approximate)}${formatCreditsValue(usd)} credits${makeSuffix(suffix)}${appendNote(note)}`\n\nexport const formatCreditsRangeValue = (\n  minUsd: number,\n  maxUsd: number\n): string => {\n  const min = formatCreditsValue(minUsd)\n  const max = formatCreditsValue(maxUsd)\n  return min === max ? min : `${min}-${max}`\n}\n\nconst formatCreditsRangeLabel = (\n  minUsd: number,\n  maxUsd: number,\n  { suffix, note, approximate }: CreditFormatOptions = {}\n): string => {\n  const rangeValue = formatCreditsRangeValue(minUsd, maxUsd)\n  return `${makePrefix(approximate)}${rangeValue} credits${makeSuffix(suffix)}${appendNote(note)}`\n}\n\nexport const formatCreditsListValue = (\n  usdValues: number[],\n  separator = '/'\n): string => {\n  const parts = usdValues.map((value) => formatCreditsValue(value))\n  return parts.join(separator)\n}\n\nconst formatCreditsListLabel = (\n  usdValues: number[],\n  { suffix, note, approximate, separator }: CreditFormatOptions = {}\n): string => {\n  const value = formatCreditsListValue(usdValues, separator)\n  return `${makePrefix(approximate)}${value} credits${makeSuffix(suffix)}${appendNote(note)}`\n}\n\n// -----------------------------\n// JSONata pricing types\n// -----------------------------\ntype PricingResult =\n  | { type: 'text'; text: string }\n  | { type: 'usd'; usd: number; format?: CreditFormatOptions }\n  | {\n      type: 'range_usd'\n      min_usd: number\n      max_usd: number\n      format?: CreditFormatOptions\n    }\n  | { type: 'list_usd'; usd: number[]; format?: CreditFormatOptions }\n\n/** Type guard to validate that a value is a PricingResult. */\nconst isPricingResult = (value: unknown): value is PricingResult => {\n  if (typeof value !== 'object' || value === null || !('type' in value)) {\n    return false\n  }\n\n  switch (value.type) {\n    case 'text':\n      return 'text' in value && typeof value.text === 'string'\n    case 'usd':\n      return 'usd' in value && typeof value.usd === 'number'\n    case 'range_usd':\n      return (\n        'min_usd' in value &&\n        typeof value.min_usd === 'number' &&\n        'max_usd' in value &&\n        typeof value.max_usd === 'number'\n      )\n    case 'list_usd':\n      return (\n        'usd' in value &&\n        Array.isArray(value.usd) &&\n        value.usd.every((usd) => typeof usd === 'number')\n      )\n    default:\n      return false\n  }\n}\n\n/**\n * Widget values are normalized based on their declared type:\n * - INT/FLOAT → number (or null if not parseable)\n * - BOOLEAN → boolean (or null if not parseable)\n * - STRING/COMBO/other → string (lowercased, trimmed)\n */\nexport type NormalizedWidgetValue = string | number | boolean | null\n\nexport type JsonataPricingRule = {\n  engine: 'jsonata'\n  depends_on: {\n    widgets: WidgetDependency[]\n    inputs: string[]\n    input_groups: string[]\n  }\n  expr: string\n}\n\nexport type CompiledJsonataPricingRule = JsonataPricingRule & {\n  _compiled: Expression | null\n}\n\nexport type JsonataEvalContext = {\n  widgets: Record<string, NormalizedWidgetValue>\n  inputs: Record<string, { connected: boolean }>\n  /** Count of connected inputs per autogrow group */\n  inputGroups: Record<string, number>\n}\n\n// -----------------------------\n// Normalization helpers\n// -----------------------------\nconst asFiniteNumber = (v: unknown): number | null => {\n  if (v === null || v === undefined) return null\n\n  if (typeof v === 'number') return Number.isFinite(v) ? v : null\n\n  if (typeof v === 'string') {\n    const t = v.trim()\n    if (t === '') return null\n    const n = Number(t)\n    return Number.isFinite(n) ? n : null\n  }\n\n  // Do not coerce booleans/objects into numbers for pricing purposes.\n  return null\n}\n\n/**\n * Normalize widget value based on its declared type.\n * Returns the value in its natural type for simpler JSONata expressions.\n */\nexport const normalizeWidgetValue = (\n  raw: unknown,\n  declaredType: string\n): NormalizedWidgetValue => {\n  if (raw === undefined || raw === null) {\n    return null\n  }\n\n  const upperType = declaredType.toUpperCase()\n\n  // Numeric types\n  if (upperType === 'INT' || upperType === 'FLOAT') {\n    return asFiniteNumber(raw)\n  }\n\n  // Boolean type\n  if (upperType === 'BOOLEAN') {\n    if (typeof raw === 'boolean') return raw\n    if (typeof raw === 'string') {\n      const ls = raw.trim().toLowerCase()\n      if (ls === 'true') return true\n      if (ls === 'false') return false\n    }\n    return null\n  }\n\n  // COMBO type - preserve string/numeric values (for options like [5, \"10\"])\n  if (upperType === 'COMBO') {\n    if (typeof raw === 'number') return raw\n    if (typeof raw === 'boolean') return raw\n    return String(raw).trim().toLowerCase()\n  }\n\n  // String/other types - return as lowercase trimmed string\n  return String(raw).trim().toLowerCase()\n}\n\ntype FormatPricingResultOptions = {\n  /** If true, return only the value without \"credits/Run\" suffix */\n  valueOnly?: boolean\n  defaults?: CreditFormatOptions\n}\n\n/**\n * Format a PricingResult into a display string.\n * @param result - The pricing result from JSONata evaluation\n * @param options - Formatting options\n * @returns Formatted string, e.g. \"10 credits/Run\" or \"10\" if valueOnly\n */\nexport const formatPricingResult = (\n  result: unknown,\n  options: FormatPricingResultOptions = {}\n): string => {\n  const { valueOnly = false, defaults = {} } = options\n\n  // Handle legacy format: { usd: number } without type field\n  if (\n    result &&\n    typeof result === 'object' &&\n    !('type' in result) &&\n    'usd' in result\n  ) {\n    const usd = asFiniteNumber(result.usd)\n    if (usd === null) return ''\n    if (valueOnly) return formatCreditsValue(usd)\n    return formatCreditsLabel(usd, defaults)\n  }\n\n  if (!isPricingResult(result)) {\n    if (result !== undefined && result !== null) {\n      console.warn('[pricing/jsonata] invalid result format:', result)\n    }\n    return ''\n  }\n\n  if (result.type === 'text') {\n    return result.text\n  }\n\n  if (result.type === 'usd') {\n    const usd = asFiniteNumber(result.usd)\n    if (usd === null) return ''\n    const fmt = { ...defaults, ...result.format }\n    if (valueOnly) {\n      const prefix = fmt.approximate ? '~' : ''\n      return `${prefix}${formatCreditsValue(usd)}`\n    }\n    return formatCreditsLabel(usd, fmt)\n  }\n\n  if (result.type === 'range_usd') {\n    const minUsd = asFiniteNumber(result.min_usd)\n    const maxUsd = asFiniteNumber(result.max_usd)\n    if (minUsd === null || maxUsd === null) return ''\n    const fmt = { ...defaults, ...result.format }\n    if (valueOnly) {\n      const prefix = fmt.approximate ? '~' : ''\n      return `${prefix}${formatCreditsRangeValue(minUsd, maxUsd)}`\n    }\n    return formatCreditsRangeLabel(minUsd, maxUsd, fmt)\n  }\n\n  {\n    const usdValues = result.usd\n      .map(asFiniteNumber)\n      .filter((x): x is number => x != null)\n\n    if (usdValues.length === 0) return ''\n\n    const fmt = { ...defaults, ...result.format }\n    if (valueOnly) {\n      const prefix = fmt.approximate ? '~' : ''\n      return `${prefix}${formatCreditsListValue(usdValues, fmt.separator)}`\n    }\n    return formatCreditsListLabel(usdValues, fmt)\n  }\n}\n\n// -----------------------------\n// Compile rules (non-fatal)\n// -----------------------------\nconst compileRule = (rule: JsonataPricingRule): CompiledJsonataPricingRule => {\n  try {\n    return { ...rule, _compiled: jsonata(rule.expr) }\n  } catch (e) {\n    // Do not crash app on bad expressions; just disable rule.\n    console.error('[pricing/jsonata] failed to compile expr:', rule.expr, e)\n    return { ...rule, _compiled: null }\n  }\n}\n\n// -----------------------------\n// Rule cache (per-node-type)\n// -----------------------------\nconst compiledRulesCache = new Map<\n  string,\n  { signature: string; rule: CompiledJsonataPricingRule }\n>()\n\n/**\n * Convert a PriceBadge from node definition to a JsonataPricingRule.\n */\nconst priceBadgeToRule = (priceBadge: PriceBadge): JsonataPricingRule => ({\n  engine: priceBadge.engine,\n  depends_on: priceBadge.depends_on,\n  expr: priceBadge.expr\n})\n\n/**\n * Get or compile a pricing rule for a node type.\n */\nexport const getCompiledRuleForNodeType = (\n  nodeName: string,\n  priceBadge: PriceBadge | undefined\n): CompiledJsonataPricingRule | null => {\n  if (!priceBadge) return null\n\n  const rule = priceBadgeToRule(priceBadge)\n  const signature = JSON.stringify(rule)\n  const cached = compiledRulesCache.get(nodeName)\n  if (cached?.signature === signature) return cached.rule\n\n  const compiled = compileRule(rule)\n  compiledRulesCache.set(nodeName, { signature, rule: compiled })\n  return compiled\n}\n\nexport async function evaluatePricingContext(\n  name: string,\n  badge: PriceBadge,\n  context: JsonataEvalContext,\n  options: FormatPricingResultOptions = {}\n): Promise<string> {\n  const rule = getCompiledRuleForNodeType(name, badge)\n  if (!rule?._compiled) return ''\n  try {\n    const result: unknown = await rule._compiled.evaluate(context)\n    return formatPricingResult(result, options)\n  } catch {\n    return ''\n  }\n}\n\n/**\n * Extract default value from an input spec.\n */\nfunction extractDefaultFromSpec(spec: unknown[]): unknown {\n  const specOptions = spec[1]\n\n  // Check for explicit default\n  if (\n    typeof specOptions === 'object' &&\n    specOptions &&\n    'default' in specOptions\n  ) {\n    return specOptions.default\n  }\n  // COMBO/DYNAMICCOMBO type with options array\n  if (\n    typeof specOptions === 'object' &&\n    specOptions &&\n    'options' in specOptions &&\n    Array.isArray(specOptions.options) &&\n    specOptions.options.length > 0\n  ) {\n    const firstOption = specOptions.options[0]\n    // Dynamic combo: options are objects with 'key' property\n    if (\n      typeof firstOption === 'object' &&\n      firstOption !== null &&\n      'key' in firstOption\n    ) {\n      return firstOption.key\n    }\n    // Standard combo: options are primitive values\n    return firstOption\n  }\n  // COMBO type (old format): [[\"option1\", \"option2\"], {...}]\n  if (Array.isArray(spec[0]) && spec[0].length > 0) {\n    return spec[0][0]\n  }\n  return null\n}\n\n/**\n * Evaluate pricing for a node definition using default widget values.\n * Used for NodePricingBadge where no LGraphNode instance exists.\n * Results are memoized by the pricing rule and input definitions.\n */\nexport const evaluateNodeDefPricing = memoize(\n  async (nodeDef: ComfyNodeDef): Promise<string> => {\n    const priceBadge = nodeDef.price_badge\n    if (!priceBadge?.expr) return ''\n\n    // Reuse compiled expression cache\n    const rule = getCompiledRuleForNodeType(nodeDef.name, priceBadge)\n    if (!rule?._compiled) return ''\n\n    try {\n      // Merge all inputs for lookup\n      const allInputs = {\n        ...nodeDef.input?.required,\n        ...nodeDef.input?.optional\n      }\n\n      // Build widgets context using depends_on.widgets (matches buildJsonataContext)\n      const widgets: Record<string, NormalizedWidgetValue> = {}\n      for (const dep of priceBadge.depends_on.widgets) {\n        const spec = allInputs[dep.name]\n        let rawValue: unknown = null\n        if (Array.isArray(spec)) {\n          rawValue = extractDefaultFromSpec(spec)\n        }\n        widgets[dep.name] = normalizeWidgetValue(rawValue, dep.type)\n      }\n      if (Object.values(widgets).some((value) => value === null)) return ''\n\n      // Build inputs context: assume all inputs are disconnected in preview\n      const inputs: Record<string, { connected: boolean }> = {}\n      for (const name of priceBadge.depends_on.inputs) {\n        inputs[name] = { connected: false }\n      }\n\n      // Build inputGroups context: assume 0 connected inputs in preview\n      const inputGroups: Record<string, number> = {}\n      for (const groupName of priceBadge.depends_on.input_groups) {\n        inputGroups[groupName] = 0\n      }\n\n      const context: JsonataEvalContext = { widgets, inputs, inputGroups }\n      const result = await rule._compiled.evaluate(context)\n      return formatPricingResult(result, { valueOnly: true })\n    } catch (e) {\n      console.error('[evaluateNodeDefPricing] error:', e)\n      return ''\n    }\n  },\n  {\n    getCacheKey: (nodeDef: ComfyNodeDef) =>\n      JSON.stringify([nodeDef.name, nodeDef.price_badge, nodeDef.input])\n  }\n)\n","// JSONata-based pricing badge evaluation for API nodes.\n//\n// Pricing declarations are read from ComfyUI node definitions (price_badge field).\n// The Frontend evaluates these declarations locally using a JSONata engine.\n//\n// JSONata v2.x NOTE:\n// - jsonata(expression).evaluate(input) returns a Promise in JSONata 2.x.\n// - Therefore, pricing evaluation is async. This file implements:\n//   - sync getter (returns cached label / last-known label),\n//   - async evaluation + cache,\n//   - reactive tick to update UI when async evaluation completes.\n\nimport {\n  formatPricingResult,\n  getCompiledRuleForNodeType,\n  normalizeWidgetValue\n} from '@comfyorg/shared-frontend-utils/nodePricing'\nimport type {\n  CompiledJsonataPricingRule,\n  JsonataEvalContext,\n  JsonataPricingRule,\n  NormalizedWidgetValue\n} from '@comfyorg/shared-frontend-utils/nodePricing'\nimport { readonly, ref } from 'vue'\nimport type { Ref } from 'vue'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { INodeInputSlot } from '@/lib/litegraph/src/types/slots'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { PriceBadge } from '@/schemas/nodeDefSchema'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport type { NodeId } from '@/types/nodeId'\n\nconst getNodeConstructorData = (node: LGraphNode) => node.constructor.nodeData\n\nconst buildJsonataContext = (\n  node: LGraphNode,\n  rule: JsonataPricingRule,\n  widgetOverrides?: ReadonlyMap<string, unknown>\n): JsonataEvalContext => {\n  const widgets: Record<string, NormalizedWidgetValue> = {}\n  for (const dep of rule.depends_on.widgets) {\n    const raw = widgetOverrides?.has(dep.name)\n      ? widgetOverrides.get(dep.name)\n      : node.widgets?.find((x: IBaseWidget) => x.name === dep.name)?.value\n    widgets[dep.name] = normalizeWidgetValue(raw, dep.type)\n  }\n\n  const inputs: Record<string, { connected: boolean }> = {}\n  for (const name of rule.depends_on.inputs) {\n    const index = node.inputs.findIndex((x: INodeInputSlot) => x.name === name)\n    inputs[name] = { connected: index !== -1 && node.isInputConnected(index) }\n  }\n\n  // Count connected inputs per autogrow group\n  const inputGroups: Record<string, number> = {}\n  for (const groupName of rule.depends_on.input_groups) {\n    const prefix = groupName + '.'\n    inputGroups[groupName] = node.inputs.filter(\n      (inp: INodeInputSlot, index: number) =>\n        inp.name.startsWith(prefix) && node.isInputConnected(index)\n    ).length\n  }\n\n  return { widgets, inputs, inputGroups }\n}\n\nconst safeValueForSig = (v: unknown): string => {\n  if (v === null || v === undefined) return ''\n  if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean')\n    return `${typeof v}:${String(v)}`\n  try {\n    return `json:${JSON.stringify(v)}`\n  } catch {\n    return `fallback:${String(v)}`\n  }\n}\n\n// Signature determines whether we need to re-evaluate when widgets/inputs change.\nconst buildSignature = (\n  ctx: JsonataEvalContext,\n  rule: JsonataPricingRule\n): string => {\n  const parts: string[] = []\n  for (const dep of rule.depends_on.widgets) {\n    parts.push(`w:${dep.name}=${safeValueForSig(ctx.widgets[dep.name])}`)\n  }\n  for (const name of rule.depends_on.inputs) {\n    parts.push(`i:${name}=${ctx.inputs[name]?.connected ? '1' : '0'}`)\n  }\n  for (const name of rule.depends_on.input_groups) {\n    parts.push(`g:${name}=${ctx.inputGroups[name] ?? 0}`)\n  }\n  return parts.join('|')\n}\n\n// -----------------------------\n// Async evaluation + cache (JSONata 2.x)\n// -----------------------------\n\n// Reactive tick to force UI updates when async evaluations resolve.\n// We purposely read pricingTick.value inside getNodeDisplayPrice to create a dependency.\nconst pricingTick = ref(0)\n\n// Per-node revision tracking for VueNodes mode (more efficient than global tick)\n// Uses plain Map with individual refs per node for fine-grained reactivity\n// Keys are stringified node IDs to handle both string and number ID types\nconst nodeRevisions = new Map<NodeId, Ref<number>>()\n\n/**\n * Get or create a revision ref for a specific node.\n * Each node has its own independent ref, so updates to one won't trigger others.\n */\nconst getNodeRevisionRef = (nodeId: NodeId): Ref<number> => {\n  let rev = nodeRevisions.get(nodeId)\n  if (!rev) {\n    rev = ref(0)\n    nodeRevisions.set(nodeId, rev)\n  }\n  return rev\n}\n\n// WeakMaps avoid memory leaks when nodes are removed.\ntype InflightEntry = { sig: string; promise: Promise<void> }\n\nconst MAX_CACHED_SIGNATURES = 8\nconst cache = new WeakMap<LGraphNode, Map<string, string>>()\nconst inflight = new WeakMap<LGraphNode, InflightEntry>()\n\nfunction nodeSigCache(node: LGraphNode): Map<string, string> {\n  const existing = cache.get(node)\n  if (existing) return existing\n  const next = new Map<string, string>()\n  cache.set(node, next)\n  return next\n}\n\nfunction cacheLabel(node: LGraphNode, sig: string, label: string): void {\n  const sigCache = nodeSigCache(node)\n  sigCache.delete(sig)\n  sigCache.set(sig, label)\n  for (const oldest of sigCache.keys()) {\n    if (sigCache.size <= MAX_CACHED_SIGNATURES) break\n    sigCache.delete(oldest)\n  }\n}\n\nconst scheduleEvaluation = (\n  node: LGraphNode,\n  rule: CompiledJsonataPricingRule,\n  ctx: JsonataEvalContext,\n  sig: string\n) => {\n  const running = inflight.get(node)\n  if (running && running.sig === sig) return\n\n  if (!rule._compiled) return\n\n  const promise = Promise.resolve(rule._compiled.evaluate(ctx))\n    .then((res) => {\n      cacheLabel(node, sig, formatPricingResult(res))\n    })\n    .catch(() => {\n      // Cache empty to avoid retry-spam for same signature\n      cacheLabel(node, sig, '')\n    })\n    .finally(() => {\n      const cur = inflight.get(node)\n      if (cur && cur.sig === sig) inflight.delete(node)\n\n      if (LiteGraph.vueNodesMode) {\n        // VueNodes mode: bump per-node revision (only this node re-renders)\n        getNodeRevisionRef(node.id).value++\n      }\n      pricingTick.value++\n    })\n\n  inflight.set(node, { sig, promise })\n}\n\n/**\n * Get the pricing rule for a node from its nodeData.price_badge field.\n */\nconst getRuleForNode = (\n  node: LGraphNode\n): CompiledJsonataPricingRule | undefined => {\n  const nodeData = getNodeConstructorData(node)\n  if (!nodeData?.api_node) return undefined\n\n  const nodeName = nodeData.name\n  const priceBadge = nodeData.price_badge\n\n  if (!priceBadge) return undefined\n\n  const compiled = getCompiledRuleForNodeType(nodeName, priceBadge)\n  return compiled ?? undefined\n}\n\n// -----------------------------\n// Helper to get price badge from node type\n// -----------------------------\nconst getNodePriceBadge = (nodeType: string): PriceBadge | undefined => {\n  const nodeDefStore = useNodeDefStore()\n  return nodeDefStore.nodeDefsByName[nodeType]?.price_badge\n}\n\n// -----------------------------\n// Public composable API\n// -----------------------------\nexport const useNodePricing = () => {\n  /**\n   * Sync getter:\n   * - returns cached label for the current node signature when available\n   * - schedules async evaluation when needed\n   * - remains non-fatal on errors (returns safe fallback '')\n   */\n  const getNodeDisplayPrice = (\n    node: LGraphNode,\n    widgetOverrides?: ReadonlyMap<string, unknown>\n  ): string => {\n    // Make this function reactive: when async evaluation completes, we bump pricingTick,\n    // which causes this getter to recompute in Vue render/computed contexts.\n    void pricingTick.value\n\n    const nodeData = getNodeConstructorData(node)\n    if (!nodeData?.api_node) return ''\n\n    const rule = getRuleForNode(node)\n    if (!rule) return ''\n    if (!rule._compiled) return ''\n\n    const ctx = buildJsonataContext(node, rule, widgetOverrides)\n    const sig = buildSignature(ctx, rule)\n\n    const sigCache = cache.get(node)\n    const hit = sigCache?.get(sig)\n    if (hit !== undefined) return hit\n\n    // Cache miss: start async evaluation.\n    // Return the last-known label (if any) to avoid flicker.\n    scheduleEvaluation(node, rule, ctx, sig)\n    const labels = [...(sigCache?.values() ?? [])]\n    return labels.at(-1) ?? ''\n  }\n\n  /**\n   * Caller compatibility helper:\n   * returns union of widget dependencies + input dependencies for a node type.\n   */\n  const getRelevantWidgetNames = (nodeType: string): string[] => {\n    const priceBadge = getNodePriceBadge(nodeType)\n    if (!priceBadge) return []\n\n    const dependsOn = priceBadge.depends_on\n    const widgetNames = dependsOn.widgets.map((w) => w.name)\n\n    // Dedupe while preserving order\n    const out: string[] = []\n    for (const n of [\n      ...widgetNames,\n      ...dependsOn.inputs,\n      ...dependsOn.input_groups\n    ]) {\n      if (!out.includes(n)) out.push(n)\n    }\n    return out\n  }\n\n  /**\n   * Check if a node type has dynamic pricing (depends on widgets, inputs, or input_groups).\n   */\n  const hasDynamicPricing = (nodeType: string): boolean => {\n    const priceBadge = getNodePriceBadge(nodeType)\n    if (!priceBadge) return false\n\n    const dependsOn = priceBadge.depends_on\n\n    return (\n      dependsOn.widgets.length > 0 ||\n      dependsOn.inputs.length > 0 ||\n      dependsOn.input_groups.length > 0\n    )\n  }\n\n  /**\n   * Get input_groups prefixes for a node type (for watching connection changes).\n   */\n  const getInputGroupPrefixes = (nodeType: string): string[] => {\n    const priceBadge = getNodePriceBadge(nodeType)\n    return priceBadge?.depends_on.input_groups ?? []\n  }\n\n  /**\n   * Get regular input names for a node type (for watching connection changes).\n   */\n  const getInputNames = (nodeType: string): string[] => {\n    const priceBadge = getNodePriceBadge(nodeType)\n    return priceBadge?.depends_on.inputs ?? []\n  }\n\n  return {\n    getNodeDisplayPrice,\n    getRelevantWidgetNames,\n    hasDynamicPricing,\n    getInputGroupPrefixes,\n    getInputNames,\n    getNodeRevisionRef, // Each node has its own independent ref, so updates to one won't trigger others\n    pricingRevision: readonly(pricingTick) // reactive invalidation signal\n  }\n}\n","/** The display order shared by badge renderers. */\nexport const CORE_PART_ORDER = ['id', 'lifecycle', 'source'] as const\n\nexport type CoreBadgePart = (typeof CORE_PART_ORDER)[number]\n\nexport interface CoreBadgeData {\n  kind: 'core'\n  part: CoreBadgePart\n  text: string\n  bgColor?: string\n  fgColor?: string\n}\n\ninterface CreditsBadgeData {\n  kind: 'credits'\n  text: string\n  bgColor?: string\n  fgColor?: string\n}\n\n/**\n * A badge row: plain presentation data projected from its sources\n * (settings, node definition, palette, pricing, connectivity).\n * Core rows carry raw source text plus which projection part they are.\n * They are emitted in display order; renderers only join and trim them.\n * Extension badges are not rows — they live on `node.badges`.\n * Never serialized.\n */\nexport type BadgeData = CoreBadgeData | CreditsBadgeData\n","import { computed } from 'vue'\nimport type { ComputedRef } from 'vue'\n\nimport { useNodePricing } from '@/composables/node/useNodePricing'\nimport { t } from '@/i18n'\nimport type {\n  LGraph,\n  LGraphNode,\n  SubgraphNode\n} from '@/lib/litegraph/src/litegraph'\nimport { registerBadgeRowsProvider } from '@/lib/litegraph/src/nodeBadgeDraw'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { CORE_PART_ORDER } from '@/types/badgeData'\nimport type { BadgeData, CoreBadgePart } from '@/types/badgeData'\nimport type { NodeId } from '@/types/nodeId'\nimport { NodeBadgeMode } from '@/types/nodeSource'\nimport { widgetId } from '@/types/widgetId'\nimport { adjustColor } from '@/utils/colorUtil'\nimport { mapUniqueNodes } from '@/utils/graphTraversalUtil'\nimport type { UUID } from '@/utils/uuid'\n\n/** The badge-relevant projection of a node's definition. */\ninterface NodeDefBadgeSources {\n  isCoreNode: boolean\n  lifecycleText: string\n  sourceText: string\n}\n\n/** How a node participates in credits pricing, decided by the gatherer. */\ntype PricingBadgeSources =\n  | { kind: 'none' }\n  | { kind: 'api-node'; label: string }\n  | { kind: 'subgraph'; apiNodeCount: number; singleLabel: string }\n\n/**\n * The domain state a node's badges are computed from. Plain data so\n * {@link computeBadges} stays pure — {@link nodeBadges}' computed\n * gathers these from the live stores.\n */\nexport interface BadgeSources {\n  nodeId: NodeId\n  nodeDef: NodeDefBadgeSources | null\n  badgeModes: {\n    id: NodeBadgeMode\n    lifecycle: NodeBadgeMode\n    source: NodeBadgeMode\n  }\n  colors: { fgColor: string; bgColor: string; creditsBgColor: string }\n  pricing: PricingBadgeSources\n}\n\nfunction badgeTextVisible(\n  nodeDef: NodeDefBadgeSources | null,\n  badgeMode: NodeBadgeMode\n): boolean {\n  return !(\n    badgeMode === NodeBadgeMode.None ||\n    (nodeDef?.isCoreNode && badgeMode === NodeBadgeMode.HideBuiltIn)\n  )\n}\n\n/** Projects a node's core and credits badge rows from their sources. */\nexport function computeBadges(sources: BadgeSources): BadgeData[] {\n  const { nodeId, nodeDef, badgeModes, colors, pricing } = sources\n  const corePartsByPart: Record<CoreBadgePart, [NodeBadgeMode, string]> = {\n    id: [badgeModes.id, `#${nodeId}`],\n    lifecycle: [badgeModes.lifecycle, nodeDef?.lifecycleText ?? ''],\n    source: [badgeModes.source, nodeDef?.sourceText ?? '']\n  }\n  const coreParts = CORE_PART_ORDER.map(\n    (part): [CoreBadgePart, NodeBadgeMode, string] => [\n      part,\n      ...corePartsByPart[part]\n    ]\n  )\n  const rows: BadgeData[] = coreParts\n    .filter(\n      ([, mode, text]) => badgeTextVisible(nodeDef, mode) && text.length > 0\n    )\n    .map(([part, , text]) => ({\n      kind: 'core',\n      part,\n      text,\n      fgColor: colors.fgColor,\n      bgColor: colors.bgColor\n    }))\n\n  const creditsText = computeCreditsText(pricing)\n  if (creditsText) {\n    rows.push({\n      kind: 'credits',\n      text: creditsText,\n      fgColor: colors.fgColor,\n      bgColor: colors.creditsBgColor\n    })\n  }\n  return rows\n}\n\nfunction computeCreditsText(pricing: PricingBadgeSources): string {\n  switch (pricing.kind) {\n    case 'none':\n      return ''\n    case 'api-node':\n      return pricing.label\n    case 'subgraph':\n      if (pricing.apiNodeCount > 1) {\n        return t('nodeBadge.partnerNodesCount', {\n          count: pricing.apiNodeCount\n        })\n      }\n      return pricing.apiNodeCount === 1 ? pricing.singleLabel : ''\n  }\n}\n\nconst CREDITS_BASE_BG_COLOR = '#8D6932'\n\n/**\n * Reads the pricing-relevant store state so the calling computed re-runs\n * when a price revision, priced widget value, or priced input connection\n * changes.\n */\nfunction touchPricingSources(graphId: UUID, node: LGraphNode): void {\n  const pricing = useNodePricing()\n  const nodeId = node.id\n  void pricing.getNodeRevisionRef(nodeId).value\n\n  if (!node.type || !pricing.hasDynamicPricing(node.type)) return\n  const widgetStore = useWidgetValueStore()\n  for (const name of pricing.getRelevantWidgetNames(node.type)) {\n    void widgetStore.getWidget(widgetId(graphId, nodeId, name))?.value\n  }\n  const linkStore = useLinkStore()\n  const inputNames = pricing.getInputNames(node.type)\n  const groupPrefixes = pricing.getInputGroupPrefixes(node.type)\n  const graph = node.graph\n  const graphScope = graph ? graphScopeOf(graph) : undefined\n  node.inputs.forEach((input, index) => {\n    const relevant =\n      (input.name && inputNames.includes(input.name)) ||\n      groupPrefixes.some((prefix) => input.name.startsWith(prefix + '.'))\n    if (relevant && graphScope) {\n      void linkStore.isInputSlotConnected(graphScope, nodeId, index)\n    }\n  })\n}\n\n/** Promoted widget values on the wrapper override the inner node's own. */\nfunction collectPromotedOverrides(\n  wrapper: SubgraphNode,\n  innerNode: LGraphNode\n): ReadonlyMap<string, unknown> {\n  const overrides = new Map<string, unknown>()\n  for (const input of wrapper.inputs) {\n    if (!input.widgetId) continue\n    for (const linkId of input._subgraphSlot?.linkIds ?? []) {\n      const link = wrapper.subgraph.getLink(linkId)\n      if (link?.target_id !== innerNode.id) continue\n      const widgetName = innerNode.inputs[link.target_slot]?.widget?.name\n      if (!widgetName) continue\n      overrides.set(\n        widgetName,\n        useWidgetValueStore().getWidget(input.widgetId)?.value\n      )\n    }\n  }\n  return overrides\n}\n\n/**\n * Aggregates the inner api nodes' credits for a wrapper, tracking their\n * pricing revisions so inner price changes recompute the wrapper.\n */\nfunction gatherSubgraphCredits(wrapper: SubgraphNode): PricingBadgeSources {\n  const pricing = useNodePricing()\n  const apiLeaves = mapUniqueNodes(wrapper.subgraph, (node) =>\n    !node.isSubgraphNode() && node.constructor.nodeData?.api_node\n      ? node\n      : undefined\n  )\n  for (const leaf of apiLeaves) {\n    const graphId = leaf.graph?.rootGraph.id\n    if (graphId !== undefined) touchPricingSources(graphId, leaf)\n  }\n\n  if (apiLeaves.length !== 1) {\n    return { kind: 'subgraph', apiNodeCount: apiLeaves.length, singleLabel: '' }\n  }\n  const leaf = apiLeaves[0]\n  const singleLabel = pricing.getNodeDisplayPrice(\n    leaf,\n    collectPromotedOverrides(wrapper, leaf)\n  )\n  return { kind: 'subgraph', apiNodeCount: 1, singleLabel }\n}\n\nfunction gatherPricing(node: LGraphNode): PricingBadgeSources {\n  if (node.isSubgraphNode()) return gatherSubgraphCredits(node)\n  if (!node.constructor.nodeData?.api_node) return { kind: 'none' }\n  const graphId = node.graph?.rootGraph.id\n  if (graphId !== undefined) touchPricingSources(graphId, node)\n  return { kind: 'api-node', label: useNodePricing().getNodeDisplayPrice(node) }\n}\n\nfunction gatherSources(node: LGraphNode): BadgeSources {\n  const settingStore = useSettingStore()\n  const palette = useColorPaletteStore().completedActivePalette\n  const def = useNodeDefStore().fromLGraphNode(node)\n  const showApiPricing = settingStore.get('Comfy.NodeBadge.ShowApiPricing')\n\n  return {\n    nodeId: node.id,\n    nodeDef: def\n      ? {\n          isCoreNode: def.isCoreNode,\n          lifecycleText: def.nodeLifeCycleBadgeText,\n          sourceText: def.nodeSource.badgeText\n        }\n      : null,\n    badgeModes: {\n      id: settingStore.get('Comfy.NodeBadge.NodeIdBadgeMode'),\n      lifecycle: settingStore.get('Comfy.NodeBadge.NodeLifeCycleBadgeMode'),\n      source: settingStore.get('Comfy.NodeBadge.NodeSourceBadgeMode')\n    },\n    colors: {\n      fgColor: palette.colors.litegraph_base.BADGE_FG_COLOR,\n      bgColor: palette.colors.litegraph_base.BADGE_BG_COLOR,\n      creditsBgColor: palette.light_theme\n        ? adjustColor(CREDITS_BASE_BG_COLOR, { lightness: 0.5 })\n        : CREDITS_BASE_BG_COLOR\n    },\n    pricing: showApiPricing ? gatherPricing(node) : { kind: 'none' }\n  }\n}\n\nconst badgeComputeds = new WeakMap<LGraphNode, ComputedRef<BadgeData[]>>()\n\n/**\n * A node's derived badge rows, memoized per node instance and recomputed\n * when a source changes. Entries die with their nodes; there is no\n * registration or teardown.\n */\nexport function nodeBadges(node: LGraphNode): readonly BadgeData[] {\n  let rows = badgeComputeds.get(node)\n  if (!rows) {\n    // Instantiate source stores outside the computed: a store's first\n    // instantiation mutates pinia.state and would invalidate it.\n    useSettingStore()\n    useNodeDefStore()\n    useColorPaletteStore()\n    useWidgetValueStore()\n    useLinkStore()\n    rows = computed(() => {\n      return computeBadges(gatherSources(node))\n    })\n    badgeComputeds.set(node, rows)\n  }\n  return rows.value\n}\n\ninterface CreditsBadgeEntry {\n  nodeId: NodeId\n  price: string\n  title: string\n}\n\nconst creditsComputeds = new WeakMap<LGraph, ComputedRef<CreditsBadgeEntry[]>>()\n\n/**\n * The credits rows of every unique non-wrapper node under a root graph,\n * memoized per graph instance like {@link nodeBadges}.\n */\nexport function graphCreditsBadges(\n  rootGraph: LGraph\n): readonly CreditsBadgeEntry[] {\n  let entries = creditsComputeds.get(rootGraph)\n  if (!entries) {\n    entries = computed(() =>\n      mapUniqueNodes(rootGraph, (node) => {\n        if (node.isSubgraphNode()) return\n        const priceRow = nodeBadges(node).find((row) => row.kind === 'credits')\n        if (!priceRow) return\n        return { nodeId: node.id, price: priceRow.text, title: node.title }\n      })\n    )\n    creditsComputeds.set(rootGraph, entries)\n  }\n  return entries.value\n}\n\n/** Installs {@link nodeBadges} as the legacy canvas's badge row source. */\nexport function installNodeBadges(): () => void {\n  return registerBadgeRowsProvider(nodeBadges)\n}\n","import { createSharedComposable } from '@vueuse/core'\nimport { computed, ref, watch } from 'vue'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { isCloud } from '@/platform/distribution/types'\nimport { remoteConfig } from '@/platform/remoteConfig/remoteConfig'\nimport { useApp } from '@/scripts/appInstance'\nimport { graphCreditsBadges } from '@/systems/badgeSystem'\n\nexport const useFreeTierQuota = createSharedComposable(function () {\n  const { flags } = useFeatureFlags()\n\n  const available = ref(0)\n  const maxAvailable = ref(0)\n  watch(\n    () => remoteConfig.value.free_tier_balance?.remaining,\n    (val) => (available.value = val ?? 0),\n    { immediate: true }\n  )\n  watch(\n    () => remoteConfig.value.free_tier_balance?.allowance,\n    (val) => (maxAvailable.value = val ?? 0),\n    { immediate: true }\n  )\n\n  const quotaEnabled = computed(\n    () => isCloud && flags.freeTierJobAllowanceEnabled && maxAvailable.value > 0\n  )\n  const hasInvalidNodes = computed(() => {\n    const app = useApp()\n    return app.isGraphReady && graphCreditsBadges(app.rootGraph).length > 0\n  })\n  const freeTierExecutionPermitted = computed(\n    () => !hasInvalidNodes.value && quotaEnabled.value && available.value > 0\n  )\n\n  function trackRun() {\n    if (available.value > 0) available.value--\n  }\n\n  return {\n    available,\n    freeTierExecutionPermitted,\n    hasInvalidNodes,\n    maxAvailable,\n    quotaEnabled,\n    trackRun\n  }\n})\n","import type { BillingRail } from '@/platform/workspace/api/workspaceApi'\n\ntype BillingRailValue = BillingRail | null | undefined\n\n/** Compile-time exhaustiveness check; unknown runtime values fall back to false. */\nfunction assertNever(_rail: never): false {\n  return false\n}\n\n/** Whether a personal workspace on this rail uses legacy account operations. */\nexport function usesLegacyAccountOperations(rail: BillingRailValue): boolean {\n  switch (rail) {\n    case 'legacy_stripe':\n      return true\n    case 'stripe':\n    case 'metronome':\n    case null:\n    case undefined:\n      return false\n    default:\n      return assertNever(rail)\n  }\n}\n\n/** Whether the in-app cancellation flow supports this rail. */\nexport function supportsInAppCancellation(rail: BillingRailValue): boolean {\n  switch (rail) {\n    case 'stripe':\n      return true\n    // The metronome cancellation route is pending a backend decision.\n    case 'metronome':\n    case 'legacy_stripe':\n    case null:\n    case undefined:\n      return false\n    default:\n      return assertNever(rail)\n  }\n}\n","import { computed } from 'vue'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\n\nimport { usesLegacyAccountOperations } from './billingRail'\nimport type { BillingType } from './types'\n\n/**\n * Selects the billing backend for the active workspace: legacy user-scoped\n * (`/customers/*`) or workspace-scoped (`/api/billing/*`). Personal workspaces\n * use workspace billing unless an explicit legacy Stripe rail selects legacy\n * account operations and its migration flag is off. Until a workspace loads\n * the type is `unknown`; Local/Desktop resolves to workspace billing once its\n * Cloud-backed workspace context loads.\n */\nexport function useBillingRouting() {\n  const { flags } = useFeatureFlags()\n  const workspaceStore = useTeamWorkspaceStore()\n\n  const shouldUseUnifiedPricing = computed(() => {\n    return isCloud && workspaceStore.activeWorkspace?.type !== undefined\n  })\n\n  const type = computed<BillingType>(() => {\n    const workspaceType = workspaceStore.activeWorkspace?.type\n    if (!workspaceType) return 'unknown'\n\n    if (\n      workspaceType === 'personal' &&\n      usesLegacyAccountOperations(workspaceStore.activeWorkspaceBillingRail) &&\n      !flags.legacyBillingMigrationEnabled\n    ) {\n      return 'legacy'\n    }\n\n    return 'workspace'\n  })\n\n  const shouldUseWorkspaceBilling = computed(() => type.value === 'workspace')\n\n  return { type, shouldUseWorkspaceBilling, shouldUseUnifiedPricing }\n}\n","import { useAuthStore } from '@/stores/authStore'\n\n/**\n * A Stripe credit top-up completes in a separate tab, and the balance only\n * changes once Stripe's webhook reaches comfy-api. Nothing re-reads the balance\n * when the user comes back, so the app keeps showing the pre-purchase amount\n * until a manual reload.\n *\n * Re-fetch when the app tab becomes visible again, retrying on a short schedule\n * because the webhook usually lands a beat after the redirect. Gaps between\n * attempts, so the run spans ~37s.\n */\nconst RETRY_GAPS_MS = [0, 2_000, 5_000, 10_000, 20_000]\n\n/** Drop the watch if the user never returns, rather than leaking listeners. */\nconst WATCH_LIFETIME_MS = 15 * 60_000\n\n/** Full retry schedules a returning user can trigger; later returns get a single fetch. */\nconst MAX_SCHEDULED_RUNS = 5\n\nlet stopActiveWatch: (() => void) | null = null\n\ninterface TopupBalanceSource {\n  current: () => number | null\n  fetch: () => Promise<number | null>\n}\n\nconst customerBalanceSource: TopupBalanceSource = {\n  current: () => useAuthStore().balance?.amount_micros ?? null,\n  fetch: async () =>\n    (await useAuthStore().fetchBalance())?.amount_micros ?? null\n}\n\n/**\n * Watch for the user returning from a Stripe top-up and refresh the balance.\n * Safe to call repeatedly: a new call replaces any watch still pending.\n */\nexport function watchForTopupBalanceUpdate(\n  source: TopupBalanceSource = customerBalanceSource\n): void {\n  if (typeof window === 'undefined' || typeof document === 'undefined') return\n\n  stopActiveWatch?.()\n\n  // Null until a balance is known: treating \"not loaded yet\" as 0 would let the\n  // first read of the *pre-purchase* balance count as the increase we are\n  // waiting for, stopping the watch on the stale amount.\n  let baselineMicros: number | null = source.current()\n\n  const timeouts = new Set<ReturnType<typeof setTimeout>>()\n  let stopped = false\n  let running = false\n  let runs = 0\n\n  const stop = () => {\n    stopped = true\n    document.removeEventListener('visibilitychange', handleReturn)\n    window.removeEventListener('focus', handleReturn)\n    for (const timeout of timeouts) clearTimeout(timeout)\n    timeouts.clear()\n    if (stopActiveWatch === stop) stopActiveWatch = null\n  }\n\n  const wait = (ms: number) =>\n    new Promise<void>((resolve) => {\n      const timeout = setTimeout(() => {\n        timeouts.delete(timeout)\n        resolve()\n      }, ms)\n      timeouts.add(timeout)\n    })\n\n  /** Fetch the balance; true once it has risen above the arming baseline. */\n  const refresh = async (): Promise<boolean> => {\n    try {\n      const amountMicros = (await source.fetch()) ?? 0\n      if (baselineMicros === null) {\n        baselineMicros = amountMicros\n        return false\n      }\n      return amountMicros > baselineMicros\n    } catch (error) {\n      // A failed poll is not actionable: the next attempt (or the panel's own\n      // fetch) covers it, and the purchase itself already succeeded.\n      console.warn('[Billing] Top-up balance refresh failed', error)\n      return false\n    }\n  }\n\n  async function onReturn() {\n    if (running || stopped || document.visibilityState !== 'visible') return\n    running = true\n    runs += 1\n\n    // Past the run cap a return still refreshes once — the return after the\n    // actual payment must fetch no matter how often the user glanced back\n    // beforehand. Only the retry schedule is withheld; the lifetime timer is\n    // the sole terminal condition.\n    const gaps = runs > MAX_SCHEDULED_RUNS ? [0] : RETRY_GAPS_MS\n    const isStopped = () => stopped\n\n    for (const gap of gaps) {\n      await wait(gap)\n      if (isStopped()) return\n      if (await refresh()) {\n        stop()\n        return\n      }\n      if (isStopped()) return\n    }\n\n    running = false\n  }\n\n  function handleReturn() {\n    void onReturn()\n  }\n\n  document.addEventListener('visibilitychange', handleReturn)\n  window.addEventListener('focus', handleReturn)\n  timeouts.add(setTimeout(stop, WATCH_LIFETIME_MS))\n\n  stopActiveWatch = stop\n}\n","import type { BillingTelemetryFailure } from '@comfyorg/account-core/billing'\n\nimport { WorkspaceApiError } from '@/platform/workspace/api/workspaceApi'\nimport { AuthStoreError } from '@/stores/authStore'\n\nexport class BillingFailureError extends Error {\n  constructor(\n    message: string,\n    public readonly failure: BillingTelemetryFailure\n  ) {\n    super(message)\n    this.name = 'BillingFailureError'\n  }\n}\n\nexport class PaymentPopupBlockedError extends BillingFailureError {\n  constructor(message: string) {\n    super(message, {\n      failure_category: 'redirect',\n      error_code: 'payment_popup_blocked'\n    })\n    this.name = 'PaymentPopupBlockedError'\n  }\n}\n\nexport function describeBillingFailure(err: unknown): BillingTelemetryFailure {\n  return err instanceof BillingFailureError\n    ? err.failure\n    : { failure_category: categorizeBillingApiError(err) }\n}\n\n/**\n * A `WorkspaceApiError` that names its category keeps it. Otherwise a\n * `WorkspaceApiError`/`AuthStoreError` with no `status` never reached the\n * backend (`network`); a `TypeError` naming fetch/network/load is what `fetch`\n * throws for connectivity failures.\n */\nexport function categorizeBillingApiError(\n  err: unknown\n): BillingTelemetryFailure['failure_category'] {\n  if (err instanceof BillingFailureError) return err.failure.failure_category\n  if (err instanceof WorkspaceApiError) {\n    if (err.failureCategory) return err.failureCategory\n    return err.status === undefined ? 'network' : 'api_rejected'\n  }\n  if (err instanceof AuthStoreError) {\n    return err.status === undefined ? 'network' : 'api_rejected'\n  }\n  if (\n    err instanceof TypeError &&\n    /fetch|network|load failed/i.test(err.message)\n  ) {\n    return 'network'\n  }\n  return 'unknown'\n}\n","import type { AuditLog } from '@/services/customerEventsService'\n\nconst STORAGE_KEY = 'pending_topup_timestamp'\nconst MAX_AGE_MS = 24 * 60 * 60 * 1000 // 24 hours\n\ninterface CompletedTopup {\n  /** Set when the checkout tab opened, one purchase request after `started`. */\n  startedAtMs: number\n}\n\nfunction getPendingTopupTimestamp(): number | null {\n  const timestampStr = localStorage.getItem(STORAGE_KEY)\n  if (timestampStr === null) return null\n\n  const timestamp = Number(timestampStr)\n  const age = Date.now() - timestamp\n  if (Number.isSafeInteger(timestamp) && age >= 0 && age <= MAX_AGE_MS) {\n    return timestamp\n  }\n\n  localStorage.removeItem(STORAGE_KEY)\n  return null\n}\n\n/**\n * Pending credit top-up marker (localStorage) so the balance can refresh on\n * return from Stripe checkout. Pure billing state, no telemetry dependency, so\n * it works regardless of telemetry consent.\n */\nexport function usePendingTopup() {\n  // Mark a top-up as pending before opening the Stripe checkout window.\n  function startPendingTopup(): void {\n    localStorage.setItem(STORAGE_KEY, Date.now().toString())\n  }\n\n  // The top-up a later credit_added completed, if any; clears the marker on hit.\n  function consumeCompletedTopup(\n    events: AuditLog[] | undefined | null\n  ): CompletedTopup | null {\n    const timestamp = getPendingTopupTimestamp()\n    if (timestamp === null) return null\n    if (!events || events.length === 0) return null\n\n    const completedTopup = events.find(\n      (e) =>\n        e.event_type === 'credit_added' &&\n        e.createdAt &&\n        new Date(e.createdAt).getTime() > timestamp\n    )\n\n    if (!completedTopup) return null\n    localStorage.removeItem(STORAGE_KEY)\n    return { startedAtMs: timestamp }\n  }\n\n  // Non-consuming: true if a pending top-up is awaiting a balance refresh.\n  function pendingTopupNeedsRefresh(): boolean {\n    return getPendingTopupTimestamp() !== null\n  }\n\n  // Clear any pending top-up marker.\n  function clearPendingTopup(): void {\n    localStorage.removeItem(STORAGE_KEY)\n  }\n\n  return {\n    startPendingTopup,\n    consumeCompletedTopup,\n    pendingTopupNeedsRefresh,\n    clearPendingTopup\n  }\n}\n","import { isDesktop } from '@/platform/distribution/types'\n\nexport interface BillingTab {\n  navigate(url: string): void\n  close(): void\n}\n\n/**\n * Desktop denies every in-app popup and hands its URL to the system browser,\n * so `window.open` there always returns `null` even though the page opened.\n */\nfunction handsPopupsToSystemBrowser(): boolean {\n  return isDesktop || window.__comfyDesktop2 !== undefined\n}\n\n/** Opens a billing page in a new tab; `false` only when the browser blocked it. */\nexport function openBillingUrl(url: string): boolean {\n  const tab = window.open(url, '_blank')\n  return tab !== null || handsPopupsToSystemBrowser()\n}\n\n/**\n * Reserves a billing tab during the click, before its URL is known; `null`\n * when the browser blocked it. On Desktop the open waits for the URL.\n */\nexport function reserveBillingTab(): BillingTab | null {\n  if (handsPopupsToSystemBrowser()) {\n    return {\n      navigate: (url) => {\n        window.open(url, '_blank')\n      },\n      close: () => {}\n    }\n  }\n  const tab = window.open('', '_blank')\n  if (!tab) return null\n  tab.opener = null\n  return {\n    navigate: (url) => {\n      tab.location.href = url\n    },\n    close: () => tab.close()\n  }\n}\n","import { FirebaseError } from 'firebase/app'\nimport { AuthErrorCodes } from 'firebase/auth'\nimport { ref } from 'vue'\n\nimport {\n  authErrorMessage,\n  classifyAuthError,\n  severityForAuthError\n} from '@comfyorg/account-core/firebaseAuthError'\nimport type { AuthErrorCopy } from '@comfyorg/account-core/firebaseAuthError'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { watchForTopupBalanceUpdate } from '@/composables/billing/topupBalanceRefresh'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport type { ErrorRecoveryStrategy } from '@/composables/useErrorHandling'\nimport { st, t } from '@/i18n'\nimport enMessages from '@/locales/en/main.json' with { type: 'json' }\nimport { presentSsoRequired } from '@/platform/auth/sso/ssoRequired'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type { AuthFlowAction } from '@/platform/telemetry/types'\nimport { PaymentPopupBlockedError } from '@/platform/telemetry/utils/billingFailureCategory'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport {\n  clearAllWorkspaceStorage,\n  prepareWorkflowLogoutTransition\n} from '@/platform/workflow/persistence/base/storageIO'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { usePendingTopup } from '@/composables/billing/usePendingTopup'\nimport { useAuthDialogs } from '@/composables/auth/useAuthDialogs'\nimport { useDialogService } from '@/services/dialogService'\nimport { SsoRequiredAuthError, useAuthStore } from '@/stores/authStore'\nimport type {\n  BillingPortalTargetTier,\n  SocialSignInOptions\n} from '@/stores/authStore'\nimport { usdToMicros } from '@/utils/formatUtil'\nimport { openBillingUrl } from '@/platform/workspace/billing/billingTab'\n\n/**\n * The app's own auth.errors table, read through vue-i18n at resolution time.\n * The key set is the app's, so a code added to main.json renders without the\n * package having to know it.\n */\nexport const localizedAuthErrorCopy = (): AuthErrorCopy => ({\n  ...Object.fromEntries(\n    Object.keys(enMessages.auth.errors).map((key) => [\n      key,\n      st(`auth.errors.${key}`, t('auth.errors.generic'))\n    ])\n  ),\n  generic: t('auth.errors.generic'),\n  signupBlocked: st('auth.errors.signupBlocked', t('auth.errors.generic'))\n})\n\n/**\n * Service for Firebase Auth actions.\n * All actions are wrapped with error handling.\n * @returns {Object} - Object containing all Firebase Auth actions\n */\nexport const useAuthActions = () => {\n  const authStore = useAuthStore()\n  const toast = useToast()\n  const { wrapWithErrorHandlingAsync, toastErrorHandler } = useErrorHandling()\n\n  const accessError = ref(false)\n\n  const reportAuthFlowError =\n    (authAction: AuthFlowAction) => (error: unknown) => {\n      useTelemetry()?.trackAuthFailed({\n        error_code: error instanceof FirebaseError ? error.code : 'unknown',\n        auth_action: authAction\n      })\n      reportError(error)\n    }\n\n  /** Sends an account its SSO organization refused to SSO instead of a failure toast. */\n  const presentSsoRefusal = (error: SsoRequiredAuthError): boolean => {\n    const presented = presentSsoRequired('customer_create', {\n      email: authStore.userEmail ?? undefined,\n      organizationId: error.organizationId\n    })\n    if (presented) void authStore.logout().catch(toastErrorHandler)\n    return presented\n  }\n\n  const reportError = (error: unknown) => {\n    if (error instanceof SsoRequiredAuthError && presentSsoRefusal(error)) {\n      return\n    }\n    const classification = classifyAuthError(error)\n    // Ref: https://firebase.google.com/docs/auth/admin/errors\n    const kind = severityForAuthError(classification)\n    const notify = (description: string) =>\n      toast[kind](t(`g.${kind}`), { description })\n    if (classification.kind === 'unauthorized-domain') {\n      accessError.value = true\n      notify(\n        t('toastMessages.unauthorizedDomain', {\n          domain: window.location.hostname,\n          email: 'support@comfy.org'\n        })\n      )\n    } else if (classification.kind !== 'unknown') {\n      notify(authErrorMessage(classification, localizedAuthErrorCopy()))\n    } else if (error instanceof FirebaseError) {\n      // classifyAuthError only knows auth/ codes; an app/ or installations/\n      // FirebaseError still gets the localized copy, never the raw SDK text.\n      toast.error(t('g.error'), {\n        description: st(`auth.errors.${error.code}`, t('auth.errors.generic'))\n      })\n    } else {\n      toastErrorHandler(error)\n    }\n  }\n\n  /** `beforeSignOut` runs once unsaved work is settled; false keeps the user signed in. */\n  const logout = wrapWithErrorHandlingAsync(\n    async ({\n      beforeSignOut\n    }: { beforeSignOut?: () => Promise<boolean> } = {}) => {\n      if (isCloud) {\n        const workflowStore = useWorkflowStore()\n        const modifiedWorkflows = workflowStore.modifiedWorkflows\n        if (modifiedWorkflows.length > 0) {\n          const dialogService = useDialogService()\n          const confirmed = await dialogService.confirm({\n            title: t('auth.signOut.unsavedChangesTitle'),\n            message: t('auth.signOut.unsavedChangesMessage'),\n            type: 'dirtyClose',\n            denyLabel: t('auth.signOut.signOutAnyway')\n          })\n          if (confirmed === null) return\n\n          if (confirmed) {\n            const workflowService = useWorkflowService()\n            for (const workflow of modifiedWorkflows) {\n              try {\n                const saved = await workflowService.saveWorkflow(workflow)\n                if (!saved) return\n              } catch {\n                throw new Error(\n                  t('auth.signOut.saveFailed', { workflow: workflow.path })\n                )\n              }\n            }\n          }\n        }\n      }\n\n      if (beforeSignOut && !(await beforeSignOut())) return\n\n      await authStore.logout()\n      if (isCloud) {\n        prepareWorkflowLogoutTransition()\n        clearAllWorkspaceStorage()\n      }\n\n      toast.success(t('auth.signOut.success'), {\n        description: t('auth.signOut.successDetail'),\n        duration: 5000\n      })\n\n      if (isCloud) {\n        try {\n          window.location.href = '/cloud/login'\n        } catch {\n          // needed for local development until we bring in cloud login pages.\n          window.location.reload()\n        }\n      }\n    },\n    reportError\n  )\n\n  const sendPasswordReset = wrapWithErrorHandlingAsync(\n    async (email: string) => {\n      await authStore.sendPasswordReset(email)\n      toast.success(t('auth.login.passwordResetSent'), {\n        description: t('auth.login.passwordResetSentDetail'),\n        duration: 5000\n      })\n      return true\n    },\n    reportAuthFlowError('password_reset')\n  )\n\n  /** Whether `purchaseCreditsDirect` goes on to open a checkout. */\n  const canPurchaseCredits = (): boolean =>\n    useBillingContext().canAccessSubscriptionFeatures.value\n\n  /**\n   * Raw (unwrapped) credit purchase. Exposed separately from `purchaseCredits`\n   * so callers that need to observe a rejection directly (e.g. to fire failure\n   * telemetry) aren't routed through `wrapWithErrorHandlingAsync`, which\n   * resolves instead of re-throwing on failure.\n   */\n  const purchaseCreditsDirect = async (amount: number): Promise<void> => {\n    if (!canPurchaseCredits()) return\n\n    const response = await authStore.initiateCreditPurchase({\n      amount_micros: usdToMicros(amount),\n      currency: 'usd'\n    })\n\n    if (!response.checkout_url) {\n      throw new Error(\n        t('toastMessages.failedToPurchaseCredits', {\n          error: 'No checkout URL returned'\n        })\n      )\n    }\n\n    // Mark the pending top-up directly, not via telemetry, so the balance\n    // refresh on return still fires when telemetry consent is off.\n    const pendingTopup = usePendingTopup()\n    pendingTopup.startPendingTopup()\n    if (!openBillingUrl(response.checkout_url)) {\n      pendingTopup.clearPendingTopup()\n      throw new PaymentPopupBlockedError(\n        t('subscription.preview.paymentPopupBlocked')\n      )\n    }\n    watchForTopupBalanceUpdate()\n  }\n\n  const purchaseCredits = wrapWithErrorHandlingAsync(\n    purchaseCreditsDirect,\n    reportError\n  )\n\n  /** Unwrapped `accessBillingPortal`: rejects on failure, false when the tab is blocked. */\n  const accessBillingPortalDirect = async (\n    targetTier?: BillingPortalTargetTier,\n    options?: { cancelSubscription?: boolean }\n  ): Promise<boolean> => {\n    const response = await authStore.accessBillingPortal(targetTier, options)\n    if (!response.billing_portal_url) {\n      throw new Error(\n        t('toastMessages.failedToAccessBillingPortal', {\n          error: 'No billing portal URL returned'\n        })\n      )\n    }\n    return window.open(response.billing_portal_url, '_blank') !== null\n  }\n\n  const accessBillingPortal = wrapWithErrorHandlingAsync(\n    accessBillingPortalDirect,\n    reportError\n  )\n\n  const fetchBalance = wrapWithErrorHandlingAsync(async () => {\n    const result = await authStore.fetchBalance()\n    // Top-up completion tracking happens in UsageLogsTable when events are fetched\n    return result\n  }, reportError)\n\n  const signInWithGoogle = async (options?: SocialSignInOptions) =>\n    await wrapWithErrorHandlingAsync(\n      async () => await authStore.loginWithGoogle(options),\n      reportAuthFlowError(\n        options?.isNewUser ? 'google_sign_up' : 'google_sign_in'\n      )\n    )()\n\n  const signInWithGithub = async (options?: SocialSignInOptions) =>\n    await wrapWithErrorHandlingAsync(\n      async () => await authStore.loginWithGithub(options),\n      reportAuthFlowError(\n        options?.isNewUser ? 'github_sign_up' : 'github_sign_in'\n      )\n    )()\n\n  const signInWithEmail = wrapWithErrorHandlingAsync(\n    async (email: string, password: string) => {\n      return await authStore.login(email, password)\n    },\n    reportAuthFlowError('email_sign_in')\n  )\n\n  const signUpWithEmail = wrapWithErrorHandlingAsync(\n    async (email: string, password: string, turnstileToken?: string) => {\n      return await authStore.register(email, password, turnstileToken)\n    },\n    reportAuthFlowError('email_sign_up')\n  )\n\n  /**\n   * Recovery strategy for Firebase auth/requires-recent-login errors.\n   * Prompts user to reauthenticate and retries the operation after successful login.\n   */\n  const createReauthenticationRecovery = <\n    TArgs extends unknown[],\n    TReturn\n  >(): ErrorRecoveryStrategy<TArgs, TReturn> => {\n    const dialogService = useDialogService()\n\n    return {\n      shouldHandle: (error: unknown) =>\n        error instanceof FirebaseError &&\n        error.code === AuthErrorCodes.CREDENTIAL_TOO_OLD_LOGIN_AGAIN,\n\n      recover: async (\n        _error: unknown,\n        retry: (...args: TArgs) => Promise<TReturn> | TReturn,\n        args: TArgs\n      ) => {\n        const confirmed = await dialogService.confirm({\n          title: t('auth.reauthRequired.title'),\n          message: t('auth.reauthRequired.message'),\n          type: 'default'\n        })\n\n        if (!confirmed) {\n          return\n        }\n\n        await authStore.logout()\n\n        const signedIn = await useAuthDialogs().showSignInDialog()\n\n        if (signedIn) {\n          await retry(...args)\n        }\n      }\n    }\n  }\n\n  const updatePassword = wrapWithErrorHandlingAsync(\n    async (newPassword: string) => {\n      await authStore.updatePassword(newPassword)\n      toast.success(t('auth.passwordUpdate.success'), {\n        description: t('auth.passwordUpdate.successDetail'),\n        duration: 5000\n      })\n    },\n    reportError,\n    undefined,\n    [createReauthenticationRecovery<[string], void>()]\n  )\n\n  return {\n    logout,\n    sendPasswordReset,\n    purchaseCredits,\n    purchaseCreditsDirect,\n    canPurchaseCredits,\n    accessBillingPortal,\n    accessBillingPortalDirect,\n    fetchBalance,\n    signInWithGoogle,\n    signInWithGithub,\n    signInWithEmail,\n    signUpWithEmail,\n    updatePassword,\n    accessError,\n    reportError\n  }\n}\n","/**\n * A cancellation, card change, or payment made in a hosted tab never pushes\n * back to this one, so every return to this tab re-reads whatever that tab\n * could have changed. A return is leaving (`blur` or hidden) and coming back\n * (`focus` or visible): the focus and visibility events of one return count\n * once, and a return that lands while a refresh is still in flight gets one\n * trailing refresh, because that read may predate what the hosted tab just\n * did. It stays armed until the returned callback runs. Shared by every\n * opener of a hosted billing tab or window so they arm the same return\n * signal one way.\n */\nexport function registerRefreshOnReturn(\n  refresh: () => Promise<unknown>\n): () => void {\n  let away = true\n  let inFlight = false\n  let trailing = false\n\n  const run = () => {\n    inFlight = true\n    void refresh().finally(() => {\n      inFlight = false\n      if (!trailing) return\n      trailing = false\n      run()\n    })\n  }\n  const onLeave = () => {\n    away = true\n  }\n  const onReturn = () => {\n    if (!away) return\n    away = false\n    if (inFlight) {\n      trailing = true\n      return\n    }\n    run()\n  }\n  const onVisibilityChange = () => {\n    if (document.visibilityState === 'visible') onReturn()\n    else onLeave()\n  }\n\n  document.addEventListener('visibilitychange', onVisibilityChange)\n  window.addEventListener('focus', onReturn)\n  window.addEventListener('blur', onLeave)\n  return () => {\n    document.removeEventListener('visibilitychange', onVisibilityChange)\n    window.removeEventListener('focus', onReturn)\n    window.removeEventListener('blur', onLeave)\n  }\n}\n","import type {\n  BillingClient,\n  BillingPortalTarget,\n  BillingTelemetryFailure\n} from '@comfyorg/account-core/billing'\n\nimport type { TelemetryDispatcher } from '@/platform/telemetry/types'\nimport { describeBillingFailure } from '@/platform/telemetry/utils/billingFailureCategory'\nimport { registerRefreshOnReturn } from '@/platform/workspace/billing/refreshOnReturn'\n\nconst PORTAL_TAB_BLOCKED: BillingTelemetryFailure = {\n  failure_category: 'redirect',\n  error_code: 'payment_popup_blocked'\n}\n\n/** Only the latest portal trip waits for a return, so one return is reported once. */\nlet stopWatchingForReturn: (() => void) | undefined\n\n/** Reports one trip to the provider's portal, which opens in its own tab. */\nexport function createBillingPortalReporter(\n  telemetry: TelemetryDispatcher | null,\n  target: BillingPortalTarget\n) {\n  const client = (billingClient?: BillingClient) =>\n    billingClient ? { billing_client: billingClient } : {}\n\n  function failed(\n    failure: BillingTelemetryFailure,\n    billingClient?: BillingClient\n  ) {\n    telemetry?.trackBillingEvent({\n      operation: 'portal',\n      stage: 'failed',\n      outcome: 'failure',\n      target,\n      ...client(billingClient),\n      ...failure\n    })\n  }\n\n  return {\n    /** Also reports the first return to this tab after the portal opened. */\n    opened(billingClient?: BillingClient) {\n      telemetry?.trackBillingEvent({\n        operation: 'portal',\n        stage: 'opened',\n        outcome: 'pending',\n        target,\n        ...client(billingClient)\n      })\n      stopWatchingForReturn?.()\n      const stopWatching = registerRefreshOnReturn(async () => {\n        stopWatching()\n        telemetry?.trackBillingEvent({\n          operation: 'portal',\n          stage: 'returned',\n          outcome: 'pending',\n          target,\n          ...client(billingClient)\n        })\n      })\n      stopWatchingForReturn = stopWatching\n    },\n    blocked(billingClient?: BillingClient) {\n      failed(PORTAL_TAB_BLOCKED, billingClient)\n    },\n    failed(error: unknown, billingClient?: BillingClient) {\n      failed(describeBillingFailure(error), billingClient)\n    }\n  }\n}\n","import type { BillingResult } from '@comfyorg/account-core/billing'\n\nimport type { WorkspaceApiOperation } from '@/platform/workspace/api/workspaceApi'\nimport { WorkspaceApiError } from '@/platform/workspace/api/workspaceApi'\n\n/**\n * A read on the SDK rail, in the shape the legacy path throws in: the HTTP\n * status rides along when the failure came from a response, so a caller that\n * treats a 401 or 403 as a denial reads it the same on either rail.\n * `operation` names the legacy method the read replaces, so both rails share\n * one Sentry group per endpoint.\n * `SUPERSEDED` is not a failure: the scope moved on under the read, so there\n * is nothing to publish and nothing to report, the same outcome as a stale\n * legacy read.\n */\nexport async function readOnRail<T>(\n  read: () => Promise<BillingResult<T>>,\n  operation: WorkspaceApiOperation\n): Promise<T | undefined> {\n  const result = await read()\n  if (result.status === 'ok') return result.value\n  if (result.code === 'SUPERSEDED') return undefined\n  throw new WorkspaceApiError(\n    result.code,\n    result.httpStatus,\n    result.code,\n    undefined,\n    operation\n  )\n}\n","/**\n * The contracts the billing core shares with its hosts. Dependency-neutral\n * by design, the same way `sessionContracts` is: the transport and the typed\n * operations depend on this module, never back on each other.\n *\n * Billing reports failures as coded results rather than thrown errors. The\n * codes carry no text; the copy that belongs to each code is owned by the\n * billing core and localized by the host. Two server values cross this\n * boundary. `serverCode` is a machine identifier and never copy: a command\n * matches it against its own closed set, and a host stores it where it\n * already keeps `WorkspaceApiError.code`. Its brand makes it unforgeable:\n * only the response decoder mints one, and `unwrapServerCode` names the one\n * sanctioned widening. `serverMessage` is the sentence the server wrote for\n * the customer, carried so a host can show it the way the legacy client does;\n * nothing in the core branches on it.\n */\nimport type { SessionClient } from '../session.js'\n\n/**\n * The session members the billing core reaches for. A host's client is typed\n * for its own user, and the identity seam is contravariant in that user, so\n * requiring the full client would reject every host whose user is more\n * specific than the base.\n */\nexport type BillingSession = Pick<\n  SessionClient,\n  'getSnapshot' | 'subscribe' | 'ensureFresh' | 'remint'\n>\n\n/**\n * The failure buckets a billing request can produce, extracted from what the\n * cloud app's `workspaceApi` callers actually distinguish today.\n * REQUEST_FAILED is the transient bucket: 5xx, a network failure, an abort,\n * and a timeout are one failure for a caller, exactly as they are in the\n * session client's `TOKEN_EXCHANGE_FAILED`.\n */\nexport type BillingErrorCode =\n  /** Nobody is signed in, or the identity could not produce a token. */\n  | 'NOT_AUTHENTICATED'\n  /** A 401 that survived the one re-mint retry, or a 403. */\n  | 'ACCESS_DENIED'\n  | 'NOT_FOUND'\n  /** A business-level 409 — never a missing customer, which self-heals. */\n  | 'CONFLICT'\n  /** The identity or workspace changed while the request was in flight. */\n  | 'SUPERSEDED'\n  | 'REQUEST_FAILED'\n  /** A 2xx whose body does not match the generated contract. */\n  | 'MALFORMED_RESPONSE'\n  /**\n   * The server already had an operation of this kind pending that this\n   * attempt did not issue. Refusing is the only honest answer: the status\n   * response names no plan, so joining it would settle whatever the earlier\n   * attempt chose and report it as this caller's success. The command\n   * usually declines before it sends anything; a subscription command also\n   * reports it when the server refuses with `SUBSCRIPTION_CHANGE_IN_PROGRESS`.\n   */\n  | 'OPERATION_ALREADY_PENDING'\n\ndeclare const billingServerCodeBrand: unique symbol\n\n/**\n * An unbounded server string that is only ever a machine identifier. Nothing\n * outside `readBillingErrorCode` mints one, so a command cannot invent a code\n * to match. The value stays a `string` underneath: `matchesServerCode` and\n * `unwrapServerCode` name the sanctioned uses rather than making the string\n * unreadable.\n */\nexport type BillingServerCode = string & {\n  readonly [billingServerCodeBrand]: true\n}\n\nexport type BillingFailure = {\n  readonly status: 'error'\n  readonly code: BillingErrorCode\n  /** Set only when the failure came from an HTTP response. */\n  readonly httpStatus?: number\n  /**\n   * The coded `code` of a generated `ErrorResponse` body, when the server\n   * sent one. It is the only server value a command branches on. Compare it\n   * through `matchesServerCode`, and widen it through `unwrapServerCode` at\n   * a host's error-store boundary. Never render it.\n   */\n  readonly serverCode?: BillingServerCode\n  /**\n   * The `message` of that same `ErrorResponse`, present when the server sent\n   * a non-empty one. This is what a host shows the customer; the legacy\n   * client shows the same string.\n   */\n  readonly serverMessage?: string\n}\n\n/** Whether a failure carries the server code a command names. */\nexport function matchesServerCode(\n  failure: Pick<BillingFailure, 'serverCode'>,\n  code: string\n): boolean {\n  return failure.serverCode === code\n}\n\n/**\n * The one widening back to `string`, for a host storing the code beside the\n * codes it already keeps. Rendering it is still a contract violation.\n */\nexport function unwrapServerCode(code: BillingServerCode): string {\n  return code\n}\n\nexport type BillingResult<T> =\n  | { readonly status: 'ok'; readonly value: T }\n  | BillingFailure\n\ninterface BillingRequestBase {\n  /** Route below the host's billing base, e.g. `/billing/topup`. */\n  readonly route: string\n  /**\n   * Present on a write whose replay the backend deduplicates. It is also\n   * what makes a 401 retry safe: see `createSessionBillingTransport`.\n   */\n  readonly idempotencyKey?: string\n  readonly signal?: AbortSignal\n  /** Total budget for session minting, retries, and reading the response. */\n  readonly timeoutMs?: number\n}\n\nexport type BillingRequest = BillingRequestBase &\n  (\n    | { readonly method: 'GET'; readonly body?: never }\n    | { readonly method: 'POST'; readonly body?: unknown }\n  )\n\nexport interface BillingHttpResponse {\n  readonly httpStatus: number\n  readonly body: unknown\n  /** True when a 401 could not be retried because the write was not replayable. */\n  readonly authenticationRetrySkipped?: true\n  /**\n   * True when the transport holds no credential of its own to re-prove with,\n   * so a 401 is the host's session ending rather than a refusal.\n   */\n  readonly authenticationNotRenewable?: true\n  /**\n   * Response header reader. The capability revision a mutation reports\n   * (`X-Capability-Revision`) reaches the capabilities cache through this,\n   * mirroring the cloud app's `attachCapabilityRevisionInterceptor`. It is\n   * absent whenever CORS is bypassed, so every reader treats a missing\n   * header as \"no revision reported\" rather than assuming presence.\n   */\n  readonly header: (name: string) => string | null\n}\n\n/**\n * One request, credentials included. An HTTP answer of any status is an `ok`\n * result — only a failure that produced no response at all (no session,\n * network, abort, timeout) is an `error`, so the typed operations above it\n * own the status-to-code mapping in one place.\n */\nexport type BillingTransport = (\n  request: BillingRequest\n) => Promise<BillingResult<BillingHttpResponse>>\n","/**\n * What every billing transport does identically, regardless of how the\n * request is credentialed: hold one timeout budget over the whole exchange,\n * send the request, and shape any answer into a `BillingHttpResponse`.\n *\n * Only the credential differs between transports, so only the credential\n * lives in them; keeping the budget and the response shaping here is what\n * lets a bearer-token host and a cookie host report the same failures.\n */\nimport type {\n  BillingHttpResponse,\n  BillingRequest,\n  BillingResult\n} from './billingContracts.js'\n\nexport const DEFAULT_BILLING_TIMEOUT_MS = 30_000\n\nexport function startRequestBudget(\n  callerSignal: AbortSignal | undefined,\n  timeoutMs: number\n) {\n  const controller = new AbortController()\n  const abort = () => controller.abort()\n  if (callerSignal?.aborted === true) {\n    controller.abort()\n  } else {\n    callerSignal?.addEventListener('abort', abort, { once: true })\n  }\n  const timeout = setTimeout(abort, timeoutMs)\n  return {\n    signal: controller.signal,\n    close: () => {\n      clearTimeout(timeout)\n      callerSignal?.removeEventListener('abort', abort)\n    }\n  }\n}\n\nexport interface BillingExchange {\n  readonly fetchImpl: typeof fetch\n  readonly url: string\n  readonly signal: AbortSignal\n  /** Merged over the headers the request itself implies. */\n  readonly headers?: Record<string, string>\n  readonly credentials?: RequestCredentials\n}\n\nexport async function exchangeBillingRequest(\n  request: BillingRequest,\n  exchange: BillingExchange\n): Promise<BillingResult<BillingHttpResponse>> {\n  // Called detached: the browser's fetch refuses any receiver but its global.\n  const { fetchImpl, url, signal, headers, credentials } = exchange\n  let response: Response\n  try {\n    response = await fetchImpl(url, {\n      method: request.method,\n      headers: {\n        'Content-Type': 'application/json',\n        ...(request.idempotencyKey === undefined\n          ? {}\n          : { 'Idempotency-Key': request.idempotencyKey }),\n        ...headers\n      },\n      ...(request.method === 'GET' || request.body === undefined\n        ? {}\n        : { body: JSON.stringify(request.body) }),\n      ...(credentials === undefined ? {} : { credentials }),\n      signal\n    })\n  } catch {\n    return { status: 'error', code: 'REQUEST_FAILED' }\n  }\n\n  return shapeResponse(response, signal)\n}\n\nasync function shapeResponse(\n  response: Response,\n  signal: AbortSignal\n): Promise<BillingResult<BillingHttpResponse>> {\n  const header = (name: string) => response.headers.get(name)\n  try {\n    return {\n      status: 'ok',\n      value: {\n        httpStatus: response.status,\n        body: await readBody(response),\n        header\n      }\n    }\n  } catch {\n    if (signal.aborted) {\n      return { status: 'error', code: 'REQUEST_FAILED' }\n    }\n    return {\n      status: 'ok',\n      value: { httpStatus: response.status, body: undefined, header }\n    }\n  }\n}\n\n/** A body that is absent, empty, or not JSON reaches callers as undefined. */\nasync function readBody(response: Response): Promise<unknown> {\n  const text = await response.text()\n  if (text === '') return undefined\n  try {\n    return JSON.parse(text)\n  } catch {\n    return undefined\n  }\n}\n","/**\n * The billing transport: one request carrying the workspace session, with the\n * reactive 401 guard the cloud app installs on its billing axios client\n * (`attachUnifiedRemintInterceptor` in\n * src/platform/auth/unified/remintRetry.ts) — re-mint once, retry once, and\n * surface a persistent 401 unchanged. Keep the two in step.\n *\n * Two deliberate differences from that interceptor. It gates the retry on a\n * replayable body; here the gate is an idempotency key, because a billing\n * write that the backend does not deduplicate must never be replayed by the\n * client even when its body is replayable. And scope comes from the minted\n * credential rather than a request header: the workspace a request runs\n * against is the workspace its JWT was minted for, and a response that\n * arrives after the host moved to another workspace (or signed out) is\n * reported as SUPERSEDED instead of being handed to a caller that would\n * attribute it to the wrong account.\n */\nimport type { SessionRequestOptions } from '../session.js'\nimport type {\n  AccountCredential,\n  SessionErrorCode,\n  SessionFailure\n} from '../sessionContracts.js'\nimport type {\n  BillingErrorCode,\n  BillingFailure,\n  BillingHttpResponse,\n  BillingRequest,\n  BillingResult,\n  BillingSession,\n  BillingTransport\n} from './billingContracts.js'\nimport {\n  DEFAULT_BILLING_TIMEOUT_MS,\n  exchangeBillingRequest,\n  startRequestBudget\n} from './transportExchange.js'\n\nexport interface SessionBillingTransportOptions {\n  readonly session: BillingSession\n  /**\n   * Resolves a route to an absolute URL. The cloud app's own resolver\n   * (`workspaceApiUrl`) differs per distribution, so the host owns it.\n   */\n  readonly resolveUrl: (route: string) => string\n  /** The workspace to mint for; absent resolves the personal workspace. */\n  readonly workspaceId?: () => string | undefined\n  readonly fetchImpl?: typeof fetch\n  readonly defaultTimeoutMs?: number\n}\n\nfunction codeForSessionFailure(code: SessionErrorCode): BillingErrorCode {\n  if (code === 'ACCESS_DENIED' || code === 'SSO_REQUIRED') {\n    return 'ACCESS_DENIED'\n  }\n  if (code === 'WORKSPACE_NOT_FOUND') return 'NOT_FOUND'\n  if (code === 'NOT_AUTHENTICATED' || code === 'INVALID_FIREBASE_TOKEN') {\n    return 'NOT_AUTHENTICATED'\n  }\n  return 'REQUEST_FAILED'\n}\n\nfunction billingFailureForSession(failure: SessionFailure): BillingFailure {\n  return {\n    status: 'error',\n    code: codeForSessionFailure(failure.code),\n    ...(failure.httpStatus === undefined\n      ? {}\n      : { httpStatus: failure.httpStatus })\n  }\n}\n\nexport function createSessionBillingTransport(\n  options: SessionBillingTransportOptions\n): BillingTransport {\n  const {\n    session,\n    resolveUrl,\n    workspaceId,\n    fetchImpl = fetch,\n    defaultTimeoutMs = DEFAULT_BILLING_TIMEOUT_MS\n  } = options\n\n  /**\n   * The identity and workspace a response is allowed to be attributed to.\n   * A snapshot still minting or not yet settled is no evidence of a change,\n   * so only a delivered sign-out or a different uid or workspace supersedes.\n   */\n  const superseded = (uid: string, workspace: string): boolean => {\n    const snapshot = session.getSnapshot()\n    if (snapshot.phase === 'signed-out') return true\n    if (snapshot.user !== null && snapshot.user.uid !== uid) return true\n    return (\n      snapshot.session !== undefined &&\n      snapshot.session.workspace.id !== workspace\n    )\n  }\n\n  async function ensureBillingSession(\n    mintOptions: SessionRequestOptions\n  ): Promise<BillingResult<AccountCredential>> {\n    const minted = await session.ensureFresh(undefined, mintOptions)\n    if (minted === undefined) {\n      return { status: 'error', code: 'NOT_AUTHENTICATED' }\n    }\n    if (minted.status === 'error') return billingFailureForSession(minted)\n    return { status: 'ok', value: minted.session }\n  }\n\n  function send(\n    request: BillingRequest,\n    token: string,\n    signal: AbortSignal\n  ): Promise<BillingResult<BillingHttpResponse>> {\n    return exchangeBillingRequest(request, {\n      fetchImpl,\n      url: resolveUrl(request.route),\n      signal,\n      headers: { Authorization: `Bearer ${token}` }\n    })\n  }\n\n  async function retryUnauthorized(\n    request: BillingRequest,\n    response: BillingHttpResponse,\n    mintOptions: SessionRequestOptions & { readonly signal: AbortSignal },\n    expectedUid: string,\n    expectedWorkspace: string\n  ): Promise<BillingResult<BillingHttpResponse>> {\n    if (response.httpStatus !== 401) return { status: 'ok', value: response }\n\n    const replayable =\n      request.method === 'GET' || request.idempotencyKey !== undefined\n    if (!replayable) {\n      return {\n        status: 'ok',\n        value: { ...response, authenticationRetrySkipped: true }\n      }\n    }\n\n    const reminted = await session.remint(undefined, mintOptions)\n    if (reminted?.status !== 'ok') return { status: 'ok', value: response }\n    if (\n      reminted.session.uid !== expectedUid ||\n      reminted.session.workspace.id !== expectedWorkspace\n    ) {\n      return { status: 'error', code: 'SUPERSEDED' }\n    }\n    return send(request, reminted.session.token, mintOptions.signal)\n  }\n\n  return async function transport(\n    request: BillingRequest\n  ): Promise<BillingResult<BillingHttpResponse>> {\n    const timeoutMs = request.timeoutMs ?? defaultTimeoutMs\n    const budget = startRequestBudget(request.signal, timeoutMs)\n    const target = workspaceId?.()\n    const mintOptions = {\n      signal: budget.signal,\n      timeoutMs,\n      ...(target === undefined ? {} : { workspaceId: target })\n    }\n\n    try {\n      const minted = await ensureBillingSession(mintOptions)\n      if (minted.status === 'error') return minted\n\n      const { uid } = minted.value\n      const workspace = minted.value.workspace.id\n      const firstAttempt = await send(\n        request,\n        minted.value.token,\n        budget.signal\n      )\n      if (firstAttempt.status === 'error') return firstAttempt\n\n      const finalAttempt = await retryUnauthorized(\n        request,\n        firstAttempt.value,\n        mintOptions,\n        uid,\n        workspace\n      )\n      if (finalAttempt.status === 'error') return finalAttempt\n\n      if (superseded(uid, workspace)) {\n        return { status: 'error', code: 'SUPERSEDED' }\n      }\n\n      return finalAttempt\n    } catch {\n      return { status: 'error', code: 'REQUEST_FAILED' }\n    } finally {\n      budget.close()\n    }\n  }\n}\n","/**\n * The scope port: the one thing the billing core needs to know about the\n * identity it runs as — which user, which workspace, which role — and when\n * that changes. A host that holds a browser session client adapts it with\n * `sessionBillingScopeSource`; a host whose credentials live on its own\n * server reads the scope out of its bootstrap payload instead, and never\n * hands the core a session client it does not have.\n */\nimport type { BillingSession } from './billingContracts.js'\nimport type { AccountCredential } from '../sessionContracts.js'\n\nexport interface BillingScope {\n  readonly userId: string\n  readonly workspaceId: string\n  readonly role: AccountCredential['role']\n}\n\nexport interface BillingScopeContext {\n  readonly scope: BillingScope\n  readonly generation: number\n}\n\nexport interface BillingScopeTracker {\n  capture: () => BillingScopeContext | undefined\n  isCurrent: (context: BillingScopeContext) => boolean\n  dispose: () => void\n}\n\n/**\n * Where the core learns its scope. `getScope` is undefined whenever no scope\n * is established — signed out, or not settled yet — and `subscribe` reports\n * that anything about it may have changed.\n */\nexport interface BillingScopeSource {\n  readonly getScope: () => BillingScope | undefined\n  readonly subscribe: (listener: () => void) => () => void\n}\n\nexport function sameBillingScope(a: BillingScope, b: BillingScope): boolean {\n  return (\n    a.userId === b.userId &&\n    a.workspaceId === b.workspaceId &&\n    a.role === b.role\n  )\n}\n\ntype BillingScopeSession = Pick<BillingSession, 'getSnapshot' | 'subscribe'>\n\n/** The scope a workspace session client is currently minted for. */\nexport function sessionBillingScopeSource(\n  session: BillingScopeSession\n): BillingScopeSource {\n  return {\n    getScope: () => readSessionScope(session),\n    subscribe: (listener) => session.subscribe(listener)\n  }\n}\n\nexport function createBillingScopeTracker(\n  source: BillingScopeSource,\n  onChange: () => void\n): BillingScopeTracker {\n  let scope = source.getScope()\n  let generation = 0\n\n  const unsubscribe = source.subscribe(() => {\n    const next = source.getScope()\n    if (\n      (scope === undefined && next === undefined) ||\n      (scope !== undefined &&\n        next !== undefined &&\n        sameBillingScope(scope, next))\n    ) {\n      return\n    }\n\n    scope = next\n    generation++\n    onChange()\n  })\n\n  return {\n    capture: () => (scope === undefined ? undefined : { scope, generation }),\n    isCurrent: (context) =>\n      context.generation === generation &&\n      scope !== undefined &&\n      sameBillingScope(context.scope, scope),\n    dispose: unsubscribe\n  }\n}\n\nfunction readSessionScope(\n  session: BillingScopeSession\n): BillingScope | undefined {\n  const state = session.getSnapshot()\n  if (state.user === null || state.session === undefined) return undefined\n  return {\n    userId: state.user.uid,\n    workspaceId: state.session.workspace.id,\n    role: state.session.role\n  }\n}\n","import { zErrorResponse } from '@comfyorg/ingest-types/zod'\n\nimport type { BillingServerCode } from './billingContracts.js'\n\n/**\n * The `code` of a generated `ErrorResponse` body, or nothing. This decode is\n * the only place a `BillingServerCode` is minted, and the brand it carries is\n * erased at runtime.\n */\nexport function readBillingErrorCode(\n  body: unknown\n): BillingServerCode | undefined {\n  const parsed = zErrorResponse.safeParse(body)\n  return parsed.success ? (parsed.data.code as BillingServerCode) : undefined\n}\n\n/**\n * The `message` of a generated `ErrorResponse` body, or nothing when the body\n * is not that contract or the message is blank.\n */\nexport function readBillingErrorMessage(body: unknown): string | undefined {\n  const parsed = zErrorResponse.safeParse(body)\n  if (!parsed.success) return undefined\n  const message = parsed.data.message.trim()\n  return message === '' ? undefined : message\n}\n","/**\n * Why a capability resolved false, decoded from the capabilities read.\n *\n * The server's contract runs one way only, and every reader here depends on\n * it: a reason is present only alongside `capabilities.<key> === false`, so\n * presence implies refusal — but absence implies nothing at all. A capability\n * with no reason may be granted, may be refused by a billing-api that predates\n * the field, or may be refused for a reason the server declined to forward.\n * `capabilities` stays the only authority for what a client may offer; these\n * keys only ever choose the wording for a refusal already decided there.\n */\nimport { z } from 'zod'\n\n/**\n * The policy branches the server names, plus the bucket this module adds for\n * a value it does not recognize. `not_a_member` is unreachable through the\n * ingest endpoint — a non-member is answered 403 before capabilities resolve —\n * and is carried anyway because the billing-api endpoint can still emit it.\n */\nexport type CapabilityDenialReason =\n  | 'not_a_member'\n  | 'not_workspace_owner'\n  | 'tier_not_self_serve'\n  /** A subscription row reserved before payment that never began. */\n  | 'subscription_not_started'\n  /** The subscription already has a successor scheduled at a billing boundary. */\n  | 'subscription_change_in_progress'\n  /** The server has no guidance for the row — distinct from a deliberate refusal. */\n  | 'subscription_status_unrecognized'\n  /**\n   * A reason outside the set above. Kept as a reason rather than dropped so a\n   * refusal the server explained still reads as explained; the copy it maps to\n   * is the generic one.\n   */\n  | 'unspecified'\n\nconst KNOWN_REASONS: ReadonlySet<string> = new Set<CapabilityDenialReason>([\n  'not_a_member',\n  'not_workspace_owner',\n  'tier_not_self_serve',\n  'subscription_not_started',\n  'subscription_change_in_progress',\n  'subscription_status_unrecognized'\n])\n\n/**\n * Only `can_subscribe_self_serve` carries a reason today. The record is open\n * because the server adds keys as policy grows, and a client that rejected an\n * unknown key would fail the whole read over a field it does not use.\n */\nexport type CapabilityDenials = Readonly<\n  Partial<Record<string, CapabilityDenialReason>>\n>\n\n/**\n * Deliberately lenient: values are read as plain strings and narrowed here,\n * never as a generated enum. A strict enum parse would make the entire\n * capabilities read malformed the first time the server names a policy branch\n * this client predates — turning a copy detail into a total loss of the\n * capability set, which is the one part of the response that gates UI.\n *\n * This mirrors what the ingest service already does on its own side, where an\n * unrecognized reason is dropped rather than forwarded.\n */\nconst DeniedReasonsSchema = z.record(z.string(), z.string()).optional()\n\nexport function decodeCapabilityDenials(raw: unknown): CapabilityDenials {\n  const parsed = DeniedReasonsSchema.safeParse(raw)\n  if (!parsed.success || parsed.data === undefined) return {}\n\n  const denials: Record<string, CapabilityDenialReason> = {}\n  for (const [capability, reason] of Object.entries(parsed.data)) {\n    denials[capability] = KNOWN_REASONS.has(reason)\n      ? (reason as CapabilityDenialReason)\n      : 'unspecified'\n  }\n  return denials\n}\n","/**\n * The one place a billing HTTP status becomes a code. The transport\n * deliberately returns an answer of any status as `ok`, so that every typed\n * operation maps status the same way instead of each inventing its own.\n */\nimport type {\n  BillingErrorCode,\n  BillingHttpResponse\n} from './billingContracts.js'\n\nexport function codeForHttpStatus(\n  response: Pick<\n    BillingHttpResponse,\n    'httpStatus' | 'authenticationRetrySkipped' | 'authenticationNotRenewable'\n  >\n): BillingErrorCode {\n  const status = response.httpStatus\n  // A 401 the transport re-minted and retried is a real refusal. One it had\n  // to leave alone, because the write was not replayable, says only that the\n  // token had gone stale; the caller's next attempt mints a fresh one, so it\n  // joins the transient bucket rather than reading as a permanent denial.\n  if (status === 401 && response.authenticationRetrySkipped) {\n    return 'REQUEST_FAILED'\n  }\n  // A 401 on a transport that never minted anything proves nothing about\n  // permission: the host's credential expired, and signing in again is the\n  // only recovery. ACCESS_DENIED is the one code that tells a user not to try.\n  if (status === 401 && response.authenticationNotRenewable) {\n    return 'NOT_AUTHENTICATED'\n  }\n  if (status === 401 || status === 403) return 'ACCESS_DENIED'\n  if (status === 404) return 'NOT_FOUND'\n  if (status === 409) return 'CONFLICT'\n  // 5xx joins the transient bucket with the network failures the transport\n  // already reports there: one retryable failure for a caller, not several.\n  return 'REQUEST_FAILED'\n}\n","/**\n * Joining a caller to a shared in-flight read without letting either one\n * decide the other's fate.\n *\n * Deduplication and cancellation pull in opposite directions: if the request\n * carries the first caller's signal, that caller aborting fails every reader\n * that joined it, and a joiner aborting does nothing at all. So the shared\n * request carries no caller signal — it is bounded by its own timeout — and\n * each caller's signal releases only that caller's wait.\n *\n * This is the semantic `SessionClient.ensureFresh` already documents for its\n * shared mint: concurrent callers share one request, and a later caller's\n * signal releases that caller with a transient failure without cancelling the\n * work the others are still waiting on.\n */\nimport type {\n  BillingRequest,\n  BillingResult,\n  BillingTransport\n} from './billingContracts.js'\nimport type { BillingScopeContext } from './billingScope.js'\nimport { sameBillingScope } from './billingScope.js'\nimport {\n  readBillingErrorCode,\n  readBillingErrorMessage\n} from './billingErrorBody.js'\nimport { codeForHttpStatus } from './httpStatus.js'\n\n/**\n * An abandoned wait is transient, the same bucket the transport reports an\n * abort under: the caller stopped waiting, which says nothing about whether\n * the read would have succeeded.\n */\nconst ABANDONED = {\n  status: 'error',\n  code: 'REQUEST_FAILED'\n} as const satisfies BillingResult<never>\n\nexport type ParsedBillingBody<T> =\n  | { readonly success: true; readonly data: T }\n  | { readonly success: false }\n\nexport interface ValidatedBillingResponse<T> {\n  readonly data: T\n  readonly body: unknown\n  readonly httpStatus: number\n}\n\nexport function matchesScopedRead<\n  T extends { readonly context: BillingScopeContext }\n>(read: T | undefined, context: BillingScopeContext): read is T {\n  return (\n    read !== undefined &&\n    read.context.generation === context.generation &&\n    sameBillingScope(read.context.scope, context.scope)\n  )\n}\n\nexport async function readValidatedBillingResponse<T>(\n  transport: BillingTransport,\n  request: BillingRequest,\n  parse: (body: unknown) => ParsedBillingBody<T>\n): Promise<BillingResult<ValidatedBillingResponse<T>>> {\n  const response = await transport(request)\n  if (response.status === 'error') return response\n\n  const { httpStatus, body } = response.value\n  if (httpStatus < 200 || httpStatus >= 300) {\n    const serverCode = readBillingErrorCode(body)\n    const serverMessage = readBillingErrorMessage(body)\n    return {\n      status: 'error',\n      code: codeForHttpStatus(response.value),\n      httpStatus,\n      ...(serverCode === undefined ? {} : { serverCode }),\n      ...(serverMessage === undefined ? {} : { serverMessage })\n    }\n  }\n\n  const parsed = parse(body)\n  if (!parsed.success) {\n    return { status: 'error', code: 'MALFORMED_RESPONSE', httpStatus }\n  }\n\n  return { status: 'ok', value: { data: parsed.data, body, httpStatus } }\n}\n\nexport function releaseOnAbort<T>(\n  shared: Promise<BillingResult<T>>,\n  signal: AbortSignal | undefined\n): Promise<BillingResult<T>> {\n  if (signal === undefined) return shared.catch(() => ABANDONED)\n  // An 'abort' listener never fires for a signal that is already aborted, so\n  // a caller who cancelled before joining would otherwise wait for the full\n  // shared read.\n  if (signal.aborted) {\n    void shared.catch(() => {})\n    return Promise.resolve(ABANDONED)\n  }\n\n  return new Promise<BillingResult<T>>((resolve) => {\n    const onAbort = () => resolve(ABANDONED)\n    signal.addEventListener('abort', onAbort, { once: true })\n    shared.then(\n      (value) => {\n        signal.removeEventListener('abort', onAbort)\n        resolve(value)\n      },\n      () => {\n        signal.removeEventListener('abort', onAbort)\n        resolve(ABANDONED)\n      }\n    )\n  })\n}\n","/**\n * The one shape every billing read has: capture the scope, issue a validated\n * request, and refuse to attribute the answer to a scope that has since taken\n * over. Only the route, the decoder, and the projection into a snapshot differ\n * between reads, so only those live in the readers.\n *\n * What the skeleton owns is what a reader therefore cannot get wrong on its\n * own: one shared request per scope and route, a caller's signal releasing\n * only that caller, the publish fence that reports a late answer as\n * `SUPERSEDED`, and the denial that drops a published snapshot unless it\n * predates a change the host reported.\n */\nimport type {\n  BillingRequest,\n  BillingResult,\n  BillingTransport\n} from './billingContracts.js'\nimport type {\n  BillingScope,\n  BillingScopeContext,\n  BillingScopeSource\n} from './billingScope.js'\nimport { createBillingScopeTracker } from './billingScope.js'\nimport type {\n  ParsedBillingBody,\n  ValidatedBillingResponse\n} from './sharedRead.js'\nimport {\n  matchesScopedRead,\n  readValidatedBillingResponse,\n  releaseOnAbort\n} from './sharedRead.js'\n\n/** Every reader's read options carry at least the caller's release signal. */\nexport interface ScopedReadOptions {\n  readonly signal?: AbortSignal\n}\n\nexport interface ScopedReaderDefinition<\n  TData,\n  TSnapshot,\n  TOptions extends ScopedReadOptions\n> {\n  readonly transport: BillingTransport\n  /** Where the core learns which user, workspace, and role it runs as. */\n  readonly scopeSource: BillingScopeSource\n  /**\n   * The route to request, as a function for a read whose query varies per\n   * call. The resolved route joins the scope in identifying an in-flight\n   * read, so two callers asking for different pages each get their own answer\n   * rather than the first one's.\n   */\n  readonly route: string | ((options: TOptions | undefined) => string)\n  readonly parse: (body: unknown) => ParsedBillingBody<TData>\n  /**\n   * The reader's own reading of a validated response. Returning a failure is\n   * how a reader refuses an answer its decoder alone cannot reject.\n   */\n  readonly project: (\n    response: ValidatedBillingResponse<TData>,\n    scope: BillingScope\n  ) => BillingResult<TSnapshot>\n  /** The request budget, for a read that bounds itself or lets its caller. */\n  readonly timeoutMs?: (options: TOptions | undefined) => number | undefined\n  /**\n   * The published snapshot this call may be served from instead of asking.\n   * Absent for a reader that always requests.\n   */\n  readonly cached?: (\n    snapshot: TSnapshot | undefined,\n    scope: BillingScope,\n    options: TOptions | undefined\n  ) => TSnapshot | undefined\n  /**\n   * What to publish once the read settles in scope, given whether the host\n   * fenced the request while it was in flight. `undefined` publishes nothing,\n   * and the callers waiting on the request are still served what it read.\n   */\n  readonly publish?: (\n    value: TSnapshot,\n    fenced: boolean\n  ) => TSnapshot | undefined\n}\n\nexport interface ScopedReader<TSnapshot, TOptions extends ScopedReadOptions> {\n  readonly read: (options?: TOptions) => Promise<BillingResult<TSnapshot>>\n  readonly getSnapshot: () => TSnapshot | undefined\n  /** Replaces what `getSnapshot` publishes; `undefined` drops it. */\n  readonly setSnapshot: (snapshot: TSnapshot | undefined) => void\n  /**\n   * Marks a request already in flight as predating a change the host is\n   * reporting, leaving `publish` to decide what its answer is still worth.\n   * `detach` also frees the shared slot, so the read that follows issues its\n   * own request rather than joining the one that predates the change.\n   */\n  readonly fenceInFlight: (options?: { readonly detach?: boolean }) => void\n  readonly dispose: () => void\n}\n\ninterface InFlightRead<TSnapshot> {\n  readonly context: BillingScopeContext\n  readonly route: string\n  readonly promise: Promise<BillingResult<TSnapshot>>\n  /**\n   * Lives outside the attempt so the read body can consult it without\n   * referencing the object that holds its own promise.\n   */\n  readonly pending: { fenced: boolean }\n}\n\nfunction publishAsRead<TSnapshot>(value: TSnapshot): TSnapshot {\n  return value\n}\n\nexport function createScopedReader<\n  TData,\n  TSnapshot,\n  TOptions extends ScopedReadOptions\n>(\n  definition: ScopedReaderDefinition<TData, TSnapshot, TOptions>\n): ScopedReader<TSnapshot, TOptions> {\n  const {\n    transport,\n    scopeSource,\n    route,\n    parse,\n    project,\n    timeoutMs,\n    cached,\n    publish = publishAsRead\n  } = definition\n\n  const resolveRoute: (options: TOptions | undefined) => string =\n    typeof route === 'string' ? () => route : route\n\n  let snapshot: TSnapshot | undefined\n  let inFlight: InFlightRead<TSnapshot> | undefined\n  const lifetime = { disposed: false }\n  const scopeTracker = createBillingScopeTracker(scopeSource, () => {\n    snapshot = undefined\n    inFlight = undefined\n  })\n\n  async function request(\n    scope: BillingScope,\n    options: TOptions | undefined,\n    resolvedRoute: string\n  ): Promise<BillingResult<TSnapshot>> {\n    const budget = timeoutMs?.(options)\n    const billingRequest: BillingRequest = {\n      method: 'GET',\n      route: resolvedRoute,\n      ...(budget === undefined ? {} : { timeoutMs: budget })\n    }\n    const response = await readValidatedBillingResponse(\n      transport,\n      billingRequest,\n      parse\n    )\n    if (response.status === 'error') return response\n\n    return project(response.value, scope)\n  }\n\n  function publishSettled(\n    value: TSnapshot,\n    fenced: boolean\n  ): BillingResult<TSnapshot> {\n    const published = publish(value, fenced)\n    if (published !== undefined) snapshot = published\n    return { status: 'ok', value: published ?? value }\n  }\n\n  async function settle(\n    context: BillingScopeContext,\n    pending: { fenced: boolean },\n    options: TOptions | undefined,\n    resolvedRoute: string\n  ): Promise<BillingResult<TSnapshot>> {\n    const result = await request(context.scope, options, resolvedRoute)\n    // The publish guard. Between issuing the request and settling it the host\n    // may have changed workspace or signed out, so an answer cached now would\n    // be attributed to whoever is signed in next, and a failure says nothing\n    // about the scope that has since taken over.\n    if (lifetime.disposed || !scopeTracker.isCurrent(context)) {\n      return { status: 'error', code: 'SUPERSEDED' }\n    }\n\n    if (result.status !== 'ok') {\n      // A denial that predates a fence is no evidence about what a later read\n      // published, and clearing on it would drop a fresh answer for a stale\n      // refusal.\n      if (result.code === 'ACCESS_DENIED' && !pending.fenced) {\n        snapshot = undefined\n      }\n      return result\n    }\n\n    return publishSettled(result.value, pending.fenced)\n  }\n\n  async function read(options?: TOptions): Promise<BillingResult<TSnapshot>> {\n    if (lifetime.disposed) return { status: 'error', code: 'SUPERSEDED' }\n\n    const context = scopeTracker.capture()\n    if (context === undefined) {\n      return { status: 'error', code: 'NOT_AUTHENTICATED' }\n    }\n\n    const served = cached?.(snapshot, context.scope, options)\n    if (served !== undefined) return { status: 'ok', value: served }\n\n    // Resolved once, then used both to issue the request and to identify it,\n    // so the answer a joining caller is served is the one its own route asked\n    // for.\n    const resolvedRoute = resolveRoute(options)\n\n    // A caller arriving mid-flight joins only a read of the same scope and\n    // route, rather than issuing a second identical request. A caller for a\n    // different scope starts its own, and the older one can no longer\n    // publish. A caller for a different route on the same scope also starts\n    // its own and takes the slot, so the displaced read still settles and\n    // publishes — the snapshot carries which page it is — but nobody can join\n    // it any more. One slot is enough for a feed read one page at a time.\n    if (\n      matchesScopedRead(inFlight, context) &&\n      inFlight.route === resolvedRoute\n    ) {\n      return releaseOnAbort(inFlight.promise, options?.signal)\n    }\n\n    // No caller signal reaches the shared request: it is bounded by its own\n    // timeout, and one caller walking away must not fail the readers still\n    // waiting on it. Each caller's signal releases only that caller, below.\n    const pending = { fenced: false }\n    const attempt: InFlightRead<TSnapshot> = {\n      context,\n      route: resolvedRoute,\n      promise: settle(context, pending, options, resolvedRoute),\n      pending\n    }\n\n    inFlight = attempt\n    // The slot is released when the request settles, not when this caller\n    // stops waiting, so an abandoned read still serves whoever joined it.\n    const release = () => {\n      if (inFlight === attempt) inFlight = undefined\n    }\n    attempt.promise.then(release, release)\n\n    return releaseOnAbort(attempt.promise, options?.signal)\n  }\n\n  return {\n    read,\n    getSnapshot: () => snapshot,\n    setSnapshot: (next) => {\n      snapshot = next\n    },\n    fenceInFlight: (fenceOptions) => {\n      if (inFlight === undefined) return\n      inFlight.pending.fenced = true\n      if (fenceOptions?.detach === true) inFlight = undefined\n    },\n    dispose: () => {\n      lifetime.disposed = true\n      snapshot = undefined\n      inFlight = undefined\n      scopeTracker.dispose()\n    }\n  }\n}\n","/**\n * The capabilities read: a server-authoritative answer to \"what may this actor\n * be offered for this workspace\", cached per scope.\n *\n * The SDK never derives a capability. It decodes what the server resolved and\n * caches it under the scope it was resolved for, so no entitlement rule is\n * reimplemented here and none can drift from the backend's.\n *\n * Freshness is pull-based on purpose: a snapshot carries the instant it stops\n * being fresh, and a caller learns it is stale by asking. The production\n * composable's timer, its visibility gating, and its retry backoff are all\n * push concerns that need a document and a scheduler, so they belong to the\n * view package that has both — not to a framework-free core.\n */\nimport {\n  zBillingCapabilities,\n  zBillingCapabilityRolloutDefaults,\n  zBillingCapabilityScope\n} from '@comfyorg/ingest-types/zod'\nimport { z } from 'zod'\n\nimport type { BillingResult, BillingTransport } from './billingContracts.js'\nimport type { BillingScope, BillingScopeSource } from './billingScope.js'\nimport { sameBillingScope } from './billingScope.js'\nimport type { CapabilityDenials } from './capabilityDenials.js'\nimport { decodeCapabilityDenials } from './capabilityDenials.js'\nimport { createScopedReader } from './scopedReader.js'\nimport type { ValidatedBillingResponse } from './sharedRead.js'\n\nexport const CAPABILITIES_ROUTE = '/billing/capabilities'\n\n/** Production's own budget for this read (`workspaceApi.getBillingCapabilities`). */\nconst CAPABILITIES_TIMEOUT_MS = 10_000\n\n/**\n * A remaining lifetime below the floor means the client clock disagrees with\n * the server's, so `expires_at` cannot pace anything and the fixed interval is\n * used instead. The ceiling bounds the opposite skew, where a lagging clock\n * reads `expires_at` as far in the future. Both bounds, and the fallback, are\n * the production composable's.\n */\nconst MIN_FRESH_MS = 5_000\nconst MAX_FRESH_MS = 60 * 60 * 1000\nconst FALLBACK_FRESH_MS = 60_000\n\nexport const CAPABILITY_REVISION_HEADER = 'X-Capability-Revision'\n\nexport type BillingCapabilities = z.infer<typeof zBillingCapabilities>\nexport type CapabilityRolloutDefaults = z.infer<\n  typeof zBillingCapabilityRolloutDefaults\n>\n\n/**\n * The generated contract minus `denied_reasons`, which is decoded separately\n * and leniently. `revision` is read as a number rather than the generated\n * bigint: the server bounds it to the JavaScript-safe range precisely so\n * clients can compare it as one.\n */\nconst CapabilitiesBodySchema = z.object({\n  capabilities: zBillingCapabilities,\n  expires_at: z.string(),\n  resolved_for: zBillingCapabilityScope,\n  revision: z.number(),\n  rollout_defaults_applied: zBillingCapabilityRolloutDefaults\n})\n\ntype CapabilitiesBody = z.infer<typeof CapabilitiesBodySchema>\n\nexport type CapabilityScope = BillingScope\n\nexport interface CapabilitiesSnapshot {\n  readonly capabilities: BillingCapabilities\n  /**\n   * Present only for a capability the server refused and explained. An absent\n   * key never implies the capability was granted — read `capabilities`.\n   */\n  readonly denials: CapabilityDenials\n  /** True values are rollout guidance, not evidence a write will succeed. */\n  readonly rolloutDefaultsApplied: CapabilityRolloutDefaults\n  readonly revision: number\n  readonly scope: CapabilityScope\n  /** ms since epoch, after which `read` refetches rather than serving this. */\n  readonly freshUntil: number\n}\n\nexport interface CapabilitiesReadOptions {\n  readonly signal?: AbortSignal\n  /** Bypasses a fresh cached snapshot; still joins an in-flight read. */\n  readonly forceRefresh?: boolean\n}\n\nexport interface CapabilitiesReader {\n  read: (\n    options?: CapabilitiesReadOptions\n  ) => Promise<BillingResult<CapabilitiesSnapshot>>\n  /** The cached snapshot for the current scope, fresh or not. */\n  getSnapshot: () => CapabilitiesSnapshot | undefined\n  /**\n   * Marks the cache stale for a revision a **mutation** reported. A read's own\n   * revision must never be fed back here: the capabilities response echoes the\n   * header it was built with, so republishing it would mark that read stale and\n   * refetch forever.\n   */\n  invalidate: (revision?: number) => void\n  /** Detaches the scope subscription. */\n  dispose: () => void\n}\n\nexport interface CapabilitiesReaderOptions {\n  readonly transport: BillingTransport\n  /** Where the core learns which user, workspace, and role it runs as. */\n  readonly scopeSource: BillingScopeSource\n  readonly now?: () => number\n}\n\n/**\n * Reads the revision a mutation reported. Absent whenever CORS is bypassed\n * (local desktop origins), so a missing header is \"nothing reported\" rather\n * than a reason to invalidate.\n */\nexport function readCapabilityRevision(\n  header: (name: string) => string | null\n): number | undefined {\n  const raw = header(CAPABILITY_REVISION_HEADER)\n  if (raw === null) return undefined\n  const revision = Number(raw)\n  return Number.isSafeInteger(revision) && revision > 0 ? revision : undefined\n}\n\nfunction freshUntilFrom(expiresAt: string, now: number): number {\n  // Date.parse yields NaN on an unparseable value; NaN fails the comparison\n  // and lands on the fixed interval, which is the intended branch.\n  const remaining = Date.parse(expiresAt) - now\n  if (remaining >= MIN_FRESH_MS) {\n    return now + Math.min(remaining, MAX_FRESH_MS)\n  }\n  return now + FALLBACK_FRESH_MS\n}\n\nfunction freshSnapshot(\n  snapshot: CapabilitiesSnapshot | undefined,\n  scope: CapabilityScope,\n  forceRefresh: boolean,\n  now: number\n): CapabilitiesSnapshot | undefined {\n  if (forceRefresh || snapshot === undefined) return undefined\n  if (!sameBillingScope(snapshot.scope, scope)) return undefined\n  return snapshot.freshUntil > now ? snapshot : undefined\n}\n\nfunction snapshotAfterInvalidation(\n  snapshot: CapabilitiesSnapshot,\n  invalidated: boolean\n): CapabilitiesSnapshot {\n  return invalidated ? { ...snapshot, freshUntil: 0 } : snapshot\n}\n\nexport function createCapabilitiesReader(\n  options: CapabilitiesReaderOptions\n): CapabilitiesReader {\n  const { transport, scopeSource, now = Date.now } = options\n\n  function projectCapabilities(\n    response: ValidatedBillingResponse<CapabilitiesBody>,\n    scope: CapabilityScope\n  ): BillingResult<CapabilitiesSnapshot> {\n    const { data, body, httpStatus } = response\n\n    // Capabilities resolve per (user, workspace), so both halves have to\n    // match. Checking only the workspace would accept another member's answer\n    // for the workspace the caller is in and publish it as the caller's own —\n    // an actor with fewer or greater rights deciding what this one is offered.\n    // Either mismatch is a contract violation rather than an answer about this\n    // scope, so it joins the transient bucket instead of being cached. The\n    // ingest service makes the same two-part check against its own upstream\n    // before it forwards a response.\n    const resolved = data.resolved_for\n    if (\n      resolved.user_id !== scope.userId ||\n      resolved.workspace_id !== scope.workspaceId\n    ) {\n      return { status: 'error', code: 'REQUEST_FAILED', httpStatus }\n    }\n\n    const denials = decodeCapabilityDenials(\n      (body as { denied_reasons?: unknown }).denied_reasons\n    )\n\n    return {\n      status: 'ok',\n      value: {\n        capabilities: data.capabilities,\n        denials,\n        rolloutDefaultsApplied: data.rollout_defaults_applied,\n        revision: data.revision,\n        scope,\n        freshUntil: freshUntilFrom(data.expires_at, now())\n      }\n    }\n  }\n\n  const reader = createScopedReader<\n    CapabilitiesBody,\n    CapabilitiesSnapshot,\n    CapabilitiesReadOptions\n  >({\n    transport,\n    scopeSource,\n    route: CAPABILITIES_ROUTE,\n    parse: (body) => CapabilitiesBodySchema.safeParse(body),\n    timeoutMs: () => CAPABILITIES_TIMEOUT_MS,\n    cached: (snapshot, scope, readOptions) =>\n      freshSnapshot(snapshot, scope, readOptions?.forceRefresh === true, now()),\n    project: projectCapabilities,\n    // A mutation committed while this read was in flight, and the revision the\n    // read returns cannot rule out having missed it: the server mints that\n    // number when it serializes, not when it read. The value is still the best\n    // available, so it is published — as already stale, so the next read\n    // refetches instead of serving it.\n    publish: snapshotAfterInvalidation\n  })\n\n  return {\n    read: reader.read,\n    getSnapshot: reader.getSnapshot,\n    invalidate: (revision?: number) => {\n      reader.fenceInFlight()\n      const snapshot = reader.getSnapshot()\n      if (snapshot === undefined) return\n      if (revision !== undefined && snapshot.revision === revision) return\n      reader.setSnapshot({ ...snapshot, freshUntil: 0 })\n    },\n    dispose: reader.dispose\n  }\n}\n","/**\n * The credits read: a workspace's balance, cached per scope.\n *\n * Balances are reported in micros and kept that way. Converting to a display\n * unit here would bake one currency's minor-unit assumption into the core and\n * lose precision before the host ever sees the number; formatting belongs to\n * the view layer, which has the locale.\n */\nimport { zBillingBalanceResponse } from '@comfyorg/ingest-types/zod'\nimport type { z } from 'zod'\n\nimport type { BillingResult, BillingTransport } from './billingContracts.js'\nimport type { BillingScope, BillingScopeSource } from './billingScope.js'\nimport { createScopedReader } from './scopedReader.js'\n\nexport const CREDITS_ROUTE = '/billing/balance'\n\nexport type BillingBalance = z.infer<typeof zBillingBalanceResponse>\n\nexport type CreditsScope = BillingScope\n\nexport interface CreditsSnapshot {\n  readonly balance: BillingBalance\n  readonly scope: CreditsScope\n  /** ms since epoch at which this read settled. */\n  readonly readAt: number\n}\n\nexport interface CreditsReadOptions {\n  readonly signal?: AbortSignal\n}\n\nexport interface CreditsReader {\n  /**\n   * Always requests. A balance has no server-declared lifetime and moves on\n   * every run, so there is no interval over which serving a cached one is\n   * correct; the cache exists to survive a failure, not to skip a read.\n   * Concurrent callers for one scope still share a single request.\n   */\n  read: (\n    options?: CreditsReadOptions\n  ) => Promise<BillingResult<CreditsSnapshot>>\n  /** The last balance published for the current scope. */\n  getSnapshot: () => CreditsSnapshot | undefined\n  dispose: () => void\n}\n\nexport interface CreditsReaderOptions {\n  readonly transport: BillingTransport\n  /** Where the core learns which user, workspace, and role it runs as. */\n  readonly scopeSource: BillingScopeSource\n  readonly now?: () => number\n}\n\nexport function createCreditsReader(\n  options: CreditsReaderOptions\n): CreditsReader {\n  const { transport, scopeSource, now = Date.now } = options\n\n  const reader = createScopedReader<\n    BillingBalance,\n    CreditsSnapshot,\n    CreditsReadOptions\n  >({\n    transport,\n    scopeSource,\n    route: CREDITS_ROUTE,\n    parse: (body) => zBillingBalanceResponse.safeParse(body),\n    project: ({ data }, scope) => ({\n      status: 'ok',\n      value: { balance: data, scope, readAt: now() }\n    })\n  })\n\n  return {\n    read: reader.read,\n    getSnapshot: reader.getSnapshot,\n    dispose: reader.dispose\n  }\n}\n","/**\n * The billing events read: one page of the workspace's history feed, the\n * charges, credits and adjustments behind the usage log.\n *\n * It is the only billing read whose request varies per call, so the page it\n * asks for is part of what identifies the read: two callers on different\n * pages each get their own answer rather than sharing the first one's. The\n * snapshot reports the page the server says it served, not the one that was\n * asked for, because the endpoint clamps a page past the end.\n */\nimport { zGetBillingEventsResponse } from '@comfyorg/ingest-types/zod'\nimport type { z } from 'zod'\n\nimport type { BillingResult, BillingTransport } from './billingContracts.js'\nimport type { BillingScope, BillingScopeSource } from './billingScope.js'\nimport { createScopedReader } from './scopedReader.js'\n\nexport const BILLING_EVENTS_ROUTE = '/billing/events'\n\nexport type BillingEventsData = z.infer<typeof zGetBillingEventsResponse>\nexport type BillingEvent = BillingEventsData['events'][number]\n\nexport type BillingEventsScope = BillingScope\n\nexport interface BillingEventsSnapshot {\n  readonly events: readonly BillingEvent[]\n  /** 1-indexed, as the endpoint counts. */\n  readonly page: number\n  readonly limit: number\n  readonly total: number\n  readonly totalPages: number\n  readonly scope: BillingEventsScope\n  readonly readAt: number\n}\n\nexport interface BillingEventsReadOptions {\n  readonly signal?: AbortSignal\n  /** 1-indexed; the endpoint's own default applies when omitted. */\n  readonly page?: number\n  readonly limit?: number\n}\n\nexport interface BillingEventsReader {\n  read: (\n    options?: BillingEventsReadOptions\n  ) => Promise<BillingResult<BillingEventsSnapshot>>\n  /** The last page read for the current scope; it carries which page it is. */\n  getSnapshot: () => BillingEventsSnapshot | undefined\n  dispose: () => void\n}\n\nexport interface BillingEventsReaderOptions {\n  readonly transport: BillingTransport\n  /** Where the core learns which user, workspace, and role it runs as. */\n  readonly scopeSource: BillingScopeSource\n  readonly now?: () => number\n}\n\n/** Stable key order, so the same page asked for twice is the same request. */\nfunction billingEventsRoute(\n  options: BillingEventsReadOptions | undefined\n): string {\n  const query = new URLSearchParams()\n  if (options?.page !== undefined) query.set('page', String(options.page))\n  if (options?.limit !== undefined) query.set('limit', String(options.limit))\n  const search = query.toString()\n  return search === ''\n    ? BILLING_EVENTS_ROUTE\n    : `${BILLING_EVENTS_ROUTE}?${search}`\n}\n\nexport function createBillingEventsReader(\n  options: BillingEventsReaderOptions\n): BillingEventsReader {\n  const { transport, scopeSource, now = Date.now } = options\n\n  const reader = createScopedReader<\n    BillingEventsData,\n    BillingEventsSnapshot,\n    BillingEventsReadOptions\n  >({\n    transport,\n    scopeSource,\n    route: billingEventsRoute,\n    parse: (body) => zGetBillingEventsResponse.safeParse(body),\n    project: ({ data }, scope) => ({\n      status: 'ok',\n      value: { ...data, scope, readAt: now() }\n    })\n  })\n\n  return {\n    read: reader.read,\n    getSnapshot: reader.getSnapshot,\n    dispose: reader.dispose\n  }\n}\n","/**\n * The plans read: the catalog a workspace may subscribe to, cached per scope.\n *\n * Availability, seat costs, and the credit-stop ladder are all resolved by the\n * server for the actor that asked, so the response is cached under the scope it\n * was resolved for and no plan is filtered, ranked, or priced here.\n */\nimport { zGetBillingPlansResponse } from '@comfyorg/ingest-types/zod'\nimport type { z } from 'zod'\n\nimport type { BillingResult, BillingTransport } from './billingContracts.js'\nimport type { BillingScope, BillingScopeSource } from './billingScope.js'\nimport { createScopedReader } from './scopedReader.js'\n\nexport const PLANS_ROUTE = '/billing/plans'\n\nexport type BillingPlansData = z.infer<typeof zGetBillingPlansResponse>\n\nexport type PlansScope = BillingScope\n\nexport interface PlansSnapshot {\n  readonly scope: PlansScope\n  readonly data: BillingPlansData\n  /** ms since epoch at which this read settled. */\n  readonly readAt: number\n}\n\nexport interface PlansReadOptions {\n  readonly signal?: AbortSignal\n  /** Bounds the request, when this caller is the one that issues it. */\n  readonly timeoutMs?: number\n}\n\nexport interface PlansReader {\n  /**\n   * Always requests. The catalog changes rarely, but nothing in the response\n   * declares how long it stays valid, so the host decides when to re-read\n   * rather than the core inventing a freshness window nobody published.\n   * Concurrent callers for one scope still share a single request.\n   */\n  read: (options?: PlansReadOptions) => Promise<BillingResult<PlansSnapshot>>\n  /** The last catalog published for the current scope. */\n  getSnapshot: () => PlansSnapshot | undefined\n  dispose: () => void\n}\n\nexport interface PlansReaderOptions {\n  readonly transport: BillingTransport\n  /** Where the core learns which user, workspace, and role it runs as. */\n  readonly scopeSource: BillingScopeSource\n  readonly now?: () => number\n}\n\nexport function createPlansReader(options: PlansReaderOptions): PlansReader {\n  const { transport, scopeSource, now = Date.now } = options\n\n  const reader = createScopedReader<\n    BillingPlansData,\n    PlansSnapshot,\n    PlansReadOptions\n  >({\n    transport,\n    scopeSource,\n    route: PLANS_ROUTE,\n    parse: (body) => zGetBillingPlansResponse.safeParse(body),\n    timeoutMs: (readOptions) => readOptions?.timeoutMs,\n    project: ({ data }, scope) => ({\n      status: 'ok',\n      value: { scope, data, readAt: now() }\n    })\n  })\n\n  return {\n    read: reader.read,\n    getSnapshot: reader.getSnapshot,\n    dispose: reader.dispose\n  }\n}\n","/**\n * The saved payment methods read: the cards a workspace can charge, cached per\n * scope.\n *\n * Card details never reach this core beyond what the server already publishes —\n * brand, last four digits, and which one is the default — so nothing here has\n * to be redacted before a host renders it.\n */\nimport { zListSavedPaymentMethodsResponse } from '@comfyorg/ingest-types/zod'\nimport type { zSavedPaymentMethod } from '@comfyorg/ingest-types/zod'\nimport type { z } from 'zod'\n\nimport type { BillingResult, BillingTransport } from './billingContracts.js'\nimport type { BillingScope, BillingScopeSource } from './billingScope.js'\nimport { createScopedReader } from './scopedReader.js'\n\nexport const PAYMENT_METHODS_ROUTE = '/billing/payment-methods'\n\nexport type SavedPaymentMethod = z.infer<typeof zSavedPaymentMethod>\n\nexport type PaymentMethodsScope = BillingScope\n\nexport interface PaymentMethodsSnapshot {\n  readonly scope: PaymentMethodsScope\n  readonly methods: readonly SavedPaymentMethod[]\n  /** ms since epoch at which this read settled. */\n  readonly readAt: number\n}\n\nexport interface PaymentMethodsReadOptions {\n  readonly signal?: AbortSignal\n  /** Bounds the request, when this caller is the one that issues it. */\n  readonly timeoutMs?: number\n}\n\nexport interface PaymentMethodsReader {\n  /**\n   * Always requests. Concurrent callers for one scope share a single request.\n   */\n  read: (\n    options?: PaymentMethodsReadOptions\n  ) => Promise<BillingResult<PaymentMethodsSnapshot>>\n  /** The last list published for the current scope. */\n  getSnapshot: () => PaymentMethodsSnapshot | undefined\n  /**\n   * Drops the published list without a scope change. A payment-portal round\n   * trip adds or removes a card outside this reader, so the host that sent the\n   * user there is the only thing that knows the list it holds is now wrong.\n   */\n  invalidate: () => void\n  dispose: () => void\n}\n\nexport interface PaymentMethodsReaderOptions {\n  readonly transport: BillingTransport\n  /** Where the core learns which user, workspace, and role it runs as. */\n  readonly scopeSource: BillingScopeSource\n  readonly now?: () => number\n}\n\nexport function createPaymentMethodsReader(\n  options: PaymentMethodsReaderOptions\n): PaymentMethodsReader {\n  const { transport, scopeSource, now = Date.now } = options\n\n  const reader = createScopedReader<\n    readonly SavedPaymentMethod[],\n    PaymentMethodsSnapshot,\n    PaymentMethodsReadOptions\n  >({\n    transport,\n    scopeSource,\n    route: PAYMENT_METHODS_ROUTE,\n    parse: (body) => zListSavedPaymentMethodsResponse.safeParse(body),\n    timeoutMs: (readOptions) => readOptions?.timeoutMs,\n    project: ({ data }, scope) => ({\n      status: 'ok',\n      value: { scope, methods: data, readAt: now() }\n    }),\n    // A list resolved before the change the host is reporting may be served to\n    // the callers already waiting on it, but must not be published.\n    publish: (value, fenced) => (fenced ? undefined : value)\n  })\n\n  return {\n    read: reader.read,\n    getSnapshot: reader.getSnapshot,\n    invalidate: () => {\n      reader.setSnapshot(undefined)\n      reader.fenceInFlight({ detach: true })\n    },\n    dispose: reader.dispose\n  }\n}\n","import { zBillingStatusResponse } from '@comfyorg/ingest-types/zod'\nimport type { z } from 'zod'\n\nimport type { BillingResult, BillingTransport } from './billingContracts.js'\nimport type { BillingScope, BillingScopeSource } from './billingScope.js'\nimport { createScopedReader } from './scopedReader.js'\n\nexport const BILLING_STATUS_ROUTE = '/billing/status'\n\nexport type BillingStatusData = z.infer<typeof zBillingStatusResponse>\n\nexport type BillingStatusScope = BillingScope\n\nexport interface BillingStatusSnapshot {\n  readonly status: BillingStatusData\n  readonly scope: BillingStatusScope\n  readonly readAt: number\n}\n\nexport interface BillingStatusReadOptions {\n  readonly signal?: AbortSignal\n}\n\nexport interface BillingStatusReader {\n  read: (\n    options?: BillingStatusReadOptions\n  ) => Promise<BillingResult<BillingStatusSnapshot>>\n  getSnapshot: () => BillingStatusSnapshot | undefined\n  dispose: () => void\n}\n\nexport interface BillingStatusReaderOptions {\n  readonly transport: BillingTransport\n  /** Where the core learns which user, workspace, and role it runs as. */\n  readonly scopeSource: BillingScopeSource\n  readonly now?: () => number\n}\n\nexport function createBillingStatusReader(\n  options: BillingStatusReaderOptions\n): BillingStatusReader {\n  const { transport, scopeSource, now = Date.now } = options\n\n  const reader = createScopedReader<\n    BillingStatusData,\n    BillingStatusSnapshot,\n    BillingStatusReadOptions\n  >({\n    transport,\n    scopeSource,\n    route: BILLING_STATUS_ROUTE,\n    parse: (body) => zBillingStatusResponse.safeParse(body),\n    project: ({ data }, scope) => ({\n      status: 'ok',\n      value: { status: data, scope, readAt: now() }\n    })\n  })\n\n  return {\n    read: reader.read,\n    getSnapshot: reader.getSnapshot,\n    dispose: reader.dispose\n  }\n}\n","import { z } from 'zod'\n\n/**\n * The generated schemas coerce every int64 to a `bigint`, which no caller can\n * add to a price or hand to a currency formatter, while the generated *type*\n * for the same field is a `number`. Billing amounts and credit counts sit well\n * inside the JavaScript-safe range, so they are read as safe integers.\n */\nexport const wireCents = z.number().int().safe()\n","import { zSubscriptionDiscount } from '@comfyorg/ingest-types/zod'\n\nimport { wireCents } from './wireCents.js'\n\nexport const SubscriptionDiscountSchema = zSubscriptionDiscount.extend({\n  amount_off_cents: wireCents.optional(),\n  duration_in_months: wireCents.optional()\n})\n","/**\n * One billing operation as the SDK sees it: a discriminated union over the\n * lifecycle a `billing_op_id` moves through, and the pure transition that\n * advances it. The identity is fixed at adoption and survives every\n * presentation change, so switching a checkout from the embedded challenge\n * to the hosted page (or back) is a transition on the same operation, never\n * a replacement one.\n *\n * The transition consumes the generated `BillingOpStatusResponse`. It reads\n * the coded `decline_reason` and `recovery_action` and never `error_message`,\n * so no server or payment-provider text can reach a consumer through this\n * state.\n */\nimport {\n  zBillingOpChargeBreakdown,\n  zBillingOpChargeReason,\n  zBillingOpReceiptPlan,\n  zBillingOpStatusResponse\n} from '@comfyorg/ingest-types/zod'\nimport { z } from 'zod'\n\nimport type { BillingScope } from './billingScope.js'\nimport { SubscriptionDiscountSchema } from './subscriptionDiscount.js'\nimport { wireCents } from './wireCents.js'\n\nconst ChargeBreakdownSchema = zBillingOpChargeBreakdown.extend({\n  amount_charged_cents: wireCents,\n  reasons: z.array(\n    zBillingOpChargeReason.extend({\n      amount_cents: wireCents,\n      discount: SubscriptionDiscountSchema.optional()\n    })\n  )\n})\n\nconst ReceiptPlanSchema = zBillingOpReceiptPlan.extend({\n  price_cents: wireCents.optional(),\n  monthly_price_cents: wireCents.optional()\n})\n\nexport const BillingOpStatusSchema = zBillingOpStatusResponse.extend({\n  amount_charged_cents: wireCents.optional(),\n  credits_added: wireCents.optional(),\n  charge_breakdown: ChargeBreakdownSchema.optional(),\n  plan: ReceiptPlanSchema.optional()\n})\n\nexport type BillingOpStatus = z.infer<typeof BillingOpStatusSchema>\n\nexport type BillingChargeBreakdown = NonNullable<\n  BillingOpStatus['charge_breakdown']\n>\nexport type BillingChargeReason = BillingChargeBreakdown['reasons'][number]\n\nexport type BillingOperationKind = 'subscription' | 'topup' | 'cancel'\n\n/**\n * The plan the server reports an operation is for, in every status of a plan\n * change, initial subscription or resubscribe. Its tier and prices are absent\n * when the server cannot describe the plan.\n */\nexport type BillingOperationPlan = NonNullable<BillingOpStatus['plan']>\n\n/**\n * Where the customer completes the operation: the challenge this tab drives\n * through the host's payment-provider adapter, or the page behind the\n * server's `action_url`.\n */\nexport type BillingPresentation = 'embedded' | 'hosted'\n\n/**\n * Which origin serves a hosted presentation: the provider page behind the\n * server's `action_url`, or the hosted billing app.\n */\nexport type HostedBillingDestination = 'stripe' | 'billing_web'\n\nexport type BillingDeclineReason = NonNullable<\n  BillingOpStatus['decline_reason']\n>\nexport type BillingRecoveryAction = NonNullable<\n  BillingOpStatus['recovery_action']\n>\nexport type BillingAuthenticationState = NonNullable<\n  BillingOpStatus['authentication_state']\n>\nexport type BillingOperationServerPhase = NonNullable<BillingOpStatus['phase']>\n\n/**\n * The phases the contract defines as blocked on the customer. Neither advances\n * on its own, so an operation reporting one waits on them even before it has a\n * link to offer.\n */\nexport function isBlockedOnCustomerPhase(\n  phase: BillingOperationServerPhase | null | undefined\n): boolean {\n  return (\n    phase === 'awaiting_payment_method' || phase === 'awaiting_invoice_payment'\n  )\n}\n\nexport type BillingPresentationState =\n  | { readonly presentation: 'embedded'; readonly hostedDestination?: never }\n  | {\n      readonly presentation: 'hosted'\n      readonly hostedDestination: HostedBillingDestination\n    }\n\nexport type BillingOperationIdentity = BillingPresentationState & {\n  readonly id: string\n  readonly kind: BillingOperationKind\n  readonly scope: BillingScope\n  /** When this tab began observing the operation; the poll budget counts from here. */\n  readonly observedAt: number\n  /** When the attempt began, before the command was issued; telemetry durations count from here. */\n  readonly attemptStartedAt: number\n  /**\n   * This tab issued the operation and was still waiting on its outcome when\n   * it adopted it: from its own command, or after a reload or a return from\n   * a provider page. Absent for an operation another tab issued, and for one\n   * this tab already saw succeed.\n   */\n  readonly awaitedHere?: true\n}\n\n/**\n * The in-page challenge for an embedded presentation. `completed` and\n * `failed` are this tab's verdicts and outrank a server echo of the same\n * challenge, so the presentation neither flaps back to \"verify\" after a\n * failure nor reopens the pay step mid-payment after a success.\n */\nexport interface EmbeddedChallenge {\n  readonly clientSecret: string\n  readonly status: 'required' | 'in_progress' | 'completed' | 'failed'\n}\n\nexport type PendingBillingOperation = BillingOperationIdentity & {\n  readonly phase: 'pending'\n  /** The hosted continuation the server currently offers; https only. */\n  readonly actionUrl?: string\n  readonly challenge?: EmbeddedChallenge\n  readonly authenticationState?: BillingAuthenticationState\n  readonly serverPhase?: BillingOperationServerPhase\n  /** Set while the customer's last attempt was declined and they may try again. */\n  readonly declineReason?: BillingDeclineReason\n  readonly recoveryAction?: BillingRecoveryAction\n  /** The server's word on whether cancelling this operation would take effect; absent is no claim. */\n  readonly cancelable?: boolean\n  /** True once the operation has ever waited on the customer; widens the poll budget. */\n  readonly customerActionSeen: boolean\n  readonly plan?: BillingOperationPlan\n}\n\nexport type FailedBillingOperation = BillingOperationIdentity & {\n  readonly phase: 'failed'\n  readonly declineReason: BillingDeclineReason\n  readonly recoveryAction?: BillingRecoveryAction\n  readonly retryable: boolean\n}\n\n/**\n * What the server reports a succeeded operation did, for display only. Each\n * fact is absent while the server cannot say it: a charge billed outside a\n * Stripe invoice, a grant not recorded yet, or an operation that is not a\n * plan change.\n */\nexport interface BillingOperationReceipt {\n  readonly amountChargedCents?: number\n  readonly chargeBreakdown?: BillingChargeBreakdown\n  readonly creditsAdded?: number\n  readonly plan?: BillingOperationPlan\n}\n\nexport type SucceededBillingOperation = BillingOperationIdentity & {\n  readonly phase: 'succeeded'\n  readonly receipt?: BillingOperationReceipt\n}\n\nexport type BillingOperationState =\n  | PendingBillingOperation\n  | SucceededBillingOperation\n  | FailedBillingOperation\n  /** This tab's poll budget ran out; the server may still settle the operation. */\n  | (BillingOperationIdentity & { readonly phase: 'timed_out' })\n  /** The server cannot settle it without a human; surface the id to support. */\n  | (BillingOperationIdentity & { readonly phase: 'reconciliation_needed' })\n  /**\n   * The session or workspace changed underneath it, or the server replaced it\n   * with a newer operation; nothing here may be attributed to this tab now.\n   */\n  | (BillingOperationIdentity & { readonly phase: 'superseded' })\n\nexport type BillingOperationPhase = BillingOperationState['phase']\n\nexport type BillingOperationEvent =\n  | { readonly type: 'status_polled'; readonly status: BillingOpStatus }\n  | { readonly type: 'timed_out' }\n  | { readonly type: 'superseded' }\n  /** The operation could not be found under this scope. */\n  | { readonly type: 'lost' }\n  | {\n      readonly type: 'presentation_switched'\n      readonly presentation: 'hosted'\n      readonly hostedDestination: HostedBillingDestination\n    }\n  | {\n      readonly type: 'presentation_switched'\n      readonly presentation: 'embedded'\n    }\n  | { readonly type: 'challenge_started' }\n  /** The server answered a resubmit with a fresh hosted step for this same operation. */\n  | { readonly type: 'action_reissued'; readonly actionUrl: string }\n  | {\n      readonly type: 'challenge_settled'\n      readonly outcome: 'completed' | 'failed'\n    }\n\nexport function isTerminal(\n  state: BillingOperationState\n): state is Exclude<BillingOperationState, PendingBillingOperation> {\n  return state.phase !== 'pending'\n}\n\n/** A continuation link the SDK will hand to a host: absolute and https, nothing else. */\nexport function validateActionUrl(\n  value: string | undefined\n): string | undefined {\n  if (value === undefined) return undefined\n  try {\n    return new URL(value).protocol === 'https:' ? value : undefined\n  } catch {\n    return undefined\n  }\n}\n\nfunction presentationOf(\n  state: BillingOperationState\n): BillingPresentationState {\n  return state.presentation === 'hosted'\n    ? { presentation: 'hosted', hostedDestination: state.hostedDestination }\n    : { presentation: 'embedded' }\n}\n\nfunction identityOf(state: BillingOperationState): BillingOperationIdentity {\n  return {\n    id: state.id,\n    kind: state.kind,\n    scope: state.scope,\n    observedAt: state.observedAt,\n    attemptStartedAt: state.attemptStartedAt,\n    ...(state.awaitedHere ? { awaitedHere: true } : {}),\n    ...presentationOf(state)\n  }\n}\n\nfunction withPhase<\n  P extends Exclude<BillingOperationPhase, 'pending' | 'failed'>\n>(\n  state: BillingOperationState,\n  phase: P\n): BillingOperationIdentity & { readonly phase: P } {\n  return { ...identityOf(state), phase }\n}\n\n/**\n * The server's `requires_action` is an echo of a challenge this tab already\n * settled when it names the same client secret (or none). The tab's verdict\n * stands until the intent actually moves.\n */\nfunction echoesSettledChallenge(\n  state: PendingBillingOperation,\n  status: BillingOpStatus\n): boolean {\n  const challenge = state.challenge\n  if (challenge === undefined) return false\n  if (status.authentication_state !== 'requires_action') return false\n  if (challenge.status !== 'completed' && challenge.status !== 'failed') {\n    return false\n  }\n  return (\n    status.payment_intent_client_secret === undefined ||\n    status.payment_intent_client_secret === challenge.clientSecret\n  )\n}\n\nfunction nextChallenge(\n  state: PendingBillingOperation,\n  status: BillingOpStatus\n): EmbeddedChallenge | undefined {\n  if (state.presentation !== 'embedded') return state.challenge\n  const secret = status.payment_intent_client_secret\n  if (secret === undefined) return state.challenge\n  if (state.challenge?.clientSecret === secret) return state.challenge\n  if (status.authentication_state !== 'requires_action') return state.challenge\n  return { clientSecret: secret, status: 'required' }\n}\n\nfunction terminalFromStatus(\n  state: PendingBillingOperation,\n  status: BillingOpStatus\n): BillingOperationState | undefined {\n  if (status.status === 'succeeded') return succeeded(state, status)\n  if (status.status === 'failed') {\n    return {\n      ...identityOf(state),\n      phase: 'failed',\n      declineReason: status.decline_reason ?? 'generic',\n      ...(status.recovery_action === undefined\n        ? {}\n        : { recoveryAction: status.recovery_action }),\n      retryable: status.retryable === true\n    }\n  }\n  if (\n    status.status === 'reconciliation_needed' ||\n    status.authentication_state === 'reconciliation_needed'\n  ) {\n    return withPhase(state, 'reconciliation_needed')\n  }\n  return undefined\n}\n\nfunction receiptOf(\n  status: BillingOpStatus\n): BillingOperationReceipt | undefined {\n  const receipt: BillingOperationReceipt = {\n    ...(status.amount_charged_cents === undefined\n      ? {}\n      : { amountChargedCents: status.amount_charged_cents }),\n    ...(status.charge_breakdown === undefined\n      ? {}\n      : { chargeBreakdown: status.charge_breakdown }),\n    ...(status.credits_added === undefined\n      ? {}\n      : { creditsAdded: status.credits_added }),\n    ...(status.plan === undefined ? {} : { plan: status.plan })\n  }\n  return Object.keys(receipt).length === 0 ? undefined : receipt\n}\n\nfunction succeeded(\n  state: BillingOperationState,\n  status: BillingOpStatus\n): SucceededBillingOperation {\n  const receipt = receiptOf(status)\n  return {\n    ...withPhase(state, 'succeeded'),\n    ...(receipt === undefined ? {} : { receipt })\n  }\n}\n\n/**\n * The charge went through and the server has not recorded its credits yet;\n * reading the operation again fills them in.\n */\nexport function isGrantLanding(state: BillingOperationState): boolean {\n  return (\n    state.phase === 'succeeded' &&\n    state.receipt?.amountChargedCents !== undefined &&\n    state.receipt.creditsAdded === undefined\n  )\n}\n\n/**\n * A link echoed while this tab's completed challenge is still processing\n * points at that same challenge; surfacing it would ask the customer to\n * redo a step they just finished. A checkout waiting on a card keeps the\n * link a resubmit reissued, because the server stores none for that phase.\n */\nfunction nextActionUrl(\n  state: PendingBillingOperation,\n  status: BillingOpStatus,\n  authenticationState: BillingAuthenticationState | undefined\n): string | undefined {\n  if (\n    state.challenge?.status === 'completed' &&\n    authenticationState !== 'requires_action'\n  ) {\n    return state.actionUrl\n  }\n  const served = validateActionUrl(status.action_url)\n  return served === undefined && status.phase === 'awaiting_payment_method'\n    ? state.actionUrl\n    : served\n}\n\n/**\n * A retryable failure served without a reason reads as `generic`, as a\n * terminal failure does, so the customer is offered the retry the state\n * promises. A challenge this tab saw fail supplies its own reason.\n */\nfunction nextDeclineReason(\n  state: PendingBillingOperation,\n  status: BillingOpStatus,\n  authenticationState: BillingAuthenticationState | undefined\n): BillingDeclineReason | undefined {\n  if (authenticationState !== 'failed_retryable') return undefined\n  const known = status.decline_reason ?? state.declineReason\n  if (known !== undefined || state.challenge?.status === 'failed') return known\n  return 'generic'\n}\n\nfunction reducePending(\n  state: PendingBillingOperation,\n  status: BillingOpStatus\n): BillingOperationState {\n  if (status.id !== state.id) return state\n  const terminal = terminalFromStatus(state, status)\n  if (terminal !== undefined) return terminal\n\n  const authenticationState = echoesSettledChallenge(state, status)\n    ? state.authenticationState\n    : status.authentication_state\n  const actionUrl = nextActionUrl(state, status, authenticationState)\n  const declineReason = nextDeclineReason(state, status, authenticationState)\n  const { plan: _previousPlan, ...rest } = state\n\n  return {\n    ...rest,\n    ...(status.plan === undefined ? {} : { plan: status.plan }),\n    challenge: nextChallenge(state, status),\n    authenticationState,\n    actionUrl,\n    serverPhase: status.phase,\n    declineReason,\n    recoveryAction: status.recovery_action,\n    cancelable: status.cancelable,\n    customerActionSeen:\n      state.customerActionSeen ||\n      actionUrl !== undefined ||\n      isBlockedOnCustomerPhase(status.phase) ||\n      status.authentication_state === 'requires_action'\n  }\n}\n\nfunction settleChallenge(\n  state: PendingBillingOperation,\n  outcome: 'completed' | 'failed'\n): PendingBillingOperation {\n  if (state.challenge === undefined) return state\n  const challenge = { ...state.challenge, status: outcome }\n  if (outcome === 'failed') {\n    return {\n      ...state,\n      challenge,\n      authenticationState: 'failed_retryable',\n      customerActionSeen: true\n    }\n  }\n  return {\n    ...state,\n    challenge,\n    authenticationState: 'processing',\n    actionUrl: undefined,\n    declineReason: undefined\n  }\n}\n\nexport function reduceBillingOperation(\n  state: BillingOperationState,\n  event: BillingOperationEvent\n): BillingOperationState {\n  if (state.phase !== 'pending') return state\n\n  switch (event.type) {\n    case 'status_polled':\n      return reducePending(state, event.status)\n    case 'timed_out':\n      return withPhase(state, 'timed_out')\n    case 'superseded':\n      return withPhase(state, 'superseded')\n    case 'lost':\n      return withPhase(state, 'reconciliation_needed')\n    case 'presentation_switched': {\n      if (event.presentation === state.presentation) return state\n      // The challenge record survives a hosted switch so a rollback keeps the\n      // client secret; a failed challenge becomes required again on return.\n      const { presentation, hostedDestination, ...rest } = state\n      return event.presentation === 'hosted'\n        ? {\n            ...rest,\n            presentation: 'hosted',\n            hostedDestination: event.hostedDestination\n          }\n        : {\n            ...rest,\n            presentation: 'embedded',\n            ...(state.challenge?.status === 'failed'\n              ? { challenge: { ...state.challenge, status: 'required' } }\n              : {})\n          }\n    }\n    case 'challenge_started':\n      return state.challenge?.status === 'required'\n        ? { ...state, challenge: { ...state.challenge, status: 'in_progress' } }\n        : state\n    case 'challenge_settled':\n      return settleChallenge(state, event.outcome)\n    case 'action_reissued': {\n      const actionUrl = validateActionUrl(event.actionUrl)\n      return actionUrl === undefined\n        ? state\n        : { ...state, actionUrl, customerActionSeen: true }\n    }\n  }\n}\n","/**\n * The cadence and budget for observing one operation, taken from the cloud\n * app's `billingOperationStore` rather than invented, so a consumer moving\n * onto the SDK sees the same request rate and the same give-up points.\n */\nimport { isBlockedOnCustomerPhase } from './operationState.js'\nimport type {\n  BillingAuthenticationState,\n  EmbeddedChallenge,\n  PendingBillingOperation\n} from './operationState.js'\n\nexport const OPERATION_POLL_TIMING = {\n  initialMs: 1_000,\n  maxMs: 8_000,\n  multiplier: 1.5,\n  /** An operation parked on the customer is checked on a slow, flat cadence. */\n  parkedMs: 30_000,\n  /** Fast backoff for an actionless blocked wait: 20 turns of the 3 s PI status cache. */\n  actionDiscoveryMs: 60_000\n} as const\n\nexport const OPERATION_POLL_BUDGET = {\n  defaultMs: 120_000,\n  /** A subscription may take minutes to discover that it needs the customer. */\n  subscriptionDiscoveryMs: 5 * 60_000,\n  /** Once the customer is involved, a bank challenge can idle for hours. */\n  customerActionMs: 23 * 60 * 60_000\n} as const\n\n/**\n * What one tab holds for the customer on a pending operation. Each rail\n * builds it from its own state, because each renders a different surface:\n * the legacy cloud store offers the hosted link beside the embedded\n * challenge, while the SDK renders exactly one presentation.\n */\nexport interface CustomerActionHold {\n  readonly authenticationState?: BillingAuthenticationState | null\n  /** A hosted page this tab would open for the customer. */\n  readonly offersHostedPage: boolean\n  /** The embedded challenge this tab holds, whatever became of it. */\n  readonly challenge?: EmbeddedChallenge['status']\n}\n\n/**\n * The one \"customer can act here\" rule both billing rails park on: a\n * retryable failure to retry, a hosted page to visit, or an embedded\n * challenge the server still says is required. A non-retryable decline never\n * reaches it; the operation is terminal by then.\n */\nexport function customerCanActHere(hold: CustomerActionHold): boolean {\n  if (hold.authenticationState === 'failed_retryable') return true\n  if (hold.offersHostedPage) return true\n  return (\n    hold.authenticationState === 'requires_action' &&\n    (hold.challenge === 'required' || hold.challenge === 'in_progress')\n  )\n}\n\n/**\n * The SDK renders one presentation: a hosted operation offers only its page,\n * an embedded one only its challenge. The cloud app's\n * `legacyOperationActionHold` names the rows where the two surfaces differ.\n */\nexport function pendingOperationActionHold(\n  state: PendingBillingOperation\n): CustomerActionHold {\n  return state.presentation === 'hosted'\n    ? {\n        authenticationState: state.authenticationState,\n        offersHostedPage: state.actionUrl !== undefined\n      }\n    : {\n        authenticationState: state.authenticationState,\n        offersHostedPage: false,\n        challenge: state.challenge?.status\n      }\n}\n\nfunction customerCanAct(state: PendingBillingOperation): boolean {\n  return customerCanActHere(pendingOperationActionHold(state))\n}\n\n/**\n * Waiting on the customer, not on the backend: a challenge to complete\n * elsewhere, a hosted page to finish, a phase the server reports as blocked on\n * them, or a declined attempt awaiting their retry. Once this tab's own\n * challenge completes the state reads processing and nothing waits on the\n * customer anymore.\n */\nfunction isWaitingOnCustomer(state: PendingBillingOperation): boolean {\n  return (\n    state.authenticationState === 'requires_action' ||\n    state.actionUrl !== undefined ||\n    isBlockedOnCustomerPhase(state.serverPhase) ||\n    (state.authenticationState === 'failed_retryable' &&\n      state.customerActionSeen)\n  )\n}\n\n/**\n * Parked only while the customer can act here. The server can report a\n * blocked phase and a client secret before its cached `authentication_state`\n * catches up, and the slow cadence would then hold a screen with no action.\n */\nexport function isParkedOnCustomer(state: PendingBillingOperation): boolean {\n  return customerCanAct(state) && isWaitingOnCustomer(state)\n}\n\n/**\n * Blocked on the customer with nothing to offer them yet: either the action\n * is still on its way, or it belongs to someone else (a member without\n * billing permission, a tab without embedded checkout).\n */\nexport function isWaitingOnCustomerWithoutAction(\n  state: PendingBillingOperation\n): boolean {\n  return !customerCanAct(state) && isWaitingOnCustomer(state)\n}\n\n/**\n * `waitedWithoutActionMs` is how long the operation has continuously been\n * {@link isWaitingOnCustomerWithoutAction}; past the discovery window it\n * parks too, so an action that never arrives here costs the slow cadence.\n */\nexport function nextPollDelayMs(\n  state: PendingBillingOperation,\n  previousDelayMs: number | undefined,\n  waitedWithoutActionMs = 0\n): number {\n  if (state.challenge?.status !== 'failed' && isParkedOnCustomer(state)) {\n    return OPERATION_POLL_TIMING.parkedMs\n  }\n  if (\n    isWaitingOnCustomerWithoutAction(state) &&\n    waitedWithoutActionMs >= OPERATION_POLL_TIMING.actionDiscoveryMs\n  ) {\n    return OPERATION_POLL_TIMING.parkedMs\n  }\n  return Math.min(\n    (previousDelayMs ?? OPERATION_POLL_TIMING.initialMs) *\n      OPERATION_POLL_TIMING.multiplier,\n    OPERATION_POLL_TIMING.maxMs\n  )\n}\n\nexport function pollBudgetMs(state: PendingBillingOperation): number {\n  if (state.kind !== 'cancel' && state.customerActionSeen) {\n    return OPERATION_POLL_BUDGET.customerActionMs\n  }\n  return state.kind === 'subscription'\n    ? OPERATION_POLL_BUDGET.subscriptionDiscoveryMs\n    : OPERATION_POLL_BUDGET.defaultMs\n}\n\nexport function hasExhaustedPollBudget(\n  state: PendingBillingOperation,\n  now: number\n): boolean {\n  return now - state.observedAt > pollBudgetMs(state)\n}\n","/**\n * The tab-local pointer to an operation this tab is observing, so a reload\n * reattaches to the same `billing_op_id` instead of starting a replacement\n * charge. The host supplies the storage (origin-scoped `sessionStorage` in a\n * browser); the SDK owns the key, the shape, and the rule for when the\n * pointer may go.\n *\n * The pointer is keyed by scope, so a workspace switch neither reads nor\n * clears another workspace's operation, and switching back finds it again.\n */\nimport { z } from 'zod'\n\nimport type { BillingScope } from './billingScope.js'\nimport type { BillingOperationState } from './operationState.js'\n\nexport interface BillingOperationPointerStorage {\n  getItem: (key: string) => string | null\n  setItem: (key: string, value: string) => void\n  removeItem: (key: string) => void\n}\n\nconst POINTER_KEY_PREFIX = 'comfy:billing:operation'\n\nexport const OPERATION_POINTER_MAX_AGE_MS = 24 * 60 * 60_000\n\nconst PointerSchema = z.object({\n  operationId: z.string().min(1),\n  kind: z.enum(['subscription', 'topup', 'cancel']),\n  presentation: z.enum(['embedded', 'hosted']),\n  attemptStartedAt: z.number().finite(),\n  /** This tab issued the operation and has not yet seen it succeed. */\n  awaited: z.literal(true).optional(),\n  /** The end this tab saw it reach, kept only by a store that retains settled pointers. */\n  settled: z.enum(['succeeded', 'reconciliation_needed']).optional(),\n  /** The hosted step this page redirected to; the page it returns to reports the return. */\n  redirect: z\n    .object({\n      destination: z.enum(['stripe', 'billing_web']),\n      step: z.enum([\n        'authentication',\n        'payment_method',\n        'invoice_payment',\n        'checkout'\n      ]),\n      method_kind: z.enum(['card', 'alipay', 'other']).optional()\n    })\n    .optional()\n})\n\nexport type BillingOperationPointer = z.infer<typeof PointerSchema>\n\ntype SettledPhase = NonNullable<BillingOperationPointer['settled']>\n\nexport function operationPointerKey(scope: BillingScope): string {\n  return `${POINTER_KEY_PREFIX}:${scope.userId}:${scope.workspaceId}`\n}\n\nexport interface OperationPointerStore {\n  read: (scope: BillingScope) => BillingOperationPointer | undefined\n  write: (scope: BillingScope, pointer: BillingOperationPointer) => void\n  /** Clears only when the stored pointer names `operationId`, or unconditionally without one. */\n  clear: (scope: BillingScope, operationId?: string) => void\n  /**\n   * What the operation's phase does to the pointer naming it. A client-side\n   * timeout is this tab giving up, not the server finishing: an operation\n   * awaiting bank authentication stays pending for hours, so the pointer\n   * outlives it. A superseded operation belongs to a scope this tab left, and\n   * its pointer waits under that scope's key for a return. A failure clears\n   * it, so a reload offers a fresh attempt. A success, or an operation the\n   * server parked for reconciliation, clears it too, unless the store retains\n   * settled pointers.\n   */\n  settle: (state: BillingOperationState) => void\n}\n\nexport interface OperationPointerStoreOptions {\n  /**\n   * Keep a settled pointer, marked with how it ended, so a page that is the\n   * checkout itself can read it back after a reload.\n   */\n  readonly retainSettled?: boolean\n}\n\n/** Storage that throws (private mode, quota) reads as empty and writes as a no-op. */\nfunction attempt<T>(read: () => T, fallback: T): T {\n  try {\n    return read()\n  } catch {\n    return fallback\n  }\n}\n\nfunction decodePointer(\n  raw: string | null,\n  now: number\n): BillingOperationPointer | undefined {\n  if (raw === null) return undefined\n  const parsed = PointerSchema.safeParse(attempt(() => JSON.parse(raw), null))\n  if (!parsed.success) return undefined\n  const age = now - parsed.data.attemptStartedAt\n  return age >= 0 && age <= OPERATION_POINTER_MAX_AGE_MS\n    ? parsed.data\n    : undefined\n}\n\n/** A success is no longer awaited; an operation still being reconciled is. */\nfunction settledPointer(\n  pointer: BillingOperationPointer,\n  phase: SettledPhase\n): BillingOperationPointer {\n  if (phase === 'reconciliation_needed') return { ...pointer, settled: phase }\n  const { awaited: _seen, ...rest } = pointer\n  return { ...rest, settled: phase }\n}\n\nexport function createOperationPointerStore(\n  storage: BillingOperationPointerStorage,\n  now: () => number = Date.now,\n  { retainSettled = false }: OperationPointerStoreOptions = {}\n): OperationPointerStore {\n  const read = (scope: BillingScope) => {\n    const key = operationPointerKey(scope)\n    const pointer = decodePointer(\n      attempt(() => storage.getItem(key), null),\n      now()\n    )\n    if (pointer === undefined) attempt(() => storage.removeItem(key), undefined)\n    return pointer\n  }\n\n  const write = (scope: BillingScope, pointer: BillingOperationPointer) =>\n    attempt(\n      () =>\n        storage.setItem(operationPointerKey(scope), JSON.stringify(pointer)),\n      undefined\n    )\n\n  const clear = (scope: BillingScope, operationId?: string) => {\n    if (operationId !== undefined && read(scope)?.operationId !== operationId) {\n      return\n    }\n    attempt(() => storage.removeItem(operationPointerKey(scope)), undefined)\n  }\n\n  const retain = (state: BillingOperationState, phase: SettledPhase) => {\n    const pointer = read(state.scope)\n    if (pointer?.operationId !== state.id) return\n    write(state.scope, settledPointer(pointer, phase))\n  }\n\n  const settle = (state: BillingOperationState) => {\n    switch (state.phase) {\n      case 'pending':\n      case 'timed_out':\n      case 'superseded':\n        return\n      case 'failed':\n        clear(state.scope, state.id)\n        return\n      case 'succeeded':\n      case 'reconciliation_needed':\n        if (retainSettled) retain(state, state.phase)\n        else clear(state.scope, state.id)\n    }\n  }\n\n  return { read, write, clear, settle }\n}\n\n/** A store for hosts without tab-local storage: nothing is ever recovered. */\nexport const NO_POINTER_STORE: OperationPointerStore = {\n  read: () => undefined,\n  write: () => {},\n  clear: () => {},\n  settle: () => {}\n}\n","/**\n * The one place a billing operation is routed to the embedded challenge or\n * the hosted page. Hosts report whether they can drive an embedded challenge\n * at all; they never choose the route.\n *\n * Every rule fails toward hosted, which works on every rail and needs\n * nothing from the host but a way to open a URL.\n */\nimport type { BillingPresentation } from './operationState.js'\nimport type { BillingStatusData } from './status.js'\n\nexport interface PresentationRoutingInput {\n  /** The host can drive an in-page challenge: its provider adapter and key are present. */\n  readonly embeddedCheckoutAvailable: boolean\n  readonly billingRail: BillingStatusData['billing_rail']\n  /** A hosted continuation the command response already carried. */\n  readonly hostedUrl?: string\n  /** An in-page challenge the command response already carried. */\n  readonly clientSecret?: string\n}\n\nexport function selectBillingPresentation(\n  input: PresentationRoutingInput\n): BillingPresentation {\n  // The backend answered with a page and no challenge: it has decided.\n  if (input.hostedUrl !== undefined && input.clientSecret === undefined) {\n    return 'hosted'\n  }\n  if (!input.embeddedCheckoutAvailable) return 'hosted'\n  // Only the workspace Stripe rail exposes payment intents to the client.\n  return input.billingRail === 'stripe' ? 'embedded' : 'hosted'\n}\n","import type {\n  BillingDeclineReason,\n  BillingOperationState,\n  EmbeddedChallenge,\n  PendingBillingOperation\n} from './operationState.js'\n\nexport type PaymentFrictionSignal =\n  | { readonly stage: 'challenge_required' }\n  | { readonly stage: 'challenge_completed' }\n  | {\n      readonly stage: 'challenge_failed'\n      readonly declineReason?: BillingDeclineReason\n    }\n\n/**\n * What one transition of a pending operation put in the customer's way: a\n * challenge first required under a client secret, this tab's verdict on it,\n * or a retryable decline with a reason the operation did not hold before.\n * The first decline the server reports for a challenge this tab already saw\n * fail is the same failure, so it is not reported twice.\n */\nexport function paymentFrictionBetween(\n  before: BillingOperationState | undefined,\n  after: BillingOperationState\n): readonly PaymentFrictionSignal[] {\n  if (after.phase !== 'pending') return []\n  const earlier = before?.phase === 'pending' ? before : undefined\n  return [\n    ...challengeSignals(earlier?.challenge, after.challenge),\n    ...declineSignals(earlier, after)\n  ]\n}\n\nfunction challengeSignals(\n  before: EmbeddedChallenge | undefined,\n  after: EmbeddedChallenge | undefined\n): readonly PaymentFrictionSignal[] {\n  if (after === undefined) return []\n  if (after.clientSecret !== before?.clientSecret) {\n    return after.status === 'required' ? [{ stage: 'challenge_required' }] : []\n  }\n  if (after.status === before.status) return []\n  if (after.status === 'completed') return [{ stage: 'challenge_completed' }]\n  if (after.status === 'failed') return [{ stage: 'challenge_failed' }]\n  return []\n}\n\nfunction declineSignals(\n  before: PendingBillingOperation | undefined,\n  after: PendingBillingOperation\n): readonly PaymentFrictionSignal[] {\n  const reason = after.declineReason\n  if (reason === undefined || reason === before?.declineReason) return []\n  const echoesFailedChallenge =\n    after.presentation === 'embedded' &&\n    after.challenge?.status === 'failed' &&\n    before?.declineReason === undefined\n  return echoesFailedChallenge\n    ? []\n    : [{ stage: 'challenge_failed', declineReason: reason }]\n}\n","/**\n * The operation lifecycle every billing command sits on: adopt a\n * `billing_op_id`, observe it to a terminal state, and reattach to it after a\n * reload, a focus, or a return to the workspace — without ever creating a\n * replacement operation. Commands issue the request; this owns everything\n * that happens to the id afterwards.\n *\n * Framework-free by construction. Nothing here opens a URL, drives a\n * payment-provider challenge, or listens to a document: a host renders the\n * state (`actionUrl`, `challenge`), performs those effects itself, and\n * reports back through `reportChallenge*` and `wake`.\n *\n * Behavior is ported from the cloud app's `billingOperationStore` — the\n * cadence, the budgets, the parked-on-customer rules, the challenge echo\n * suppression — and from the pending-checkout pointer's terminal rule; the\n * wiring onto the scope source, the scope tracker, and the generated\n * contract is new.\n */\n\nimport {\n  BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT,\n  BILLING_OPERATION_TELEMETRY_EVENT\n} from '../../telemetry.js'\nimport type {\n  BillingFailure,\n  BillingResult,\n  BillingTransport\n} from './billingContracts.js'\nimport type {\n  BillingScope,\n  BillingScopeContext,\n  BillingScopeSource\n} from './billingScope.js'\nimport { createBillingScopeTracker } from './billingScope.js'\nimport type {\n  BillingOperationPointer,\n  BillingOperationPointerStorage,\n  OperationPointerStore\n} from './operationPointer.js'\nimport {\n  NO_POINTER_STORE,\n  createOperationPointerStore\n} from './operationPointer.js'\nimport {\n  hasExhaustedPollBudget,\n  isWaitingOnCustomerWithoutAction,\n  nextPollDelayMs\n} from './operationPolicy.js'\nimport type {\n  BillingDeclineReason,\n  BillingOpStatus,\n  BillingOperationEvent,\n  BillingOperationKind,\n  BillingOperationState,\n  BillingPresentation,\n  BillingPresentationState,\n  HostedBillingDestination,\n  PendingBillingOperation\n} from './operationState.js'\nimport {\n  BillingOpStatusSchema,\n  isGrantLanding,\n  isTerminal,\n  reduceBillingOperation,\n  validateActionUrl\n} from './operationState.js'\nimport type { PaymentFrictionSignal } from './paymentFriction.js'\nimport type {\n  CheckoutHostedStep,\n  CheckoutRedirectNavigation\n} from './telemetry/checkoutRedirectEvent.js'\nimport type { CheckoutMethodKind } from './telemetry/checkoutJourney.js'\nimport { paymentFrictionBetween } from './paymentFriction.js'\nimport { selectBillingPresentation } from './presentation.js'\nimport { readValidatedBillingResponse } from './sharedRead.js'\nimport type { BillingStatusData, BillingStatusReader } from './status.js'\n\n/** Settled, but a later read may still change what the operation reports. */\nfunction isStillSettling(state: BillingOperationState): boolean {\n  return state.phase === 'reconciliation_needed' || isGrantLanding(state)\n}\n\nexport function operationRoute(operationId: string): string {\n  return `/billing/ops/${encodeURIComponent(operationId)}`\n}\n\n/** What a command learned from the backend when it issued the operation. */\nexport interface IssuedBillingOperation {\n  readonly operationId: string\n  /** A hosted continuation the response already carried (`payment_method_url`, `action_url`). */\n  readonly actionUrl?: string\n  /** An in-page challenge the response already carried. */\n  readonly clientSecret?: string\n}\n\nexport type BillingOperationFailureCategory =\n  | 'provider_decline'\n  | 'api_rejected'\n  | 'poll_timeout'\n  | 'reconciliation_needed'\n  | 'stale_operation'\n\ntype HostedStepEventName =\n  | typeof BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.redirectStarted\n  | typeof BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.returned\n\ntype BillingOperationTelemetryEventName = Exclude<\n  | (typeof BILLING_OPERATION_TELEMETRY_EVENT)[keyof typeof BILLING_OPERATION_TELEMETRY_EVENT]\n  | (typeof BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT)[keyof typeof BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT],\n  HostedStepEventName\n>\n\n/** A hosted step this tab handed the customer to. */\ninterface HostedStepVisit {\n  readonly destination: HostedBillingDestination\n  readonly step: CheckoutHostedStep\n  readonly navigation: CheckoutRedirectNavigation\n  readonly method_kind?: CheckoutMethodKind\n}\n\ninterface BillingOperationTelemetryBase {\n  readonly billing_op_id: string\n  readonly operation_type: BillingOperationKind\n  readonly presentation: BillingPresentation\n  /** True when this tab reattached to an operation it did not issue. */\n  readonly resumed: boolean\n}\n\nexport type BillingOperationTelemetryEvent = BillingOperationTelemetryBase &\n  (\n    | {\n        readonly name: BillingOperationTelemetryEventName\n        readonly failure_category?: BillingOperationFailureCategory\n        readonly decline_reason?: BillingDeclineReason\n        /** From the attempt's start, so a resumed operation reports its whole life. */\n        readonly duration_ms?: number\n      }\n    | (HostedStepVisit & { readonly name: HostedStepEventName })\n  )\n\nexport type PresentationSwitchOutcome =\n  | 'switched'\n  | 'unchanged'\n  /** The server has offered no hosted continuation yet. */\n  | 'no_hosted_url'\n  /** The host cannot drive a challenge, or none has been issued for this operation. */\n  | 'embedded_unavailable'\n  | 'not_pending'\n  | 'unknown_operation'\n\nexport interface BillingOperationLifecycleOptions {\n  readonly transport: BillingTransport\n  /** Where the core learns which user, workspace, and role it runs as. */\n  readonly scopeSource: BillingScopeSource\n  /** The Phase 2 status reader; consulted before every start and recovery. */\n  readonly statusReader: BillingStatusReader\n  /** Tab-local storage for the operation pointer; absent means nothing survives a reload. */\n  readonly pointerStorage?: BillingOperationPointerStorage\n  /**\n   * Keep the pointer of an operation that succeeded or needs reconciliation,\n   * for a host whose page is the checkout itself: a revisit reads it back\n   * through `recover({ includeSettled: true })`. A plain `recover` never\n   * sees it, so every other caller recovers exactly what it did before.\n   */\n  readonly retainSettledPointer?: boolean\n  /** Whether the host can drive an in-page challenge right now. Absent routes everything hosted. */\n  readonly embeddedCheckoutAvailable?: () => boolean\n  /** Which origin serves a hosted page right now. Absent keeps every hosted operation on the provider page. */\n  readonly hostedDestination?: () => HostedBillingDestination\n  readonly onTelemetry?: (event: BillingOperationTelemetryEvent) => void\n  readonly now?: () => number\n}\n\nexport interface BillingRecoverOptions {\n  /**\n   * Also read back the operation a retained pointer says already settled, so\n   * the checkout that issued it can show it finished. Only a lifecycle with\n   * `retainSettledPointer` keeps one.\n   */\n  readonly includeSettled?: boolean\n}\n\nexport interface BillingOperationLifecycle {\n  /**\n   * Runs a command on the lifecycle: single-flight per kind, the backend's\n   * pending operation adopted instead of a second one issued, and the\n   * issued id observed from the moment it exists. Resolves once the\n   * operation is adopted, not once it settles — see `settled`.\n   */\n  begin: (\n    kind: BillingOperationKind,\n    issue: (\n      scope: BillingScope\n    ) => Promise<BillingResult<IssuedBillingOperation>>\n  ) => Promise<BillingResult<BillingOperationState>>\n  /**\n   * Reattaches to whatever this scope is already waiting on: the backend's\n   * pending operation first, then the tab-local pointer. Resolves undefined\n   * when there is nothing to recover.\n   */\n  recover: (\n    options?: BillingRecoverOptions\n  ) => Promise<BillingResult<BillingOperationState | undefined>>\n  /** The host became visible or focused: poll every pending operation now. */\n  wake: () => void\n  /** Moves the operation between presentations under the same id. */\n  switchPresentation: (\n    operationId: string,\n    presentation: BillingPresentation\n  ) => PresentationSwitchOutcome\n  /**\n   * The host opened the operation's hosted step. A redirect is remembered in\n   * the pointer, so the page it returns to reports the return; a new tab\n   * reports it on the next wake.\n   */\n  reportHostedStepOpened: (\n    operationId: string,\n    navigation: CheckoutRedirectNavigation,\n    methodKind?: CheckoutMethodKind\n  ) => void\n  /** The host began driving the operation's challenge; polling pauses until it settles. */\n  reportChallengeStarted: (operationId: string) => void\n  reportChallengeSettled: (\n    operationId: string,\n    outcome: 'completed' | 'failed'\n  ) => void\n  get: (operationId: string) => BillingOperationState | undefined\n  getSnapshot: () => readonly BillingOperationState[]\n  subscribe: (listener: (state: BillingOperationState) => void) => () => void\n  /** Resolves with the terminal state; undefined for an id this lifecycle never adopted. */\n  settled: (operationId: string) => Promise<BillingOperationState> | undefined\n  dispose: () => void\n}\n\nconst NOT_AUTHENTICATED = {\n  status: 'error',\n  code: 'NOT_AUTHENTICATED'\n} as const satisfies BillingFailure\n\nconst SUPERSEDED = {\n  status: 'error',\n  code: 'SUPERSEDED'\n} as const satisfies BillingFailure\n\nconst OPERATION_ALREADY_PENDING = {\n  status: 'error',\n  code: 'OPERATION_ALREADY_PENDING'\n} as const satisfies BillingFailure\n\n/** A command attempt still settling, kept with the scope that issued it. */\ninterface InFlightCommand {\n  readonly context: BillingScopeContext\n  readonly promise: Promise<BillingResult<BillingOperationState>>\n}\n\ninterface OperationRecord {\n  state: BillingOperationState\n  readonly context: BillingScopeContext\n  readonly resumed: boolean\n  /** The end this tab already reported, kept on every pointer rewrite; a revisit says nothing new. */\n  readonly reportedAs: BillingOperationPointer['settled']\n  delayMs: number | undefined\n  /** When the operation last became blocked on the customer with no action here. */\n  waitingWithoutActionSince: number | undefined\n  timer: ReturnType<typeof setTimeout> | undefined\n  inFlightPoll: Promise<void> | undefined\n  /** A hosted step this tab opened in a new tab; the next wake is the customer back. */\n  awaitingReturn: HostedStepVisit | undefined\n  readonly settled: Promise<BillingOperationState>\n  resolveSettled: (state: BillingOperationState) => void\n}\n\ninterface AdoptInput {\n  readonly id: string\n  readonly kind: BillingOperationKind\n  readonly context: BillingScopeContext\n  readonly presentation: BillingPresentation\n  readonly actionUrl?: string\n  readonly clientSecret?: string\n  readonly attemptStartedAt: number\n  readonly resumed: boolean\n  readonly awaitedHere: boolean\n  /** A status already read for this operation; observed from it instead of polled again. */\n  readonly initialStatus?: BillingOpStatus\n  /** The hosted step a redirect left this page for; adopting it is the return. */\n  readonly returnedFrom?: BillingOperationPointer['redirect']\n  readonly reportedAs?: BillingOperationPointer['settled']\n}\n\ntype ResumedAttempt = Pick<\n  AdoptInput,\n  | 'presentation'\n  | 'attemptStartedAt'\n  | 'resumed'\n  | 'awaitedHere'\n  | 'returnedFrom'\n  | 'reportedAs'\n>\n\n/** The attempt a pointer remembers, picked up again by this tab. */\nfunction resumedFrom(pointer: BillingOperationPointer): ResumedAttempt {\n  return {\n    presentation: pointer.presentation,\n    attemptStartedAt: pointer.attemptStartedAt,\n    resumed: true,\n    awaitedHere: pointer.awaited === true,\n    ...(pointer.settled === undefined ? {} : { reportedAs: pointer.settled }),\n    ...(pointer.redirect === undefined\n      ? {}\n      : { returnedFrom: pointer.redirect })\n  }\n}\n\ninterface ServerPendingOperation {\n  readonly id: string\n  readonly kind: BillingOperationKind\n  readonly actionUrl?: string\n  readonly clientSecret?: string\n}\n\nfunction continuationOf(issued: {\n  readonly actionUrl?: string | undefined\n  readonly clientSecret?: string | undefined\n}): Pick<AdoptInput, 'actionUrl' | 'clientSecret'> {\n  return {\n    ...(issued.actionUrl === undefined ? {} : { actionUrl: issued.actionUrl }),\n    ...(issued.clientSecret === undefined\n      ? {}\n      : { clientSecret: issued.clientSecret })\n  }\n}\n\nfunction pendingFromStatus(\n  status: BillingStatusData\n): ServerPendingOperation | undefined {\n  if (status.pending_billing_op_id === undefined) return undefined\n  return {\n    id: status.pending_billing_op_id,\n    kind: status.pending_billing_op_type === 'topup' ? 'topup' : 'subscription',\n    ...continuationOf({\n      actionUrl: status.action_url,\n      clientSecret: status.payment_intent_client_secret\n    })\n  }\n}\n\nfunction initialPendingState(\n  input: AdoptInput,\n  observedAt: number,\n  presentation: BillingPresentationState\n): PendingBillingOperation {\n  const actionUrl = validateActionUrl(input.actionUrl)\n  const challenge =\n    input.clientSecret === undefined || input.presentation !== 'embedded'\n      ? undefined\n      : { clientSecret: input.clientSecret, status: 'required' as const }\n  return {\n    id: input.id,\n    kind: input.kind,\n    scope: input.context.scope,\n    ...presentation,\n    observedAt,\n    attemptStartedAt: input.attemptStartedAt,\n    ...(input.awaitedHere ? { awaitedHere: true } : {}),\n    phase: 'pending',\n    ...(actionUrl === undefined ? {} : { actionUrl }),\n    ...(challenge === undefined ? {} : { challenge }),\n    customerActionSeen:\n      actionUrl !== undefined || input.clientSecret !== undefined\n  }\n}\n\nexport function failureCategoryFor(\n  state: Exclude<BillingOperationState, PendingBillingOperation>\n): BillingOperationFailureCategory | undefined {\n  switch (state.phase) {\n    case 'succeeded':\n      return undefined\n    case 'failed':\n      return state.kind === 'cancel' ? 'api_rejected' : 'provider_decline'\n    case 'timed_out':\n      return 'poll_timeout'\n    case 'reconciliation_needed':\n      return 'reconciliation_needed'\n    case 'superseded':\n      return 'stale_operation'\n  }\n}\n\nconst FRICTION_EVENT_NAME = {\n  challenge_required:\n    BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.challengeRequired,\n  challenge_completed:\n    BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.challengeCompleted,\n  challenge_failed: BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.challengeFailed\n} as const satisfies Record<PaymentFrictionSignal['stage'], string>\n\n/** What the hosted page asks of the customer, from what the server waits on. */\nfunction hostedStepOf(state: PendingBillingOperation): CheckoutHostedStep {\n  if (\n    state.authenticationState === 'requires_action' ||\n    (state.presentation === 'embedded' && state.challenge !== undefined)\n  ) {\n    return 'authentication'\n  }\n  if (state.serverPhase === 'awaiting_payment_method') return 'payment_method'\n  if (state.serverPhase === 'awaiting_invoice_payment') return 'invoice_payment'\n  return 'checkout'\n}\n\n/** The pause is this tab's own challenge on screen; a hosted page never pauses. */\nfunction isDrivingChallenge(state: PendingBillingOperation): boolean {\n  return (\n    state.presentation === 'embedded' &&\n    state.challenge?.status === 'in_progress'\n  )\n}\n\nexport function createBillingOperationLifecycle(\n  options: BillingOperationLifecycleOptions\n): BillingOperationLifecycle {\n  const {\n    transport,\n    scopeSource,\n    statusReader,\n    embeddedCheckoutAvailable = () => false,\n    hostedDestination = () => 'stripe',\n    onTelemetry,\n    now = Date.now\n  } = options\n  const pointers: OperationPointerStore =\n    options.pointerStorage === undefined\n      ? NO_POINTER_STORE\n      : createOperationPointerStore(options.pointerStorage, now, {\n          retainSettled: options.retainSettledPointer === true\n        })\n\n  const operations = new Map<string, OperationRecord>()\n  const inFlightCommands = new Map<BillingOperationKind, InFlightCommand>()\n  const listeners = new Set<(state: BillingOperationState) => void>()\n  const lifetime = { disposed: false }\n\n  // Role is part of the scope, so a demotion mid-payment supersedes the\n  // operation and this tab stops observing it. The pointer key omits role on\n  // purpose: the charge still belongs to (user, workspace), so `recover` finds\n  // it again under the new role. Keying the pointer by role would strand it.\n  const scopeTracker = createBillingScopeTracker(scopeSource, () => {\n    for (const record of operations.values()) {\n      dispatch(record, { type: 'superseded' })\n    }\n  })\n\n  function isLive(context: BillingScopeContext): boolean {\n    return !lifetime.disposed && scopeTracker.isCurrent(context)\n  }\n\n  function publish(record: OperationRecord) {\n    for (const listener of Array.from(listeners)) listener(record.state)\n  }\n\n  function stopTimer(record: OperationRecord) {\n    if (record.timer === undefined) return\n    clearTimeout(record.timer)\n    record.timer = undefined\n  }\n\n  function report(\n    record: OperationRecord,\n    event: BillingOperationTelemetryEvent\n  ) {\n    if (record.reportedAs === undefined) onTelemetry?.(event)\n  }\n\n  function emitTerminalTelemetry(record: OperationRecord) {\n    const state = record.state\n    if (!isTerminal(state)) return\n    const category = failureCategoryFor(state)\n    report(record, {\n      name:\n        state.phase === 'succeeded'\n          ? BILLING_OPERATION_TELEMETRY_EVENT.succeeded\n          : state.phase === 'timed_out'\n            ? BILLING_OPERATION_TELEMETRY_EVENT.timeout\n            : BILLING_OPERATION_TELEMETRY_EVENT.failed,\n      billing_op_id: state.id,\n      operation_type: state.kind,\n      presentation: state.presentation,\n      resumed: record.resumed,\n      ...(category === undefined ? {} : { failure_category: category }),\n      ...(state.phase === 'failed'\n        ? { decline_reason: state.declineReason }\n        : {}),\n      duration_ms: now() - state.attemptStartedAt\n    })\n  }\n\n  function emitFrictionTelemetry(\n    record: OperationRecord,\n    before: BillingOperationState | undefined\n  ) {\n    const state = record.state\n    for (const signal of paymentFrictionBetween(before, state)) {\n      report(record, {\n        name: FRICTION_EVENT_NAME[signal.stage],\n        billing_op_id: state.id,\n        operation_type: state.kind,\n        presentation: state.presentation,\n        resumed: record.resumed,\n        ...('declineReason' in signal && signal.declineReason !== undefined\n          ? { decline_reason: signal.declineReason }\n          : {})\n      })\n    }\n  }\n\n  function dispatch(record: OperationRecord, event: BillingOperationEvent) {\n    const before = record.state\n    const next = reduceBillingOperation(before, event)\n    if (next === before) return\n    record.state = next\n    emitFrictionTelemetry(record, before)\n    if (isTerminal(next)) {\n      stopTimer(record)\n      pointers.settle(next)\n      emitTerminalTelemetry(record)\n      record.resolveSettled(next)\n    }\n    publish(record)\n  }\n\n  function schedule(record: OperationRecord) {\n    if (record.state.phase !== 'pending') return\n    stopTimer(record)\n    record.waitingWithoutActionSince = isWaitingOnCustomerWithoutAction(\n      record.state\n    )\n      ? (record.waitingWithoutActionSince ?? now())\n      : undefined\n    const delayMs = nextPollDelayMs(\n      record.state,\n      record.delayMs,\n      record.waitingWithoutActionSince === undefined\n        ? 0\n        : now() - record.waitingWithoutActionSince\n    )\n    record.delayMs = delayMs\n    record.timer = setTimeout(() => void poll(record), delayMs)\n  }\n\n  // One request per record at a time: a wake arriving mid-poll joins the\n  // poll in flight instead of doubling the request rate. The request is\n  // bound to the record, not the id, so an id re-adopted after supersession\n  // starts its own observation instead of joining a poll that can no longer\n  // schedule it.\n  function poll(record: OperationRecord): Promise<void> {\n    if (record.inFlightPoll !== undefined) return record.inFlightPoll\n    const request = pollOnce(record).finally(() => {\n      record.inFlightPoll = undefined\n    })\n    record.inFlightPoll = request\n    return request\n  }\n\n  function savedRedirect(scope: BillingScope, operationId: string) {\n    const saved = pointers.read(scope)\n    return saved?.operationId === operationId ? saved.redirect : undefined\n  }\n\n  function writePointer(\n    record: OperationRecord,\n    redirect?: BillingOperationPointer['redirect']\n  ) {\n    const { state, reportedAs } = record\n    pointers.write(record.context.scope, {\n      operationId: state.id,\n      kind: state.kind,\n      presentation: state.presentation,\n      attemptStartedAt: state.attemptStartedAt,\n      ...(state.awaitedHere ? { awaited: true } : {}),\n      ...(redirect === undefined ? {} : { redirect }),\n      ...(reportedAs === undefined ? {} : { settled: reportedAs })\n    })\n  }\n\n  function emitHostedStepTelemetry(\n    record: OperationRecord,\n    name: HostedStepEventName,\n    visit: HostedStepVisit\n  ) {\n    report(record, {\n      name,\n      billing_op_id: record.state.id,\n      operation_type: record.state.kind,\n      presentation: record.state.presentation,\n      resumed: record.resumed,\n      ...visit\n    })\n  }\n\n  function readOperation(operationId: string) {\n    return readValidatedBillingResponse(\n      transport,\n      { method: 'GET', route: operationRoute(operationId) },\n      (body) => BillingOpStatusSchema.safeParse(body)\n    )\n  }\n\n  function continueOrExpire(record: OperationRecord) {\n    if (record.state.phase !== 'pending') return\n    if (hasExhaustedPollBudget(record.state, now())) {\n      dispatch(record, { type: 'timed_out' })\n      return\n    }\n    schedule(record)\n  }\n\n  async function pollOnce(record: OperationRecord) {\n    const state = record.state\n    if (state.phase !== 'pending') return\n    stopTimer(record)\n    if (isDrivingChallenge(state)) return\n    if (!scopeTracker.isCurrent(record.context)) {\n      dispatch(record, { type: 'superseded' })\n      return\n    }\n    if (hasExhaustedPollBudget(state, now())) {\n      dispatch(record, { type: 'timed_out' })\n      return\n    }\n\n    const response = await readOperation(state.id)\n\n    if (record.state.phase !== 'pending') return\n    if (!isLive(record.context)) {\n      dispatch(record, { type: 'superseded' })\n      return\n    }\n    applyPollResponse(record, response)\n  }\n\n  function applyPollResponse(\n    record: OperationRecord,\n    response: Awaited<ReturnType<typeof readOperation>>\n  ) {\n    if (response.status === 'ok') {\n      dispatch(record, { type: 'status_polled', status: response.value.data })\n      continueOrExpire(record)\n      return\n    }\n    if (\n      response.code === 'SUPERSEDED' ||\n      response.code === 'ACCESS_DENIED' ||\n      response.code === 'NOT_AUTHENTICATED'\n    ) {\n      dispatch(record, { type: 'superseded' })\n    } else if (response.code === 'NOT_FOUND') {\n      dispatch(record, { type: 'lost' })\n    } else {\n      continueOrExpire(record)\n    }\n  }\n\n  /** Read at every adoption, so an operation recovered from the pointer lands on today's destination. */\n  function destinationFor(\n    presentation: BillingPresentation\n  ): BillingPresentationState {\n    return presentation === 'hosted'\n      ? { presentation, hostedDestination: hostedDestination() }\n      : { presentation }\n  }\n\n  /**\n   * An id is observed afresh once this tab has stopped learning anything new\n   * about it: its poll budget ran out or it left the scope. One the server\n   * parked for reconciliation, or a success whose credits were still landing,\n   * is observed afresh only for a caller reading settled operations, since\n   * the server may since have settled it or recorded the grant.\n   */\n  function adopt(input: AdoptInput, includeSettled = false): OperationRecord {\n    const existing = operations.get(input.id)\n    if (\n      existing !== undefined &&\n      existing.state.phase !== 'timed_out' &&\n      existing.state.phase !== 'superseded' &&\n      !(includeSettled && isStillSettling(existing.state))\n    ) {\n      return existing\n    }\n\n    const state = initialPendingState(\n      input,\n      now(),\n      destinationFor(input.presentation)\n    )\n\n    let resolveSettled: (state: BillingOperationState) => void = () => {}\n    const settled = new Promise<BillingOperationState>((resolve) => {\n      resolveSettled = resolve\n    })\n    const record: OperationRecord = {\n      state,\n      context: input.context,\n      resumed: input.resumed,\n      reportedAs: input.reportedAs,\n      delayMs: undefined,\n      waitingWithoutActionSince: undefined,\n      timer: undefined,\n      inFlightPoll: undefined,\n      awaitingReturn: undefined,\n      settled,\n      resolveSettled\n    }\n    operations.set(input.id, record)\n    writePointer(record)\n    report(record, {\n      name: BILLING_OPERATION_TELEMETRY_EVENT.started,\n      billing_op_id: input.id,\n      operation_type: input.kind,\n      presentation: input.presentation,\n      resumed: input.resumed\n    })\n    emitFrictionTelemetry(record, undefined)\n    if (input.returnedFrom !== undefined) {\n      emitHostedStepTelemetry(\n        record,\n        BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.returned,\n        {\n          ...input.returnedFrom,\n          navigation: 'redirect'\n        }\n      )\n    }\n    startObserving(record, input, state)\n    return record\n  }\n\n  // A resumed operation without a served link is announced by its first\n  // status, never before it: the status read names it but not what it waits\n  // on, and a checkout parked on a card must not be announced as processing\n  // for the length of a poll. A served link already says what it waits on.\n  function startObserving(\n    record: OperationRecord,\n    input: AdoptInput,\n    state: PendingBillingOperation\n  ) {\n    if (input.initialStatus !== undefined) {\n      dispatch(record, { type: 'status_polled', status: input.initialStatus })\n      continueOrExpire(record)\n      return\n    }\n    if (!input.resumed || state.actionUrl !== undefined) publish(record)\n    void poll(record)\n  }\n\n  function routeFor(\n    rail: BillingStatusData['billing_rail'],\n    issued: { readonly actionUrl?: string; readonly clientSecret?: string }\n  ): BillingPresentation {\n    return selectBillingPresentation({\n      embeddedCheckoutAvailable: embeddedCheckoutAvailable(),\n      billingRail: rail,\n      ...(issued.actionUrl === undefined\n        ? {}\n        : { hostedUrl: issued.actionUrl }),\n      ...(issued.clientSecret === undefined\n        ? {}\n        : { clientSecret: issued.clientSecret })\n    })\n  }\n\n  async function beginOnce(\n    kind: BillingOperationKind,\n    context: BillingScopeContext,\n    issue: (\n      scope: BillingScope\n    ) => Promise<BillingResult<IssuedBillingOperation>>\n  ): Promise<BillingResult<BillingOperationState>> {\n    // The backend's word on what is already pending comes first: a second\n    // charge attempt is never issued over one the server is still settling.\n    const status = await statusReader.read()\n    // A scope change outranks a failed read, as in recover().\n    if (!isLive(context)) return SUPERSEDED\n    if (status.status === 'error') return status\n\n    const rail = status.value.status.billing_rail\n    const parked = await resubmitTarget(\n      pendingFromStatus(status.value.status),\n      kind\n    )\n    if (!isLive(context)) return SUPERSEDED\n    if (parked === 'refused') return OPERATION_ALREADY_PENDING\n\n    const attemptStartedAt = now()\n    const issued = await issue(context.scope)\n    if (!isLive(context)) {\n      return leftScope(context, kind, rail, issued, attemptStartedAt)\n    }\n    if (issued.status === 'error') return issued\n\n    const resumed =\n      parked === undefined ? undefined : resumeParked(parked, issued.value)\n    if (resumed !== undefined) return { status: 'ok', value: resumed }\n\n    const record = adopt({\n      id: issued.value.operationId,\n      kind,\n      context,\n      presentation: routeFor(rail, issued.value),\n      ...continuationOf(issued.value),\n      attemptStartedAt,\n      resumed: false,\n      awaitedHere: true\n    })\n    return { status: 'ok', value: record.state }\n  }\n\n  // The operation exists server-side under the scope this tab just left; the\n  // pointer waits there so a return recovers it rather than reissuing.\n  function leftScope(\n    context: BillingScopeContext,\n    kind: BillingOperationKind,\n    rail: BillingStatusData['billing_rail'],\n    issued: BillingResult<IssuedBillingOperation>,\n    attemptStartedAt: number\n  ): typeof SUPERSEDED {\n    if (issued.status === 'ok') {\n      pointers.write(context.scope, {\n        operationId: issued.value.operationId,\n        kind,\n        presentation: routeFor(rail, issued.value),\n        attemptStartedAt,\n        awaited: true\n      })\n    }\n    return SUPERSEDED\n  }\n\n  /**\n   * Declines rather than joins an operation of this kind the server already\n   * has pending, because the status names no plan: this caller asked for one\n   * outcome and the parked attempt settles another, so reporting that one as\n   * this command's result would tell the customer they bought something they\n   * did not choose. recover() is where a deliberate return to it belongs.\n   *\n   * The exception is a checkout this tab watches parked on a card. The server\n   * keeps no link back to it, and a resubmit is how it resumes that checkout\n   * or replaces it, so the command goes through with that record in hand.\n   */\n  async function resubmitTarget(\n    pending: ServerPendingOperation | undefined,\n    kind: BillingOperationKind\n  ): Promise<OperationRecord | 'refused' | undefined> {\n    if (pending?.kind !== kind) return undefined\n    const record = operations.get(pending.id)\n    if (\n      record?.state.phase === 'pending' &&\n      record.state.serverPhase === undefined\n    ) {\n      const read = await readOperation(pending.id)\n      if (read.status === 'ok') {\n        dispatch(record, { type: 'status_polled', status: read.value.data })\n      }\n    }\n    return record?.state.phase === 'pending' &&\n      record.state.serverPhase === 'awaiting_payment_method'\n      ? record\n      : 'refused'\n  }\n\n  /**\n   * The same id is the parked checkout resumed, with the fresh hosted step the\n   * server minted for it; another id replaced it, so this tab stops watching.\n   */\n  function resumeParked(\n    parked: OperationRecord,\n    issued: IssuedBillingOperation\n  ): BillingOperationState | undefined {\n    if (parked.state.id !== issued.operationId) {\n      dispatch(parked, { type: 'superseded' })\n      return undefined\n    }\n    if (issued.actionUrl !== undefined) {\n      dispatch(parked, { type: 'action_reissued', actionUrl: issued.actionUrl })\n    }\n    return parked.state\n  }\n\n  function begin(\n    kind: BillingOperationKind,\n    issue: (\n      scope: BillingScope\n    ) => Promise<BillingResult<IssuedBillingOperation>>\n  ): Promise<BillingResult<BillingOperationState>> {\n    if (lifetime.disposed) return Promise.resolve(SUPERSEDED)\n    const context = scopeTracker.capture()\n    if (context === undefined) return Promise.resolve(NOT_AUTHENTICATED)\n\n    // Single-flight holds only within a scope: an attempt the scope change\n    // already doomed to SUPERSEDED must not stand in for this caller's.\n    const inFlight = inFlightCommands.get(kind)\n    if (inFlight !== undefined && isLive(inFlight.context)) {\n      return inFlight.promise\n    }\n    const attempt = beginOnce(kind, context, issue).finally(() => {\n      if (inFlightCommands.get(kind)?.promise === attempt) {\n        inFlightCommands.delete(kind)\n      }\n    })\n    inFlightCommands.set(kind, { context, promise: attempt })\n    return attempt\n  }\n\n  function fromPointer(\n    pointer: BillingOperationPointer,\n    context: BillingScopeContext\n  ): AdoptInput {\n    return {\n      id: pointer.operationId,\n      kind: pointer.kind,\n      context,\n      ...resumedFrom(pointer)\n    }\n  }\n\n  // Unreachable is not \"nothing pending\": the pointer is the only evidence\n  // left, and observing it costs a poll while reissuing could cost a charge.\n  function recoverFromPointer(\n    failure: BillingFailure,\n    pointer: BillingOperationPointer | undefined,\n    context: BillingScopeContext,\n    includeSettled: boolean\n  ): BillingResult<BillingOperationState | undefined> {\n    if (failure.code !== 'REQUEST_FAILED' || pointer === undefined) {\n      return failure\n    }\n    const record = adopt(fromPointer(pointer, context), includeSettled)\n    return { status: 'ok', value: record.state }\n  }\n\n  function resumeServerPending(\n    pending: ServerPendingOperation,\n    rail: BillingStatusData['billing_rail'],\n    pointer: BillingOperationPointer | undefined,\n    context: BillingScopeContext,\n    includeSettled: boolean\n  ): BillingResult<BillingOperationState> {\n    const known = pointer?.operationId === pending.id ? pointer : undefined\n    const record = adopt(\n      {\n        ...pending,\n        context,\n        ...(known === undefined\n          ? {\n              presentation: routeFor(rail, pending),\n              attemptStartedAt: now(),\n              resumed: true,\n              awaitedHere: false\n            }\n          : resumedFrom(known))\n      },\n      includeSettled\n    )\n    return { status: 'ok', value: record.state }\n  }\n\n  // The server reports nothing pending, so the pointed-at operation has\n  // either settled since this tab last saw it or never belonged to this\n  // scope. One read decides which; a stale pointer is dropped, never\n  // re-observed on a schedule.\n  async function probePointer(\n    pointer: BillingOperationPointer,\n    context: BillingScopeContext,\n    includeSettled: boolean\n  ): Promise<BillingResult<BillingOperationState | undefined>> {\n    const probe = await readOperation(pointer.operationId)\n    if (!isLive(context)) return SUPERSEDED\n    if (probe.status === 'error') {\n      if (probe.code !== 'NOT_FOUND') return probe\n      pointers.clear(context.scope, pointer.operationId)\n      return { status: 'ok', value: undefined }\n    }\n    const record = adopt(\n      { ...fromPointer(pointer, context), initialStatus: probe.value.data },\n      includeSettled\n    )\n    return { status: 'ok', value: record.state }\n  }\n\n  /** A settled pointer answers only a caller that asked for it. */\n  function readPointer(\n    scope: BillingScope,\n    includeSettled: boolean\n  ): BillingOperationPointer | undefined {\n    const pointer = pointers.read(scope)\n    return pointer?.settled === undefined || includeSettled\n      ? pointer\n      : undefined\n  }\n\n  async function recover({\n    includeSettled = false\n  }: BillingRecoverOptions = {}): Promise<\n    BillingResult<BillingOperationState | undefined>\n  > {\n    if (lifetime.disposed) return SUPERSEDED\n    const context = scopeTracker.capture()\n    if (context === undefined) return NOT_AUTHENTICATED\n\n    const status = await statusReader.read()\n    if (!isLive(context)) return SUPERSEDED\n    const pointer = readPointer(context.scope, includeSettled)\n    if (status.status === 'error') {\n      return recoverFromPointer(status, pointer, context, includeSettled)\n    }\n\n    const pending = pendingFromStatus(status.value.status)\n    if (pending !== undefined) {\n      return resumeServerPending(\n        pending,\n        status.value.status.billing_rail,\n        pointer,\n        context,\n        includeSettled\n      )\n    }\n    if (pointer === undefined) return { status: 'ok', value: undefined }\n    return probePointer(pointer, context, includeSettled)\n  }\n\n  function wake() {\n    for (const record of operations.values()) {\n      reportReturnFromNewTab(record)\n      if (record.state.phase !== 'pending') continue\n      if (isDrivingChallenge(record.state)) continue\n      void poll(record)\n    }\n  }\n\n  function refusedSwitch(\n    state: PendingBillingOperation,\n    presentation: BillingPresentation\n  ): PresentationSwitchOutcome | undefined {\n    if (state.presentation === presentation) return 'unchanged'\n    if (presentation === 'hosted') {\n      return state.actionUrl === undefined ? 'no_hosted_url' : undefined\n    }\n    return !embeddedCheckoutAvailable() || state.challenge === undefined\n      ? 'embedded_unavailable'\n      : undefined\n  }\n\n  function switchEvent(\n    presentation: BillingPresentation\n  ): BillingOperationEvent {\n    return presentation === 'hosted'\n      ? {\n          type: 'presentation_switched',\n          presentation,\n          hostedDestination: hostedDestination()\n        }\n      : { type: 'presentation_switched', presentation }\n  }\n\n  function switchPresentation(\n    operationId: string,\n    presentation: BillingPresentation\n  ): PresentationSwitchOutcome {\n    const record = operations.get(operationId)\n    if (record === undefined) return 'unknown_operation'\n    const state = record.state\n    if (state.phase !== 'pending') return 'not_pending'\n    const refusal = refusedSwitch(state, presentation)\n    if (refusal !== undefined) return refusal\n    dispatch(record, switchEvent(presentation))\n    writePointer(record, savedRedirect(record.context.scope, operationId))\n    record.delayMs = undefined\n    schedule(record)\n    return 'switched'\n  }\n\n  function reportReturnFromNewTab(record: OperationRecord) {\n    const visit = record.awaitingReturn\n    if (visit === undefined) return\n    record.awaitingReturn = undefined\n    emitHostedStepTelemetry(\n      record,\n      BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.returned,\n      visit\n    )\n  }\n\n  function reportHostedStepOpened(\n    operationId: string,\n    navigation: CheckoutRedirectNavigation,\n    methodKind?: CheckoutMethodKind\n  ) {\n    const record = operations.get(operationId)\n    if (record === undefined || record.state.phase !== 'pending') return\n    const state = record.state\n    const redirect = {\n      destination:\n        state.presentation === 'hosted' ? state.hostedDestination : 'stripe',\n      step: hostedStepOf(state),\n      ...(methodKind === undefined ? {} : { method_kind: methodKind })\n    } as const\n    const visit = { ...redirect, navigation }\n    if (navigation === 'redirect') {\n      writePointer(record, redirect)\n    } else {\n      record.awaitingReturn = visit\n    }\n    emitHostedStepTelemetry(\n      record,\n      BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.redirectStarted,\n      visit\n    )\n  }\n\n  function reportChallengeStarted(operationId: string) {\n    const record = operations.get(operationId)\n    if (record === undefined) return\n    dispatch(record, { type: 'challenge_started' })\n    if (record.state.phase === 'pending' && isDrivingChallenge(record.state)) {\n      stopTimer(record)\n    }\n  }\n\n  function reportChallengeSettled(\n    operationId: string,\n    outcome: 'completed' | 'failed'\n  ) {\n    const record = operations.get(operationId)\n    if (record === undefined || record.state.phase !== 'pending') return\n    dispatch(record, { type: 'challenge_settled', outcome })\n    record.delayMs = undefined\n    // A completed challenge is read back at once; a failed one is not a\n    // verdict on the payment — the server may have seen it succeed — so the\n    // operation stays observed on the parked cadence rather than stopping.\n    if (outcome === 'completed') void poll(record)\n    else schedule(record)\n  }\n\n  return {\n    begin,\n    recover,\n    wake,\n    switchPresentation,\n    reportHostedStepOpened,\n    reportChallengeStarted,\n    reportChallengeSettled,\n    get: (operationId) => operations.get(operationId)?.state,\n    getSnapshot: () => [...operations.values()].map((record) => record.state),\n    subscribe: (listener) => {\n      listeners.add(listener)\n      return () => listeners.delete(listener)\n    },\n    settled: (operationId) => operations.get(operationId)?.settled,\n    dispose: () => {\n      lifetime.disposed = true\n      // Every pending settlement resolves so no awaiting host hangs; this is\n      // the tab giving up observation, not an outcome, so no telemetry.\n      for (const record of operations.values()) {\n        stopTimer(record)\n        const next = reduceBillingOperation(record.state, {\n          type: 'superseded'\n        })\n        if (next === record.state) continue\n        record.state = next\n        record.resolveSettled(next)\n      }\n      operations.clear()\n      inFlightCommands.clear()\n      listeners.clear()\n      scopeTracker.dispose()\n    }\n  }\n}\n","import {\n  BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT,\n  BILLING_OPERATION_TELEMETRY_EVENT\n} from '../../../telemetry.js'\nimport type { BillingOperationTelemetryEvent } from '../operationLifecycle.js'\nimport type { BillingTelemetryEvent } from './billingTelemetryEvent.js'\nimport type { PaymentIntentSource } from './vocabulary.js'\n\n/**\n * The lifecycle's event onto the poller's `billing.operation.*` stages, so\n * both rails count in one funnel; only this rail sets `presentation` and\n * `resumed`. Friction inside the operation maps onto `billing.checkout.*`.\n */\nexport function toBillingTelemetryEvent(\n  event: BillingOperationTelemetryEvent,\n  paymentIntentSource?: PaymentIntentSource\n): BillingTelemetryEvent {\n  const friction = {\n    operation: 'checkout',\n    outcome: 'pending',\n    billing_client: 'sdk',\n    operation_type: event.operation_type,\n    billing_op_id: event.billing_op_id,\n    presentation: event.presentation,\n    resumed: event.resumed\n  } as const\n  if (\n    event.name === BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.redirectStarted ||\n    event.name === BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.returned\n  ) {\n    return {\n      ...friction,\n      stage:\n        event.name === BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.returned\n          ? 'returned'\n          : 'redirect_started',\n      destination: event.destination,\n      step: event.step,\n      navigation: event.navigation,\n      ...(event.method_kind === undefined\n        ? {}\n        : { method_kind: event.method_kind })\n    }\n  }\n  const shared = {\n    operation: 'operation',\n    billing_client: 'sdk',\n    operation_type: event.operation_type,\n    billing_op_id: event.billing_op_id,\n    presentation: event.presentation,\n    resumed: event.resumed,\n    ...(paymentIntentSource === undefined\n      ? {}\n      : { payment_intent_source: paymentIntentSource }),\n    ...('duration_ms' in event && event.duration_ms !== undefined\n      ? { duration_ms: event.duration_ms }\n      : {})\n  } as const\n\n  switch (event.name) {\n    case BILLING_OPERATION_TELEMETRY_EVENT.started:\n      return { ...shared, stage: 'started', outcome: 'pending' }\n    case BILLING_OPERATION_TELEMETRY_EVENT.succeeded:\n      return { ...shared, stage: 'succeeded', outcome: 'success' }\n    case BILLING_OPERATION_TELEMETRY_EVENT.timeout:\n      return {\n        ...shared,\n        stage: 'timeout',\n        outcome: 'failure',\n        failure_category: 'poll_timeout'\n      }\n    case BILLING_OPERATION_TELEMETRY_EVENT.failed:\n      return {\n        ...shared,\n        stage: 'failed',\n        outcome: 'failure',\n        failure_category: event.failure_category ?? 'provider_decline',\n        decline_reason: event.decline_reason\n      }\n    case BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.challengeRequired:\n      return { ...friction, stage: 'challenge_required' }\n    case BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.challengeCompleted:\n      return { ...friction, stage: 'challenge_completed' }\n    case BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT.challengeFailed:\n      return {\n        ...friction,\n        stage: 'challenge_failed',\n        ...(event.decline_reason === undefined\n          ? {}\n          : { decline_reason: event.decline_reason })\n      }\n  }\n}\n","import type { CreateTopupResponse } from '@comfyorg/ingest-types'\n\nimport type {\n  BillingCheckoutReceived,\n  BillingFailed,\n  BillingIntent,\n  BillingRequestSent,\n  BillingStarted,\n  BillingSucceeded\n} from './stages.js'\nimport type { PaymentIntentSource } from './vocabulary.js'\n\n/** The fixed amounts, in USD, a top-up dialog offers as one-click choices. */\nexport const TOPUP_AMOUNT_PRESETS_USD = [10, 25, 50, 100] as const\n\n/** The preset the customer picked, or `custom` for any typed amount. */\nexport type TopupAmountPreset =\n  | `${(typeof TOPUP_AMOUNT_PRESETS_USD)[number]}`\n  | 'custom'\n\nexport function getTopupAmountPreset(\n  pickedPresetUsd: number | null\n): TopupAmountPreset {\n  const preset = TOPUP_AMOUNT_PRESETS_USD.find((usd) => usd === pickedPresetUsd)\n  return preset === undefined ? 'custom' : `${preset}`\n}\n\ntype TopupStarted = BillingStarted & {\n  /** The amount being bought, in whole cents. */\n  amount_cents?: number\n  amount_preset?: TopupAmountPreset\n}\n\nexport type TopupBillingEvent = {\n  operation: 'topup'\n  billing_op_id?: string\n  /**\n   * Surface the top-up was opened from. Absent when the caller named none,\n   * exactly as on the subscription rail's events — absent is no claim, never\n   * an implied default. Named `payment_intent_source` to match its siblings\n   * above; the journey's own `entry_source` is a separate, smaller enum.\n   */\n  payment_intent_source?: PaymentIntentSource\n  /**\n   * Client-observed end-to-end wall time from this attempt's canonical\n   * `started` event through to this terminal event.\n   */\n  duration_ms?: number\n} & (\n  | BillingIntent\n  | BillingCheckoutReceived<CreateTopupResponse['status']>\n  | BillingRequestSent\n  | TopupStarted\n  | BillingSucceeded\n  | BillingFailed\n)\n","/**\n * Drives one embedded challenge through the host's payment-provider port and\n * reports the verdict back to the lifecycle. The provider object stays on the\n * host side: the core sees only `handleNextAction`, so no provider SDK is\n * imported here and a test can hand in a plain function.\n */\nimport type { BillingOperationLifecycle } from './operationLifecycle.js'\n\nexport interface EmbeddedChallengePort {\n  /** Stripe's `handleNextAction` shape: resolve the challenge for one client secret. */\n  handleNextAction: (clientSecret: string) => Promise<{\n    readonly error?: unknown\n    readonly paymentIntent?: { readonly status: string }\n  }>\n}\n\n/**\n * Statuses that mean the resumed challenge left the intent exactly where it\n * started, so the attempt needs a fresh start rather than a poll. A denylist\n * fails toward the server: an unlisted or future status reports optimistically\n * as completed, and the next poll's own `authentication_state` corrects it.\n */\nconst UNMOVED_INTENT_STATUSES: ReadonlySet<string> = new Set([\n  'requires_payment_method',\n  'requires_action',\n  'canceled'\n])\n\nexport type EmbeddedChallengeOutcome =\n  | 'completed'\n  | 'failed'\n  /** No required challenge on an embedded, pending operation with that id. */\n  | 'not_required'\n\ntype ChallengeLifecycle = Pick<\n  BillingOperationLifecycle,\n  'get' | 'reportChallengeStarted' | 'reportChallengeSettled'\n>\n\nexport async function driveEmbeddedChallenge(\n  lifecycle: ChallengeLifecycle,\n  operationId: string,\n  port: EmbeddedChallengePort\n): Promise<EmbeddedChallengeOutcome> {\n  const state = lifecycle.get(operationId)\n  if (\n    state?.phase !== 'pending' ||\n    state.presentation !== 'embedded' ||\n    state.challenge?.status !== 'required'\n  ) {\n    return 'not_required'\n  }\n\n  lifecycle.reportChallengeStarted(operationId)\n  const outcome = await settle(port, state.challenge.clientSecret)\n  lifecycle.reportChallengeSettled(operationId, outcome)\n  return outcome\n}\n\nasync function settle(\n  port: EmbeddedChallengePort,\n  clientSecret: string\n): Promise<'completed' | 'failed'> {\n  try {\n    const result = await port.handleNextAction(clientSecret)\n    if (result.error !== undefined) return 'failed'\n    if (\n      result.paymentIntent !== undefined &&\n      UNMOVED_INTENT_STATUSES.has(result.paymentIntent.status)\n    ) {\n      return 'failed'\n    }\n    return 'completed'\n  } catch {\n    return 'failed'\n  }\n}\n","/**\n * The subscription commands on the shared operation lifecycle: subscribe,\n * resubscribe, cancel, and the payment portal. Each one encodes its request\n * against the generated contract, issues it through `lifecycle.begin`, and\n * waits for the settled operation; polling, routing, recovery, and telemetry\n * stay in the lifecycle. `previewSubscribe` sits beside them without a\n * lifecycle: it only quotes a change.\n *\n * No command decides for the server whether a transition is allowed\n * (`../../../docs/billing-command-eligibility.md`). Server codes are matched\n * against the closed set named here; a code outside it reaches the caller only\n * as the transport's coded failure.\n */\nimport {\n  zCancelBillingOpResponse,\n  zCancelSubscriptionResponse2,\n  zPaymentPortalResponse,\n  zPreviewPlanInfo,\n  zPreviewSubscribeRequest,\n  zPreviewSubscribeResponse,\n  zResubscribeResponse,\n  zSubscribeRequest,\n  zSubscribeResponse\n} from '@comfyorg/ingest-types/zod'\nimport { z } from 'zod'\n\nimport type { BillingFailure, BillingTransport } from './billingContracts.js'\nimport { matchesServerCode } from './billingContracts.js'\nimport type { CapabilitiesReader } from './capabilities.js'\nimport type { CreditsReader } from './credits.js'\nimport type {\n  BillingOperationLifecycle,\n  IssuedBillingOperation\n} from './operationLifecycle.js'\nimport { operationRoute } from './operationLifecycle.js'\nimport type {\n  BillingOperationKind,\n  BillingOperationState,\n  PendingBillingOperation\n} from './operationState.js'\nimport { validateActionUrl } from './operationState.js'\nimport type { ParsedBillingBody } from './sharedRead.js'\nimport { readValidatedBillingResponse } from './sharedRead.js'\nimport type { BillingStatusReader } from './status.js'\nimport { SubscriptionDiscountSchema } from './subscriptionDiscount.js'\nimport { wireCents } from './wireCents.js'\n\nexport const SUBSCRIBE_ROUTE = '/billing/subscribe'\nexport const RESUBSCRIBE_ROUTE = '/billing/subscription/resubscribe'\nexport const CANCEL_SUBSCRIPTION_ROUTE = '/billing/subscription/cancel'\nexport const PAYMENT_PORTAL_ROUTE = '/billing/payment-portal'\nexport const PREVIEW_SUBSCRIBE_ROUTE = '/billing/preview-subscribe'\n\nexport function cancelOperationRoute(operationId: string): string {\n  return `${operationRoute(operationId)}/cancel`\n}\n\n/** The closed set of `serverCode` values these commands act on. */\nconst NO_ACTIVE_SUBSCRIPTION_SERVER_CODE = 'NO_ACTIVE_SUBSCRIPTION'\nconst REACTIVATION_CONFIRMATION_REQUIRED_SERVER_CODE =\n  'REACTIVATION_CONFIRMATION_REQUIRED'\nconst NOT_SCHEDULED_FOR_CANCELLATION_SERVER_CODE =\n  'NOT_SCHEDULED_FOR_CANCELLATION'\nconst ALREADY_CANCELED_SERVER_CODE = 'ALREADY_CANCELED'\nconst SUBSCRIPTION_QUOTE_STALE_SERVER_CODE = 'SUBSCRIPTION_QUOTE_STALE'\nconst SUBSCRIPTION_CHANGE_IN_PROGRESS_SERVER_CODE =\n  'SUBSCRIPTION_CHANGE_IN_PROGRESS'\nconst CANCEL_REFUSAL_SERVER_CODES = [\n  'NOT_CANCELABLE',\n  'PAYMENT_IN_FLIGHT'\n] as const\n\nexport type SubscribeInput = z.infer<typeof zSubscribeRequest>\n\nexport type TerminalBillingOperation = Exclude<\n  BillingOperationState,\n  PendingBillingOperation\n>\n\n/** Outcomes a subscription command adds to the shared `BillingErrorCode` set. */\nexport type SubscriptionCommandCode =\n  /** The input fails the generated request contract; nothing was sent. */\n  | 'INVALID_REQUEST'\n  /** `confirmation_token` and `saved_payment_method_id` were both given. */\n  | 'CONFLICTING_PAYMENT_METHOD'\n  /** The server wants the host to re-preview and resend with `confirm_reactivation`. */\n  | 'REACTIVATION_CONFIRMATION_REQUIRED'\n  | 'NO_ACTIVE_SUBSCRIPTION'\n  /** The server asked for a hosted payment step but offered no page for it. */\n  | 'MISSING_PAYMENT_METHOD_URL'\n  /** The quote no longer matches what the server would charge; re-preview. */\n  | 'QUOTE_STALE'\n\nexport type SubscriptionCommandFailure =\n  | BillingFailure\n  | { readonly status: 'error'; readonly code: SubscriptionCommandCode }\n\n/** What the subscribe route answered before the lifecycle drove the operation on. */\ntype SubscribeIssuedStatus = z.infer<typeof zSubscribeResponse>['status']\n\nexport interface SubscriptionCommandOutcome {\n  readonly phase: TerminalBillingOperation['phase']\n  /** Absent when the requested state already held and nothing was issued. */\n  readonly operation?: TerminalBillingOperation\n  /**\n   * The `status` the subscribe response carried, before the lifecycle settled\n   * the operation: `subscribed` is a plan the server activated on the spot,\n   * the other two are payment steps it could not complete without the\n   * customer. Absent for every other command, and whenever this call read no\n   * subscribe response at all: `begin` adopted an operation the server was\n   * already settling, or joined one another `subscription` command had in\n   * flight. Both land on `requiredPayment: true`, the side an operation the\n   * server is mid-payment on belongs to.\n   */\n  readonly issuedStatus?: SubscribeIssuedStatus\n}\n\nexport type SubscriptionCommandResult =\n  | { readonly status: 'ok'; readonly value: SubscriptionCommandOutcome }\n  | SubscriptionCommandFailure\n\n/**\n * Why the server kept a payment it was asked to cancel. `PAYMENT_IN_FLIGHT`:\n * the payment won the race and the operation will settle on its own.\n * `NOT_CANCELABLE`: the operation is not one waiting on authentication.\n */\nexport type CancelRefusalCode = (typeof CANCEL_REFUSAL_SERVER_CODES)[number]\n\n/**\n * The server's answer to cancelling a pending operation. `canceled`: dropped,\n * nothing charged, also for one already discarded. `cancel_requested`: the\n * cancel was delivered but has not settled; asking again is safe.\n */\nexport type CancelOperationResult =\n  | { readonly status: 'canceled' | 'cancel_requested' }\n  | { readonly status: 'not_canceled'; readonly code: CancelRefusalCode }\n  | BillingFailure\n\nexport type PaymentPortalResult =\n  | { readonly status: 'ok'; readonly value: { readonly url: string } }\n  | BillingFailure\n\nconst PlanInfoSchema = zPreviewPlanInfo.extend({\n  credits_cents: wireCents,\n  price_cents: wireCents,\n  list_price_cents: wireCents.optional(),\n  monthly_list_price_cents: wireCents.optional(),\n  monthly_price_cents: wireCents.optional(),\n  seat_summary: zPreviewPlanInfo.shape.seat_summary.extend({\n    total_cost_cents: wireCents,\n    total_credits_cents: wireCents\n  })\n})\n\nconst PreviewSchema = zPreviewSubscribeResponse.extend({\n  amount_due_cents: wireCents.optional(),\n  cost_next_period_cents: wireCents,\n  cost_today_cents: wireCents,\n  credits_next_period_cents: wireCents,\n  credits_today_cents: wireCents,\n  credits_today: wireCents.nonnegative().optional(),\n  credits_next_period: wireCents.nonnegative().optional(),\n  renewal_amount_cents: wireCents.optional(),\n  subtotal_cents: wireCents.optional(),\n  balance_applied_cents: wireCents.optional(),\n  proration_remaining_cents: wireCents.optional(),\n  proration_unused_cents: wireCents.optional(),\n  current_plan: PlanInfoSchema.optional(),\n  new_plan: PlanInfoSchema,\n  discounts: z.array(SubscriptionDiscountSchema).optional()\n})\n\n/**\n * The quote the server returns for a plan change, in the generated field names.\n *\n * Its strings are product copy, not `serverCode`'s kind of machine identifier:\n * a `discounts[]` entry describes a discount the server applied, and a\n * `promotion` one carries back the very `promotionCode` the caller sent, so a\n * host renders `code` and `name` rather than matching them.\n */\nexport type SubscriptionPreview = z.infer<typeof PreviewSchema>\n\nexport interface PreviewSubscribeInput {\n  readonly planSlug: string\n  readonly promotionCode?: string\n  readonly teamCreditStopId?: string\n  readonly checkoutAttemptId?: string\n}\n\nexport interface PreviewSubscribeOptions {\n  readonly signal?: AbortSignal\n  readonly timeoutMs?: number\n}\n\nexport type PreviewSubscribeResult =\n  | { readonly status: 'ok'; readonly value: SubscriptionPreview }\n  | SubscriptionCommandFailure\n\nexport interface BillingCommandsOptions {\n  readonly transport: BillingTransport\n  readonly lifecycle: BillingOperationLifecycle\n  readonly statusReader: BillingStatusReader\n  readonly capabilities: CapabilitiesReader\n  readonly credits: CreditsReader\n  /** One key per attempt; the backend's dedupe key and the transport's replay gate. */\n  readonly idempotencyKey?: () => string\n}\n\nexport interface BillingCommands {\n  subscribe: (input: SubscribeInput) => Promise<SubscriptionCommandResult>\n  /**\n   * Quotes a plan change without issuing an operation or touching the\n   * capability cache: a read the backend happens to shape as a POST. It sends\n   * no idempotency key, so a stale token surfaces as the transient\n   * `REQUEST_FAILED` that callers already retry rather than as a denial.\n   */\n  previewSubscribe: (\n    input: PreviewSubscribeInput,\n    options?: PreviewSubscribeOptions\n  ) => Promise<PreviewSubscribeResult>\n  resubscribe: () => Promise<SubscriptionCommandResult>\n  cancelSubscription: () => Promise<SubscriptionCommandResult>\n  /**\n   * Asks the server to drop an operation still waiting on the customer's\n   * authentication. Any answer that names the operation's fate wakes the\n   * lifecycle, so the operation it follows catches up with the server.\n   */\n  cancelOperation: (operationId: string) => Promise<CancelOperationResult>\n  /** Returns the portal URL; the host decides how to open it. */\n  openPaymentPortal: (input: {\n    readonly returnUrl?: string\n  }) => Promise<PaymentPortalResult>\n}\n\ninterface IssuedOutcome {\n  readonly status: 'ok'\n  readonly value: IssuedBillingOperation\n  readonly issuedStatus?: SubscribeIssuedStatus\n}\n\ntype IssueOutcome =\n  | IssuedOutcome\n  /** The server refused because the requested state already holds. */\n  | { readonly status: 'already_held' }\n  | SubscriptionCommandFailure\n\nconst ALREADY_HELD: SubscriptionCommandResult = {\n  status: 'ok',\n  value: { phase: 'succeeded' }\n}\n\nfunction coded(code: SubscriptionCommandCode): SubscriptionCommandFailure {\n  return { status: 'error', code }\n}\n\n/**\n * A server code is trusted as state only from a 4xx: a 5xx echoing the code\n * is an upstream failure that happens to carry it, and the state it names\n * cannot be assumed to hold.\n */\nfunction refusedWith(failure: BillingFailure, serverCode: string): boolean {\n  return (\n    matchesServerCode(failure, serverCode) &&\n    failure.httpStatus !== undefined &&\n    failure.httpStatus >= 400 &&\n    failure.httpStatus < 500\n  )\n}\n\n/**\n * The server's refusal because another subscription operation is still open\n * is the same answer the lifecycle gives when it sees that operation first.\n */\nfunction refusedWhilePending(failure: BillingFailure): BillingFailure {\n  return refusedWith(failure, SUBSCRIPTION_CHANGE_IN_PROGRESS_SERVER_CODE)\n    ? { ...failure, code: 'OPERATION_ALREADY_PENDING' }\n    : failure\n}\n\nfunction mapServerCode(\n  failure: BillingFailure,\n  alreadyHeldCode: string\n): IssueOutcome {\n  // A server code the caller's request already satisfies is a success.\n  if (refusedWith(failure, alreadyHeldCode)) {\n    return { status: 'already_held' }\n  }\n  return matchesServerCode(failure, NO_ACTIVE_SUBSCRIPTION_SERVER_CODE)\n    ? coded('NO_ACTIVE_SUBSCRIPTION')\n    : refusedWhilePending(failure)\n}\n\nfunction dropEmpty(value: string | undefined): string | undefined {\n  return value === '' ? undefined : value\n}\n\nfunction previewRequestBody(input: PreviewSubscribeInput): unknown {\n  const { planSlug, promotionCode, teamCreditStopId, checkoutAttemptId } = input\n  return {\n    plan_slug: planSlug,\n    ...(promotionCode === undefined ? {} : { promotion_code: promotionCode }),\n    ...(teamCreditStopId === undefined\n      ? {}\n      : { team_credit_stop_id: teamCreditStopId }),\n    ...(checkoutAttemptId === undefined\n      ? {}\n      : { checkout_attempt_id: checkoutAttemptId })\n  }\n}\n\nexport function createBillingCommands(\n  options: BillingCommandsOptions\n): BillingCommands {\n  const {\n    transport,\n    lifecycle,\n    statusReader,\n    capabilities,\n    credits,\n    idempotencyKey = () => crypto.randomUUID()\n  } = options\n\n  async function refreshAfterSuccess(): Promise<void> {\n    capabilities.invalidate()\n    await Promise.all([credits.read(), statusReader.read()])\n  }\n\n  function post<T>(\n    route: string,\n    body: unknown,\n    parse: (body: unknown) => ParsedBillingBody<T>,\n    key?: string\n  ) {\n    return readValidatedBillingResponse(\n      transport,\n      {\n        method: 'POST',\n        route,\n        body,\n        ...(key === undefined ? {} : { idempotencyKey: key })\n      },\n      parse\n    )\n  }\n\n  async function settle(\n    kind: BillingOperationKind,\n    issue: () => Promise<IssueOutcome>\n  ): Promise<SubscriptionCommandResult> {\n    // The lifecycle carries only the shared codes; the command's own verdict\n    // and what it read off the issuing response wait here for `begin` to\n    // return. Both stay unset whenever `begin` never ran this caller's issue:\n    // it adopted an operation the server was already settling, or joined one\n    // another command of the same kind had in flight.\n    const verdict: { value?: Exclude<IssueOutcome, { status: 'ok' }> } = {}\n    const issued: { value?: IssuedOutcome } = {}\n    const began = await lifecycle.begin(kind, async () => {\n      const outcome = await issue()\n      if (outcome.status === 'ok') {\n        issued.value = outcome\n        return outcome\n      }\n      verdict.value = outcome\n      return { status: 'error', code: 'REQUEST_FAILED' }\n    })\n    if (verdict.value !== undefined) {\n      if (verdict.value.status !== 'already_held') return verdict.value\n      await refreshAfterSuccess()\n      return ALREADY_HELD\n    }\n    if (began.status === 'error') return began\n\n    const settled = lifecycle.settled(began.value.id)\n    const operation = settled === undefined ? began.value : await settled\n    if (operation.phase === 'pending') {\n      return { status: 'error', code: 'SUPERSEDED' }\n    }\n    if (operation.phase === 'succeeded') await refreshAfterSuccess()\n    const issuedStatus = issued.value?.issuedStatus\n    return {\n      status: 'ok',\n      value: {\n        phase: operation.phase,\n        operation,\n        ...(issuedStatus === undefined ? {} : { issuedStatus })\n      }\n    }\n  }\n\n  async function issueSubscribe(input: SubscribeInput): Promise<IssueOutcome> {\n    const key = idempotencyKey()\n    const response = await post(\n      SUBSCRIBE_ROUTE,\n      { ...input, idempotency_key: key },\n      (body) => zSubscribeResponse.safeParse(body),\n      key\n    )\n    if (response.status === 'error') {\n      if (\n        matchesServerCode(\n          response,\n          REACTIVATION_CONFIRMATION_REQUIRED_SERVER_CODE\n        )\n      ) {\n        return coded('REACTIVATION_CONFIRMATION_REQUIRED')\n      }\n      return refusedWith(response, SUBSCRIPTION_QUOTE_STALE_SERVER_CODE)\n        ? coded('QUOTE_STALE')\n        : refusedWhilePending(response)\n    }\n    const { billing_op_id, status, payment_method_url } = response.value.data\n    if (status !== 'needs_payment_method') {\n      return {\n        status: 'ok',\n        value: { operationId: billing_op_id },\n        issuedStatus: status\n      }\n    }\n    if (payment_method_url === undefined) {\n      return coded('MISSING_PAYMENT_METHOD_URL')\n    }\n    return {\n      status: 'ok',\n      value: { operationId: billing_op_id, actionUrl: payment_method_url },\n      issuedStatus: status\n    }\n  }\n\n  async function issueResubscribe(): Promise<IssueOutcome> {\n    const key = idempotencyKey()\n    const response = await post(\n      RESUBSCRIBE_ROUTE,\n      { idempotency_key: key },\n      (body) => zResubscribeResponse.safeParse(body),\n      key\n    )\n    if (response.status === 'error') {\n      return mapServerCode(response, NOT_SCHEDULED_FOR_CANCELLATION_SERVER_CODE)\n    }\n    return {\n      status: 'ok',\n      value: { operationId: response.value.data.billing_op_id }\n    }\n  }\n\n  async function issueCancel(): Promise<IssueOutcome> {\n    const key = idempotencyKey()\n    const response = await post(\n      CANCEL_SUBSCRIPTION_ROUTE,\n      { idempotency_key: key },\n      (body) => zCancelSubscriptionResponse2.safeParse(body),\n      key\n    )\n    if (response.status === 'error') {\n      return mapServerCode(response, ALREADY_CANCELED_SERVER_CODE)\n    }\n    return {\n      status: 'ok',\n      value: { operationId: response.value.data.billing_op_id }\n    }\n  }\n\n  const resubscribe = () => settle('subscription', issueResubscribe)\n\n  async function subscribe(\n    input: SubscribeInput\n  ): Promise<SubscriptionCommandResult> {\n    const confirmationToken = dropEmpty(input.confirmation_token)\n    const savedPaymentMethodId = dropEmpty(input.saved_payment_method_id)\n    if (confirmationToken !== undefined && savedPaymentMethodId !== undefined) {\n      return coded('CONFLICTING_PAYMENT_METHOD')\n    }\n    // JSON drops `undefined` but keeps `''`, so an empty credential would\n    // reach the server as a present-but-meaningless value.\n    const request: SubscribeInput = {\n      ...input,\n      confirmation_token: confirmationToken,\n      saved_payment_method_id: savedPaymentMethodId\n    }\n    if (!zSubscribeRequest.safeParse(request).success) {\n      return coded('INVALID_REQUEST')\n    }\n\n    return settle('subscription', () => issueSubscribe(request))\n  }\n\n  async function previewSubscribe(\n    input: PreviewSubscribeInput,\n    options: PreviewSubscribeOptions = {}\n  ): Promise<PreviewSubscribeResult> {\n    const body = previewRequestBody(input)\n    if (!zPreviewSubscribeRequest.safeParse(body).success) {\n      return coded('INVALID_REQUEST')\n    }\n    const response = await readValidatedBillingResponse(\n      transport,\n      {\n        method: 'POST',\n        route: PREVIEW_SUBSCRIBE_ROUTE,\n        body,\n        ...(options.signal === undefined ? {} : { signal: options.signal }),\n        ...(options.timeoutMs === undefined\n          ? {}\n          : { timeoutMs: options.timeoutMs })\n      },\n      (raw) => PreviewSchema.safeParse(raw)\n    )\n    return response.status === 'error'\n      ? response\n      : { status: 'ok', value: response.value.data }\n  }\n\n  async function openPaymentPortal(input: {\n    readonly returnUrl?: string\n  }): Promise<PaymentPortalResult> {\n    const response = await post(\n      PAYMENT_PORTAL_ROUTE,\n      input.returnUrl === undefined ? {} : { return_url: input.returnUrl },\n      (body) => zPaymentPortalResponse.safeParse(body)\n    )\n    if (response.status === 'error') return response\n    const url = validateActionUrl(response.value.data.url)\n    if (url === undefined) {\n      return {\n        status: 'error',\n        code: 'MALFORMED_RESPONSE',\n        httpStatus: response.value.httpStatus\n      }\n    }\n    return { status: 'ok', value: { url } }\n  }\n\n  async function cancelOperation(\n    operationId: string\n  ): Promise<CancelOperationResult> {\n    const response = await post(\n      cancelOperationRoute(operationId),\n      undefined,\n      (body) => zCancelBillingOpResponse.safeParse(body)\n    )\n    if (response.status === 'error') {\n      const refusal = CANCEL_REFUSAL_SERVER_CODES.find((code) =>\n        refusedWith(response, code)\n      )\n      if (refusal === undefined) return response\n      lifecycle.wake()\n      return { status: 'not_canceled', code: refusal }\n    }\n    lifecycle.wake()\n    return { status: response.value.data.status }\n  }\n\n  return {\n    subscribe,\n    previewSubscribe,\n    resubscribe,\n    cancelSubscription: () => settle('cancel', issueCancel),\n    cancelOperation,\n    openPaymentPortal\n  }\n}\n","/**\n * The copy keys behind the payment projection, with a default English table\n * a host may override — except the safety line, which only the projection's\n * `noChargeConfirmed` may ever unlock.\n */\nimport type {\n  BillingDeclineReason,\n  BillingRecoveryAction\n} from './operationState.js'\nimport type {\n  PaymentProjection,\n  PaymentReasonKey,\n  PaymentStep\n} from './paymentProjection.js'\n\nexport type PaymentCopyKey =\n  | `billing.step.${PaymentStep}.header`\n  | `billing.step.${PaymentStep}.body`\n  | `billing.reason.${PaymentReasonKey}`\n  | `billing.recovery.${BillingRecoveryAction}`\n  | 'billing.action.retry'\n  | 'billing.action.replace_payment_method'\n  | 'billing.action.contact_support'\n  | 'billing.action.continue_verification'\n  | 'billing.safety.nothing_was_charged'\n\nconst SAFETY_KEY = 'billing.safety.nothing_was_charged'\n\nexport const DEFAULT_PAYMENT_COPY: Readonly<Record<PaymentCopyKey, string>> = {\n  'billing.step.select.header': 'Choose an option',\n  'billing.step.select.body': 'Select a plan or credit amount.',\n  'billing.step.preview.header': 'Review payment',\n  'billing.step.preview.body': 'Confirm your selection.',\n  'billing.step.verifying.header': 'Verify your payment',\n  'billing.step.verifying.body': 'Complete verification to continue.',\n  'billing.step.canceled.header': 'Payment canceled',\n  'billing.step.canceled.body': 'The payment was canceled.',\n  'billing.step.declined.header': 'Payment declined',\n  'billing.step.declined.body': 'Try another payment method.',\n  'billing.step.processing_error.header': 'Payment could not be processed',\n  'billing.step.processing_error.body': 'Please try again.',\n  'billing.step.payment_received_hold.header': 'Payment received',\n  'billing.step.payment_received_hold.body':\n    'We are finishing your account update.',\n  'billing.step.success.header': 'Payment complete',\n  'billing.step.success.body': 'Your account is updated.',\n  'billing.reason.generic': 'Something went wrong.',\n  'billing.reason.checkout_expired':\n    'This checkout expired. Start again when you are ready.',\n  'billing.reason.card_declined': 'Your bank declined the payment.',\n  'billing.reason.insufficient_funds': 'Your bank reported insufficient funds.',\n  'billing.reason.expired_card': 'This card has expired.',\n  'billing.reason.incorrect_cvc': 'The security code did not match.',\n  'billing.reason.authentication_required':\n    'Your bank requires authentication.',\n  'billing.reason.authentication_failed':\n    'Authentication with your bank did not complete.',\n  'billing.reason.payment_not_completed': 'The payment was not completed.',\n  'billing.reason.processing_error':\n    'The payment could not be processed right now.',\n  'billing.recovery.retry': 'Please try again.',\n  'billing.recovery.replace_payment_method':\n    'Try again with a different payment method.',\n  'billing.recovery.authenticate_payment':\n    'Try again and complete the verification your bank asks for.',\n  'billing.recovery.contact_support':\n    'This payment cannot be retried. Contact support@comfy.org and we will help you finish it.',\n  'billing.action.retry': 'Try again',\n  'billing.action.replace_payment_method': 'Use a different payment method',\n  'billing.action.contact_support': 'Contact support',\n  'billing.action.continue_verification': 'Continue verification',\n  [SAFETY_KEY]: 'Nothing was charged.'\n}\n\n/** The host's toast detail for a payment the server declined. */\nexport type DeclineDetailKey =\n  | 'insufficientFundsDetail'\n  | 'expiredCardDetail'\n  | 'incorrectCvcDetail'\n  | 'authenticationFailedDetail'\n  | 'processingErrorDetail'\n  | 'paymentDeclinedDetail'\n\nexport function declineDetailKey(\n  reason: BillingDeclineReason\n): DeclineDetailKey {\n  switch (reason) {\n    case 'insufficient_funds':\n      return 'insufficientFundsDetail'\n    case 'expired_card':\n      return 'expiredCardDetail'\n    case 'incorrect_cvc':\n      return 'incorrectCvcDetail'\n    case 'authentication_required':\n    case 'authentication_failed':\n    case 'payment_not_completed':\n      return 'authenticationFailedDetail'\n    case 'processing_error':\n      return 'processingErrorDetail'\n    case 'card_declined':\n    case 'generic':\n      return 'paymentDeclinedDetail'\n  }\n}\n\nexport function createPaymentCopy(\n  overrides: Partial<Record<PaymentCopyKey, string>> = {}\n): Readonly<Record<PaymentCopyKey, string>> {\n  const { [SAFETY_KEY]: _protected, ...safe } = overrides\n  return { ...DEFAULT_PAYMENT_COPY, ...safe }\n}\n\nexport interface PaymentCopyKeys {\n  readonly header: PaymentCopyKey\n  /** The server's recovery line when it names one, else the step's own body. */\n  readonly body: PaymentCopyKey\n  readonly reason?: PaymentCopyKey\n  readonly safety?: typeof SAFETY_KEY\n}\n\nfunction recoveryCopyKey(\n  action: BillingRecoveryAction | undefined\n): PaymentCopyKey | undefined {\n  if (action === undefined) return undefined\n  const key = `billing.recovery.${action}` as const\n  return key in DEFAULT_PAYMENT_COPY ? key : undefined\n}\n\nexport function paymentCopyKeys(\n  projection: PaymentProjection\n): PaymentCopyKeys {\n  return {\n    header: `billing.step.${projection.step}.header`,\n    body:\n      recoveryCopyKey(projection.recoveryAction) ??\n      `billing.step.${projection.step}.body`,\n    ...(projection.reasonKey === undefined\n      ? {}\n      : { reason: `billing.reason.${projection.reasonKey}` as const }),\n    ...(projection.step === 'canceled' && projection.noChargeConfirmed\n      ? { safety: SAFETY_KEY }\n      : {})\n  }\n}\n","/**\n * The top-up command: one credit purchase mapped onto the shared billing\n * lifecycle. This module owns the request and response shapes and nothing\n * else — the status-read gate, single-flight, polling, routing, the pointer,\n * failure meaning, and telemetry all come from the lifecycle it runs on.\n *\n * The result is a command-level union rather than an extension of\n * `BillingErrorCode`: what a top-up can conclude (refused by capability,\n * declined by the provider, not available on this backend) is the command's\n * own vocabulary, and the terminal operation is embedded whenever one was\n * observed so a host reads the coded decline and recovery action from it.\n */\nimport {\n  zCreateTopupCheckoutRequest,\n  zCreateTopupCheckoutResponse,\n  zCreateTopupRequest,\n  zCreateTopupResponse,\n  zTopupQuoteResponse\n} from '@comfyorg/ingest-types/zod'\n\nimport type {\n  BillingFailure,\n  BillingResult,\n  BillingTransport\n} from './billingContracts.js'\nimport { matchesServerCode } from './billingContracts.js'\nimport type { CapabilitiesReader } from './capabilities.js'\nimport type { CapabilityDenialReason } from './capabilityDenials.js'\nimport type { CreditsReader } from './credits.js'\nimport type {\n  BillingOperationLifecycle,\n  IssuedBillingOperation\n} from './operationLifecycle.js'\nimport type {\n  BillingOperationState,\n  FailedBillingOperation\n} from './operationState.js'\nimport { isTerminal, validateActionUrl } from './operationState.js'\nimport { readValidatedBillingResponse } from './sharedRead.js'\nimport { wireCents } from './wireCents.js'\n\nexport const TOPUP_ROUTE = '/billing/topup'\n/**\n * The hosted variant: a provider-hosted Checkout session with no operation to\n * observe. The purchase happens on the returned page and the credits land\n * through a webhook, so completion is the host's return plus a balance watch.\n */\nexport const TOPUP_CHECKOUT_ROUTE = '/billing/topup/checkout'\n/** A read the backend shapes as a POST: nothing is charged or reserved. */\nexport const TOPUP_QUOTE_ROUTE = '/billing/topup/quote'\n\n/** The server's own server code for an amount it will not sell. */\nconst INVALID_AMOUNT_SERVER_CODE = 'INVALID_AMOUNT'\n\nconst TopupQuoteSchema = zTopupQuoteResponse.extend({\n  amount_cents: wireCents,\n  credits: wireCents\n})\n\n/**\n * What the server says an amount buys. `credits` is the server's display\n * count; `expiresAt` is when the grant would lapse, which the server may\n * move, so a host never states the expiry policy itself.\n */\nexport interface TopupQuote {\n  readonly amountCents: number\n  readonly credits: number\n  readonly expiresAt: string\n}\n\nexport type TopupQuoteResult =\n  | { readonly status: 'ok'; readonly value: TopupQuote }\n  | BillingFailure\n  | TopupNotAvailable\n  | TopupInvalidAmount\n\nexport interface QuoteTopupInput {\n  readonly amountCents: number\n  readonly signal?: AbortSignal\n}\n\n/** The one coded error body this command acts on; every other code stays a `BillingFailure`. */\nconst NO_PAYMENT_METHOD_SERVER_CODE = 'NO_PAYMENT_METHOD'\n\ntype OperationIn<P extends BillingOperationState['phase']> = Extract<\n  BillingOperationState,\n  { readonly phase: P }\n>\n\nexport interface TopupSucceeded {\n  readonly status: 'ok'\n  readonly operation: OperationIn<'succeeded'>\n  /**\n   * True once the balance read after settlement exceeds the one read before\n   * the command. False is \"payment received, credits pending\": the purchase\n   * settled and the balance has not caught up, or no baseline was readable.\n   */\n  readonly creditsReconciled: boolean\n}\n\nexport interface TopupDeclined {\n  readonly status: 'declined'\n  readonly operation: FailedBillingOperation\n}\n\n/** The lifecycle stopped observing without a verdict; the id is the host's handle to support. */\nexport interface TopupUnsettled {\n  readonly status: 'unsettled'\n  readonly operation: OperationIn<'timed_out' | 'reconciliation_needed'>\n}\n\n/** The server resolved `can_top_up` false for this scope; nothing was sent. */\nexport interface TopupDenied {\n  readonly status: 'error'\n  readonly code: 'ACCESS_DENIED'\n  readonly denial?: CapabilityDenialReason\n}\n\n/** The top-up route is not deployed on this backend. */\nexport interface TopupNotAvailable {\n  readonly status: 'error'\n  readonly code: 'NOT_AVAILABLE'\n}\n\nexport interface TopupNoPaymentMethod {\n  readonly status: 'error'\n  readonly code: 'NO_PAYMENT_METHOD'\n  readonly recoveryAction: 'replace_payment_method'\n}\n\n/** The amount fails the generated request contract; nothing was sent. */\nexport interface TopupInvalidAmount {\n  readonly status: 'error'\n  readonly code: 'INVALID_AMOUNT'\n}\n\nexport type TopupFailure =\n  | BillingFailure\n  | TopupDenied\n  | TopupNotAvailable\n  | TopupNoPaymentMethod\n  | TopupInvalidAmount\n\nexport type TopupResult =\n  | TopupSucceeded\n  | TopupDeclined\n  | TopupUnsettled\n  | TopupFailure\n\n/** The return URL fails the generated request contract; nothing was sent. */\nexport interface TopupInvalidReturnUrl {\n  readonly status: 'error'\n  readonly code: 'INVALID_RETURN_URL'\n}\n\n/**\n * A hosted Checkout session the host now sends the customer to. There is no\n * operation and none is invented: the host executes its `OpenUrlMode` on\n * `url`, and on return arms `createBalanceWatch` with `baselineMicros` to\n * learn that the credits landed.\n */\nexport interface HostedTopupCheckout {\n  readonly status: 'ok'\n  /** The provider-hosted Checkout page; https only. */\n  readonly url: string\n  /** The provider's session id, for support and log correlation. */\n  readonly sessionId?: string\n  /** The balance read before the session was created; absent when that read failed. */\n  readonly baselineMicros?: number\n}\n\nexport type HostedTopupCheckoutFailure =\n  | BillingFailure\n  | TopupDenied\n  | TopupNotAvailable\n  | TopupInvalidAmount\n  | TopupInvalidReturnUrl\n\nexport type HostedTopupCheckoutResult =\n  | HostedTopupCheckout\n  | HostedTopupCheckoutFailure\n\nexport interface CreateHostedTopupCheckoutInput {\n  readonly amountCents: number\n  /** Where the provider returns the customer; the backend allowlists its origin. */\n  readonly returnUrl: string\n  readonly signal?: AbortSignal\n}\n\nexport interface CreateTopupCheckoutInput {\n  readonly amountCents: number\n  /**\n   * Releases the capability read and the POST. Once the operation is adopted\n   * the lifecycle owns it, and the wait follows it to a terminal state.\n   */\n  readonly signal?: AbortSignal\n}\n\nexport interface TopupCommandOptions {\n  readonly transport: BillingTransport\n  readonly lifecycle: Pick<BillingOperationLifecycle, 'begin' | 'settled'>\n  readonly capabilities: Pick<CapabilitiesReader, 'read' | 'invalidate'>\n  readonly credits: Pick<CreditsReader, 'read'>\n  /** One key per POST attempt: the backend dedupes on it and the transport replays a 401 under it. */\n  readonly idempotencyKey?: () => string\n}\n\nexport interface TopupCommand {\n  /**\n   * Quotes an amount without starting anything. It does not check the plan\n   * tier or the payment method, so a quote does not promise the top-up will\n   * go through.\n   */\n  quoteTopup: (input: QuoteTopupInput) => Promise<TopupQuoteResult>\n  createTopupCheckout: (input: CreateTopupCheckoutInput) => Promise<TopupResult>\n  /**\n   * The route Workshop and Platform ship on today. Unlike\n   * `createTopupCheckout` it resolves as soon as the session exists, because\n   * nothing about the purchase can be observed until the customer returns.\n   */\n  createHostedTopupCheckout: (\n    input: CreateHostedTopupCheckoutInput\n  ) => Promise<HostedTopupCheckoutResult>\n}\n\nconst INVALID_AMOUNT = {\n  status: 'error',\n  code: 'INVALID_AMOUNT'\n} as const satisfies TopupInvalidAmount\n\nconst INVALID_RETURN_URL = {\n  status: 'error',\n  code: 'INVALID_RETURN_URL'\n} as const satisfies TopupInvalidReturnUrl\n\nconst NOT_AVAILABLE = {\n  status: 'error',\n  code: 'NOT_AVAILABLE'\n} as const satisfies TopupNotAvailable\n\nfunction validateHostedCheckoutInput(\n  input: CreateHostedTopupCheckoutInput\n): TopupInvalidAmount | TopupInvalidReturnUrl | undefined {\n  const parsed = zCreateTopupCheckoutRequest.safeParse({\n    amount_cents: input.amountCents,\n    return_url: input.returnUrl\n  })\n  if (parsed.success) return undefined\n  const fields = new Set(parsed.error.issues.map((issue) => issue.path[0]))\n  return fields.has('amount_cents') ? INVALID_AMOUNT : INVALID_RETURN_URL\n}\n\nconst SUPERSEDED = {\n  status: 'error',\n  code: 'SUPERSEDED'\n} as const satisfies BillingFailure\n\nfunction commandFailure(failure: BillingFailure): TopupFailure {\n  if (matchesServerCode(failure, NO_PAYMENT_METHOD_SERVER_CODE)) {\n    return {\n      status: 'error',\n      code: 'NO_PAYMENT_METHOD',\n      recoveryAction: 'replace_payment_method'\n    }\n  }\n  if (failure.httpStatus === 404) return NOT_AVAILABLE\n  return failure\n}\n\nexport function createTopupCommand(options: TopupCommandOptions): TopupCommand {\n  const {\n    transport,\n    lifecycle,\n    capabilities,\n    credits,\n    idempotencyKey = () => crypto.randomUUID()\n  } = options\n\n  async function issue(\n    amountCents: number,\n    signal: AbortSignal | undefined\n  ): Promise<BillingResult<IssuedBillingOperation>> {\n    // The schema coerces `amount_cents` to a bigint, which the transport\n    // could not serialize; the validated input is what travels, not the\n    // parsed output.\n    const body = {\n      amount_cents: amountCents,\n      idempotency_key: idempotencyKey()\n    }\n    const response = await readValidatedBillingResponse(\n      transport,\n      {\n        method: 'POST',\n        route: TOPUP_ROUTE,\n        body,\n        idempotencyKey: body.idempotency_key,\n        ...(signal === undefined ? {} : { signal })\n      },\n      (raw) => zCreateTopupResponse.safeParse(raw)\n    )\n    if (response.status === 'error') return response\n    // Adopted regardless of the response's own `status`: the first poll\n    // settles a synchronous result and carries the decline reason, which the\n    // POST response does not.\n    return {\n      status: 'ok',\n      value: { operationId: response.value.data.billing_op_id }\n    }\n  }\n\n  async function conclude(\n    operation: BillingOperationState,\n    baselineMicros: number | undefined\n  ): Promise<TopupResult> {\n    if (!isTerminal(operation)) return SUPERSEDED\n    switch (operation.phase) {\n      case 'succeeded': {\n        capabilities.invalidate()\n        const after = await credits.read()\n        return {\n          status: 'ok',\n          operation,\n          creditsReconciled:\n            baselineMicros !== undefined &&\n            after.status === 'ok' &&\n            after.value.balance.amount_micros > baselineMicros\n        }\n      }\n      case 'failed':\n        return { status: 'declined', operation }\n      case 'timed_out':\n      case 'reconciliation_needed':\n        return { status: 'unsettled', operation }\n      case 'superseded':\n        return SUPERSEDED\n    }\n  }\n\n  async function readTopupEligibility(\n    signal: AbortSignal | undefined\n  ): Promise<BillingFailure | TopupDenied | undefined> {\n    const allowed = await capabilities.read(\n      signal === undefined ? {} : { signal }\n    )\n    if (allowed.status === 'error') return allowed\n    if (allowed.value.capabilities.can_top_up) return undefined\n    const denial = allowed.value.denials.can_top_up\n    return {\n      status: 'error',\n      code: 'ACCESS_DENIED',\n      ...(denial === undefined ? {} : { denial })\n    }\n  }\n\n  async function createTopupCheckout(\n    input: CreateTopupCheckoutInput\n  ): Promise<TopupResult> {\n    const { amountCents, signal } = input\n    if (!zCreateTopupRequest.safeParse({ amount_cents: amountCents }).success) {\n      return INVALID_AMOUNT\n    }\n\n    const refused = await readTopupEligibility(signal)\n    if (refused) return refused\n\n    const baseline = await credits.read()\n    const baselineMicros =\n      baseline.status === 'ok'\n        ? baseline.value.balance.amount_micros\n        : undefined\n\n    // `begin` reports every failure as a `BillingFailure`; the command-level\n    // meaning of its own POST failure is kept here so a status-read failure\n    // is never mistaken for one.\n    let issueFailure: TopupFailure | undefined\n    const began = await lifecycle.begin('topup', async () => {\n      const issued = await issue(amountCents, signal)\n      if (issued.status === 'error') issueFailure = commandFailure(issued)\n      return issued\n    })\n    if (began.status === 'error') return issueFailure ?? began\n\n    const settled = lifecycle.settled(began.value.id)\n    if (settled === undefined) return SUPERSEDED\n    return conclude(await settled, baselineMicros)\n  }\n\n  async function issueHostedCheckout(\n    input: CreateHostedTopupCheckoutInput\n  ): Promise<BillingResult<Pick<HostedTopupCheckout, 'url' | 'sessionId'>>> {\n    const body = {\n      amount_cents: input.amountCents,\n      return_url: input.returnUrl,\n      idempotency_key: idempotencyKey()\n    }\n    const response = await readValidatedBillingResponse(\n      transport,\n      {\n        method: 'POST',\n        route: TOPUP_CHECKOUT_ROUTE,\n        body,\n        idempotencyKey: body.idempotency_key,\n        ...(input.signal === undefined ? {} : { signal: input.signal })\n      },\n      (raw) => zCreateTopupCheckoutResponse.safeParse(raw)\n    )\n    if (response.status === 'error') return response\n\n    // The generated contract only requires a URL; the page a host will open\n    // on the customer's behalf has to be https as well, like every\n    // continuation the lifecycle hands out.\n    const { data, httpStatus } = response.value\n    const url = validateActionUrl(data.checkout_url)\n    if (url === undefined) {\n      return { status: 'error', code: 'MALFORMED_RESPONSE', httpStatus }\n    }\n    return {\n      status: 'ok',\n      value: {\n        url,\n        ...(data.session_id === undefined ? {} : { sessionId: data.session_id })\n      }\n    }\n  }\n\n  async function createHostedTopupCheckout(\n    input: CreateHostedTopupCheckoutInput\n  ): Promise<HostedTopupCheckoutResult> {\n    const invalid = validateHostedCheckoutInput(input)\n    if (invalid) return invalid\n\n    const refused = await readTopupEligibility(input.signal)\n    if (refused) return refused\n\n    const baseline = await credits.read()\n    const session = await issueHostedCheckout(input)\n    if (session.status === 'error') {\n      return session.httpStatus === 404 ? NOT_AVAILABLE : session\n    }\n    return {\n      status: 'ok',\n      ...session.value,\n      ...(baseline.status === 'ok'\n        ? { baselineMicros: baseline.value.balance.amount_micros }\n        : {})\n    }\n  }\n\n  async function quoteTopup(input: QuoteTopupInput): Promise<TopupQuoteResult> {\n    const { amountCents, signal } = input\n    if (!wireCents.positive().safeParse(amountCents).success)\n      return INVALID_AMOUNT\n    const response = await readValidatedBillingResponse(\n      transport,\n      {\n        method: 'POST',\n        route: TOPUP_QUOTE_ROUTE,\n        body: { amount_cents: amountCents },\n        ...(signal === undefined ? {} : { signal })\n      },\n      (raw) => TopupQuoteSchema.safeParse(raw)\n    )\n    if (response.status === 'error') {\n      if (matchesServerCode(response, INVALID_AMOUNT_SERVER_CODE))\n        return INVALID_AMOUNT\n      return response.httpStatus === 404 ? NOT_AVAILABLE : response\n    }\n    const quote = response.value.data\n    return {\n      status: 'ok',\n      value: {\n        amountCents: quote.amount_cents,\n        credits: quote.credits,\n        expiresAt: quote.expires_at\n      }\n    }\n  }\n\n  return { quoteTopup, createTopupCheckout, createHostedTopupCheckout }\n}\n","import type { CustomerActionHold } from '@comfyorg/account-core/billing'\nimport { isBlockedOnCustomerPhase } from '@comfyorg/account-core/billing'\n\nimport type {\n  BillingAuthenticationState,\n  BillingOperationPhase\n} from '@/platform/workspace/api/workspaceApi'\nimport type { ToastId } from '@/types/toastId'\n\n// Re-exported so both rails read one definition: a second copy that drifted\n// would reintroduce the give-up bug this predicate exists to prevent.\nexport { isBlockedOnCustomerPhase }\n\ntype OperationStatus =\n  | 'pending'\n  | 'succeeded'\n  | 'failed'\n  | 'timeout'\n  | 'reconciliation_needed'\n\ninterface CustomerAttentionOperation {\n  readonly status: OperationStatus\n  readonly actionUrl: string | null\n  readonly authenticationState: BillingAuthenticationState | null\n  readonly phase?: BillingOperationPhase | null\n}\n\n/** The poller's rule for which operation a dialog must show instead of its first step. */\nexport function needsCustomerAttention(\n  operation: CustomerAttentionOperation\n): boolean {\n  return (\n    operation.status === 'reconciliation_needed' ||\n    (operation.status === 'pending' &&\n      (operation.actionUrl !== null ||\n        isBlockedOnCustomerPhase(operation.phase) ||\n        operation.authenticationState === 'requires_action' ||\n        operation.authenticationState === 'failed_retryable'))\n  )\n}\n\nexport type ProgressToastKind = 'processing' | 'action'\n\nexport interface ProgressToast {\n  id: ToastId\n  kind: ProgressToastKind\n}\n\ninterface ProgressToastOperation {\n  readonly actionUrl?: string | null\n  readonly phase?: BillingOperationPhase | null\n}\n\n/**\n * A checkout parked on a card with no link to offer is a state the customer\n * leaves by subscribing again, not a payment in flight, so no surface may\n * describe it as one. A served link turns it back into a verification ask.\n */\nexport function isParkedCheckout(operation: ProgressToastOperation): boolean {\n  return !operation.actionUrl && operation.phase === 'awaiting_payment_method'\n}\n\nexport function progressToastKind(\n  operation: ProgressToastOperation\n): ProgressToastKind | undefined {\n  if (operation.actionUrl) return 'action'\n  if (isParkedCheckout(operation)) return undefined\n  return 'processing'\n}\n\ninterface LegacyActionOperation {\n  readonly actionUrl: string | null\n  readonly authenticationState: BillingAuthenticationState | null\n  readonly isAuthenticating: boolean\n}\n\n/**\n * This store's surface offers the hosted link beside the embedded challenge,\n * and its challenge exists only while it holds the client secret. Rows that\n * intentionally differ from the SDK's `pendingOperationActionHold`:\n * - embedded with only an `action_url`: acts here, where the link is shown\n *   beside the challenge; the SDK's embedded surface never opens it.\n * - embedded checkout off with a retryable failure: waits here, where\n *   `authentication_state` is never read; the SDK's hosted surface shows the\n *   decline.\n */\nexport function legacyOperationActionHold(\n  operation: LegacyActionOperation,\n  holdsClientSecret: boolean\n): CustomerActionHold {\n  return {\n    authenticationState: operation.authenticationState,\n    offersHostedPage: operation.actionUrl !== null,\n    ...(holdsClientSecret && {\n      challenge: operation.isAuthenticating ? 'in_progress' : 'required'\n    })\n  }\n}\n","import { remoteConfig } from '@/platform/remoteConfig/remoteConfig'\n\n/**\n * The server's `/features` value when configured, this deployment's\n * build-time fallback otherwise. `remoteConfig` already carries this\n * document — fetched once at boot — so reading it here costs no extra\n * request; a non-string or empty server value is treated as absent.\n */\nexport function resolveStripePublishableKey(): string | undefined {\n  const fromServer = remoteConfig.value.stripe_publishable_key\n  return typeof fromServer === 'string' && fromServer !== ''\n    ? fromServer\n    : import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY\n}\n","declare const serverFactField: unique symbol\n\n/**\n * A server fact as received, tagged with the API field that answered it. It\n * reads as the plain value, but a gate typed as one rejects anything mixed in\n * by `||`, `&&`, `!` or a ternary. See ADR-API-SERVER-FACTS-0042.\n */\nexport type ServerFact<Field extends string, T = boolean> = T & {\n  readonly [serverFactField]: Field\n}\n\n/**\n * A `true` literal types as always truthy, so `fact || local` would collapse to\n * `fact` and pass the gate.\n */\nexport type FactValue<T> = T extends boolean ? boolean : T\n\n/**\n * The only constructor. Call it where a response is decoded or in a local\n * provider for a non-cloud build, never at a gate.\n */\nexport function receiveServerFact<Field extends string, T>(\n  _field: Field,\n  value: T\n): ServerFact<Field, FactValue<T>> {\n  return value as ServerFact<Field, FactValue<T>>\n}\n\n/** Local transient UI state may withhold a fact, never grant it. */\nexport function narrowServerFact<Field extends string>(\n  fact: ServerFact<Field>,\n  localAllows: boolean\n): ServerFact<Field> {\n  return localAllows ? fact : (false as ServerFact<Field>)\n}\n","import { onScopeDispose, watch } from 'vue'\n\nimport { webSessionUser } from '@/platform/auth/session/webSessionUser'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type { WorkspaceTelemetryContext } from '@/platform/telemetry/types'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\n\nconst reportedScopeMismatches = new Set<string>()\n\n/** Undefined until a workspace is selected. Reactive when read in an effect. */\nexport function getWorkspaceTelemetryContext():\n  | WorkspaceTelemetryContext\n  | undefined {\n  const workspace = useTeamWorkspaceStore().activeWorkspace\n  if (!workspace) return undefined\n  return {\n    workspace_id: workspace.id,\n    workspace_type: workspace.type,\n    workspace_role: workspace.role,\n    workspace_tier: workspace.subscriptionTier,\n    auth_rail: webSessionUser.value ? 'web_session' : 'token'\n  }\n}\n\nexport function syncWorkspaceTelemetryContext(): void {\n  watch(\n    getWorkspaceTelemetryContext,\n    (context) => useTelemetry()?.setWorkspaceContext(context),\n    { immediate: true }\n  )\n  onScopeDispose(() => useTelemetry()?.setWorkspaceContext(undefined))\n}\n\n/**\n * Reports a billing read that targeted the selected workspace and still\n * resolved for another. The event pages, so each pair reports once per page\n * load; a stuck scope would otherwise repeat on every refresh.\n */\nexport function reportWorkspaceScopeMismatch(\n  requestedWorkspaceId: string,\n  resolvedWorkspaceId: string\n): void {\n  const context = getWorkspaceTelemetryContext()\n  if (context?.workspace_id !== requestedWorkspaceId) return\n  const key = JSON.stringify([requestedWorkspaceId, resolvedWorkspaceId])\n  if (reportedScopeMismatches.has(key)) return\n  reportedScopeMismatches.add(key)\n\n  const resolved = useTeamWorkspaceStore().workspaces.find(\n    (workspace) => workspace.id === resolvedWorkspaceId\n  )\n  useTelemetry()?.trackWorkspaceScopeMismatch({\n    ...context,\n    resolved_workspace_id: resolvedWorkspaceId,\n    resolved_workspace_type: resolved?.type ?? 'unknown'\n  })\n}\n","import type { BillingCapabilitiesResponse } from '@comfyorg/ingest-types'\nimport {\n  createSharedComposable,\n  defaultDocument,\n  useEventListener\n} from '@vueuse/core'\nimport { computed, onScopeDispose, shallowRef, watch } from 'vue'\n\nimport { isCloud } from '@/platform/distribution/types'\nimport { receiveServerFact } from '@/platform/serverFacts/serverFact'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { onCapabilityRevision } from '@/platform/workspace/api/capabilityRevision'\nimport {\n  WorkspaceApiError,\n  workspaceApi\n} from '@/platform/workspace/api/workspaceApi'\nimport { readOnRail } from '@/platform/workspace/composables/readOnRail'\nimport { useBillingReadRail } from '@/platform/workspace/composables/useBillingReadRail'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { reportWorkspaceScopeMismatch } from '@/platform/workspace/telemetry/workspaceTelemetryContext'\nimport { useAuthStore } from '@/stores/authStore'\n\ntype CapabilityReadState =\n  | { status: 'idle' }\n  | {\n      status: 'pending' | 'denied'\n      authUid: string\n      workspaceId: string\n    }\n  | {\n      status: 'unavailable'\n      authUid: string\n      workspaceId: string\n      retryAt: number\n    }\n  | {\n      status: 'resolved'\n      authUid: string\n      workspaceId: string\n      response: BillingCapabilitiesResponse\n      refreshAt: number\n    }\n\n// A remaining lifetime below the floor means the client clock disagrees with\n// the server's, so it cannot pace the refetch and the fixed interval is used\n// instead; clamping it would only slow the loop. The ceiling bounds the\n// opposite skew, where a lagging clock reads expires_at as far in the future.\nconst MIN_REFRESH_DELAY_MS = 5_000\nconst MAX_REFRESH_DELAY_MS = 60 * 60 * 1000\nconst FALLBACK_REFRESH_DELAY_MS = 60_000\n// An outage fails every visible session at once, so a flat retry interval would\n// keep them retrying in lockstep. Consecutive failures double up to this\n// ceiling, and each delay is jittered to spread the sessions apart.\nconst MAX_RETRY_DELAY_MS = 5 * 60 * 1000\n\ninterface ActiveCapabilityRequest {\n  requestId: number\n  authUid: string\n  workspaceId: string\n  controller: AbortController\n  promise: Promise<void>\n}\n\n/**\n * The read itself, on whichever rail the tab is on. A revalidation already\n * knows the snapshot is stale — a mutation or the expiry timer said so — so it\n * bypasses the SDK's cache; the first read for a scope takes what the SDK\n * already holds, which is what the shared top-up flow read.\n */\nfunction readCapabilitiesResponse(\n  signal: AbortSignal,\n  revalidating: boolean\n): Promise<BillingCapabilitiesResponse | undefined> {\n  const rail = useBillingReadRail()\n  if (rail === null) return workspaceApi.getBillingCapabilities(signal)\n  return readOnRail(\n    () => rail.readCapabilities({ signal, forceRefresh: revalidating }),\n    'getBillingCapabilities'\n  )\n}\n\nfunction useBillingCapabilitiesInternal() {\n  const authStore = useAuthStore()\n  const workspaceStore = useTeamWorkspaceStore()\n  const readState = shallowRef<CapabilityReadState>({ status: 'idle' })\n  let initialized = false\n  let latestRequestId = 0\n  let activeRequest: ActiveCapabilityRequest | null = null\n  let refreshTimer: ReturnType<typeof setTimeout> | null = null\n  let readFailures = 0\n  let invalidatedRequestId = 0\n\n  const capabilities = computed(() => {\n    const userId = authStore.userId\n    const workspaceId = workspaceStore.activeWorkspaceId\n    const state = readState.value\n    if (\n      !userId ||\n      !workspaceId ||\n      state.status !== 'resolved' ||\n      state.authUid !== userId ||\n      state.workspaceId !== workspaceId ||\n      state.response.resolved_for.workspace_id !== workspaceId\n    ) {\n      return null\n    }\n\n    return state.response.capabilities\n  })\n  const hasResolvedCapabilities = computed(() => capabilities.value !== null)\n  const readUnavailableForCurrentScope = computed(() => {\n    const state = readState.value\n    return (\n      state.status === 'unavailable' &&\n      state.authUid === authStore.userId &&\n      state.workspaceId === workspaceStore.activeWorkspaceId\n    )\n  })\n  const canTopUp = computed(() => {\n    if (!isCloud) return workspaceStore.activeWorkspace?.role !== 'member'\n    // An unreadable capability keeps top-up available only for owners, so a\n    // transient outage does not strand the one role that can actually top up.\n    // Every other role - including an unresolved one - fails closed.\n    return (\n      capabilities.value?.can_top_up ??\n      (readUnavailableForCurrentScope.value &&\n        workspaceStore.activeWorkspace?.role === 'owner')\n    )\n  })\n  const canSubscribeSelfServe = computed(\n    () => capabilities.value?.can_subscribe_self_serve ?? false\n  )\n  const canCancel = computed(() => capabilities.value?.can_cancel ?? false)\n  const canReactivate = computed(\n    () => capabilities.value?.can_reactivate ?? false\n  )\n  const canChangeSeats = computed(\n    () => capabilities.value?.can_change_seats ?? false\n  )\n  const canManageMembers = computed(() =>\n    receiveServerFact(\n      'can_manage_members',\n      capabilities.value?.can_manage_members ?? false\n    )\n  )\n  const canInviteMembers = computed(() =>\n    receiveServerFact(\n      'can_invite_members',\n      capabilities.value?.can_invite_members ?? false\n    )\n  )\n  const canDowngradeToPersonal = computed(\n    () => capabilities.value?.can_downgrade_to_personal ?? false\n  )\n  const isReady = computed(() => {\n    if (!isCloud) return true\n    const state = readState.value\n    if (state.status === 'idle' || state.status === 'pending') return false\n    return (\n      state.authUid === authStore.userId &&\n      state.workspaceId === workspaceStore.activeWorkspaceId\n    )\n  })\n\n  const snapshotAuthoritative = computed(() => {\n    if (!isCloud) return true\n    const state = readState.value\n    if (state.status !== 'resolved' && state.status !== 'denied') return false\n    return (\n      state.authUid === authStore.userId &&\n      state.workspaceId === workspaceStore.activeWorkspaceId\n    )\n  })\n\n  function trackCapabilityRead(succeeded: boolean): void {\n    useTelemetry()?.trackBillingEvent({\n      operation: 'capability_read',\n      ...(succeeded\n        ? { stage: 'succeeded', outcome: 'success' }\n        : { stage: 'failed', outcome: 'failure' })\n    })\n  }\n\n  function clearRefreshTimer(): void {\n    if (refreshTimer === null) return\n    clearTimeout(refreshTimer)\n    refreshTimer = null\n  }\n\n  function scheduledRefreshAt(state: CapabilityReadState): number | null {\n    if (state.status === 'resolved') return state.refreshAt\n    return state.status === 'unavailable' ? state.retryAt : null\n  }\n\n  /** Requires `readFailures` to already count this failure. */\n  function unavailableState(\n    authUid: string,\n    workspaceId: string\n  ): CapabilityReadState {\n    const delay = Math.min(\n      FALLBACK_REFRESH_DELAY_MS * 2 ** (readFailures - 1),\n      MAX_RETRY_DELAY_MS\n    )\n    return {\n      status: 'unavailable',\n      authUid,\n      workspaceId,\n      retryAt: Date.now() + delay / 2 + Math.random() * (delay / 2)\n    }\n  }\n\n  // NaN from an unparseable timestamp fails the comparison and lands on the\n  // fixed interval.\n  function nextRefreshAt(response: BillingCapabilitiesResponse): number {\n    const now = Date.now()\n    const remaining = Date.parse(response.expires_at) - now\n    if (remaining >= MIN_REFRESH_DELAY_MS) {\n      return now + Math.min(remaining, MAX_REFRESH_DELAY_MS)\n    }\n    return now + FALLBACK_REFRESH_DELAY_MS\n  }\n\n  // `capabilities` is a computed, and wall-clock time is not a reactive\n  // dependency, so expiry has to be pushed rather than read lazily. The timer\n  // runs only while the document is visible: staleness is unobservable in a\n  // hidden tab, and returning to the tab is itself a visibility transition.\n  function scheduleRefresh(): void {\n    clearRefreshTimer()\n    const refreshAt = scheduledRefreshAt(readState.value)\n    if (refreshAt === null) return\n    if (defaultDocument?.visibilityState === 'hidden') return\n\n    const delay = Math.max(0, refreshAt - Date.now())\n    refreshTimer = setTimeout(() => {\n      refreshTimer = null\n      void fetchCapabilities()\n    }, delay)\n  }\n\n  useEventListener(defaultDocument, 'visibilitychange', () => {\n    if (defaultDocument?.visibilityState === 'hidden') {\n      clearRefreshTimer()\n      return\n    }\n    const refreshAt = scheduledRefreshAt(readState.value)\n    if (refreshAt === null) return\n    if (refreshAt <= Date.now()) void fetchCapabilities()\n    else scheduleRefresh()\n  })\n\n  const stopRevisionListener = onCapabilityRevision((revision) => {\n    // A read already in flight may have loaded its data before this mutation\n    // committed, and the revision it returns cannot rule that out: the server\n    // mints that number when it serializes the response, not when it read. So\n    // the read is refetched once it settles - the dedupe below would otherwise\n    // hand back the very request that missed the mutation.\n    if (activeRequest) invalidatedRequestId = activeRequest.requestId\n    const state = readState.value\n    if (state.status !== 'resolved' || state.response.revision === revision) {\n      return\n    }\n    void fetchCapabilities()\n  })\n\n  onScopeDispose(() => {\n    clearRefreshTimer()\n    stopRevisionListener()\n  })\n\n  /** Cancels the in-flight read and its timer, leaving the snapshot in place. */\n  function cancelActiveRead(): void {\n    clearRefreshTimer()\n    latestRequestId++\n    activeRequest?.controller.abort()\n    activeRequest = null\n  }\n\n  function resetRead(): void {\n    cancelActiveRead()\n    readState.value = { status: 'idle' }\n  }\n\n  async function fetchCapabilities(signal?: AbortSignal): Promise<void> {\n    const userId = authStore.userId\n    const workspaceId = workspaceStore.activeWorkspaceId\n    if (!userId || !workspaceId) {\n      resetRead()\n      return\n    }\n\n    if (\n      activeRequest?.authUid === userId &&\n      activeRequest.workspaceId === workspaceId &&\n      !activeRequest.controller.signal.aborted\n    ) {\n      return activeRequest.promise\n    }\n\n    // Refetching the same scope revalidates in the background, keeping the\n    // prior read - a resolved snapshot or the unavailable fallback - readable\n    // so its affordances do not blink out once per refresh. A scope change\n    // makes it wrong, not stale, so it resets.\n    const currentState = readState.value\n    const revalidating =\n      (currentState.status === 'resolved' ||\n        currentState.status === 'unavailable') &&\n      currentState.authUid === userId &&\n      currentState.workspaceId === workspaceId\n    const priorSnapshot =\n      revalidating && currentState.status === 'resolved' ? currentState : null\n\n    if (revalidating) cancelActiveRead()\n    else resetRead()\n\n    const requestId = ++latestRequestId\n    const controller = new AbortController()\n    const abortRequest = () => controller.abort()\n    if (signal?.aborted) controller.abort()\n    else signal?.addEventListener('abort', abortRequest, { once: true })\n    if (!revalidating) {\n      readState.value = {\n        status: 'pending',\n        authUid: userId,\n        workspaceId\n      }\n    }\n\n    const promise = (async () => {\n      let refetchAfterSettle = false\n      try {\n        const response = await readCapabilitiesResponse(\n          controller.signal,\n          revalidating\n        )\n        if (\n          requestId !== latestRequestId ||\n          userId !== authStore.userId ||\n          workspaceId !== workspaceStore.activeWorkspaceId\n        ) {\n          return\n        }\n        // The SDK's scope moved on under the read while the stores' did not:\n        // a switch mid-flight. It retries on the outage timer, unreported,\n        // because the next read answers for whichever scope settles.\n        if (response === undefined) {\n          readFailures++\n          readState.value = priorSnapshot\n            ? {\n                ...priorSnapshot,\n                refreshAt: Date.now() + FALLBACK_REFRESH_DELAY_MS\n              }\n            : unavailableState(userId, workspaceId)\n          scheduleRefresh()\n          return\n        }\n\n        const resolvedForScope =\n          response.resolved_for.workspace_id === workspaceId\n        trackCapabilityRead(resolvedForScope)\n        if (resolvedForScope) {\n          readFailures = 0\n          readState.value = {\n            status: 'resolved',\n            authUid: userId,\n            workspaceId,\n            response,\n            refreshAt: nextRefreshAt(response)\n          }\n        } else {\n          readFailures++\n          readState.value = unavailableState(userId, workspaceId)\n          reportWorkspaceScopeMismatch(\n            workspaceId,\n            response.resolved_for.workspace_id\n          )\n        }\n        scheduleRefresh()\n        refetchAfterSettle =\n          resolvedForScope && invalidatedRequestId === requestId\n      } catch (error) {\n        if (\n          requestId !== latestRequestId ||\n          userId !== authStore.userId ||\n          workspaceId !== workspaceStore.activeWorkspaceId\n        ) {\n          return\n        }\n        if (controller.signal.aborted) {\n          if (!revalidating) readState.value = { status: 'idle' }\n          return\n        }\n\n        const denied =\n          (error instanceof WorkspaceApiError &&\n            (error.status === 401 || error.status === 403)) ||\n          (error instanceof Error && error.name === 'AuthStoreError')\n        if (!denied) trackCapabilityRead(false)\n        // A transient failure keeps the last good snapshot - stale, not wrong -\n        // and retries. A denial is the server answering about this actor, so it\n        // replaces the snapshot even mid-revalidation.\n        const firstFailure = readFailures === 0\n        if (!denied) readFailures++\n        if (priorSnapshot && !denied) {\n          readState.value = {\n            ...priorSnapshot,\n            refreshAt: Date.now() + FALLBACK_REFRESH_DELAY_MS\n          }\n        } else {\n          readState.value = denied\n            ? { status: 'denied', authUid: userId, workspaceId }\n            : unavailableState(userId, workspaceId)\n        }\n        scheduleRefresh()\n        // A sustained outage retries on a timer, so reporting every attempt\n        // would emit one warning a minute for as long as the tab is open.\n        if (!denied && !firstFailure) return\n        reportError(error, {\n          surface: 'workspace',\n          errorType: 'billing_capabilities_read_failure',\n          level: 'warning',\n          tags: {\n            status:\n              error instanceof WorkspaceApiError\n                ? (error.status ?? 'unknown')\n                : 'unknown',\n            outcome: denied ? 'denied' : 'unavailable'\n          }\n        })\n      } finally {\n        signal?.removeEventListener('abort', abortRequest)\n        if (activeRequest?.requestId === requestId) {\n          activeRequest = null\n          // Deferred to here so the refetch is not deduped onto the request\n          // it replaces. It cannot loop: this one is issued after the revision\n          // that marked it, so only a further mutation can mark it in turn.\n          if (refetchAfterSettle) void fetchCapabilities()\n        }\n      }\n    })()\n\n    activeRequest = {\n      requestId,\n      authUid: userId,\n      workspaceId,\n      controller,\n      promise\n    }\n    return promise\n  }\n\n  async function initialize(signal?: AbortSignal): Promise<void> {\n    initialized = true\n    if (!isCloud) return\n    do {\n      await fetchCapabilities(signal)\n    } while (\n      !signal?.aborted &&\n      !!authStore.userId &&\n      !!workspaceStore.activeWorkspaceId &&\n      !isReady.value\n    )\n  }\n\n  async function refresh(): Promise<void> {\n    await initialize()\n  }\n\n  watch(\n    [\n      () => authStore.userId,\n      () => workspaceStore.activeWorkspaceId,\n      () => workspaceStore.activeWorkspace?.role\n    ],\n    () => {\n      readFailures = 0\n      resetRead()\n      if (initialized && isCloud) void fetchCapabilities()\n    }\n  )\n\n  return {\n    canTopUp,\n    canSubscribeSelfServe,\n    canCancel,\n    canReactivate,\n    canChangeSeats,\n    canInviteMembers,\n    canManageMembers,\n    canDowngradeToPersonal,\n    isReady,\n    hasResolvedCapabilities,\n    snapshotAuthoritative,\n    initialize,\n    refresh\n  }\n}\n\nexport const useBillingCapabilities = createSharedComposable(\n  useBillingCapabilitiesInternal\n)\n","/**\n * The versioned URL contract every Comfy product uses to hand a customer to\n * the hosted billing app, and that the app reads back on arrival.\n *\n * The entry URL is routing input and nothing more. It never carries a token,\n * a JWT, a payment-provider secret, an authoritative price, or a caller-chosen\n * return URL: a product states which billing screen it wants, which product is\n * asking, and which registered destination the customer should land on\n * afterwards. Billing resolves everything else against its own environment and\n * the signed-in session, so a workspace id here is a requested scope and never\n * an authorization.\n *\n * Route and parameter names are provisional while the hosted app is behind a\n * flag. `BILLING_CONTRACT_VERSION` is what lets them change without stranding\n * a product that is already deployed against the older shape.\n *\n * Whether a payment renders embedded or hosted is not decided here — that is\n * the SDK core's `hostedDestination` port. This package stays dependency-free\n * and framework-free so a product, the billing app, and a future non-Vue host\n * can share exactly one definition of the route surface.\n */\nexport const BILLING_CONTRACT_VERSION = 'v1'\n\nexport const BILLING_INTENTS = [\n  'pricing',\n  'checkout',\n  'top-up',\n  'subscription',\n  'payment-methods',\n  'invoices',\n  'result'\n] as const\n\nexport type BillingIntent = (typeof BILLING_INTENTS)[number]\n\nexport function isBillingIntent(\n  value: string | null | undefined\n): value is BillingIntent {\n  return BILLING_INTENTS.some((intent) => intent === value)\n}\n\n/** The route an intent occupies, e.g. `/v1/checkout`. */\nexport function billingIntentPath(intent: BillingIntent): string {\n  return `/${BILLING_CONTRACT_VERSION}/${intent}`\n}\n\n/** The surfaces allowed to originate a billing trip. */\nexport const BILLING_PRODUCTS = [\n  'comfyui',\n  'platform',\n  'workshop',\n  'models'\n] as const\n\nexport type BillingProduct = (typeof BILLING_PRODUCTS)[number]\n\nexport function isBillingProduct(\n  value: string | null | undefined\n): value is BillingProduct {\n  return BILLING_PRODUCTS.some((product) => product === value)\n}\n\n/**\n * Where in a product the customer asked for billing. A value outside this list\n * is read as no source.\n */\nexport const BILLING_SOURCES = [\n  'subscription_required',\n  'out_of_credits',\n  'top_up_blocked',\n  'deep_link',\n  'subscribe_to_run',\n  'subscribe_now_button',\n  'upgrade_to_add_credits',\n  'settings_billing_panel',\n  'avatar_menu_plans',\n  'team_members_panel',\n  'invite_member_upsell',\n  'upload_model_upgrade',\n  'team_upgrade_resume',\n  'free_tier_quota',\n  'agent_paywall'\n] as const\n\nexport type BillingSource = (typeof BILLING_SOURCES)[number]\n\nexport function isBillingSource(\n  value: string | null | undefined\n): value is BillingSource {\n  return BILLING_SOURCES.some((source) => source === value)\n}\n\n/**\n * Which deployment family a return destination belongs to. The backends run\n * three of them, not two, and pair each origin with exactly one family, so a\n * product resolves its return target in the same family its session was\n * minted against.\n *\n * A host picks its family by origin, never by the label on its own build: the\n * cloud app's \"staging\" distribution points at `testcloud.comfy.org`\n * (`STAGING_CLOUD_BASE_URL` in `src/config/comfyApi.ts`) and therefore maps to\n * `test` here, while `staging` means `stagingcloud.comfy.org`.\n */\nexport type BillingEnvironment = 'production' | 'staging' | 'test'\n","/**\n * The query shape of an entry URL, in one table so the builder and the parser\n * cannot drift apart: a field is written and read under the same name, and a\n * value that fails the shared charset reports the same code on both sides.\n * The one exception is `promo`: the parser carries an unreadable one apart\n * rather than refusing the link, because it only prefills a field.\n */\n\n/** Names are provisional; see `contract.ts`. */\nexport const ENTRY_PARAM_PRODUCT = 'product'\nexport const ENTRY_PARAM_RETURN_TO = 'return_to'\n/** Also what a return URL names the billed workspace under. */\nexport const ENTRY_PARAM_WORKSPACE = 'workspace'\n/** Outside the table below: a source off the shared list is dropped, never an error. */\nexport const ENTRY_PARAM_SOURCE = 'source'\n\nexport type OptionalEntryKey =\n  | 'plan'\n  | 'correlationId'\n  | 'workspaceId'\n  | 'teamCreditStopId'\n  | 'promotionCode'\n\nexport type InvalidIdentifierCode =\n  | 'INVALID_PLAN'\n  | 'INVALID_CORRELATION_ID'\n  | 'INVALID_WORKSPACE_ID'\n  | 'INVALID_TEAM_CREDIT_STOP_ID'\n  | 'INVALID_PROMOTION_CODE'\n\ninterface OptionalEntryField {\n  readonly key: OptionalEntryKey\n  readonly param: string\n  readonly code: InvalidIdentifierCode\n}\n\nexport const OPTIONAL_ENTRY_FIELDS: readonly OptionalEntryField[] = [\n  { key: 'plan', param: 'plan', code: 'INVALID_PLAN' },\n  {\n    key: 'correlationId',\n    param: 'correlation_id',\n    code: 'INVALID_CORRELATION_ID'\n  },\n  {\n    key: 'workspaceId',\n    param: ENTRY_PARAM_WORKSPACE,\n    code: 'INVALID_WORKSPACE_ID'\n  },\n  {\n    key: 'teamCreditStopId',\n    param: 'team_credit_stop_id',\n    code: 'INVALID_TEAM_CREDIT_STOP_ID'\n  },\n  /** Prefills checkout's promo field; billing applies it only on the customer's Apply. */\n  { key: 'promotionCode', param: 'promo', code: 'INVALID_PROMOTION_CODE' }\n]\n\nexport type OptionalEntryValues = {\n  readonly [K in OptionalEntryKey]?: string\n}\n\n/**\n * The credit amount a top-up link asks for, in whole cents. It is the\n * customer's chosen quantity, not a price: billing quotes the credits it\n * buys from the server.\n */\nexport const ENTRY_PARAM_AMOUNT = 'amount_cents'\n\n/** At most $9,999,999.99; the server applies its own limits on top. */\nconst MAX_AMOUNT_CENTS = 999_999_999\n\nconst WHOLE_CENTS = /^[1-9][0-9]{0,8}$/\n\nexport function isEntryAmountCents(value: number): boolean {\n  return Number.isInteger(value) && value > 0 && value <= MAX_AMOUNT_CENTS\n}\n\nexport function readEntryAmountCents(raw: string): number | undefined {\n  return WHOLE_CENTS.test(raw) ? Number(raw) : undefined\n}\n","/**\n * The charset every free-form identifier in the contract shares: plan slugs,\n * correlation ids, workspace ids, and the reference billing hands back. It is\n * deliberately narrower than what a URL permits, so nothing that survives it\n * can carry a path separator, a query delimiter, or a percent escape into a\n * downstream URL.\n */\nconst CONTRACT_IDENTIFIER = /^[A-Za-z0-9_-]{1,128}$/\n\nexport function isContractIdentifier(value: string): boolean {\n  return CONTRACT_IDENTIFIER.test(value)\n}\n","/**\n * The one place a string becomes a `URL` in this package. Every entry point\n * here takes input that arrived over a URL bar, so a parse failure is a value\n * to branch on rather than an exception each caller has to remember to catch.\n */\nexport function parseUrl(value: string | URL, base?: string): URL | undefined {\n  try {\n    return new URL(value instanceof URL ? value.href : value, base)\n  } catch {\n    return undefined\n  }\n}\n\n/**\n * Lets the parsers accept the path-and-query form a router hands them\n * (`/v1/checkout?...`) as readily as a full href. It is never read back: only\n * the pathname and the query survive parsing, and `.invalid` is reserved by\n * RFC 2606 so a bug that leaked it could not reach a real host.\n */\nexport const CONTRACT_PARSE_BASE = 'https://billing.invalid/'\n","/**\n * Where billing is allowed to send a customer back to. A closed registry, not\n * a caller-supplied URL: `return_to=<identifier>` names a target, and the\n * absolute destination is chosen here per environment, so a crafted entry URL\n * cannot turn the hosted app into an open redirect.\n *\n * Every destination below is one this repository already states. A family a\n * target has no confirmed origin for stays absent rather than being derived\n * from a sibling's hostname, because an unresolvable target fails closed while\n * a guessed one sends a customer somewhere nobody serves.\n *\n * Localhost and desktop return targets are out of scope: a developer running a\n * product locally returns to the deployed destination of whichever environment\n * their backend belongs to.\n */\nimport type { BillingEnvironment } from './contract.js'\nimport { parseUrl } from './url.js'\n\nexport const RETURN_TARGETS = [\n  'comfyui_workspace',\n  'comfyui_credits',\n  'platform_account',\n  'platform_billing'\n] as const\n\nexport type ReturnTarget = (typeof RETURN_TARGETS)[number]\n\ntype ReturnTargetDestinations = Readonly<\n  Partial<Record<BillingEnvironment, string>>\n>\n\nconst RETURN_TARGET_DESTINATIONS: Readonly<\n  Record<ReturnTarget, ReturnTargetDestinations>\n> = {\n  comfyui_workspace: {\n    production: 'https://cloud.comfy.org/',\n    staging: 'https://stagingcloud.comfy.org/',\n    test: 'https://testcloud.comfy.org/'\n  },\n  // The cloud app's credits settings page, the same URL the Workshop builds as\n  // `WORKSHOP_CREDITS_URL`.\n  comfyui_credits: {\n    production: 'https://cloud.comfy.org/?settings=plan-credits',\n    staging: 'https://stagingcloud.comfy.org/?settings=plan-credits',\n    test: 'https://testcloud.comfy.org/?settings=plan-credits'\n  },\n  // Platform lives in its own repository and names no account route here, so\n  // its origin root is the destination until that app names one.\n  platform_account: {\n    production: 'https://platform.comfy.org/',\n    staging: 'https://stagingplatform.comfy.org/'\n  },\n  // Platform's own billing page, `pages/profile/billing.vue` in that app.\n  platform_billing: {\n    production: 'https://platform.comfy.org/profile/billing',\n    staging: 'https://stagingplatform.comfy.org/profile/billing'\n  }\n}\n\nexport function isReturnTarget(value: string): value is ReturnTarget {\n  return RETURN_TARGETS.some((target) => target === value)\n}\n\n/**\n * Undefined for an identifier outside the registry, and for a registered\n * target that has no destination in the requested environment. Each call\n * returns a fresh `URL` so a caller can append to it without editing the\n * registry.\n */\nexport function resolveReturnTarget(\n  target: string,\n  environment: BillingEnvironment\n): URL | undefined {\n  if (!isReturnTarget(target)) return undefined\n\n  const destination = RETURN_TARGET_DESTINATIONS[target][environment]\n  return destination === undefined ? undefined : parseUrl(destination)\n}\n","/**\n * The product side of the contract: turn a billing request into the URL to\n * navigate to. Failures are coded results in the style of the billing core's\n * `BillingResult` — the builder never throws, and a code carries no server or\n * caller text a host could render by accident.\n */\nimport type { BillingIntent, BillingProduct } from './contract.js'\nimport { billingIntentPath, isBillingSource } from './contract.js'\nimport type {\n  InvalidIdentifierCode,\n  OptionalEntryValues\n} from './entryFields.js'\nimport {\n  ENTRY_PARAM_AMOUNT,\n  ENTRY_PARAM_PRODUCT,\n  ENTRY_PARAM_RETURN_TO,\n  ENTRY_PARAM_SOURCE,\n  OPTIONAL_ENTRY_FIELDS,\n  isEntryAmountCents\n} from './entryFields.js'\nimport { isContractIdentifier } from './identifiers.js'\nimport { isReturnTarget } from './returnTargets.js'\nimport { parseUrl } from './url.js'\n\nexport interface BillingEntryInput extends OptionalEntryValues {\n  /** Only the origin is used; any path or query on it is discarded. */\n  readonly billingOrigin: string | URL\n  readonly intent: BillingIntent\n  readonly product: BillingProduct\n  /**\n   * A `ReturnTarget`. Typed wide because the registry lookup is the real gate:\n   * a JavaScript host, or a generic that widened the literal, still has to\n   * name a registered target.\n   */\n  readonly returnTo: string\n  /** A `BillingSource`; anything else is left off the link. */\n  readonly source?: string\n  /** The credit amount a top-up asks for, in whole cents. */\n  readonly amountCents?: number\n}\n\nexport type BillingEntryUrlErrorCode =\n  | 'INVALID_ORIGIN'\n  | 'UNKNOWN_RETURN_TARGET'\n  | 'INVALID_AMOUNT'\n  | InvalidIdentifierCode\n\nexport type BillingEntryUrlResult =\n  | { readonly status: 'ok'; readonly url: URL }\n  | { readonly status: 'error'; readonly code: BillingEntryUrlErrorCode }\n\nconst LOCAL_HOSTNAMES = new Set(['localhost', '127.0.0.1', '[::1]'])\n\nfunction billingOriginHref(origin: string | URL): string | undefined {\n  const url = parseUrl(origin)\n  if (!url || url.username || url.password) return undefined\n  if (url.protocol === 'https:') return url.origin\n  if (url.protocol === 'http:' && LOCAL_HOSTNAMES.has(url.hostname))\n    return url.origin\n  return undefined\n}\n\nfunction invalidIdentifierCode(\n  values: OptionalEntryValues\n): InvalidIdentifierCode | undefined {\n  for (const field of OPTIONAL_ENTRY_FIELDS) {\n    const value = values[field.key]\n    if (value !== undefined && !isContractIdentifier(value)) return field.code\n  }\n  return undefined\n}\n\nexport function buildBillingEntryUrl(\n  input: BillingEntryInput\n): BillingEntryUrlResult {\n  const origin = billingOriginHref(input.billingOrigin)\n  if (origin === undefined) return { status: 'error', code: 'INVALID_ORIGIN' }\n\n  if (!isReturnTarget(input.returnTo))\n    return { status: 'error', code: 'UNKNOWN_RETURN_TARGET' }\n\n  const invalid = invalidIdentifierCode(input)\n  if (invalid !== undefined) return { status: 'error', code: invalid }\n\n  const { amountCents } = input\n  if (amountCents !== undefined && !isEntryAmountCents(amountCents))\n    return { status: 'error', code: 'INVALID_AMOUNT' }\n\n  const url = new URL(billingIntentPath(input.intent), origin)\n  url.searchParams.set(ENTRY_PARAM_PRODUCT, input.product)\n  url.searchParams.set(ENTRY_PARAM_RETURN_TO, input.returnTo)\n  for (const field of OPTIONAL_ENTRY_FIELDS) {\n    const value = input[field.key]\n    if (value !== undefined) url.searchParams.set(field.param, value)\n  }\n  if (isBillingSource(input.source))\n    url.searchParams.set(ENTRY_PARAM_SOURCE, input.source)\n  if (amountCents !== undefined)\n    url.searchParams.set(ENTRY_PARAM_AMOUNT, String(amountCents))\n\n  return { status: 'ok', url }\n}\n","import type { CheckoutEntrySource } from '@comfyorg/account-core/billing'\n\nimport type { AddCreditsClickMetadata, PaymentIntentSource } from '../types'\n\ntype AddCreditsClickSource = AddCreditsClickMetadata['source']\n\nconst FROM_ADD_CREDITS_CLICK = {\n  credits_panel: 'settings_billing_panel',\n  avatar_menu: 'avatar_menu_plans',\n  settings_billing_panel: 'settings_billing_panel',\n  deep_link: 'deep_link',\n  agent_paywall: 'agent_paywall'\n} as const satisfies Record<AddCreditsClickSource, PaymentIntentSource>\n\nconst FROM_JOURNEY_ENTRY: ReadonlyMap<\n  CheckoutEntrySource,\n  PaymentIntentSource\n> = new Map([\n  ['deep_link', 'deep_link'],\n  ['settings_billing', 'settings_billing_panel'],\n  ['agent_paywall', 'agent_paywall']\n])\n\n/** The one source list's value for the control a customer clicked to add credits. */\nexport function paymentIntentSourceForAddCreditsClick(\n  source: AddCreditsClickSource\n): PaymentIntentSource {\n  return FROM_ADD_CREDITS_CLICK[source]\n}\n\n/**\n * The one source list's value for a checkout journey's entry source, when the\n * entry source names one. `pricing`, `recovery`, `other` and `unknown` say\n * where the customer was, not which control they used.\n */\nexport function paymentIntentSourceForJourneyEntry(\n  source: CheckoutEntrySource\n): PaymentIntentSource | undefined {\n  return FROM_JOURNEY_ENTRY.get(source)\n}\n","import type {\n  CheckoutAssignmentStatus,\n  CheckoutEntryFlow,\n  CheckoutEntrySource,\n  CheckoutJourneyArm,\n  CheckoutJourneyContext,\n  CheckoutUiMode\n} from '@comfyorg/account-core/billing'\nimport {\n  isBillingSource,\n  isContractIdentifier\n} from '@comfyorg/billing-contract'\n\nimport type { ServerFeatureFlag } from '@/platform/remoteConfig/serverFeatureFlag'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport { paymentIntentSourceForJourneyEntry } from '@/platform/telemetry/utils/paymentIntentSource'\n\n/**\n * One lifecycle owner for a checkout journey's frozen entry context and\n * durable resume metadata, shared by the subscription and top-up rails and\n * by both rollout arms. The journey identity and its server-assigned arm are\n * captured once at entry and preserved across reload; a later flag refresh\n * changes observed behaviour but never the frozen assignment. See\n * ADR-AUTH-BILLING-0014 for the rail-neutral attempt context this extends.\n */\n\nconst CHECKOUT_JOURNEY_MAX_AGE_MS = 24 * 60 * 60 * 1000\nconst CHECKOUT_JOURNEY_STORAGE_KEY = 'comfy.checkout.journey'\n// Typed to the enum member's value so a future correction of the flag key (or\n// its `checked`/`checkout` typo) fails to compile here instead of silently\n// reading a stale key. Type-only, so consumers' test mocks need no runtime enum.\nconst EMBEDDED_CHECKOUT_FLAG_KEY: `${ServerFeatureFlag.EMBEDDED_CHECKOUT_ENABLED}` =\n  'embedded_checked_enabled'\n\nconst ENTRY_FLOWS = {\n  initial_subscription: true,\n  paid_upgrade: true,\n  topup: true,\n  other: true,\n  unknown: true\n} satisfies Record<CheckoutEntryFlow, true>\nconst ENTRY_SOURCES = {\n  pricing: true,\n  deep_link: true,\n  recovery: true,\n  settings_billing: true,\n  other: true,\n  unknown: true,\n  agent_paywall: true\n} satisfies Record<CheckoutEntrySource, true>\n\nfunction isAllowlisted<T extends string>(\n  allowlist: Record<T, true>,\n  value: unknown\n): value is T {\n  return typeof value === 'string' && Object.hasOwn(allowlist, value)\n}\n\nfunction toEntryFlow(value: unknown): CheckoutEntryFlow {\n  return isAllowlisted(ENTRY_FLOWS, value) ? value : 'unknown'\n}\n\nfunction toEntrySource(value: unknown): CheckoutEntrySource {\n  return isAllowlisted(ENTRY_SOURCES, value) ? value : 'unknown'\n}\n\nconst PAYMENT_INTENT_ENTRY_SOURCES: Partial<\n  Record<PaymentIntentSource, CheckoutEntrySource>\n> = {\n  agent_paywall: 'agent_paywall'\n}\n\nfunction isMappedPaymentIntentSource(\n  value: string\n): value is keyof typeof PAYMENT_INTENT_ENTRY_SOURCES {\n  return Object.hasOwn(PAYMENT_INTENT_ENTRY_SOURCES, value)\n}\n\n/**\n * Entry source for a journey opened with `paymentIntentSource`.\n *\n * Takes a `string` rather than a `PaymentIntentSource` because this function\n * owns the runtime hardening: its callers read the value from a Vue prop and a\n * composable argument, neither of which TypeScript enforces at runtime. Own-key\n * narrowing is what makes that safe — a bare lookup would resolve an inherited\n * `Object.prototype` member (`'constructor'`, `'toString'`) truthy, so\n * `?? fallback` would not fire and a non-`CheckoutEntrySource` value would\n * reach the record, storage and every downstream phase.\n */\nexport function resolveEntrySource(\n  paymentIntentSource: string | undefined,\n  fallback: CheckoutEntrySource\n): CheckoutEntrySource {\n  if (paymentIntentSource === undefined) return fallback\n  if (!isMappedPaymentIntentSource(paymentIntentSource)) return fallback\n  return PAYMENT_INTENT_ENTRY_SOURCES[paymentIntentSource] ?? fallback\n}\n\nexport interface CheckoutJourneyRecord {\n  journey_id: string\n  entered_at: string\n  started_at_ms: number\n  actor_uid: string\n  workspace_id: string\n  entry_flow: CheckoutEntryFlow\n  entry_source: CheckoutEntrySource\n  /**\n   * The source the customer entered from, as the one source list names it.\n   * Absent on a record written before it was kept, or opened with no source.\n   */\n  payment_intent_source?: PaymentIntentSource\n  /**\n   * Stable key for the intended purchase within the flow (e.g. tier:cycle).\n   * A change of intent starts a new journey rather than resuming.\n   */\n  intent?: string\n  assignment_status: CheckoutAssignmentStatus\n  assigned_arm?: CheckoutJourneyArm\n  ui_mode?: CheckoutUiMode\n  billing_op_id?: string\n}\n\nexport type CheckoutAssignment =\n  | { status: 'resolved'; arm: CheckoutJourneyArm }\n  | { status: 'unavailable' }\n\ninterface CheckoutJourneyIdentity {\n  actorUid: string\n  workspaceId: string\n}\n\nexport interface StartCheckoutJourneyInput extends CheckoutJourneyIdentity {\n  entryFlow: CheckoutEntryFlow\n  entrySource: CheckoutEntrySource\n  paymentIntentSource?: PaymentIntentSource\n  assignment: CheckoutAssignment\n  /** Stable key for the intended purchase (e.g. tier:cycle); a change starts a new journey. */\n  intent?: string\n  /** Checkout UI the user actually sees, so a frozen arm can be reconciled against real experience. */\n  uiMode?: CheckoutUiMode\n}\n\nexport type ResolveCheckoutJourneyResult =\n  | {\n      status: 'active'\n      record: CheckoutJourneyRecord\n      /** True when an in-flight journey was recovered rather than newly created. */\n      resumed: boolean\n    }\n  /**\n   * Another rail owns the single journey slot with an operation still in\n   * flight. This rail gets no journey at all rather than a foreign one: its\n   * phases would otherwise be emitted under the other rail's `entry_flow`.\n   */\n  | { status: 'blocked' }\n\n/**\n * Freeze the rollout arm from the server feature response used at entry. An\n * absent flag is `unavailable`, never a fabricated `control`, so an unknown\n * assignment cannot masquerade as a resolved control arm downstream.\n */\nexport function resolveCheckoutAssignment(\n  serverFeatures: Record<string, unknown>\n): CheckoutAssignment {\n  if (!Object.hasOwn(serverFeatures, EMBEDDED_CHECKOUT_FLAG_KEY)) {\n    return { status: 'unavailable' }\n  }\n\n  return {\n    status: 'resolved',\n    arm:\n      serverFeatures[EMBEDDED_CHECKOUT_FLAG_KEY] === true\n        ? 'treatment'\n        : 'control'\n  }\n}\n\nexport function createCheckoutJourneyRecord(\n  input: StartCheckoutJourneyInput,\n  now: number\n): CheckoutJourneyRecord {\n  return {\n    journey_id: createJourneyId(),\n    entered_at: new Date(now).toISOString(),\n    started_at_ms: now,\n    actor_uid: input.actorUid,\n    workspace_id: input.workspaceId,\n    entry_flow: input.entryFlow,\n    entry_source: input.entrySource,\n    ...(input.paymentIntentSource !== undefined && {\n      payment_intent_source: input.paymentIntentSource\n    }),\n    ...(input.intent !== undefined && { intent: input.intent }),\n    assignment_status: input.assignment.status,\n    ...(input.assignment.status === 'resolved' && {\n      assigned_arm: input.assignment.arm\n    }),\n    ...(input.uiMode !== undefined && { ui_mode: input.uiMode })\n  }\n}\n\nexport function toCheckoutJourneyContext(\n  record: CheckoutJourneyRecord\n): CheckoutJourneyContext {\n  const base = {\n    checkout_journey_id: record.journey_id,\n    checkout_entered_at: record.entered_at,\n    entry_flow: record.entry_flow,\n    entry_source: record.entry_source,\n    ...(record.ui_mode !== undefined && { ui_mode: record.ui_mode }),\n    ...(record.billing_op_id !== undefined && {\n      billing_op_id: record.billing_op_id\n    })\n  }\n\n  return record.assignment_status === 'resolved' &&\n    record.assigned_arm !== undefined\n    ? {\n        ...base,\n        assignment_status: 'resolved',\n        assigned_arm: record.assigned_arm\n      }\n    : { ...base, assignment_status: 'unavailable' }\n}\n\nfunction isCheckoutJourneyExpired(\n  record: CheckoutJourneyRecord,\n  now: number\n): boolean {\n  return now - record.started_at_ms > CHECKOUT_JOURNEY_MAX_AGE_MS\n}\n\nfunction journeyMatchesIdentity(\n  record: CheckoutJourneyRecord,\n  identity: CheckoutJourneyIdentity\n): boolean {\n  return (\n    record.actor_uid === identity.actorUid &&\n    record.workspace_id === identity.workspaceId\n  )\n}\n\n/**\n * Recover an in-flight journey for the same actor, workspace, and purchase\n * intent, or begin a new one. A changed actor/workspace or a different entry\n * flow never inherits the previous context: the stale record is discarded and\n * a fresh journey created.\n */\nexport function resolveCheckoutJourney(\n  input: StartCheckoutJourneyInput\n): ResolveCheckoutJourneyResult {\n  const now = Date.now()\n  const existing = loadCheckoutJourney()\n\n  const live = existing && !isCheckoutJourneyExpired(existing, now)\n\n  if (\n    live &&\n    journeyMatchesIdentity(existing, input) &&\n    existing.entry_flow === input.entryFlow &&\n    existing.intent === input.intent\n  ) {\n    return { status: 'active', record: existing, resumed: true }\n  }\n\n  if (live && existing.billing_op_id !== undefined) {\n    return { status: 'blocked' }\n  }\n\n  const record = createCheckoutJourneyRecord(input, now)\n  saveCheckoutJourney(record)\n  return { status: 'active', record, resumed: false }\n}\n\nexport function getActiveCheckoutJourney(): CheckoutJourneyRecord | null {\n  return loadCheckoutJourney()\n}\n\n/**\n * The source of the journey bound to `billingOpId`, for an operation event\n * emitted by a tab that did not start it (a poll recovered after reload).\n */\nexport function getCheckoutJourneyPaymentIntentSource(\n  billingOpId: string\n): PaymentIntentSource | undefined {\n  const journey = loadCheckoutJourney()\n  if (journey?.billing_op_id !== billingOpId) return undefined\n  return (\n    journey.payment_intent_source ??\n    paymentIntentSourceForJourneyEntry(journey.entry_source)\n  )\n}\n\nexport function bindOperationToCheckoutJourney(\n  billingOpId: string\n): CheckoutJourneyRecord | null {\n  const existing = loadCheckoutJourney()\n  if (!existing) {\n    return null\n  }\n\n  // A journey binds to exactly one operation. If it is already bound (e.g. a\n  // concurrent rail's operation is in flight), refuse to rebind so the first\n  // operation keeps ownership of the terminal clear.\n  if (existing.billing_op_id !== undefined) {\n    return existing.billing_op_id === billingOpId ? existing : null\n  }\n\n  const updated: CheckoutJourneyRecord = {\n    ...existing,\n    billing_op_id: billingOpId\n  }\n  saveCheckoutJourney(updated)\n  return updated\n}\n\nexport function clearCheckoutJourney(): void {\n  inMemoryJourney = null\n  const storage = getStorage()\n  if (!storage) {\n    return\n  }\n\n  try {\n    storage.removeItem(CHECKOUT_JOURNEY_STORAGE_KEY)\n    persistedJourneyIsStale = false\n  } catch {\n    persistedJourneyIsStale = true\n  }\n}\n\nlet fallbackJourneyIdCounter = 0\n\nexport function createJourneyId(): string {\n  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {\n    return crypto.randomUUID()\n  }\n\n  // Monotonic suffix so journeys created within the same millisecond stay\n  // distinct when randomUUID is unavailable.\n  fallbackJourneyIdCounter += 1\n  return `journey-${Date.now()}-${fallbackJourneyIdCounter}`\n}\n\n/**\n * Session-scoped mirror so the journey stays consistent even when\n * `sessionStorage` is unavailable (private mode, quota, disabled). Reload\n * resilience still requires storage, but within a session the active journey\n * never silently vanishes and `entered` is not re-emitted.\n */\nlet inMemoryJourney: CheckoutJourneyRecord | null = null\n\n/**\n * Set when a write to persistent storage failed, leaving a record there that no\n * longer reflects this session. Rehydrating it would resurrect a journey the\n * session already cleared, so persisted reads are suppressed until a write\n * succeeds.\n */\nlet persistedJourneyIsStale = false\n\ntype CheckoutStorage = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>\n\nfunction getStorage(): CheckoutStorage | null {\n  let storage: unknown\n\n  try {\n    storage = globalThis.sessionStorage\n  } catch {\n    return null\n  }\n\n  return isCheckoutStorage(storage) ? storage : null\n}\n\nfunction isCheckoutStorage(value: unknown): value is CheckoutStorage {\n  return (\n    !!value &&\n    typeof value === 'object' &&\n    'getItem' in value &&\n    typeof value.getItem === 'function' &&\n    'setItem' in value &&\n    typeof value.setItem === 'function' &&\n    'removeItem' in value &&\n    typeof value.removeItem === 'function'\n  )\n}\n\nfunction saveCheckoutJourney(record: CheckoutJourneyRecord): void {\n  inMemoryJourney = record\n  const storage = getStorage()\n  if (!storage) {\n    return\n  }\n\n  try {\n    storage.setItem(CHECKOUT_JOURNEY_STORAGE_KEY, JSON.stringify(record))\n    persistedJourneyIsStale = false\n  } catch {\n    persistedJourneyIsStale = true\n  }\n}\n\nfunction loadCheckoutJourney(): CheckoutJourneyRecord | null {\n  // The mirror is the source of truth within a session: it holds the latest\n  // write even when persistence failed, so a stale persisted record can never\n  // shadow it. Persisted storage is only consulted to rehydrate after reload.\n  const record = inMemoryJourney ?? readPersistedJourney()\n  if (!record) {\n    return null\n  }\n\n  if (isCheckoutJourneyExpired(record, Date.now())) {\n    clearCheckoutJourney()\n    return null\n  }\n\n  inMemoryJourney = record\n  return record\n}\n\nfunction readPersistedJourney(): CheckoutJourneyRecord | null {\n  if (persistedJourneyIsStale) {\n    return null\n  }\n\n  const storage = getStorage()\n  if (!storage) {\n    return null\n  }\n\n  let raw: string | null\n  try {\n    raw = storage.getItem(CHECKOUT_JOURNEY_STORAGE_KEY)\n  } catch {\n    return null\n  }\n\n  if (!raw) {\n    return null\n  }\n\n  try {\n    const record = normalizeRecord(JSON.parse(raw))\n    if (!record) {\n      clearCheckoutJourney()\n      return null\n    }\n    return record\n  } catch {\n    clearCheckoutJourney()\n    return null\n  }\n}\n\nconst UI_MODES = {\n  embedded: true,\n  full_page: true,\n  hosted: true,\n  unknown: true\n} satisfies Record<CheckoutUiMode, true>\n\ntype PersistedJourneyIdentity = Pick<\n  CheckoutJourneyRecord,\n  'journey_id' | 'entered_at' | 'started_at_ms' | 'actor_uid' | 'workspace_id'\n>\n\nfunction readIdentity(\n  candidate: Record<string, unknown>\n): PersistedJourneyIdentity | null {\n  const { journey_id, entered_at, started_at_ms, actor_uid, workspace_id } =\n    candidate\n  // A non-finite started_at_ms would make every expiry comparison false, so an\n  // immortal journey could be persisted by hand; an unparseable entered_at\n  // would reach telemetry as the journey's declared UTC entry time; a\n  // journey_id the billing contract refuses would stop the hosted handoff.\n  return typeof journey_id === 'string' &&\n    isContractIdentifier(journey_id) &&\n    typeof entered_at === 'string' &&\n    !Number.isNaN(Date.parse(entered_at)) &&\n    typeof started_at_ms === 'number' &&\n    Number.isFinite(started_at_ms) &&\n    typeof actor_uid === 'string' &&\n    typeof workspace_id === 'string'\n    ? { journey_id, entered_at, started_at_ms, actor_uid, workspace_id }\n    : null\n}\n\ntype PersistedAssignment = Pick<\n  CheckoutJourneyRecord,\n  'assignment_status' | 'assigned_arm'\n>\n\n/**\n * Enforce the assignment invariant on persisted records: resolved must carry an\n * arm, unavailable must not. A contradictory record is rejected rather than\n * replayed as a fabricated assignment.\n */\nfunction readAssignment(\n  candidate: Record<string, unknown>\n): PersistedAssignment | null {\n  const status = candidate.assignment_status\n  const arm = candidate.assigned_arm\n\n  if (status === 'unavailable') {\n    return arm === undefined ? { assignment_status: 'unavailable' } : null\n  }\n  if (status !== 'resolved') {\n    return null\n  }\n  return arm === 'control' || arm === 'treatment'\n    ? { assignment_status: 'resolved', assigned_arm: arm }\n    : null\n}\n\nfunction readOptionalFields(candidate: Record<string, unknown>) {\n  const { intent, ui_mode, billing_op_id, payment_intent_source } = candidate\n  return {\n    ...(typeof payment_intent_source === 'string' &&\n      isBillingSource(payment_intent_source) && { payment_intent_source }),\n    ...(typeof intent === 'string' && { intent }),\n    ...(isAllowlisted(UI_MODES, ui_mode) && { ui_mode }),\n    ...(typeof billing_op_id === 'string' && { billing_op_id })\n  }\n}\n\nfunction normalizeRecord(value: unknown): CheckoutJourneyRecord | null {\n  if (!value || typeof value !== 'object') {\n    return null\n  }\n\n  const candidate = value as Record<string, unknown>\n  const identity = readIdentity(candidate)\n  const assignment = readAssignment(candidate)\n  if (!identity || !assignment) {\n    return null\n  }\n\n  return {\n    ...identity,\n    entry_flow: toEntryFlow(candidate.entry_flow),\n    entry_source: toEntrySource(candidate.entry_source),\n    ...assignment,\n    ...readOptionalFields(candidate)\n  }\n}\n","import type { CapabilitiesSnapshot } from '@comfyorg/account-core/billing'\n\nimport type { BillingCapabilitiesResponse } from '@/platform/workspace/api/workspaceApi'\n\n/**\n * The SDK's cached capabilities snapshot in the shape the capabilities\n * composable already holds: the scope it was resolved for and the instant the\n * SDK stops serving it, which is the instant the composable would refetch.\n */\nexport function projectBillingCapabilities(\n  snapshot: CapabilitiesSnapshot\n): BillingCapabilitiesResponse {\n  return {\n    capabilities: snapshot.capabilities,\n    expires_at: new Date(snapshot.freshUntil).toISOString(),\n    resolved_for: {\n      user_id: snapshot.scope.userId,\n      workspace_id: snapshot.scope.workspaceId\n    },\n    revision: snapshot.revision,\n    rollout_defaults_applied: snapshot.rolloutDefaultsApplied\n  }\n}\n","/**\n * The generated zod schemas coerce every int64 to `bigint` and accept the\n * whole signed range, while the generated types the host reads through say\n * `number`. `Number()` on a value past 2^53 rounds silently, so a value the\n * host cannot hold exactly is refused rather than reshaped: the read then\n * fails as malformed, the way a body the core cannot decode does.\n */\nconst MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER)\n\nexport function asSafeNumber(value: bigint): number | undefined {\n  return value >= -MAX_SAFE && value <= MAX_SAFE ? Number(value) : undefined\n}\n","import type { BillingPlansData } from '@comfyorg/account-core/billing'\n\nimport type {\n  BillingPlansResponse,\n  Plan,\n  TeamCreditStops\n} from '@/platform/workspace/api/workspaceApi'\n\nimport { asSafeNumber } from './safeInt64'\n\ntype DecodedPlan = BillingPlansData['plans'][number]\ntype DecodedStops = NonNullable<BillingPlansData['team_credit_stops']>\ntype DecodedStop = DecodedStops['stops'][number]\ntype StopPrice = TeamCreditStops['stops'][number]['monthly']\n\n/**\n * The generated zod schema coerces every int64 in the catalog to `bigint` —\n * prices, credits, seat caps, the credit-stop ladder — while the generated\n * type the pricing surfaces read them through says `number`. Each is read\n * back as a number when a number holds it exactly; one that does not fails\n * the whole projection, so a catalog is never published with a rounded price.\n * Nothing is filtered, ranked or priced here.\n */\n/** An absent grant stays absent; one a number cannot hold exactly fails the plan. */\nfunction projectCredits(\n  raw: DecodedPlan['credits']\n): Pick<Plan, 'credits'> | undefined {\n  if (raw === undefined) return {}\n  const credits = asSafeNumber(raw)\n  return credits === undefined ? undefined : { credits }\n}\n\nfunction projectPlan({\n  credits: rawCredits,\n  ...plan\n}: DecodedPlan): Plan | undefined {\n  const credits = projectCredits(rawCredits)\n  const credits_cents = asSafeNumber(plan.credits_cents)\n  const max_seats = asSafeNumber(plan.max_seats)\n  const price_cents = asSafeNumber(plan.price_cents)\n  const total_cost_cents = asSafeNumber(plan.seat_summary.total_cost_cents)\n  const total_credits_cents = asSafeNumber(\n    plan.seat_summary.total_credits_cents\n  )\n  if (\n    credits === undefined ||\n    credits_cents === undefined ||\n    max_seats === undefined ||\n    price_cents === undefined ||\n    total_cost_cents === undefined ||\n    total_credits_cents === undefined\n  )\n    return undefined\n  return {\n    ...plan,\n    ...credits,\n    credits_cents,\n    max_seats,\n    price_cents,\n    seat_summary: {\n      seat_count: plan.seat_summary.seat_count,\n      total_cost_cents,\n      total_credits_cents\n    }\n  }\n}\n\nfunction projectStopPrice(\n  price: DecodedStop['monthly']\n): StopPrice | undefined {\n  const list_price_cents = asSafeNumber(price.list_price_cents)\n  const price_cents = asSafeNumber(price.price_cents)\n  if (list_price_cents === undefined || price_cents === undefined)\n    return undefined\n  return { list_price_cents, price_cents }\n}\n\nfunction projectStop(\n  stop: DecodedStop\n): TeamCreditStops['stops'][number] | undefined {\n  const credits = asSafeNumber(stop.credits)\n  const monthly = projectStopPrice(stop.monthly)\n  const yearly = projectStopPrice(stop.yearly)\n  if (credits === undefined || monthly === undefined || yearly === undefined)\n    return undefined\n  return { id: stop.id, credits, monthly, yearly }\n}\n\nfunction projectAll<T, U>(\n  items: readonly T[],\n  project: (item: T) => U | undefined\n): U[] | undefined {\n  const projected: U[] = []\n  for (const item of items) {\n    const result = project(item)\n    if (result === undefined) return undefined\n    projected.push(result)\n  }\n  return projected\n}\n\n/**\n * The SDK's decoded catalog in the shape the host's plan state holds, or\n * undefined when a value in it cannot be held exactly.\n */\nexport function projectBillingPlans(\n  data: BillingPlansData\n): BillingPlansResponse | undefined {\n  const { team_credit_stops, ...rest } = data\n  const plans = projectAll(data.plans, projectPlan)\n  if (plans === undefined) return undefined\n  if (team_credit_stops === undefined) return { ...rest, plans }\n  const stops = projectAll(team_credit_stops.stops, projectStop)\n  if (stops === undefined) return undefined\n  return {\n    ...rest,\n    plans,\n    team_credit_stops: {\n      default_stop_index: team_credit_stops.default_stop_index,\n      stops\n    }\n  }\n}\n","import type { BillingStatusData } from '@comfyorg/account-core/billing'\n\nimport type {\n  BillingStatusResponse,\n  RenewalInvoice,\n  TeamCreditStopSummary\n} from '@/platform/workspace/api/workspaceApi'\n\nimport { asSafeNumber } from './safeInt64'\n\ntype DecodedCreditStop = NonNullable<BillingStatusData['team_credit_stop']>\ntype DecodedRenewalInvoice = NonNullable<BillingStatusData['renewal_invoice']>\n\n/**\n * The credit stop's two int64 fields — a monthly credit count and a monthly\n * USD commitment — read back as the numbers the host holds; undefined when\n * either is past what a number can hold exactly.\n */\nfunction projectCreditStop(\n  stop: DecodedCreditStop\n): TeamCreditStopSummary | undefined {\n  const credits_monthly = asSafeNumber(stop.credits_monthly)\n  const stop_usd = asSafeNumber(stop.stop_usd)\n  if (credits_monthly === undefined || stop_usd === undefined) return undefined\n  return { id: stop.id, credits_monthly, stop_usd }\n}\n\nfunction projectRenewalInvoice(\n  invoice: DecodedRenewalInvoice\n): RenewalInvoice | undefined {\n  const amount_due = asSafeNumber(invoice.amount_due)\n  if (amount_due === undefined) return undefined\n  return { ...invoice, amount_due }\n}\n\n/**\n * The SDK's decoded status in the shape the host's billing state holds, or\n * undefined when a value in it cannot be held exactly — a read the caller\n * reports as malformed rather than publishes rounded.\n */\nexport function projectBillingStatus(\n  status: BillingStatusData\n): BillingStatusResponse | undefined {\n  const { team_credit_stop, scheduled_change, renewal_invoice, ...rest } =\n    status\n  const stop =\n    team_credit_stop === null ? null : projectCreditStop(team_credit_stop)\n  if (stop === undefined) return undefined\n  const scheduledStop =\n    scheduled_change === null || scheduled_change.team_credit_stop === null\n      ? null\n      : projectCreditStop(scheduled_change.team_credit_stop)\n  if (scheduledStop === undefined) return undefined\n  // An unreadable invoice amount drops only the invoice, not the whole status.\n  const invoice =\n    renewal_invoice === undefined\n      ? undefined\n      : projectRenewalInvoice(renewal_invoice)\n  return {\n    ...rest,\n    ...(invoice && { renewal_invoice: invoice }),\n    team_credit_stop: stop,\n    scheduled_change:\n      scheduled_change === null\n        ? null\n        : { ...scheduled_change, team_credit_stop: scheduledStop }\n  }\n}\n","/**\n * The app's one composition of `@comfyorg/account-core/billing`: the session-backed\n * transport, the readers, the operation lifecycle, and the payment commands,\n * wired once over ports the host supplies. Everything browser-bound (storage,\n * the payment-provider script, the document listeners) stays with the caller;\n * this module only assembles.\n */\nimport type {\n  BillingCommands,\n  BillingEventsReader,\n  BillingOperationLifecycle,\n  BillingOperationPointerStorage,\n  BillingOperationTelemetryEvent,\n  BillingScopeSource,\n  BillingSession,\n  BillingStatusReader,\n  CapabilitiesReader,\n  CreditsReader,\n  EmbeddedChallengeOutcome,\n  EmbeddedChallengePort,\n  HostedBillingDestination,\n  PaymentMethodsReader,\n  PlansReader,\n  TopupCommand\n} from '@comfyorg/account-core/billing'\nimport {\n  createBillingCommands,\n  createBillingEventsReader,\n  createBillingOperationLifecycle,\n  createBillingStatusReader,\n  createCapabilitiesReader,\n  createCreditsReader,\n  createPaymentMethodsReader,\n  createPlansReader,\n  createSessionBillingTransport,\n  createTopupCommand,\n  driveEmbeddedChallenge,\n  sessionBillingScopeSource\n} from '@comfyorg/account-core/billing'\n\nexport interface BillingSdkOptions {\n  readonly session: BillingSession\n  /** Defaults to the scope the session last minted for. */\n  readonly scopeSource?: BillingScopeSource\n  readonly resolveUrl: (route: string) => string\n  /** The target the host's session minted for; must match it or every request re-mints. */\n  readonly workspaceId: () => string | undefined\n  readonly pointerStorage?: BillingOperationPointerStorage\n  readonly embeddedCheckoutAvailable: () => boolean\n  /** Which origin serves a hosted page. */\n  readonly hostedDestination: () => HostedBillingDestination\n  readonly onTelemetry: (event: BillingOperationTelemetryEvent) => void\n  /** The payment-provider port, loaded on first use; undefined or a rejection when it cannot load. */\n  readonly challengePort: () => Promise<EmbeddedChallengePort | undefined>\n  readonly fetchImpl?: typeof fetch\n}\n\nexport interface BillingSdk {\n  readonly lifecycle: BillingOperationLifecycle\n  readonly status: BillingStatusReader\n  readonly credits: CreditsReader\n  readonly capabilities: CapabilitiesReader\n  readonly plans: PlansReader\n  readonly paymentMethods: PaymentMethodsReader\n  readonly events: BillingEventsReader\n  readonly topup: TopupCommand\n  readonly commands: BillingCommands\n  readonly driveChallenge: (\n    operationId: string\n  ) => Promise<EmbeddedChallengeOutcome>\n  readonly dispose: () => void\n}\n\n/** A port that could not load fails the challenge; the operation stays observed. */\nconst UNAVAILABLE_CHALLENGE_PORT: EmbeddedChallengePort = {\n  handleNextAction: () => Promise.resolve({ error: 'port_unavailable' })\n}\n\nexport function createBillingSdk(options: BillingSdkOptions): BillingSdk {\n  const {\n    session,\n    resolveUrl,\n    workspaceId,\n    pointerStorage,\n    embeddedCheckoutAvailable,\n    hostedDestination,\n    onTelemetry,\n    challengePort,\n    fetchImpl\n  } = options\n\n  const transport = createSessionBillingTransport({\n    session,\n    resolveUrl,\n    workspaceId,\n    ...(fetchImpl === undefined ? {} : { fetchImpl })\n  })\n  const scopeSource = options.scopeSource ?? sessionBillingScopeSource(session)\n  const status = createBillingStatusReader({ transport, scopeSource })\n  const credits = createCreditsReader({ transport, scopeSource })\n  const capabilities = createCapabilitiesReader({ transport, scopeSource })\n  const plans = createPlansReader({ transport, scopeSource })\n  const paymentMethods = createPaymentMethodsReader({ transport, scopeSource })\n  const events = createBillingEventsReader({ transport, scopeSource })\n  const lifecycle = createBillingOperationLifecycle({\n    transport,\n    scopeSource,\n    statusReader: status,\n    ...(pointerStorage === undefined ? {} : { pointerStorage }),\n    embeddedCheckoutAvailable,\n    hostedDestination,\n    onTelemetry\n  })\n  const topup = createTopupCommand({\n    transport,\n    lifecycle,\n    capabilities,\n    credits\n  })\n  const commands = createBillingCommands({\n    transport,\n    lifecycle,\n    statusReader: status,\n    capabilities,\n    credits\n  })\n\n  return {\n    lifecycle,\n    status,\n    credits,\n    capabilities,\n    plans,\n    paymentMethods,\n    events,\n    topup,\n    commands,\n    driveChallenge: async (operationId) =>\n      driveEmbeddedChallenge(\n        lifecycle,\n        operationId,\n        (await challengePort().catch(() => undefined)) ??\n          UNAVAILABLE_CHALLENGE_PORT\n      ),\n    // Every scope-holder the core exposes, listed a second time next to the\n    // helper in @comfyorg/account-ui; a new core reader has to join both.\n    dispose: () => {\n      lifecycle.dispose()\n      status.dispose()\n      credits.dispose()\n      capabilities.dispose()\n      plans.dispose()\n      paymentMethods.dispose()\n      events.dispose()\n    }\n  }\n}\n","/**\n * Projections from the SDK's operation state and top-up result onto the two\n * shapes the top-up dialog already reads: the poller's operation record and\n * the `CreateTopupResponse` the legacy call returned, plus the terminal the\n * SDK observed where those shapes cannot hold it.\n */\nimport type {\n  BillingDeclineReason,\n  BillingOperationState,\n  BillingOperationTerminal,\n  BillingTelemetryFailure,\n  HostedTopupCheckoutFailure,\n  HostedTopupCheckoutResult,\n  TopupFailure,\n  TopupResult\n} from '@comfyorg/account-core/billing'\nimport {\n  declineDetailKey,\n  unwrapServerCode\n} from '@comfyorg/account-core/billing'\n\nimport { t } from '@/i18n'\nimport type {\n  BillingAuthenticationState,\n  BillingOperationPhase,\n  CreateTopupResponse\n} from '@/platform/workspace/api/workspaceApi'\nimport { WorkspaceApiError } from '@/platform/workspace/api/workspaceApi'\n\nexport interface TopupOperationView {\n  readonly opId: string\n  readonly status: 'pending' | 'reconciliation_needed'\n  readonly actionUrl: string | null\n  readonly phase: BillingOperationPhase | null\n  readonly authenticationState: BillingAuthenticationState | null\n  readonly isAuthenticating: boolean\n  readonly canRetryAuthentication: boolean\n  readonly errorMessage: string | null\n}\n\nexport function declineDetail(reason: BillingDeclineReason): string {\n  return t(`billingOperation.${declineDetailKey(reason)}`)\n}\n\nexport function projectTopupOperation(\n  state: BillingOperationState\n): TopupOperationView | undefined {\n  if (state.kind !== 'topup') return undefined\n  if (state.phase === 'reconciliation_needed') {\n    return {\n      opId: state.id,\n      status: 'reconciliation_needed',\n      actionUrl: null,\n      phase: null,\n      authenticationState: 'reconciliation_needed',\n      isAuthenticating: false,\n      canRetryAuthentication: false,\n      errorMessage: null\n    }\n  }\n  if (state.phase !== 'pending') return undefined\n\n  const authenticationState = state.authenticationState ?? null\n  return {\n    opId: state.id,\n    status: 'pending',\n    actionUrl: state.actionUrl ?? null,\n    phase: state.serverPhase ?? null,\n    authenticationState,\n    isAuthenticating: state.challenge?.status === 'in_progress',\n    canRetryAuthentication: state.challenge?.status === 'required',\n    errorMessage:\n      authenticationState === 'failed_retryable'\n        ? declineDetail(state.declineReason ?? 'authentication_failed')\n        : null\n  }\n}\n\n/**\n * A purchase the SDK settled without crediting, as the response the dialog\n * handles, carrying the terminal its status cannot: the decline reason, or\n * that this tab stopped watching, or that support must reconcile it.\n */\nexport class UncreditedTopupResponse implements CreateTopupResponse {\n  readonly topup_id = ''\n\n  constructor(\n    readonly billing_op_id: string,\n    readonly status: 'failed' | 'pending',\n    readonly amount_cents: number,\n    readonly terminal: BillingOperationTerminal\n  ) {}\n}\n\nfunction topupFailureError(\n  failure: TopupFailure | HostedTopupCheckoutFailure\n): WorkspaceApiError {\n  if (failure.code === 'OPERATION_ALREADY_PENDING') {\n    return new WorkspaceApiError(\n      t('billingOperation.topupAlreadyPendingDetail'),\n      undefined,\n      failure.code,\n      'stale_operation'\n    )\n  }\n  const serverCode = 'serverCode' in failure ? failure.serverCode : undefined\n  return new WorkspaceApiError(\n    t('credits.topUp.unknownError'),\n    'httpStatus' in failure ? failure.httpStatus : undefined,\n    serverCode === undefined ? failure.code : unwrapServerCode(serverCode),\n    topupFailureCategory(failure)\n  )\n}\n\nfunction topupFailureCategory(\n  failure: TopupFailure | HostedTopupCheckoutFailure\n): BillingTelemetryFailure['failure_category'] {\n  switch (failure.code) {\n    case 'REQUEST_FAILED':\n      return failure.httpStatus === undefined ? 'network' : 'api_rejected'\n    case 'SUPERSEDED':\n      return 'stale_operation'\n    case 'INVALID_AMOUNT':\n    case 'INVALID_RETURN_URL':\n      return 'validation'\n    default:\n      return 'api_rejected'\n  }\n}\n\n/**\n * A settled result as the response the dialog handles today. `unsettled` is\n * the pending response: the server may still settle it, and the operation\n * stays visible through `projectTopupOperation`. `topup_id` is not surfaced\n * by the SDK and nothing reads it.\n */\nexport function projectTopupResult(\n  result: TopupResult,\n  amountCents: number\n): CreateTopupResponse {\n  switch (result.status) {\n    case 'ok':\n      return {\n        billing_op_id: result.operation.id,\n        topup_id: '',\n        status: 'completed',\n        amount_cents: amountCents\n      }\n    case 'declined':\n      return new UncreditedTopupResponse(\n        result.operation.id,\n        'failed',\n        amountCents,\n        {\n          stage: 'failed',\n          outcome: 'failure',\n          failure_category: 'provider_decline',\n          decline_reason: result.operation.declineReason\n        }\n      )\n    case 'unsettled':\n      return new UncreditedTopupResponse(\n        result.operation.id,\n        'pending',\n        amountCents,\n        result.operation.phase === 'timed_out'\n          ? {\n              stage: 'timeout',\n              outcome: 'failure',\n              failure_category: 'poll_timeout'\n            }\n          : {\n              stage: 'failed',\n              outcome: 'failure',\n              failure_category: 'reconciliation_needed'\n            }\n      )\n    case 'error':\n      throw topupFailureError(result)\n  }\n}\n\n/** The hosted Checkout URL, or the failure as the error the dialog handles. */\nexport function projectHostedTopupCheckoutResult(\n  result: HostedTopupCheckoutResult\n): string {\n  if (result.status === 'ok') return result.url\n  throw topupFailureError(result)\n}\n","/**\n * An SDK operation state as the record the legacy poller handed out. The\n * surfaces that look an operation up by id, or ask which one is waiting on the\n * customer, read these fields off `billingOperationStore` today; projecting\n * them here is what lets those call sites move to the rail without their\n * templates or their conditions changing.\n */\nimport type { BillingOperationState } from '@comfyorg/account-core/billing'\nimport { validateActionUrl } from '@comfyorg/account-core/billing'\n\nimport type {\n  BillingAuthenticationState,\n  BillingOperationPhase\n} from '@/platform/workspace/api/workspaceApi'\n\nimport { declineDetail } from './topupOperationView'\n\ntype OperationKind = BillingOperationState['kind']\n\ntype OperationStatus =\n  | 'pending'\n  | 'succeeded'\n  | 'failed'\n  | 'timeout'\n  | 'reconciliation_needed'\n\nexport interface BillingOperationRecordView {\n  readonly opId: string\n  readonly kind: OperationKind\n  readonly workspaceId: string\n  readonly status: OperationStatus\n  readonly actionUrl: string | null\n  readonly phase: BillingOperationPhase | null\n  readonly authenticationState: BillingAuthenticationState | null\n  readonly isAuthenticating: boolean\n  readonly canRetryAuthentication: boolean\n  /** The declined-attempt line a surface shows under its own summary. */\n  readonly errorMessage: string | null\n  /** True only when the server says cancelling this pending operation would take effect. */\n  readonly cancelable: boolean\n}\n\n/**\n * `actionUrl` is validated here for the same reason the legacy store validates\n * it at registration: the surfaces that read this record hand the URL to\n * `window.open`.\n *\n * `superseded` has no counterpart in the legacy record: the scope moved on\n * under the operation, so there is nothing for this workspace's surfaces to\n * read — the same outcome `readOnRail` gives a superseded read.\n */\nexport function projectOperationRecord(\n  state: BillingOperationState\n): BillingOperationRecordView | undefined {\n  if (state.phase === 'superseded') return undefined\n\n  const identity = {\n    opId: state.id,\n    kind: state.kind,\n    workspaceId: state.scope.workspaceId\n  } as const\n\n  if (state.phase !== 'pending') {\n    return {\n      ...identity,\n      status: state.phase === 'timed_out' ? 'timeout' : state.phase,\n      actionUrl: null,\n      phase: null,\n      authenticationState:\n        state.phase === 'reconciliation_needed'\n          ? 'reconciliation_needed'\n          : null,\n      isAuthenticating: false,\n      canRetryAuthentication: false,\n      errorMessage: null,\n      cancelable: false\n    }\n  }\n\n  return {\n    ...identity,\n    status: 'pending',\n    actionUrl: validateActionUrl(state.actionUrl) ?? null,\n    phase: state.serverPhase ?? null,\n    authenticationState: state.authenticationState ?? null,\n    isAuthenticating: state.challenge?.status === 'in_progress',\n    canRetryAuthentication: state.challenge?.status === 'required',\n    errorMessage:\n      state.authenticationState === 'failed_retryable'\n        ? declineDetail(state.declineReason ?? 'authentication_failed')\n        : null,\n    cancelable: state.cancelable === true\n  }\n}\n","/**\n * Projections from the SDK's subscription results onto what the workspace\n * billing adapter already does with the legacy calls: succeed, throw a\n * `WorkspaceApiError`, or hand the action back so the legacy call runs.\n *\n * A 404 is the third case. The backend gate on these routes is independent of\n * the client flag, so a rail that is on before the routes are deployed must\n * leave the customer on the path that still works.\n */\nimport type {\n  BillingClient,\n  BillingTelemetryFailure,\n  CancelOperationResult,\n  PaymentPortalResult,\n  PreviewSubscribeInput,\n  PreviewSubscribeResult,\n  SubscribeInput,\n  SubscriptionCommandFailure,\n  SubscriptionCommandOutcome,\n  SubscriptionCommandResult\n} from '@comfyorg/account-core/billing'\nimport { failureCategoryFor } from '@comfyorg/account-core/billing'\n\nimport { t } from '@/i18n'\nimport type {\n  PreviewSubscribeResponse,\n  SubscribeResponse\n} from '@/platform/workspace/api/workspaceApi'\nimport { WorkspaceApiError } from '@/platform/workspace/api/workspaceApiError'\n\nimport { declineDetail } from './topupOperationView'\n\n/** False only when the server said the state already held: no operation was issued, so the lifecycle reported nothing. */\nexport interface SettledCommand {\n  readonly operationObserved: boolean\n}\n\n/**\n * A subscribe response as the checkout reads it. `requiredPayment` is set only\n * by the SDK rail, where `status` is always the settled `subscribed`: it says\n * whether the server had to take a payment from the customer to get there.\n * The legacy path leaves it unset — there a `subscribed` response is a plan\n * that was already active, and the poller it never started is what drew the\n * same line. `operationObserved` is set on the same rail, for the same reason\n * as on `SettledCommand`.\n */\nexport interface SettledSubscribeResponse\n  extends SubscribeResponse, Partial<SettledCommand> {\n  readonly requiredPayment?: boolean\n}\n\n/** The lifecycle drove the operation to a failed terminal and reported it; a refused attempt stays a plain `WorkspaceApiError` for the caller to report. */\nexport class SettledOperationError extends WorkspaceApiError {\n  constructor(\n    message: string,\n    phase: string,\n    readonly billingOpId: string | undefined,\n    failureCategory?: BillingTelemetryFailure['failure_category']\n  ) {\n    super(message, undefined, phase, failureCategory)\n    this.name = 'SettledOperationError'\n  }\n}\n\nimport type { BillingOperationRecordView } from './operationRecordView'\n\n/** The client a subscription action issued now runs on: the rail while its routes serve, else the legacy call. */\nexport function billingClientOf(rail: SubscriptionRail | null): BillingClient {\n  return rail?.subscriptionRouteAvailable ? 'sdk' : 'legacy'\n}\n\nexport type SubscriptionRailOutcome<T = void> =\n  | { readonly status: 'ok'; readonly value: T }\n  | { readonly status: 'error'; readonly error: Error }\n  /** The route is not deployed here; the caller runs its legacy path. */\n  | { readonly status: 'unavailable' }\n\n/**\n * The subscription actions the host routes through the SDK. Cancel and\n * resubscribe report only whether they settled; the portal hands back the URL\n * the host opens; subscribe and its quote hand back the bodies the checkout\n * already reads.\n */\nexport interface SubscriptionRail {\n  /**\n   * The hosted step a subscribe on this rail is parked on, or null. The rail\n   * opens it once itself, so this is what the checkout puts behind a button\n   * when the browser blocked that open.\n   */\n  readonly subscriptionActionUrl: string | null\n  /**\n   * The subscribe waiting on the customer, as the poller's record. The checkout\n   * drives its parked-recovery prompt, its authentication state and its busy\n   * state off this, so on this rail it has to come from the lifecycle.\n   */\n  readonly subscriptionActionOperation: BillingOperationRecordView | undefined\n  /** False once this tab's backend answered that the routes are not deployed. */\n  readonly subscriptionRouteAvailable: boolean\n  /** One operation by id, unscoped: the caller compares the workspace itself. */\n  getOperation: (opId: string) => BillingOperationRecordView | undefined\n  /** `callerStarted`: the caller reported `started`, so the rail reports only the terminal. */\n  subscribe: (\n    input: SubscribeInput,\n    options?: { readonly callerStarted?: boolean }\n  ) => Promise<SubscriptionRailOutcome<SettledSubscribeResponse>>\n  previewSubscribe: (\n    input: PreviewSubscribeInput\n  ) => Promise<SubscriptionRailOutcome<PreviewSubscribeResponse>>\n  cancelSubscription: () => Promise<SubscriptionRailOutcome<SettledCommand>>\n  resubscribe: () => Promise<SubscriptionRailOutcome<SettledCommand>>\n  openPaymentPortal: (\n    returnUrl: string\n  ) => Promise<SubscriptionRailOutcome<string>>\n  /** Asks the server to drop a pending payment it reported `cancelable`. */\n  cancelOperation: (opId: string) => Promise<SubscriptionRailOutcome>\n}\n\nconst UNAVAILABLE = { status: 'unavailable' } as const\n\nconst OBSERVED: SubscriptionRailOutcome<SettledCommand> = {\n  status: 'ok',\n  value: { operationObserved: true }\n}\n\nconst ALREADY_HELD: SubscriptionRailOutcome<SettledCommand> = {\n  status: 'ok',\n  value: { operationObserved: false }\n}\n\n/**\n * The failure as the adapter's own error. `serverCode` lands where the\n * adapter already keeps `WorkspaceApiError.code`, and the server's own\n * sentence is the message, as on the legacy rail.\n */\nfunction projectFailure(\n  failure: SubscriptionCommandFailure\n): SubscriptionRailOutcome<never> {\n  const httpStatus = 'httpStatus' in failure ? failure.httpStatus : undefined\n  if (httpStatus === 404) return UNAVAILABLE\n\n  // Nothing failed and nothing was charged, so the generic subscription\n  // failure would misread. The earlier payment is what the customer has to\n  // finish, and this sentence is the only thing that says so.\n  if (failure.code === 'OPERATION_ALREADY_PENDING') {\n    return {\n      status: 'error',\n      error: new WorkspaceApiError(\n        t('billingOperation.operationAlreadyPendingDetail'),\n        undefined,\n        failure.code\n      )\n    }\n  }\n\n  const serverCode = 'serverCode' in failure ? failure.serverCode : undefined\n  const serverMessage =\n    'serverMessage' in failure ? failure.serverMessage : undefined\n  return {\n    status: 'error',\n    error: new WorkspaceApiError(\n      serverMessage ?? t('billingOperation.subscriptionFailedDetail'),\n      httpStatus,\n      serverCode ?? failure.code\n    )\n  }\n}\n\n/**\n * A settle that ended anywhere but `succeeded` as a sentence for the customer:\n * a declined card carries the reason the top-up view already localizes, and\n * every other terminal phase is the generic subscription failure. The phase\n * itself lands on `code`, where the adapter keeps machine identifiers.\n */\nfunction projectUnsuccessfulSettle(\n  outcome: SubscriptionCommandOutcome\n): SubscriptionRailOutcome<never> {\n  const { operation, phase } = outcome\n  return {\n    status: 'error',\n    error: new SettledOperationError(\n      operation?.phase === 'failed'\n        ? declineDetail(operation.declineReason)\n        : t('billingOperation.subscriptionFailedDetail'),\n      phase,\n      operation?.id,\n      operation && failureCategoryFor(operation)\n    )\n  }\n}\n\n/**\n * A command that settled anywhere but `succeeded` failed for the customer,\n * exactly as a poller operation that ends in any other status does. A success\n * with no operation is the server saying the state already held.\n */\nexport function projectSubscriptionResult(\n  result: SubscriptionCommandResult\n): SubscriptionRailOutcome<SettledCommand> {\n  if (result.status === 'error') return projectFailure(result)\n  const { phase, operation } = result.value\n  if (phase !== 'succeeded') return projectUnsuccessfulSettle(result.value)\n  return operation === undefined ? ALREADY_HELD : OBSERVED\n}\n\n/**\n * A settled subscribe as the body `handleSubscribeResponse` already handles.\n * The SDK waits for the operation, so by the time this projects there is\n * nothing left to poll: the status is always the settled `subscribed`, never\n * the response's `needs_payment_method` or `pending_payment`, both of which\n * the lifecycle drove to a conclusion first. `issuedStatus` is what the\n * server answered before that, so `requiredPayment` keeps the line the legacy\n * poller drew: it watched — and so counted and announced — exactly the\n * subscribes the server could not activate on the spot. An adopted operation\n * carries no issued status and is one the server was still settling, which is\n * the same side of that line.\n *\n * An outcome carries no operation only when the server answered that the\n * requested state already held, which subscribe never reaches: the route\n * documents no already-held code.\n */\nexport function projectSubscribeResult(\n  result: SubscriptionCommandResult\n): SubscriptionRailOutcome<SettledSubscribeResponse> {\n  if (result.status === 'error') return projectFailure(result)\n  const { phase, operation, issuedStatus } = result.value\n  if (phase !== 'succeeded' || operation === undefined) {\n    return projectUnsuccessfulSettle(result.value)\n  }\n  return {\n    status: 'ok',\n    value: {\n      billing_op_id: operation.id,\n      status: 'subscribed',\n      requiredPayment: issuedStatus !== 'subscribed',\n      operationObserved: true\n    }\n  }\n}\n\nexport function projectPreviewSubscribeResult(\n  result: PreviewSubscribeResult\n): SubscriptionRailOutcome<PreviewSubscribeResponse> {\n  return result.status === 'error'\n    ? projectFailure(result)\n    : { status: 'ok', value: result.value }\n}\n\nexport function projectPaymentPortalResult(\n  result: PaymentPortalResult\n): SubscriptionRailOutcome<string> {\n  if (result.status === 'error') return projectFailure(result)\n  return { status: 'ok', value: result.value.url }\n}\n\nconst CANCEL_REFUSAL_COPY = {\n  NOT_CANCELABLE: 'billingOperation.cancelPaymentNotCancelable',\n  PAYMENT_IN_FLIGHT: 'billingOperation.cancelPaymentInFlight'\n} as const\n\n/**\n * A cancel the server took is done: the lifecycle it woke re-reads the\n * operation and settles it. Anything else reads as our own copy; the\n * server's text stays diagnostic.\n */\nexport function projectCancelOperationResult(\n  result: CancelOperationResult\n): SubscriptionRailOutcome {\n  if (result.status !== 'not_canceled' && result.status !== 'error')\n    return { status: 'ok', value: undefined }\n  return {\n    status: 'error',\n    error: new WorkspaceApiError(\n      t(\n        result.status === 'not_canceled'\n          ? CANCEL_REFUSAL_COPY[result.code]\n          : 'billingOperation.cancelPaymentFailed'\n      ),\n      'httpStatus' in result ? result.httpStatus : undefined,\n      result.code\n    )\n  }\n}\n","import type {\n  BillingScope,\n  BillingScopeSource,\n  BillingSession\n} from '@comfyorg/account-core/billing'\nimport type {\n  SessionErrorCode,\n  SessionRequestOptions,\n  SessionResult,\n  SessionSnapshot\n} from '@comfyorg/account-core/session'\nimport type { SessionTokenResult } from '@comfyorg/account-core/sessionTokenMint'\nimport type { WebSessionErrorCode } from '@comfyorg/account-core/webSession'\nimport { watch } from 'vue'\n\nimport { useCloudWebSessionStore } from '@/platform/auth/session/cloudWebSessionStore'\nimport type {\n  WebSessionRequestScope,\n  WebSessionRequests\n} from '@/platform/auth/session/webSessionFetch'\nimport { useWorkspaceAuthStore } from '@/platform/workspace/stores/workspaceAuthStore'\n\nexport type WebSessionBillingSession = BillingSession & BillingScopeSource\n\nconst SESSION_CODE: Readonly<\n  Record<Exclude<WebSessionErrorCode, 'IDENTITY_CHANGED'>, SessionErrorCode>\n> = {\n  NO_SESSION: 'NOT_AUTHENTICATED',\n  SESSION_EXPIRED: 'NOT_AUTHENTICATED',\n  SESSION_REVOKED: 'NOT_AUTHENTICATED',\n  WORKSPACE_ACCESS_DENIED: 'ACCESS_DENIED',\n  CSRF_STALE: 'TOKEN_EXCHANGE_FAILED',\n  SESSION_REQUEST_REFUSED: 'TOKEN_EXCHANGE_FAILED',\n  SSO_REQUIRED: 'SSO_REQUIRED',\n  SESSION_UNAVAILABLE: 'TOKEN_EXCHANGE_FAILED'\n}\n\nconst SIGNED_OUT: SessionSnapshot = {\n  phase: 'signed-out',\n  user: null,\n  session: undefined\n}\n\nfunction sessionResult(result: SessionTokenResult): SessionResult | undefined {\n  if (result.status === 'ok')\n    return { status: 'ok', session: result.credential }\n  if (result.code === 'IDENTITY_CHANGED') return undefined\n  return {\n    status: 'error',\n    code: SESSION_CODE[result.code],\n    ...(result.httpStatus === undefined\n      ? {}\n      : { httpStatus: result.httpStatus })\n  }\n}\n\n/**\n * The billing SDK's session on a tab signed in on the web session: tokens\n * come from the session mint, and the scope from the session user and the\n * selected workspace, which are known before anything is minted.\n */\nexport function createWebSessionBillingSession(\n  requests: WebSessionRequests\n): WebSessionBillingSession {\n  const webSession = useCloudWebSessionStore()\n  const workspaceAuth = useWorkspaceAuthStore()\n\n  function getScope(): BillingScope | undefined {\n    const user = webSession.signedInUser\n    const workspace = workspaceAuth.currentWorkspace\n    if (!user || !workspace) return undefined\n    return { userId: user.id, workspaceId: workspace.id, role: workspace.role }\n  }\n\n  function getSnapshot(): SessionSnapshot {\n    const scope = getScope()\n    if (!scope) return SIGNED_OUT\n    return {\n      phase: 'minting',\n      user: {\n        uid: scope.userId,\n        getIdToken: () =>\n          Promise.reject(new Error('A web session has no Firebase ID token'))\n      },\n      session: undefined\n    }\n  }\n\n  const mintWith =\n    (mint: (scope: WebSessionRequestScope) => Promise<SessionTokenResult>) =>\n    async (\n      _user: unknown,\n      options?: SessionRequestOptions\n    ): Promise<SessionResult | undefined> => {\n      const scope = await requests.scope()\n      if (!scope) return undefined\n      return sessionResult(\n        await mint({ ...scope, workspaceId: options?.workspaceId })\n      )\n    }\n\n  return {\n    getScope,\n    getSnapshot,\n    subscribe: (listener) =>\n      watch(getScope, () => listener(getSnapshot()), {\n        flush: 'sync'\n      }),\n    ensureFresh: mintWith(requests.workspaceToken),\n    remint: mintWith(requests.remintWorkspaceToken)\n  }\n}\n","import { openBillingUrl } from '@/platform/workspace/billing/billingTab'\n/**\n * The app's single billing SDK instance and the top-up effects the poller\n * performs today, moved onto the lifecycle's state: the progress toast, the\n * in-page challenge, and — for an operation this tab reattached to rather\n * than issued — the refresh, dialog routing, toast, and telemetry that the\n * dialog performs for the operations it issues itself.\n */\nimport type {\n  BillingOperationKind,\n  BillingOperationState,\n  BillingEventsReadOptions,\n  BillingOperationTelemetryEvent,\n  BillingResult,\n  CapabilitiesReadOptions,\n  EmbeddedChallengePort,\n  PendingBillingOperation,\n  PreviewSubscribeInput,\n  SubscribeInput\n} from '@comfyorg/account-core/billing'\nimport {\n  BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT,\n  BILLING_OPERATION_TELEMETRY_EVENT,\n  toBillingTelemetryEvent,\n  validateActionUrl\n} from '@comfyorg/account-core/billing'\nimport { loadStripe } from '@stripe/stripe-js/pure'\nimport { until, useEventListener } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { computed, shallowRef } from 'vue'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { t } from '@/i18n'\nimport { webSessionRequests } from '@/platform/auth/session/webSessionFetch'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type {\n  BillingBalanceResponse,\n  BillingCapabilitiesResponse,\n  BillingEventsResponse,\n  BillingPlansResponse,\n  BillingStatusResponse,\n  CreateTopupResponse,\n  PreviewSubscribeResponse,\n  SavedPaymentMethod\n} from '@/platform/workspace/api/workspaceApi'\nimport { workspaceApiUrl } from '@/platform/workspace/api/workspaceApiUrl'\nimport type {\n  ProgressToast,\n  ProgressToastKind\n} from '@/platform/workspace/billing/customerAttention'\nimport {\n  isParkedCheckout,\n  needsCustomerAttention,\n  progressToastKind\n} from '@/platform/workspace/billing/customerAttention'\nimport { resolveStripePublishableKey } from '@/platform/workspace/billing/stripePublishableKey'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { useWorkspaceAuthStore } from '@/platform/workspace/stores/workspaceAuthStore'\nimport { getCheckoutJourneyPaymentIntentSource } from '@/platform/workspace/utils/checkoutJourney'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nimport { projectBillingCapabilities } from './billingCapabilitiesView'\nimport { projectBillingPlans } from './billingPlansView'\nimport { projectBillingStatus } from './billingStatusView'\nimport type { BillingSdkOptions } from './createBillingSdk'\nimport { createBillingSdk } from './createBillingSdk'\nimport type { BillingOperationRecordView } from './operationRecordView'\nimport { projectOperationRecord } from './operationRecordView'\nimport type {\n  SettledCommand,\n  SettledSubscribeResponse,\n  SubscriptionRailOutcome\n} from './subscriptionOperationView'\nimport {\n  projectCancelOperationResult,\n  projectPaymentPortalResult,\n  projectPreviewSubscribeResult,\n  projectSubscribeResult,\n  projectSubscriptionResult\n} from './subscriptionOperationView'\nimport {\n  declineDetail,\n  projectHostedTopupCheckoutResult,\n  projectTopupOperation,\n  projectTopupResult\n} from './topupOperationView'\nimport { createWebSessionBillingSession } from './webSessionBillingSession'\n\nconst PROGRESS_SUMMARY = {\n  topup: {\n    processing: 'billingOperation.topupProcessing',\n    action: 'billingOperation.topupActionRequired'\n  },\n  subscription: {\n    processing: 'billingOperation.subscriptionProcessing',\n    action: 'billingOperation.subscriptionActionRequired'\n  }\n} as const satisfies Record<string, Record<ProgressToastKind, string>>\n\nconst FRICTION_EVENT_NAMES: ReadonlySet<string> = new Set(\n  Object.values(BILLING_CHECKOUT_FRICTION_TELEMETRY_EVENT)\n)\n\nfunction isFrictionEvent(event: BillingOperationTelemetryEvent): boolean {\n  return FRICTION_EVENT_NAMES.has(event.name)\n}\n\nasync function loadChallengePort(): Promise<EmbeddedChallengePort | undefined> {\n  const publishableKey = resolveStripePublishableKey()\n  const stripe = publishableKey\n    ? await loadStripe(publishableKey).catch(() => null)\n    : null\n  if (!stripe) return undefined\n  return {\n    handleNextAction: (clientSecret) =>\n      stripe.handleNextAction({ clientSecret })\n  }\n}\n\nexport const useBillingSdkStore = defineStore('billingSdk', () => {\n  const workspaceAuthStore = useWorkspaceAuthStore()\n  const workspaceStore = useTeamWorkspaceStore()\n  const toast = useToast()\n  const { flags } = useFeatureFlags()\n  const billingCapabilities = useBillingCapabilities()\n\n  const operations = shallowRef<readonly BillingOperationState[]>([])\n  const dismissed = shallowRef<ReadonlySet<string>>(new Set())\n  const resumedOperations = new Set<string>()\n  const callerStarted = new Set<BillingOperationKind>()\n  const drivenChallenges = new Set<string>()\n  const offeredActions = new Map<string, Set<string>>()\n  const progressToasts = new Map<string, ProgressToast>()\n\n  function sessionPorts(): Pick<\n    BillingSdkOptions,\n    'session' | 'scopeSource' | 'workspaceId'\n  > {\n    const requests = webSessionRequests()\n    if (requests) {\n      const session = createWebSessionBillingSession(requests)\n      return {\n        session,\n        scopeSource: session,\n        workspaceId: requests.workspaceId\n      }\n    }\n    return {\n      session: workspaceAuthStore.getUnifiedSessionClient(),\n      workspaceId: () => workspaceAuthStore.getUnifiedMintWorkspaceId()\n    }\n  }\n\n  const sdk = createBillingSdk({\n    ...sessionPorts(),\n    resolveUrl: workspaceApiUrl,\n    pointerStorage: sessionStorage,\n    embeddedCheckoutAvailable: () =>\n      flags.embeddedCheckoutEnabled && Boolean(resolveStripePublishableKey()),\n    hostedDestination: () => flags.hostedBillingDestination,\n    onTelemetry: reportTelemetry,\n    challengePort: loadChallengePort\n  })\n\n  sdk.lifecycle.subscribe((state) => {\n    operations.value = sdk.lifecycle.getSnapshot()\n    if (state.kind === 'topup') onTopupChanged(state)\n    else onSubscriptionChanged(state)\n  })\n\n  const wake = () => {\n    if (document.visibilityState === 'visible') sdk.lifecycle.wake()\n  }\n  useEventListener(document, 'visibilitychange', wake)\n  useEventListener(window, 'focus', wake)\n\n  const topupViews = computed(() =>\n    operations.value\n      .filter((state) => !dismissed.value.has(state.id))\n      .flatMap((state) => projectTopupOperation(state) ?? [])\n  )\n  const isAddingCredits = computed(() =>\n    topupViews.value.some(\n      (view) =>\n        view.status === 'pending' &&\n        view.authenticationState !== 'failed_retryable'\n    )\n  )\n  const topupActionOperation = computed(() =>\n    topupViews.value.find(needsCustomerAttention)\n  )\n\n  // The lifecycle already refuses anything but https on the way in\n  // (`operationLifecycle.ts` adoption, `operationState.ts` on every poll); the\n  // same predicate runs again here so the rule holds for whoever publishes a\n  // state, and so the guarantee is readable where the URL is handed out.\n  const hostedActionUrl = (state: BillingOperationState): string | undefined =>\n    state.phase === 'pending' ? validateActionUrl(state.actionUrl) : undefined\n\n  const subscriptionActionUrl = computed(\n    () =>\n      operations.value.flatMap((state) =>\n        state.kind === 'subscription' ? (hostedActionUrl(state) ?? []) : []\n      )[0] ?? null\n  )\n\n  // The four below mirror `billingOperationStore`'s own predicates, including\n  // where it does and does not scope to the active workspace: the lifecycle\n  // keeps operations from a scope it has left, and a consumer switching rails\n  // must not find a different answer on the other side.\n  const operationRecords = computed(() =>\n    operations.value.flatMap((state) => projectOperationRecord(state) ?? [])\n  )\n\n  const hasPendingOperations = computed(() =>\n    operationRecords.value.some((record) => record.status === 'pending')\n  )\n\n  const isSettingUp = computed(() =>\n    operationRecords.value.some(\n      (record) =>\n        record.kind === 'subscription' &&\n        record.status === 'pending' &&\n        record.authenticationState !== 'requires_action' &&\n        record.authenticationState !== 'failed_retryable' &&\n        !isParkedCheckout(record) &&\n        record.workspaceId === workspaceStore.activeWorkspaceId\n    )\n  )\n\n  const subscriptionActionOperation = computed(() =>\n    operationRecords.value.find(\n      (record) =>\n        record.kind === 'subscription' &&\n        record.workspaceId === workspaceStore.activeWorkspaceId &&\n        needsCustomerAttention(record)\n    )\n  )\n\n  function getOperation(opId: string): BillingOperationRecordView | undefined {\n    return operationRecords.value.find((record) => record.opId === opId)\n  }\n\n  // A top-up the dialog issued is reported by the dialog, exactly as before;\n  // the lifecycle's events stand in for the poller's only on an operation\n  // this tab reattached to. A cancel or subscribe the caller announced with\n  // its own `started` keeps that one event: the lifecycle's `started` is\n  // dropped inside the caller's command window, and its terminal is always\n  // forwarded, since only the lifecycle holds the operation's id, category\n  // and timing. A command no caller announced — a resubscribe, a checkout\n  // that reports nothing — is reported at both ends by the lifecycle.\n  // Friction inside an operation has no other reporter, so it always goes.\n  function reportTelemetry(event: BillingOperationTelemetryEvent) {\n    if (isFrictionEvent(event)) {\n      useTelemetry()?.trackBillingEvent(toBillingTelemetryEvent(event))\n      return\n    }\n    if (event.operation_type === 'topup' && !event.resumed) return\n    const started = event.name === BILLING_OPERATION_TELEMETRY_EVENT.started\n    if (started && event.resumed) resumedOperations.add(event.billing_op_id)\n    if (started && !event.resumed && callerStarted.has(event.operation_type)) {\n      return\n    }\n    useTelemetry()?.trackBillingEvent(\n      toBillingTelemetryEvent(\n        event,\n        getCheckoutJourneyPaymentIntentSource(event.billing_op_id)\n      )\n    )\n  }\n\n  // Sound because the lifecycle runs one command per kind at a time and\n  // emits both of an issued operation's events before the command resolves.\n  async function withCallerStart<T>(\n    kind: BillingOperationKind,\n    run: () => Promise<T>\n  ): Promise<T> {\n    callerStarted.add(kind)\n    try {\n      return await run()\n    } finally {\n      callerStarted.delete(kind)\n    }\n  }\n\n  function onTopupChanged(state: BillingOperationState) {\n    if (state.phase === 'pending') {\n      syncProgressToast(state, 'topup')\n      void driveRequiredChallenge(state)\n      return\n    }\n    clearProgressToast(state.id)\n    dismissed.value = new Set(\n      [...dismissed.value].filter((id) => id !== state.id)\n    )\n    if (state.phase === 'timed_out') {\n      toast.error(t('billingOperation.topupTimeout'))\n    }\n    if (resumedOperations.delete(state.id)) void settleResumed(state)\n  }\n\n  function syncProgressToast(\n    state: PendingBillingOperation,\n    kind: keyof typeof PROGRESS_SUMMARY\n  ) {\n    const progress = progressToastKind({\n      actionUrl: state.actionUrl,\n      phase: state.serverPhase\n    })\n    const current = progressToasts.get(state.id)\n    if (current?.kind === progress) return\n    clearProgressToast(state.id)\n    if (progress === undefined) return\n    const title = t(PROGRESS_SUMMARY[kind][progress])\n    const id =\n      progress === 'action' ? toast.warning(title) : toast.loading(title)\n    progressToasts.set(state.id, { kind: progress, id })\n  }\n\n  function clearProgressToast(operationId: string) {\n    const current = progressToasts.get(operationId)\n    if (!current) return\n    toast.dismiss(current.id)\n    progressToasts.delete(operationId)\n  }\n\n  // A subscribe the SDK settles has no dialog watching it, so the two customer\n  // steps the checkout performs for the legacy response — driving the in-page\n  // challenge and opening the hosted payment page — are performed here, or the\n  // operation waits on a customer who was never shown anything.\n  function onSubscriptionChanged(state: BillingOperationState) {\n    if (state.phase !== 'pending') {\n      clearProgressToast(state.id)\n      offeredActions.delete(state.id)\n      if (resumedOperations.delete(state.id)) {\n        void settleResumedSubscription(state)\n      }\n      return\n    }\n    if (state.kind === 'subscription') syncProgressToast(state, 'subscription')\n    // A reattached operation may be one billing-web is paying right now, so its\n    // challenge is that page's to drive, as on the legacy rail.\n    if (resumedOperations.has(state.id)) return\n    void driveRequiredChallenge(state)\n    if (!drivesInPageChallenge(state)) openHostedAction(state)\n  }\n\n  // The server offers its hosted page beside the client secret, so an\n  // embedded operation carries both; the in-page challenge is its route.\n  function drivesInPageChallenge(state: PendingBillingOperation): boolean {\n    return state.presentation === 'embedded' && state.challenge !== undefined\n  }\n\n  // One offer per hosted step, not per poll, and not again for a step this\n  // operation already offered: the open runs off the lifecycle rather than a\n  // click, so a browser that blocked the first one blocks every retry and each\n  // retry would repeat the warning. An operation reattached on load is never\n  // offered at all, since no click of this page started it. A step the\n  // customer still owes stays on `subscriptionActionUrl` for the checkout to\n  // put behind a button of their own.\n  function openHostedAction(state: PendingBillingOperation) {\n    const actionUrl = hostedActionUrl(state)\n    if (actionUrl === undefined) return\n    const offered = offeredActions.get(state.id) ?? new Set<string>()\n    if (offered.has(actionUrl)) return\n    offeredActions.set(state.id, offered.add(actionUrl))\n    if (openBillingUrl(actionUrl)) {\n      sdk.lifecycle.reportHostedStepOpened(state.id, 'new_tab')\n      return\n    }\n    toast.warning(t('g.warning'), {\n      description: t('subscription.preview.paymentPopupBlocked')\n    })\n  }\n\n  // One in-page challenge per operation, as the poller drives it: a later\n  // challenge for the same operation waits for the customer's retry.\n  async function driveRequiredChallenge(state: PendingBillingOperation) {\n    if (state.challenge?.status !== 'required') return\n    if (drivenChallenges.has(state.id)) return\n    drivenChallenges.add(state.id)\n    await sdk.driveChallenge(state.id)\n  }\n\n  async function settleResumed(state: BillingOperationState) {\n    if (state.phase === 'succeeded') {\n      const billingContext = useBillingContext()\n      await Promise.allSettled([\n        billingContext.fetchStatus(),\n        billingContext.fetchBalance(),\n        billingCapabilities.refresh()\n      ])\n      useDialogStore().closeDialog({ key: 'top-up-credits' })\n      useSettingsDialog().show(isCloud ? 'workspace' : 'credits')\n      toast.success(t('billingOperation.topupSuccess'), {\n        duration: 5000\n      })\n      return\n    }\n    if (state.phase === 'failed') {\n      toast.error(t('billingOperation.topupFailed'), {\n        description: declineDetail(state.declineReason),\n        duration: 7000\n      })\n    }\n  }\n\n  // A subscribe this tab reattached to after a reload has no checkout left to\n  // report it, so it settles the way the poller settled it. Only a subscribe\n  // is ever reattached: the status names a pending subscription or top-up.\n  async function settleResumedSubscription(state: BillingOperationState) {\n    if (state.phase === 'succeeded') {\n      await refreshAfterSubscriptionChange()\n      toast.success(t('billingOperation.subscriptionSuccess'), {\n        duration: 5000\n      })\n      return\n    }\n    if (state.phase === 'timed_out') {\n      toast.error(t('billingOperation.subscriptionTimeout'))\n      return\n    }\n    if (state.phase === 'failed') {\n      toast.error(t('billingOperation.subscriptionFailed'), {\n        description: declineDetail(state.declineReason),\n        duration: 7000\n      })\n    }\n  }\n\n  async function createTopup(\n    amountCents: number\n  ): Promise<CreateTopupResponse | undefined> {\n    const result = await sdk.topup.createTopupCheckout({ amountCents })\n    if (result.status === 'ok') void billingCapabilities.refresh()\n    return projectTopupResult(result, amountCents)\n  }\n\n  async function createHostedTopupCheckout(\n    amountCents: number,\n    returnUrl: string\n  ): Promise<string> {\n    return projectHostedTopupCheckoutResult(\n      await sdk.topup.createHostedTopupCheckout({ amountCents, returnUrl })\n    )\n  }\n\n  // The backend gate on these routes is independent of the client flag, so a\n  // 404 means the rail is on too early. One answer settles it for the tab:\n  // every later action goes straight to the legacy call.\n  const subscriptionRouteAvailable = shallowRef(true)\n\n  async function onSubscriptionRoute<T>(\n    run: () => Promise<SubscriptionRailOutcome<T>>\n  ): Promise<SubscriptionRailOutcome<T>> {\n    if (!subscriptionRouteAvailable.value) return { status: 'unavailable' }\n    const outcome = await run()\n    if (outcome.status === 'unavailable') {\n      subscriptionRouteAvailable.value = false\n    }\n    return outcome\n  }\n\n  async function runSubscriptionCommand<T>(\n    command: () => Promise<SubscriptionRailOutcome<T>>,\n    refresh: () => Promise<void>\n  ): Promise<SubscriptionRailOutcome<T>> {\n    const outcome = await onSubscriptionRoute(command)\n    if (outcome.status === 'ok') await refresh()\n    return outcome\n  }\n\n  // What the poller refreshes when one of its operations succeeds, so the\n  // panels read the same state whichever rail settled the operation.\n  async function refreshAfterCancel(): Promise<void> {\n    const billingContext = useBillingContext()\n    await Promise.allSettled([\n      billingContext.fetchStatus(),\n      billingContext.fetchBalance(),\n      billingCapabilities.refresh()\n    ])\n  }\n\n  async function refreshAfterSubscriptionChange(): Promise<void> {\n    const billingContext = useBillingContext()\n    await Promise.allSettled([\n      billingContext.reconcileSubscriptionSuccess(),\n      billingCapabilities.refresh()\n    ])\n  }\n\n  function cancelSubscription(): Promise<\n    SubscriptionRailOutcome<SettledCommand>\n  > {\n    return withCallerStart('cancel', () =>\n      runSubscriptionCommand(\n        async () =>\n          projectSubscriptionResult(await sdk.commands.cancelSubscription()),\n        refreshAfterCancel\n      )\n    )\n  }\n\n  function resubscribe(): Promise<SubscriptionRailOutcome<SettledCommand>> {\n    return runSubscriptionCommand(\n      async () => projectSubscriptionResult(await sdk.commands.resubscribe()),\n      refreshAfterSubscriptionChange\n    )\n  }\n\n  function subscribe(\n    input: SubscribeInput,\n    { callerStarted: announced = false }: { callerStarted?: boolean } = {}\n  ): Promise<SubscriptionRailOutcome<SettledSubscribeResponse>> {\n    const run = () =>\n      runSubscriptionCommand(\n        async () => projectSubscribeResult(await sdk.commands.subscribe(input)),\n        refreshAfterSubscriptionChange\n      )\n    return announced ? withCallerStart('subscription', run) : run()\n  }\n\n  // A quote changes nothing, so it refreshes nothing; it shares the route\n  // latch because the backend gates it with the rest of them.\n  async function previewSubscribe(\n    input: PreviewSubscribeInput\n  ): Promise<SubscriptionRailOutcome<PreviewSubscribeResponse>> {\n    return onSubscriptionRoute(async () =>\n      projectPreviewSubscribeResult(await sdk.commands.previewSubscribe(input))\n    )\n  }\n\n  async function openPaymentPortal(\n    returnUrl: string\n  ): Promise<SubscriptionRailOutcome<string>> {\n    const outcome = await onSubscriptionRoute(async () =>\n      projectPaymentPortalResult(\n        await sdk.commands.openPaymentPortal({ returnUrl })\n      )\n    )\n    // The portal may add or remove a card and says nothing on the way back, so\n    // handing the URL out is the last moment this tab's list is known good.\n    if (outcome.status === 'ok') sdk.paymentMethods.invalidate()\n    return outcome\n  }\n\n  async function cancelOperation(\n    opId: string\n  ): Promise<SubscriptionRailOutcome> {\n    return projectCancelOperationResult(\n      await sdk.commands.cancelOperation(opId)\n    )\n  }\n\n  /** Adopts the operation the server reports pending; true once one is adopted. */\n  async function recover(): Promise<boolean> {\n    const adopted = await sdk.lifecycle.recover()\n    return adopted.status === 'ok' && adopted.value !== undefined\n  }\n\n  /**\n   * Adopt the operation the server reports pending and resolve once it settles,\n   * for the caller that has something to decide on the outcome.\n   * `lifecycle.recover()` resolves at adoption, not at settlement, and it\n   * adopts whatever the server names — so an id other than the one asked for\n   * means the pointer this caller held is stale.\n   */\n  async function recoverPendingOperation(\n    opId: string\n  ): Promise<BillingOperationRecordView | undefined> {\n    const adopted = await sdk.lifecycle.recover()\n    if (adopted.status === 'error' || adopted.value?.id !== opId) {\n      return undefined\n    }\n    const record = computed(() => getOperation(opId))\n    return until(record).toMatch(\n      (view) => view === undefined || view.status !== 'pending'\n    )\n  }\n\n  // The readers the commands above already refresh after a success, exposed\n  // so the panels read the state the rail settled rather than a second read\n  // through the workspace client.\n  async function readStatus(): Promise<BillingResult<BillingStatusResponse>> {\n    const result = await sdk.status.read()\n    if (result.status === 'error') return result\n    const status = projectBillingStatus(result.value.status)\n    return status === undefined\n      ? { status: 'error', code: 'MALFORMED_RESPONSE' }\n      : { status: 'ok', value: status }\n  }\n\n  async function readBalance(): Promise<BillingResult<BillingBalanceResponse>> {\n    const result = await sdk.credits.read()\n    return result.status === 'ok'\n      ? { status: 'ok', value: result.value.balance }\n      : result\n  }\n\n  async function readPlans(): Promise<BillingResult<BillingPlansResponse>> {\n    const result = await sdk.plans.read()\n    if (result.status === 'error') return result\n    const plans = projectBillingPlans(result.value.data)\n    return plans === undefined\n      ? { status: 'error', code: 'MALFORMED_RESPONSE' }\n      : { status: 'ok', value: plans }\n  }\n\n  async function readCapabilities(\n    options: CapabilitiesReadOptions\n  ): Promise<BillingResult<BillingCapabilitiesResponse>> {\n    const result = await sdk.capabilities.read(options)\n    return result.status === 'ok'\n      ? { status: 'ok', value: projectBillingCapabilities(result.value) }\n      : result\n  }\n\n  async function readPaymentMethods(): Promise<\n    BillingResult<SavedPaymentMethod[]>\n  > {\n    const result = await sdk.paymentMethods.read()\n    return result.status === 'ok'\n      ? { status: 'ok', value: [...result.value.methods] }\n      : result\n  }\n\n  // The one read with nothing to project: the events response carries no\n  // int64, so the decoded page already holds the numbers the host's type\n  // says it does. Only the scope and read instant the snapshot adds are\n  // dropped here.\n  async function readEvents(\n    options?: BillingEventsReadOptions\n  ): Promise<BillingResult<BillingEventsResponse>> {\n    const result = await sdk.events.read(options)\n    if (result.status === 'error') return result\n    const { events, page, limit, total, totalPages } = result.value\n    return {\n      status: 'ok',\n      value: { events: [...events], page, limit, total, totalPages }\n    }\n  }\n\n  async function retryPaymentAuthentication(\n    operationId: string\n  ): Promise<boolean> {\n    if (!flags.embeddedCheckoutEnabled) return false\n    drivenChallenges.add(operationId)\n    return (await sdk.driveChallenge(operationId)) === 'completed'\n  }\n\n  function dismissOperation(operationId: string) {\n    dismissed.value = new Set([...dismissed.value, operationId])\n  }\n\n  return {\n    isAddingCredits,\n    topupActionOperation,\n    subscriptionActionUrl,\n    hasPendingOperations,\n    isSettingUp,\n    subscriptionActionOperation,\n    subscriptionRouteAvailable,\n    getOperation,\n    recoverPendingOperation,\n    createTopup,\n    createHostedTopupCheckout,\n    subscribe,\n    previewSubscribe,\n    cancelSubscription,\n    resubscribe,\n    openPaymentPortal,\n    cancelOperation,\n    recover,\n    readStatus,\n    readBalance,\n    readPlans,\n    readCapabilities,\n    readPaymentMethods,\n    readEvents,\n    retryPaymentAuthentication,\n    dismissOperation\n  }\n})\n","import type {\n  BillingEventsReadOptions,\n  BillingResult,\n  CapabilitiesReadOptions\n} from '@comfyorg/account-core/billing'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport type {\n  BillingBalanceResponse,\n  BillingCapabilitiesResponse,\n  BillingEventsResponse,\n  BillingPlansResponse,\n  BillingStatusResponse,\n  SavedPaymentMethod\n} from '@/platform/workspace/api/workspaceApi'\nimport { useBillingSdkStore } from '@/platform/workspace/billing/sdk/billingSdkStore'\n\n/** The reads a rail serves, in the shape the host's billing state holds. */\nexport interface BillingReadRail {\n  readStatus: () => Promise<BillingResult<BillingStatusResponse>>\n  readBalance: () => Promise<BillingResult<BillingBalanceResponse>>\n  readPlans: () => Promise<BillingResult<BillingPlansResponse>>\n  readCapabilities: (\n    options: CapabilitiesReadOptions\n  ) => Promise<BillingResult<BillingCapabilitiesResponse>>\n  readPaymentMethods: () => Promise<BillingResult<SavedPaymentMethod[]>>\n  /** The only read whose request varies per call: it asks for one page. */\n  readEvents: (\n    options?: BillingEventsReadOptions\n  ) => Promise<BillingResult<BillingEventsResponse>>\n}\n\n/**\n * Which rail the billing reads — status, balance, plans, capabilities, saved\n * payment methods and the history feed — are served on. Null is the legacy\n * client. Either write rail turns the reads on: a status the SDK's lifecycle\n * recovers from, or a balance its top-up refreshes, should come from the same\n * readers those commands already refreshed, or the panels read one thing and\n * the rail settled another.\n *\n * Read once per fetch and held for it, like the write rails: a flag flip\n * mid-read must not start on one client and publish through the other.\n */\nexport function useBillingReadRail(): BillingReadRail | null {\n  const { flags } = useFeatureFlags()\n  return flags.billingSdkTopupRailEnabled ||\n    flags.billingSdkSubscriptionRailEnabled\n    ? useBillingSdkStore()\n    : null\n}\n","/**\n * The workspace deep-link contract: the one query parameter, `workspace`,\n * that every surface — the cloud app, comfy.org, and the billing SDK's entry\n * URL — reads and writes to say which workspace a link is for.\n *\n * It is the URL parameter only, never the token API field. `POST\n * /api/auth/token` still takes `{ workspace_id }` in its request body; that\n * name does not change here and this module does not touch it.\n *\n * A destination applies the link before it loads workspace-scoped content:\n * it mints a token for the named id and lets the server decide membership,\n * the same way any other mint does. A payment or billing destination fails\n * closed on a link it cannot honor and never acts on a workspace other than\n * the one named — silently falling back to the caller's own active workspace\n * would bill or expose the wrong one. A navigation destination may fall back\n * to its own active workspace when the link is absent or invalid, but must\n * show which workspace it landed on rather than switch silently. The\n * parameter is carried through the sign-in redirect like any other query\n * parameter on the path being returned to.\n */\n\nexport const WORKSPACE_LINK_PARAM = 'workspace'\n\nexport type WorkspaceLinkRead =\n  | { readonly status: 'absent' }\n  | { readonly status: 'ok'; readonly workspaceId: string }\n  | { readonly status: 'invalid' }\n\n/** Same charset as `@comfyorg/billing-contract`'s identifiers: no path separator, query delimiter, or percent escape survives it. */\nconst WORKSPACE_ID = /^[A-Za-z0-9_-]{1,128}$/\n\nexport function isWorkspaceId(value: string): boolean {\n  return WORKSPACE_ID.test(value)\n}\n\n/** Reserved by RFC 2606; only used to parse a path+query string that carries no origin of its own. */\nconst PARSE_BASE = 'https://workspace-link.invalid/'\n\nfunction searchParamsOf(\n  source: URL | URLSearchParams | string\n): URLSearchParams | undefined {\n  if (source instanceof URLSearchParams) return source\n  if (source instanceof URL) return source.searchParams\n  try {\n    return new URL(source, PARSE_BASE).searchParams\n  } catch {\n    return undefined\n  }\n}\n\n/**\n * Reads the link out of a URL, a `URLSearchParams`, or a string (a full URL\n * or the path-and-query form a router hands over). A missing parameter is\n * `absent`; a present-but-empty value is `invalid`, the same as any other\n * value outside the shared charset — an empty `workspace=` is a producer\n * bug, not \"no link,\" and a payment destination has to fail closed on it\n * rather than treat it as though the link were never there. A repeated\n * parameter is also `invalid` rather than picking one, so a caller cannot be\n * pointed at two different workspaces by ambiguity.\n */\nexport function readWorkspaceLink(\n  source: URL | URLSearchParams | string\n): WorkspaceLinkRead {\n  const params = searchParamsOf(source)\n  if (!params) return { status: 'absent' }\n\n  const values = params.getAll(WORKSPACE_LINK_PARAM)\n  if (values.length === 0) return { status: 'absent' }\n  if (values.length > 1) return { status: 'invalid' }\n\n  const [value] = values\n  if (!isWorkspaceId(value)) return { status: 'invalid' }\n\n  return { status: 'ok', workspaceId: value }\n}\n\n/** Returns a new `URL` carrying the link; never mutates `url`. Throws `RangeError` on an id outside the shared charset. */\nexport function withWorkspaceLink(url: URL, workspaceId: string): URL {\n  if (!isWorkspaceId(workspaceId))\n    throw new RangeError(`not a workspace id: ${workspaceId}`)\n  const next = new URL(url.href)\n  next.searchParams.set(WORKSPACE_LINK_PARAM, workspaceId)\n  return next\n}\n\n/** Returns a new `URL` with the link removed; never mutates `url`. */\nexport function withoutWorkspaceLink(url: URL): URL {\n  const next = new URL(url.href)\n  next.searchParams.delete(WORKSPACE_LINK_PARAM)\n  return next\n}\n","import {\n  isWorkspaceId,\n  withWorkspaceLink\n} from '@comfyorg/account-core/workspaceLink'\n\nimport { getComfyPlatformBaseUrl } from '@/config/comfyApi'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\n\n/** A platform URL for `path` that opens in the cloud app's active workspace, when there is one. */\nexport function platformLink(path: `/${string}`): string {\n  const url = new URL(`${getComfyPlatformBaseUrl()}${path}`)\n  const workspaceId = useTeamWorkspaceStore().activeWorkspaceId\n  if (!workspaceId || !isWorkspaceId(workspaceId)) return url.href\n  return withWorkspaceLink(url, workspaceId).href\n}\n","<template>\n  <div\n    class=\"flex min-w-[460px] flex-col rounded-2xl border border-border-default bg-base-background shadow-[1px_1px_8px_0_rgba(0,0,0,0.4)]\"\n  >\n    <!-- Header -->\n    <div class=\"flex items-center justify-between p-8\">\n      <h2 class=\"m-0 text-lg font-bold text-base-foreground\">\n        {{\n          isInsufficientCredits\n            ? $t('credits.topUp.addMoreCreditsToRun')\n            : $t('credits.topUp.addMoreCredits')\n        }}\n      </h2>\n      <button\n        class=\"cursor-pointer rounded-sm border-none bg-transparent p-0 text-muted-foreground transition-colors hover:text-base-foreground focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none\"\n        :aria-label=\"$t('g.close')\"\n        @click=\"() => handleClose()\"\n      >\n        <i class=\"icon-[lucide--x] size-6\" />\n      </button>\n    </div>\n    <p\n      v-if=\"isInsufficientCredits\"\n      class=\"m-0 px-8 text-sm text-muted-foreground\"\n    >\n      {{ $t('credits.topUp.insufficientWorkflowMessage') }}\n    </p>\n\n    <!-- Preset amount buttons -->\n    <div class=\"px-8\">\n      <h3 class=\"m-0 text-sm font-normal text-muted-foreground\">\n        {{ $t('credits.topUp.selectAmount') }}\n      </h3>\n      <div class=\"flex gap-2 pt-3\">\n        <Button\n          v-for=\"amount in TOPUP_AMOUNT_PRESETS_USD\"\n          :key=\"amount\"\n          :autofocus=\"amount === 50\"\n          variant=\"secondary\"\n          size=\"lg\"\n          :aria-pressed=\"selectedPreset === amount\"\n          :class=\"\n            cn(\n              'h-10 w-full text-base font-medium focus-visible:ring-border-default',\n              selectedPreset === amount && 'bg-secondary-background-selected'\n            )\n          \"\n          @click=\"handlePresetClick(amount)\"\n        >\n          ${{ amount }}\n        </Button>\n      </div>\n    </div>\n    <!-- Amount (USD) / Credits -->\n    <div class=\"flex gap-2 px-8 pt-8\">\n      <!-- You Pay -->\n      <div\n        class=\"flex min-w-0 flex-1 flex-col gap-3\"\n        data-testid=\"top-up-pay-amount\"\n      >\n        <div class=\"text-sm text-muted-foreground\">\n          {{ $t('credits.topUp.youPay') }}\n        </div>\n        <NumberField\n          :model-value=\"payAmount\"\n          :min=\"0\"\n          :max=\"MAX_AMOUNT\"\n          :step=\"getStepAmount(payAmount)\"\n          :format-options=\"{ maximumFractionDigits: 0 }\"\n          @update:model-value=\"handlePayAmountChange\"\n        >\n          <NumberFieldDecrement />\n          <span class=\"shrink-0 text-base font-semibold text-base-foreground\"\n            >$</span\n          >\n          <NumberFieldInput\n            :aria-label=\"$t('credits.topUp.youPay')\"\n            class=\"text-lg font-medium\"\n          />\n          <NumberFieldIncrement />\n        </NumberField>\n      </div>\n\n      <!-- You Get -->\n      <div class=\"flex min-w-0 flex-1 flex-col gap-3\">\n        <div class=\"text-sm text-muted-foreground\">\n          {{ $t('credits.topUp.youGet') }}\n        </div>\n        <NumberField\n          v-model=\"creditsModel\"\n          :min=\"0\"\n          :max=\"usdToCredits(MAX_AMOUNT)\"\n          :step=\"getCreditsStepAmount(creditsModel)\"\n          :format-options=\"{ maximumFractionDigits: 0 }\"\n        >\n          <NumberFieldDecrement />\n          <i class=\"icon-[lucide--coins] size-4 shrink-0 text-gold-500\" />\n          <NumberFieldInput\n            :aria-label=\"$t('credits.topUp.youGet')\"\n            class=\"text-lg font-medium\"\n          />\n          <NumberFieldIncrement />\n        </NumberField>\n      </div>\n    </div>\n\n    <!-- Warnings -->\n\n    <p\n      v-if=\"isBelowMin\"\n      class=\"m-0 flex items-center justify-center gap-1 px-8 pt-4 text-center text-sm text-red-500\"\n    >\n      <i class=\"icon-[lucide--coins] size-4\" />\n      {{\n        $t('credits.topUp.minRequired', {\n          credits: formatNumber(usdToCredits(MIN_AMOUNT))\n        })\n      }}\n    </p>\n    <p\n      v-if=\"showCeilingWarning\"\n      class=\"m-0 flex items-center justify-center gap-1 px-8 pt-4 text-center text-sm text-gold-500\"\n    >\n      <i class=\"icon-[lucide--coins] size-4\" />\n      {{\n        $t('credits.topUp.maxAllowed', {\n          credits: formatNumber(usdToCredits(MAX_AMOUNT))\n        })\n      }}\n      <span>{{ $t('credits.topUp.needMore') }}</span>\n      <a\n        href=\"https://comfy.org/cloud/enterprise/\"\n        target=\"_blank\"\n        class=\"ml-1 text-inherit\"\n        >{{ $t('credits.topUp.contactUs') }}</a\n      >\n    </p>\n\n    <div class=\"flex flex-col gap-8 p-8\">\n      <Button\n        :disabled=\"!isValidAmount || loading\"\n        :loading=\"loading\"\n        variant=\"primary\"\n        size=\"lg\"\n        class=\"h-10 justify-center\"\n        @click=\"handleBuy\"\n      >\n        {{ $t('credits.topUp.buyCredits') }}\n      </Button>\n      <div class=\"flex items-center justify-center gap-1\">\n        <a\n          :href=\"pricingUrl\"\n          target=\"_blank\"\n          class=\"flex items-center gap-1 text-sm text-muted-foreground no-underline transition-colors hover:text-base-foreground\"\n        >\n          {{ $t('credits.topUp.viewPricing') }}\n          <i class=\"icon-[lucide--external-link] size-4\" />\n        </a>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport {\n  getTopupAmountPreset,\n  TOPUP_AMOUNT_PRESETS_USD\n} from '@comfyorg/account-core/billing'\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { creditsToUsd, usdToCredits } from '@/base/credits/comfyCredits'\nimport Button from '@/components/ui/button/Button.vue'\nimport NumberField from '@/components/ui/number-field/NumberField.vue'\nimport NumberFieldDecrement from '@/components/ui/number-field/NumberFieldDecrement.vue'\nimport NumberFieldIncrement from '@/components/ui/number-field/NumberFieldIncrement.vue'\nimport NumberFieldInput from '@/components/ui/number-field/NumberFieldInput.vue'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useAuthActions } from '@/composables/auth/useAuthActions'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { usePendingTopup } from '@/composables/billing/usePendingTopup'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport { describeBillingFailure } from '@/platform/telemetry/utils/billingFailureCategory'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { isInsufficientCredits = false, source } = defineProps<{\n  isInsufficientCredits?: boolean\n  source?: PaymentIntentSource\n}>()\n\nconst { t } = useI18n()\nconst authActions = useAuthActions()\nconst dialogStore = useDialogStore()\nconst settingsDialog = useSettingsDialog()\nconst telemetry = useTelemetry()\nconst toast = useToast()\nconst { buildDocsUrl, docsPaths } = useExternalLink()\n\n// Constants\nconst MIN_AMOUNT = 5\nconst MAX_AMOUNT = 10000\n\n// State\nconst selectedPreset = ref<number | null>(50)\nconst payAmount = ref(50)\nconst loading = ref(false)\n\n// Computed\nconst pricingUrl = computed(() =>\n  buildDocsUrl(docsPaths.partnerNodesPricing, { includeLocale: true })\n)\n\nconst creditsModel = computed({\n  get: () => usdToCredits(payAmount.value),\n  set: (newCredits: number) => {\n    payAmount.value = Math.round(creditsToUsd(newCredits))\n    selectedPreset.value = null\n  }\n})\n\nconst isValidAmount = computed(\n  () => payAmount.value >= MIN_AMOUNT && payAmount.value <= MAX_AMOUNT\n)\n\nconst isBelowMin = computed(() => payAmount.value < MIN_AMOUNT)\nconst showCeilingWarning = computed(() => payAmount.value >= MAX_AMOUNT)\n\n// Utility functions\nfunction formatNumber(num: number): string {\n  return num.toLocaleString('en-US')\n}\n\n// Step amount functions\nfunction getStepAmount(currentAmount: number): number {\n  if (currentAmount < 100) return 5\n  if (currentAmount < 1000) return 50\n  return 100\n}\n\nfunction getCreditsStepAmount(currentCredits: number): number {\n  const usdAmount = creditsToUsd(currentCredits)\n  return usdToCredits(getStepAmount(usdAmount))\n}\n\n// Event handlers\nfunction handlePayAmountChange(value: number) {\n  payAmount.value = value\n  selectedPreset.value = null\n}\n\nfunction handlePresetClick(amount: number) {\n  payAmount.value = amount\n  selectedPreset.value = amount\n}\n\nfunction handleClose(clearTracking = true) {\n  if (clearTracking) {\n    usePendingTopup().clearPendingTopup()\n  }\n  dialogStore.closeDialog({ key: 'top-up-credits' })\n}\n\nasync function handleBuy() {\n  // Prevent double-clicks\n  if (loading.value || !isValidAmount.value) return\n\n  loading.value = true\n  try {\n    telemetry?.trackApiCreditTopupButtonPurchaseClicked(payAmount.value)\n    if (authActions.canPurchaseCredits()) {\n      telemetry?.trackBillingEvent({\n        operation: 'topup',\n        stage: 'started',\n        outcome: 'pending',\n        payment_intent_source: source,\n        amount_cents: payAmount.value * 100,\n        amount_preset: getTopupAmountPreset(selectedPreset.value)\n      })\n    }\n    await authActions.purchaseCreditsDirect(payAmount.value)\n\n    // Close top-up dialog (keep tracking) and open Plan & Credits to show the\n    // updated balance. The destination is the V1 panel for every session: the\n    // legacy `credits` panel is hidden from the settings menu, and keying this\n    // off the billing rail sent rail-less sessions (API key, pre-workspace\n    // bootstrap) to that hidden screen.\n    handleClose(false)\n\n    settingsDialog.show('workspace')\n  } catch (error) {\n    console.error('Purchase failed:', error)\n\n    const errorMessage =\n      error instanceof Error ? error.message : t('credits.topUp.unknownError')\n    telemetry?.trackBillingEvent({\n      operation: 'topup',\n      stage: 'failed',\n      outcome: 'failure',\n      payment_intent_source: source,\n      ...describeBillingFailure(error)\n    })\n    toast.error(t('credits.topUp.purchaseError'), {\n      description: t('credits.topUp.purchaseErrorDetail', {\n        error: errorMessage\n      })\n    })\n  } finally {\n    loading.value = false\n  }\n}\n</script>\n","<template>\n  <div\n    class=\"flex w-90 max-w-full flex-col overflow-hidden rounded-2xl border border-border-default bg-base-background\"\n    data-testid=\"insufficient-credits-member-message\"\n  >\n    <div\n      class=\"flex h-12 items-center gap-2 border-b border-border-default p-4\"\n    >\n      <p class=\"m-0 min-w-0 flex-1 font-inter text-sm text-base-foreground\">\n        {{ $t('credits.insufficient.memberTitle') }}\n      </p>\n      <button\n        type=\"button\"\n        :aria-label=\"$t('g.close')\"\n        class=\"flex size-4 shrink-0 cursor-pointer items-center justify-center border-none bg-transparent text-base-foreground\"\n        @click=\"onClose\"\n      >\n        <i class=\"icon-[lucide--x] size-3\" />\n      </button>\n    </div>\n\n    <div class=\"p-4\">\n      <p class=\"m-0 font-inter text-sm text-muted-foreground\">\n        {{ $t('credits.insufficient.memberDescription') }}\n      </p>\n    </div>\n\n    <div class=\"flex items-center justify-end p-4\">\n      <Button variant=\"secondary\" size=\"lg\" @click=\"onClose\">\n        {{ $t('credits.insufficient.memberCta') }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\n\nconst { onClose } = defineProps<{\n  onClose: () => void\n}>()\n</script>\n","/**\n * Layer C of the billing rollout: which origin a hosted billing action opens.\n *\n * The server decides, through `hosted_billing_destination`. `stripe` means the\n * URL the backend already handed back — `action_url`, `payment_method_url`, a\n * portal link — is opened unchanged, so the host never composes a provider\n * URL of its own. `billing_web` means the host mints a `/v1/<intent>` entry\n * from `@comfyorg/billing-contract`, the one definition of that route surface.\n *\n * Every hosted surface reads the same flag, so they flip together and stay\n * independent of Layer A: whether an action reached here over the SDK rail or\n * the legacy client says nothing about where it should land.\n *\n * Anything unresolved fails closed to the provider — no configured billing-web\n * origin, an environment whose return target has no destination, an entry the\n * contract refuses to build. A customer on the provider page is served; one on\n * an origin nobody hosts, or with no way back, is stranded.\n */\nimport type {\n  BillingEntryInput,\n  BillingEnvironment,\n  BillingIntent,\n  ReturnTarget\n} from '@comfyorg/billing-contract'\nimport {\n  buildBillingEntryUrl,\n  resolveReturnTarget\n} from '@comfyorg/billing-contract'\nimport type { DeployEnv } from '@comfyorg/shared-frontend-utils/telemetry'\n\nimport type { HostedBillingDestination } from '@/config/billingWeb'\nimport { getBillingWebUrl } from '@/config/billingWeb'\nimport { getComfyCloudBaseUrl } from '@/config/comfyApi'\nimport { resolveDeployEnv } from '@/platform/telemetry/initDatadogRum'\n\nexport type HostedBillingRoute =\n  | { readonly kind: 'billing_web'; readonly url: URL }\n  | { readonly kind: 'provider' }\n\n/** The caller-supplied part of the entry, as opposed to the environment the host resolves for itself. */\nexport type HostedBillingRouteFields = Pick<\n  BillingEntryInput,\n  'plan' | 'workspaceId' | 'teamCreditStopId' | 'correlationId' | 'source'\n>\n\nconst PROVIDER: HostedBillingRoute = { kind: 'provider' }\n\nconst PRODUCT = 'comfyui'\nconst RETURN_TO: ReturnTarget = 'comfyui_workspace'\n\nconst BILLING_ENVIRONMENT_BY_DEPLOY_ENV: Readonly<\n  Record<DeployEnv, BillingEnvironment>\n> = {\n  'prod-v2': 'production',\n  'stg-v2': 'staging',\n  'test-v2': 'test'\n}\n\nfunction hostnameOf(url: string): string | undefined {\n  try {\n    return new URL(url).hostname\n  } catch {\n    return undefined\n  }\n}\n\n/**\n * The family the session was minted against, not the label on this build: a\n * developer running the frontend locally still talks to a deployed backend,\n * so the cloud base URL classifies the trip and `window.location` cannot. A\n * base URL that will not parse classifies nothing, so it fails closed like any\n * other unresolved environment rather than throwing through the caller.\n */\nexport function hostBillingEnvironment(\n  cloudBaseUrl = getComfyCloudBaseUrl()\n): BillingEnvironment | undefined {\n  const hostname = hostnameOf(cloudBaseUrl)\n  if (hostname === undefined) return undefined\n\n  const deployEnv = resolveDeployEnv(hostname)\n  return deployEnv === undefined\n    ? undefined\n    : BILLING_ENVIRONMENT_BY_DEPLOY_ENV[deployEnv]\n}\n\n/**\n * Re-bases a contract route under the configured billing-web path, which the\n * builder drops because an entry URL is only ever routing input. A prefixed\n * deployment (`https://host/billing/`) serves `/v1/<intent>` beneath its own\n * prefix, so the origin alone would point at nothing.\n */\nfunction underBase(base: URL, entry: URL): URL {\n  const prefix = base.pathname.replace(/\\/$/, '')\n  return new URL(`${prefix}${entry.pathname}${entry.search}`, base.origin)\n}\n\nexport function hostedBillingRoute(\n  destination: HostedBillingDestination,\n  intent: BillingIntent,\n  fields: HostedBillingRouteFields = {},\n  billingWebBase: URL | null = getBillingWebUrl(),\n  environment: BillingEnvironment | undefined = hostBillingEnvironment()\n): HostedBillingRoute {\n  if (destination !== 'billing_web' || !billingWebBase) return PROVIDER\n  if (!environment || !resolveReturnTarget(RETURN_TO, environment)) {\n    return PROVIDER\n  }\n\n  const entry = buildBillingEntryUrl({\n    ...fields,\n    billingOrigin: billingWebBase,\n    intent,\n    product: PRODUCT,\n    returnTo: RETURN_TO\n  })\n  return entry.status === 'ok'\n    ? { kind: 'billing_web', url: underBase(billingWebBase, entry.url) }\n    : PROVIDER\n}\n","import type { BillingEnvironment } from '@comfyorg/billing-contract'\n\nimport { getBillingWebUrl } from '@/config/billingWeb'\nimport { isCloud } from '@/platform/distribution/types'\nimport { hostBillingEnvironment } from '@/platform/workspace/billing/hostedBillingRoutes'\n\nconst TOPUP_RETURN_PATH = '/return/topup'\n\nconst BILLING_WEB_ORIGINS: Readonly<Record<BillingEnvironment, string>> = {\n  production: 'https://billing.comfy.org',\n  staging: 'https://stagingbilling.comfy.org',\n  test: 'https://testbilling.comfy.org'\n}\n\ninterface TopupCheckoutReturnContext {\n  readonly servesCloudWeb: boolean\n  readonly currentUrl: string\n  readonly billingWebBase: URL | null\n  readonly environment: BillingEnvironment | undefined\n}\n\nfunction currentContext(): TopupCheckoutReturnContext {\n  return {\n    servesCloudWeb: isCloud && window.__comfyDesktop2 === undefined,\n    currentUrl: window.location.href,\n    billingWebBase: getBillingWebUrl(),\n    environment: hostBillingEnvironment()\n  }\n}\n\n/**\n * Where hosted top-up checkout returns: the current page on cloud web, else\n * billing-web's neutral return page; undefined when no billing-web origin resolves.\n */\nexport function topupCheckoutReturnUrl(\n  context: TopupCheckoutReturnContext = currentContext()\n): string | undefined {\n  if (context.servesCloudWeb) return context.currentUrl\n\n  const base =\n    context.billingWebBase ??\n    (context.environment && new URL(BILLING_WEB_ORIGINS[context.environment]))\n  if (!base) return undefined\n\n  const prefix = base.pathname.replace(/\\/$/, '')\n  return new URL(`${prefix}${TOPUP_RETURN_PATH}`, base.origin).href\n}\n","import type {\n  BillingTelemetryEvent,\n  BillingTelemetryFailure,\n  SubscriptionCheckoutTier,\n  SubscriptionCheckoutType\n} from '@comfyorg/account-core/billing'\nimport type { PaymentIntent } from '@stripe/stripe-js'\nimport { loadStripe } from '@stripe/stripe-js/pure'\nimport { customerCanActHere } from '@comfyorg/account-core/billing'\nimport { useEventListener } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { t } from '@/i18n'\nimport type { TierKey } from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { BillingCycle } from '@/platform/cloud/subscription/utils/subscriptionTierRank'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport { workspaceApi } from '@/platform/workspace/api/workspaceApi'\nimport type {\n  BillingAuthenticationState,\n  BillingOperationPhase,\n  BillingDeclineReason,\n  BillingRecoveryAction\n} from '@/platform/workspace/api/workspaceApi'\nimport type {\n  ProgressToast,\n  ProgressToastKind\n} from '@/platform/workspace/billing/customerAttention'\nimport {\n  isBlockedOnCustomerPhase,\n  isParkedCheckout,\n  legacyOperationActionHold,\n  needsCustomerAttention,\n  progressToastKind\n} from '@/platform/workspace/billing/customerAttention'\nimport { resolveStripePublishableKey } from '@/platform/workspace/billing/stripePublishableKey'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport {\n  clearCheckoutJourney,\n  getActiveCheckoutJourney,\n  getCheckoutJourneyPaymentIntentSource\n} from '@/platform/workspace/utils/checkoutJourney'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst INITIAL_INTERVAL_MS = 1000\nconst MAX_INTERVAL_MS = 8000\nconst ACTION_REQUIRED_INTERVAL_MS = 30_000\n// Twenty turns of the backend's 3 s PaymentIntent status cache.\nconst ACTION_DISCOVERY_WINDOW_MS = 60_000\nconst BACKOFF_MULTIPLIER = 1.5\nconst TIMEOUT_MS = 120_000\nconst SUBSCRIPTION_ACTION_DISCOVERY_TIMEOUT_MS = 5 * 60_000\nconst AUTHENTICATION_TIMEOUT_MS = 23 * 60 * 60_000\n// Failure reason for a checkout the user replaced by picking a different plan\n// mid-flow. The operation is terminal-failed only because it never completed —\n// its replacement is proceeding normally, so there is nothing to report.\nconst CHECKOUT_SUPERSEDED_REASON = 'checkout_superseded'\n// Statuses that mean the resumed challenge left the intent exactly where it\n// started, so the attempt needs a fresh start rather than a poll. A denylist\n// fails toward the server rather than toward the customer: an unlisted or\n// future Stripe status reports optimistically as processing, which the next\n// poll's own authentication_state corrects if that guess was wrong — unlike\n// an allowlist, where the same gap would report a live payment as failed.\nconst UNMOVED_INTENT_STATUSES: ReadonlySet<PaymentIntent.Status> = new Set([\n  'requires_payment_method',\n  'requires_action',\n  'canceled'\n])\n\n// The poller adopts only operations the legacy rail issued; the SDK rail settles its own.\nfunction trackLegacyBillingEvent(event: BillingTelemetryEvent) {\n  useTelemetry()?.trackBillingEvent({ ...event, billing_client: 'legacy' })\n}\n\ntype OperationType = 'subscription' | 'topup' | 'cancel' | 'retention'\ntype PaymentOperationType = Extract<OperationType, 'subscription' | 'topup'>\n\nfunction isPaymentOperation(type: OperationType): type is PaymentOperationType {\n  return type === 'subscription' || type === 'topup'\n}\n\ntype OperationStatus =\n  | 'pending'\n  | 'succeeded'\n  | 'failed'\n  | 'timeout'\n  | 'reconciliation_needed'\n\nexport interface StartOperationMetadata {\n  workspaceId?: string\n  tier?: SubscriptionCheckoutTier\n  cycle?: BillingCycle\n  checkoutType?: SubscriptionCheckoutType\n  paymentIntentSource?: PaymentIntentSource\n  suppressProcessingToast?: boolean\n  /**\n   * Adopted from a status read rather than started by the customer here. The\n   * read names the operation but not what it waits on, so without a served\n   * link it is announced by its first status, never before it.\n   */\n  resumed?: boolean\n  autoHandleRequiresAction?: boolean\n  downgradeToPersonal?: {\n    memberRemovalCount: number\n    memberRemovalFailures: number\n    targetTier?: TierKey\n    startedAt: number\n  }\n  /**\n   * The timestamp the caller used for its own canonical `started` telemetry\n   * event (i.e. before the initiating subscribe/top-up/cancel API call), so\n   * `duration_ms` on the poller's terminal events spans the full emitted\n   * lifecycle instead of just the poll-observation window. Defaults to\n   * `Date.now()` (poll-start time) when the caller has no such timestamp,\n   * e.g. recovering a pending operation on page load.\n   */\n  attemptStartedAt?: number\n}\n\ninterface BillingOperation {\n  opId: string\n  type: OperationType\n  status: OperationStatus\n  errorMessage: string | null\n  startedAt: number\n  operationStartedAt: number\n  businessAttemptStartedAt?: number\n  actionUrl: string | null\n  authenticationState: BillingAuthenticationState | null\n  isAuthenticating: boolean\n  canRetryAuthentication: boolean\n  authenticationRequiredSeen: boolean\n  // Latches once the server has reported a phase blocked on the customer. The\n  // phase itself moves on — an invoice being finalised reports in_progress —\n  // and elapsed time is counted from the start, so re-reading it would measure\n  // the whole parked wait against the short budget the moment it advances.\n  blockedOnCustomerSeen: boolean\n  workspaceId: string | null\n  tier?: SubscriptionCheckoutTier\n  cycle?: BillingCycle\n  checkoutType?: SubscriptionCheckoutType\n  paymentIntentSource?: PaymentIntentSource\n  autoHandleRequiresAction: boolean\n  // Last phase the server reported for a pending operation. The phases\n  // isBlockedOnCustomerPhase names will not advance until the customer acts, so\n  // a dialog should offer them a way back rather than keep waiting. Null while\n  // unknown — the field is optional in the contract, and absent is explicitly\n  // no claim, never an implied in_progress.\n  phase: BillingOperationPhase | null\n  downgradeToPersonal?: StartOperationMetadata['downgradeToPersonal']\n  // Set when the customer walked away from this operation in the UI (e.g.\n  // \"Start over\" after a failed challenge). The operation itself is not\n  // over — only the server decides that — so it keeps polling and can still\n  // resolve normally; this only hides it from the selectors a dialog reads.\n  dismissed: boolean\n}\n\ntype TerminalResolver = (operation: BillingOperation) => void\n\ninterface FailureRecovery {\n  readonly action?: BillingRecoveryAction\n  // The contract's authority on whether starting another operation can succeed.\n  readonly retryable?: boolean\n}\n\nexport const useBillingOperationStore = defineStore('billingOperation', () => {\n  const workspaceStore = useTeamWorkspaceStore()\n  const { flags } = useFeatureFlags()\n  const toast = useToast()\n  const operations = ref<Map<string, BillingOperation>>(new Map())\n  const timeouts = new Map<string, ReturnType<typeof setTimeout>>()\n  const intervals = new Map<string, number>()\n  const waitingWithoutActionSince = new Map<string, number>()\n  const progressToasts = new Map<string, ProgressToast>()\n  const progressToastsAwaitingFirstRead = new Set<string>()\n  const terminalResolvers = new Map<string, TerminalResolver>()\n  const terminalPromises = new Map<string, Promise<BillingOperation>>()\n  const autoHandledPaymentActions = new Set<string>()\n  const paymentIntentClientSecrets = new Map<string, string>()\n  const inFlightPolls = new Map<string, Promise<void>>()\n\n  useEventListener(document, 'visibilitychange', () => {\n    if (document.visibilityState === 'visible') pollPendingOperations()\n  })\n\n  const hasPendingOperations = computed(() =>\n    [...operations.value.values()].some((op) => op.status === 'pending')\n  )\n\n  const isSettingUp = computed(() =>\n    [...operations.value.values()].some(\n      (op) =>\n        op.status === 'pending' &&\n        op.authenticationState !== 'requires_action' &&\n        op.authenticationState !== 'failed_retryable' &&\n        !isParkedCheckout(op) &&\n        op.type === 'subscription' &&\n        op.workspaceId === workspaceStore.activeWorkspaceId\n    )\n  )\n\n  const isAddingCredits = computed(() =>\n    [...operations.value.values()].some(\n      (op) =>\n        op.status === 'pending' &&\n        op.authenticationState !== 'failed_retryable' &&\n        !op.dismissed &&\n        op.type === 'topup' &&\n        op.workspaceId === workspaceStore.activeWorkspaceId\n    )\n  )\n\n  const subscriptionActionOperation = computed(() =>\n    [...operations.value.values()].find(\n      (op) =>\n        op.type === 'subscription' &&\n        op.workspaceId === workspaceStore.activeWorkspaceId &&\n        needsCustomerAttention(op)\n    )\n  )\n\n  const topupActionOperation = computed(() =>\n    [...operations.value.values()].find(\n      (op) =>\n        op.type === 'topup' &&\n        op.workspaceId === workspaceStore.activeWorkspaceId &&\n        !op.dismissed &&\n        needsCustomerAttention(op)\n    )\n  )\n\n  function getOperation(opId: string) {\n    return operations.value.get(opId)\n  }\n\n  // An operation parked on a bank challenge is waiting on the customer, not on\n  // us, so it must not keep announcing \"processing\" — that reads as \"nothing to\n  // do here\" next to the verification prompt the same state renders.\n  function syncProgressToast(\n    opId: string,\n    type: PaymentOperationType,\n    kind: ProgressToastKind | undefined\n  ) {\n    const previous = progressToasts.get(opId)\n    if (previous?.kind === kind) return\n    if (previous) {\n      toast.dismiss(previous.id)\n      progressToasts.delete(opId)\n    }\n    if (kind === undefined) return\n\n    const messageKey =\n      type === 'subscription'\n        ? kind === 'action'\n          ? 'billingOperation.subscriptionActionRequired'\n          : 'billingOperation.subscriptionProcessing'\n        : kind === 'action'\n          ? 'billingOperation.topupActionRequired'\n          : 'billingOperation.topupProcessing'\n\n    const id =\n      kind === 'action'\n        ? toast.warning(t(messageKey))\n        : toast.loading(t(messageKey))\n    progressToasts.set(opId, { kind, id })\n  }\n\n  function announceStart(\n    operation: BillingOperation,\n    metadata: StartOperationMetadata | undefined\n  ) {\n    if (\n      !isPaymentOperation(operation.type) ||\n      metadata?.suppressProcessingToast\n    )\n      return\n    if (metadata?.resumed && operation.actionUrl === null) {\n      progressToastsAwaitingFirstRead.add(operation.opId)\n      return\n    }\n    syncProgressToast(\n      operation.opId,\n      operation.type,\n      progressToastKind(operation)\n    )\n  }\n\n  // The action URL is the last field a read applies, so an operation awaiting\n  // its first read is announced here by what that read found.\n  function syncProgressToastAfterRead(\n    before: BillingOperation,\n    after: BillingOperation\n  ) {\n    if (\n      isPaymentOperation(after.type) &&\n      progressToastsAwaitingFirstRead.delete(after.opId)\n    ) {\n      syncProgressToast(after.opId, after.type, progressToastKind(after))\n      return\n    }\n    syncProgressToastOnChange(before, after)\n  }\n\n  function syncProgressToastOnChange(\n    before: BillingOperation,\n    after: BillingOperation\n  ) {\n    if (!isPaymentOperation(after.type)) return\n    const kind = progressToastKind(after)\n    if (kind !== progressToastKind(before)) {\n      syncProgressToast(after.opId, after.type, kind)\n    }\n  }\n\n  function startOperation(\n    opId: string,\n    type: OperationType,\n    metadata?: StartOperationMetadata,\n    initialActionUrl?: string\n  ): Promise<BillingOperation> {\n    const existing = operations.value.get(opId)\n    if (existing && existing.status !== 'timeout') {\n      return terminalPromises.get(opId) ?? Promise.resolve(existing)\n    }\n    if (existing) clearOperation(opId)\n\n    const actionUrl = validateActionUrl(initialActionUrl)\n    const now = Date.now()\n    const operation: BillingOperation = {\n      opId,\n      type,\n      status: 'pending',\n      errorMessage: null,\n      startedAt: now,\n      operationStartedAt: metadata?.attemptStartedAt ?? now,\n      businessAttemptStartedAt: metadata?.attemptStartedAt,\n      actionUrl,\n      authenticationState: null,\n      isAuthenticating: false,\n      canRetryAuthentication: false,\n      authenticationRequiredSeen: actionUrl !== null,\n      blockedOnCustomerSeen: false,\n      workspaceId: metadata?.workspaceId ?? workspaceStore.activeWorkspaceId,\n      tier: metadata?.tier,\n      cycle: metadata?.cycle,\n      checkoutType: metadata?.checkoutType,\n      paymentIntentSource:\n        metadata?.paymentIntentSource ??\n        getCheckoutJourneyPaymentIntentSource(opId),\n      autoHandleRequiresAction: metadata?.autoHandleRequiresAction ?? false,\n      phase: null,\n      downgradeToPersonal: metadata?.downgradeToPersonal,\n      dismissed: false\n    }\n\n    operations.value = new Map(operations.value).set(opId, operation)\n    intervals.set(opId, INITIAL_INTERVAL_MS)\n\n    if (metadata?.attemptStartedAt === undefined) {\n      trackLegacyBillingEvent({\n        operation: 'operation',\n        stage: 'started',\n        outcome: 'pending',\n        operation_type: type\n      })\n    }\n\n    announceStart(operation, metadata)\n\n    const terminal = new Promise<BillingOperation>((resolve) => {\n      terminalResolvers.set(opId, resolve)\n    })\n    terminalPromises.set(opId, terminal)\n\n    void poll(opId)\n\n    return terminal\n  }\n\n  async function poll(opId: string) {\n    const inFlight = inFlightPolls.get(opId)\n    if (inFlight) {\n      await inFlight\n      return\n    }\n\n    const request = pollOnce(opId).finally(() => {\n      inFlightPolls.delete(opId)\n    })\n    inFlightPolls.set(opId, request)\n    await request\n  }\n\n  async function pollOnce(opId: string) {\n    const operation = operations.value.get(opId)\n    if (!operation || operation.status !== 'pending') return\n    pausePolling(opId)\n    if (operation.isAuthenticating) return\n\n    if (stopIfTimedOut(opId, operation)) return\n\n    if (operation.workspaceId !== workspaceStore.activeWorkspaceId) {\n      scheduleNextPoll(opId)\n      return\n    }\n\n    try {\n      const response = await workspaceApi.getBillingOpStatus(opId)\n      const currentOperation = operations.value.get(opId)\n      if (currentOperation !== operation) return\n      if (operation.workspaceId !== workspaceStore.activeWorkspaceId) {\n        if (stopIfTimedOut(opId, operation)) return\n        scheduleNextPoll(opId)\n        return\n      }\n\n      if (response.status === 'succeeded') {\n        await handleSuccess(opId)\n        return\n      }\n\n      if (response.status === 'failed') {\n        handleFailure(opId, response.error_message ?? null, {\n          action: response.recovery_action,\n          retryable: response.retryable\n        })\n        return\n      }\n\n      if (\n        response.status === 'reconciliation_needed' ||\n        (flags.embeddedCheckoutEnabled &&\n          response.authentication_state === 'reconciliation_needed')\n      ) {\n        handleReconciliationNeeded(opId)\n        return\n      }\n\n      // The phase can widen the budget, so it is applied before the decision,\n      // which then reads the updated operation. The action URL stays after it:\n      // a link landing on an operation already out of budget is not retained.\n      updateOperationPhase(opId, response.phase ?? null)\n      if (stopIfTimedOut(opId, operations.value.get(opId) ?? operation)) return\n\n      const pollingPaused = flags.embeddedCheckoutEnabled\n        ? await updateAuthenticationState(\n            opId,\n            response.authentication_state,\n            response.payment_intent_client_secret,\n            response.decline_reason\n          )\n        : false\n      updateOperationActionUrl(opId, validateActionUrl(response.action_url))\n      if (pollingPaused) return\n      scheduleNextPoll(opId)\n    } catch {\n      const currentOperation = operations.value.get(opId)\n      if (currentOperation !== operation) return\n      if (stopIfTimedOut(opId, currentOperation)) return\n      scheduleNextPoll(opId)\n    }\n  }\n\n  function pollPendingOperations() {\n    for (const operation of operations.value.values()) {\n      if (\n        operation.workspaceId === workspaceStore.activeWorkspaceId &&\n        operation.status === 'pending' &&\n        !operation.isAuthenticating\n      ) {\n        pausePolling(operation.opId)\n        void poll(operation.opId)\n      }\n    }\n  }\n\n  // The slow cadence is for an operation parked on the customer: a challenge\n  // to complete elsewhere, or a failed attempt awaiting their retry. Once this\n  // tab's own challenge completes, the state reads processing and nothing\n  // waits on the customer anymore — holding the slow cadence there left a\n  // settled payment spinning for half a minute.\n  function isWaitingOnCustomer(operation: BillingOperation): boolean {\n    return (\n      isBlockedOnCustomerPhase(operation.phase) ||\n      operation.authenticationState === 'requires_action' ||\n      operation.actionUrl !== null ||\n      (operation.authenticationState === 'failed_retryable' &&\n        operation.authenticationRequiredSeen)\n    )\n  }\n\n  // Parked straight away only while the customer can act here. The server can\n  // report a blocked phase and a client secret before its cached\n  // authentication_state catches up, so an actionless wait keeps the backoff\n  // for the discovery window. Past it the action is not coming to this tab (a\n  // member without billing permission, embedded checkout off) and it parks.\n  function isParkedAwaitingCustomer(\n    operation: BillingOperation,\n    waitedWithoutActionMs: number\n  ): boolean {\n    if (!isWaitingOnCustomer(operation)) return false\n    return (\n      customerCanAct(operation) ||\n      waitedWithoutActionMs >= ACTION_DISCOVERY_WINDOW_MS\n    )\n  }\n\n  function trackWaitWithoutAction(operation: BillingOperation): number {\n    if (!isWaitingOnCustomer(operation) || customerCanAct(operation)) {\n      waitingWithoutActionSince.delete(operation.opId)\n      return 0\n    }\n    const now = Date.now()\n    const since = waitingWithoutActionSince.get(operation.opId) ?? now\n    waitingWithoutActionSince.set(operation.opId, since)\n    return now - since\n  }\n\n  function customerCanAct(operation: BillingOperation): boolean {\n    return customerCanActHere(\n      legacyOperationActionHold(\n        operation,\n        paymentIntentClientSecrets.has(operation.opId)\n      )\n    )\n  }\n\n  function scheduleNextPoll(opId: string) {\n    const operation = operations.value.get(opId)\n    if (!operation || operation.status !== 'pending') return\n    // One chain per operation: an explicit retry polls immediately while a\n    // scheduled poll may still be armed, and two chains would double the\n    // request rate and race each other's state writes.\n    pausePolling(opId)\n    const nextInterval = isParkedAwaitingCustomer(\n      operation,\n      trackWaitWithoutAction(operation)\n    )\n      ? ACTION_REQUIRED_INTERVAL_MS\n      : Math.min(\n          (intervals.get(opId) ?? INITIAL_INTERVAL_MS) * BACKOFF_MULTIPLIER,\n          MAX_INTERVAL_MS\n        )\n    intervals.set(opId, nextInterval)\n\n    const timeoutId = setTimeout(() => void poll(opId), nextInterval)\n    timeouts.set(opId, timeoutId)\n  }\n\n  function validateActionUrl(value: string | undefined): string | null {\n    if (!value) return null\n    try {\n      const url = new URL(value)\n      return url.protocol === 'https:' ? value : null\n    } catch {\n      return null\n    }\n  }\n\n  function hasTimedOut(operation: BillingOperation): boolean {\n    const elapsed = Date.now() - operation.startedAt\n    if (\n      isPaymentOperation(operation.type) &&\n      (operation.authenticationRequiredSeen || operation.blockedOnCustomerSeen)\n    ) {\n      return elapsed > AUTHENTICATION_TIMEOUT_MS\n    }\n    return operation.type === 'subscription'\n      ? elapsed > SUBSCRIPTION_ACTION_DISCOVERY_TIMEOUT_MS\n      : elapsed > TIMEOUT_MS\n  }\n\n  async function updateAuthenticationState(\n    opId: string,\n    state?: BillingAuthenticationState,\n    clientSecret?: string,\n    declineReason?: BillingDeclineReason\n  ): Promise<boolean> {\n    if (!state) return false\n    const operation = operations.value.get(opId)\n    if (!operation || operation.status !== 'pending') return true\n\n    const knownSecret = paymentIntentClientSecrets.get(opId)\n    if (clientSecret) paymentIntentClientSecrets.set(opId, clientSecret)\n    const secret = clientSecret ?? knownSecret\n    // requires_action after a failed browser attempt is the same challenge the\n    // customer just abandoned — the intent has not moved. Keeping the failure\n    // presentation stops the alert flapping between polls; a state that\n    // actually advanced (processing, succeeded, failed) still flows through and\n    // resolves the UI. A different client secret is a genuinely new challenge\n    // and still flows through — same rule the echo check below applies.\n    //\n    // Likewise after a browser attempt that SUCCEEDED: the server can keep\n    // reporting requires_action for the same intent until it observes the\n    // completion, and downgrading processing back to requires_action reopened\n    // the pay button mid-payment.\n    const isStaleFailure =\n      state === 'requires_action' &&\n      operation.authenticationState === 'failed_retryable' &&\n      (!clientSecret || clientSecret === knownSecret)\n    const isEchoOfHandledChallenge =\n      state === 'requires_action' &&\n      operation.authenticationState === 'processing' &&\n      autoHandledPaymentActions.has(opId) &&\n      (!clientSecret || clientSecret === knownSecret)\n    const displayState =\n      isStaleFailure || isEchoOfHandledChallenge\n        ? operation.authenticationState\n        : state\n    const declineDetail =\n      state === 'failed_retryable' && declineReason\n        ? billingFailureDetail(operation.type, declineReason)\n        : null\n    updateOperation(opId, {\n      authenticationState: displayState,\n      canRetryAuthentication:\n        Boolean(secret) && displayState === 'requires_action',\n      authenticationRequiredSeen:\n        operation.authenticationRequiredSeen || state === 'requires_action',\n      ...(declineDetail && { errorMessage: declineDetail })\n    })\n\n    // Neither authentication state is terminal for a pending operation: the\n    // customer may complete the challenge on a hosted page or another device,\n    // and the server learns before this tab does. Polling therefore continues\n    // at the slower authentication cadence until the operation settles or times\n    // out — pausing here left a completed payment showing \"complete\n    // verification\" forever.\n    if (state === 'failed_retryable') return false\n    if (\n      state !== 'requires_action' ||\n      !operation.autoHandleRequiresAction ||\n      autoHandledPaymentActions.has(opId)\n    ) {\n      return false\n    }\n    // Only the in-page challenge we drive ourselves suspends polling, for as\n    // long as it is on screen.\n    autoHandledPaymentActions.add(opId)\n    return !(await runPaymentIntentAction(opId))\n  }\n\n  async function retryPaymentAuthentication(opId: string): Promise<boolean> {\n    if (!flags.embeddedCheckoutEnabled) return false\n    const operation = operations.value.get(opId)\n    if (\n      !operation ||\n      operation.status !== 'pending' ||\n      !paymentIntentClientSecrets.has(opId) ||\n      operation.authenticationState !== 'requires_action'\n    ) {\n      return false\n    }\n    const completed = await runPaymentIntentAction(opId)\n    if (completed) void poll(opId)\n    return completed\n  }\n\n  async function runPaymentIntentAction(opId: string): Promise<boolean> {\n    const operation = operations.value.get(opId)\n    const clientSecret = paymentIntentClientSecrets.get(opId)\n    if (!operation || !clientSecret || operation.isAuthenticating) return false\n    updateOperation(opId, {\n      isAuthenticating: true,\n      canRetryAuthentication: false,\n      errorMessage: null\n    })\n\n    try {\n      const publishableKey = resolveStripePublishableKey()\n      const stripe = publishableKey ? await loadStripe(publishableKey) : null\n      if (!stripe) {\n        setAuthenticationFailed(\n          opId,\n          t('billingOperation.authenticationUnavailable')\n        )\n        return false\n      }\n      const { error, paymentIntent } = await stripe.handleNextAction({\n        clientSecret\n      })\n      if (error) {\n        setAuthenticationFailed(\n          opId,\n          error.message || t('billingOperation.authenticationFailedDetail')\n        )\n        return false\n      }\n      // With no action left to resume the call succeeds and changes nothing, so\n      // an intent still sitting on its pre-challenge status has not paid.\n      if (paymentIntent && UNMOVED_INTENT_STATUSES.has(paymentIntent.status)) {\n        setAuthenticationFailed(\n          opId,\n          t('billingOperation.authenticationFailedDetail')\n        )\n        return false\n      }\n      updateOperation(opId, {\n        authenticationState: 'processing',\n        isAuthenticating: false,\n        canRetryAuthentication: false,\n        errorMessage: null,\n        actionUrl: null\n      })\n      autoHandledPaymentActions.add(opId)\n      intervals.set(opId, INITIAL_INTERVAL_MS)\n      waitingWithoutActionSince.delete(opId)\n      return true\n    } catch (error) {\n      setAuthenticationFailed(\n        opId,\n        error instanceof Error\n          ? error.message\n          : t('billingOperation.authenticationFailedDetail')\n      )\n      return false\n    }\n  }\n\n  function setAuthenticationFailed(opId: string, errorMessage: string) {\n    const operation = operations.value.get(opId)\n    if (!operation) return\n    updateOperation(opId, {\n      authenticationState: 'failed_retryable',\n      isAuthenticating: false,\n      canRetryAuthentication: false,\n      errorMessage\n    })\n    // A browser-step error is not a verdict on the payment: the challenge may\n    // have completed server-side despite the client error (observed: the\n    // intent succeeded seconds after handleNextAction reported failure, and a\n    // paused UI stayed on \"failed\" for a live subscription). Keep polling so\n    // the server's state resolves the presentation.\n    scheduleNextPoll(opId)\n  }\n\n  function updateOperation(opId: string, patch: Partial<BillingOperation>) {\n    const operation = operations.value.get(opId)\n    if (!operation) return\n    operations.value = new Map(operations.value).set(opId, {\n      ...operation,\n      ...patch\n    })\n  }\n\n  function pausePolling(opId: string) {\n    const timeoutId = timeouts.get(opId)\n    if (timeoutId) clearTimeout(timeoutId)\n    timeouts.delete(opId)\n  }\n\n  function stopIfTimedOut(opId: string, operation: BillingOperation): boolean {\n    if (!hasTimedOut(operation)) return false\n    handleTimeout(opId)\n    return true\n  }\n\n  function updateOperationPhase(\n    opId: string,\n    phase: BillingOperationPhase | null\n  ) {\n    const operation = operations.value.get(opId)\n    if (\n      !operation ||\n      operation.status !== 'pending' ||\n      operation.phase === phase\n    ) {\n      return\n    }\n    const updated: BillingOperation = {\n      ...operation,\n      phase,\n      blockedOnCustomerSeen:\n        operation.blockedOnCustomerSeen || isBlockedOnCustomerPhase(phase)\n    }\n    operations.value = new Map(operations.value).set(opId, updated)\n    syncProgressToastOnChange(operation, updated)\n  }\n\n  function updateOperationActionUrl(opId: string, actionUrl: string | null) {\n    const operation = operations.value.get(opId)\n    if (!operation || operation.status !== 'pending') return\n    // An action link echoed while this tab's completed challenge is still\n    // processing points at that same challenge; surfacing it would ask the\n    // customer to redo a step they just finished.\n    if (\n      actionUrl !== null &&\n      autoHandledPaymentActions.has(opId) &&\n      operation.authenticationState !== 'requires_action'\n    ) {\n      return\n    }\n    const updated: BillingOperation = {\n      ...operation,\n      actionUrl,\n      authenticationRequiredSeen:\n        operation.authenticationRequiredSeen || actionUrl !== null\n    }\n    operations.value = new Map(operations.value).set(opId, updated)\n    // Tracks the CURRENT action_url, which the contract defines as present\n    // exactly while the operation cannot proceed without the customer — so the\n    // toast never outlives the verification action it points at. Swapped only\n    // when that answer changes, or a dismissed toast would return every poll.\n    syncProgressToastAfterRead(operation, updated)\n  }\n\n  async function handleSuccess(opId: string) {\n    const operation = operations.value.get(opId)\n    if (!operation) return\n\n    updateOperationStatus(opId, 'succeeded', null)\n\n    if (getActiveCheckoutJourney()?.billing_op_id === opId) {\n      clearCheckoutJourney()\n    }\n\n    try {\n      cleanup(opId)\n\n      const telemetry = useTelemetry()\n      const now = Date.now()\n      const operationDurationMs = now - operation.operationStartedAt\n      trackLegacyBillingEvent({\n        operation: 'operation',\n        stage: 'succeeded',\n        outcome: 'success',\n        billing_op_id: opId,\n        operation_type: operation.type,\n        tier: operation.tier,\n        cycle: operation.cycle,\n        checkout_type: operation.checkoutType,\n        payment_intent_source: operation.paymentIntentSource,\n        duration_ms: operationDurationMs\n      })\n\n      if (\n        operation.type === 'subscription' &&\n        operation.businessAttemptStartedAt !== undefined\n      ) {\n        const durationMs = now - operation.businessAttemptStartedAt\n        trackLegacyBillingEvent({\n          operation: 'subscription_checkout',\n          stage: 'succeeded',\n          outcome: 'success',\n          tier: operation.tier,\n          cycle: operation.cycle,\n          checkout_type: operation.checkoutType,\n          payment_intent_source: operation.paymentIntentSource,\n          billing_op_id: opId,\n          duration_ms: durationMs\n        })\n        // Also fires the legacy event for providers (Mixpanel, GTM) that don't\n        // implement trackBillingEvent. Gated to actual new/upgraded\n        // subscriptions — a downgrade-to-personal is churn, not a conversion,\n        // and this event drives a GA4 \"subscription succeeded\" conversion goal.\n        if (!operation.downgradeToPersonal) {\n          telemetry?.trackMonthlySubscriptionSucceeded({\n            tier: operation.tier,\n            cycle: operation.cycle,\n            checkout_type: operation.checkoutType,\n            payment_intent_source: operation.paymentIntentSource,\n            billing_op_id: opId\n          })\n        }\n      } else if (\n        operation.type === 'topup' &&\n        operation.businessAttemptStartedAt !== undefined\n      ) {\n        trackLegacyBillingEvent({\n          operation: 'topup',\n          stage: 'succeeded',\n          outcome: 'success',\n          billing_op_id: opId,\n          payment_intent_source: operation.paymentIntentSource,\n          duration_ms: now - operation.businessAttemptStartedAt\n        })\n      }\n      // Mirrors handleFailure's structure: not gated on businessAttemptStartedAt,\n      // since a downgrade always has its own startedAt for duration_ms below.\n      if (operation.downgradeToPersonal) {\n        trackLegacyBillingEvent({\n          operation: 'downgrade_to_personal',\n          stage: 'succeeded',\n          outcome: 'success',\n          member_removal_count:\n            operation.downgradeToPersonal.memberRemovalCount,\n          member_removal_failures:\n            operation.downgradeToPersonal.memberRemovalFailures,\n          target_tier: operation.downgradeToPersonal.targetTier,\n          duration_ms: now - operation.downgradeToPersonal.startedAt\n        })\n      }\n\n      if (operation.type === 'retention') return\n\n      const billingContext = useBillingContext()\n      const capabilities = useBillingCapabilities()\n      if (operation.type === 'subscription') {\n        await Promise.allSettled([\n          billingContext.reconcileSubscriptionSuccess(),\n          capabilities.refresh()\n        ])\n      } else {\n        await Promise.allSettled([\n          billingContext.fetchStatus(),\n          billingContext.fetchBalance(),\n          capabilities.refresh()\n        ])\n      }\n\n      if (operation.type === 'cancel') {\n        useTeamWorkspaceStore().updateActiveWorkspace({ isSubscribed: false })\n        return\n      }\n\n      // A subscription checkout shows its own success step in the pricing dialog,\n      // so leave it open. Top-ups have no such step: close and surface settings.\n      if (operation.type === 'topup') {\n        useDialogStore().closeDialog({ key: 'top-up-credits' })\n        useSettingsDialog().show(isCloud ? 'workspace' : 'credits')\n      }\n\n      const messageKey =\n        operation.type === 'subscription'\n          ? 'billingOperation.subscriptionSuccess'\n          : 'billingOperation.topupSuccess'\n\n      toast.success(t(messageKey), { duration: 5000 })\n    } catch (error) {\n      reportError(error, {\n        surface: 'billing',\n        errorType: 'failure_handling_billing_operation_success',\n        context: { billing_op_id: opId }\n      })\n      throw error\n    } finally {\n      resolveTerminal(opId)\n    }\n  }\n\n  function handleFailure(\n    opId: string,\n    errorMessage: string | null,\n    recovery?: FailureRecovery\n  ) {\n    const operation = operations.value.get(opId)\n    if (!operation) return\n\n    const superseded = errorMessage === CHECKOUT_SUPERSEDED_REASON\n    const defaultMessage = failureMessage(operation.type)\n    // A recovery action describes a card the customer must re-present. An\n    // operation that never charges one — a cancellation, a downgrade — cannot\n    // be recovered that way whatever the server reports.\n    const chargesACard =\n      isPaymentOperation(operation.type) && !operation.downgradeToPersonal\n    const detail = billingFailureDetail(\n      operation.type,\n      errorMessage,\n      chargesACard ? recovery : undefined\n    )\n\n    updateOperationStatus(opId, 'failed', detail ?? defaultMessage)\n    cleanup(opId)\n\n    const now = Date.now()\n    const failureCategory = superseded\n      ? 'stale_operation'\n      : categorizePollFailure(\n          operation.type,\n          errorMessage,\n          Boolean(operation.downgradeToPersonal)\n        )\n    trackLegacyBillingEvent({\n      operation: 'operation',\n      stage: 'failed',\n      outcome: 'failure',\n      billing_op_id: opId,\n      operation_type: operation.type,\n      tier: operation.tier,\n      cycle: operation.cycle,\n      checkout_type: operation.checkoutType,\n      payment_intent_source: operation.paymentIntentSource,\n      failure_category: failureCategory,\n      duration_ms: now - operation.operationStartedAt\n    })\n    if (\n      operation.type === 'subscription' &&\n      operation.businessAttemptStartedAt !== undefined\n    ) {\n      trackLegacyBillingEvent({\n        operation: 'subscription_checkout',\n        stage: 'failed',\n        outcome: 'failure',\n        tier: operation.tier,\n        cycle: operation.cycle,\n        checkout_type: operation.checkoutType,\n        payment_intent_source: operation.paymentIntentSource,\n        billing_op_id: opId,\n        failure_category: failureCategory,\n        duration_ms: now - operation.businessAttemptStartedAt\n      })\n    } else if (\n      operation.type === 'topup' &&\n      operation.businessAttemptStartedAt !== undefined\n    ) {\n      trackLegacyBillingEvent({\n        operation: 'topup',\n        stage: 'failed',\n        outcome: 'failure',\n        billing_op_id: opId,\n        payment_intent_source: operation.paymentIntentSource,\n        failure_category: failureCategory,\n        duration_ms: now - operation.businessAttemptStartedAt\n      })\n    }\n    if (operation.downgradeToPersonal) {\n      trackLegacyBillingEvent({\n        operation: 'downgrade_to_personal',\n        stage: 'failed',\n        outcome: 'failure',\n        member_removal_count: operation.downgradeToPersonal.memberRemovalCount,\n        member_removal_failures:\n          operation.downgradeToPersonal.memberRemovalFailures,\n        target_tier: operation.downgradeToPersonal.targetTier,\n        failure_category: failureCategory,\n        duration_ms: now - operation.downgradeToPersonal.startedAt\n      })\n    }\n\n    if (isPaymentOperation(operation.type) && !superseded) {\n      toast.error(defaultMessage, {\n        description: detail ?? undefined,\n        duration: 7000\n      })\n    }\n\n    resolveTerminal(opId)\n  }\n\n  function handleReconciliationNeeded(opId: string) {\n    const operation = operations.value.get(opId)\n    if (!operation) return\n    updateOperation(opId, {\n      status: 'reconciliation_needed',\n      authenticationState: 'reconciliation_needed',\n      canRetryAuthentication: false,\n      isAuthenticating: false,\n      errorMessage: null,\n      actionUrl: null\n    })\n    cleanup(opId)\n\n    const now = Date.now()\n    trackLegacyBillingEvent({\n      operation: 'operation',\n      stage: 'failed',\n      outcome: 'failure',\n      billing_op_id: opId,\n      operation_type: operation.type,\n      tier: operation.tier,\n      cycle: operation.cycle,\n      checkout_type: operation.checkoutType,\n      payment_intent_source: operation.paymentIntentSource,\n      failure_category: 'reconciliation_needed',\n      duration_ms: now - operation.operationStartedAt\n    })\n    if (\n      operation.type === 'subscription' &&\n      operation.businessAttemptStartedAt !== undefined\n    ) {\n      trackLegacyBillingEvent({\n        operation: 'subscription_checkout',\n        stage: 'failed',\n        outcome: 'failure',\n        tier: operation.tier,\n        cycle: operation.cycle,\n        checkout_type: operation.checkoutType,\n        payment_intent_source: operation.paymentIntentSource,\n        billing_op_id: opId,\n        failure_category: 'reconciliation_needed',\n        duration_ms: now - operation.businessAttemptStartedAt\n      })\n    } else if (\n      operation.type === 'topup' &&\n      operation.businessAttemptStartedAt !== undefined\n    ) {\n      trackLegacyBillingEvent({\n        operation: 'topup',\n        stage: 'failed',\n        outcome: 'failure',\n        billing_op_id: opId,\n        payment_intent_source: operation.paymentIntentSource,\n        failure_category: 'reconciliation_needed',\n        duration_ms: now - operation.businessAttemptStartedAt\n      })\n    }\n    if (operation.downgradeToPersonal) {\n      trackLegacyBillingEvent({\n        operation: 'downgrade_to_personal',\n        stage: 'failed',\n        outcome: 'failure',\n        member_removal_count: operation.downgradeToPersonal.memberRemovalCount,\n        member_removal_failures:\n          operation.downgradeToPersonal.memberRemovalFailures,\n        target_tier: operation.downgradeToPersonal.targetTier,\n        failure_category: 'reconciliation_needed',\n        duration_ms: now - operation.downgradeToPersonal.startedAt\n      })\n    }\n    resolveTerminal(opId)\n  }\n\n  function handleTimeout(opId: string) {\n    const operation = operations.value.get(opId)\n    if (!operation) return\n\n    const message = timeoutMessage(operation.type)\n\n    updateOperationStatus(opId, 'timeout', message)\n    cleanup(opId)\n\n    const now = Date.now()\n    trackLegacyBillingEvent({\n      operation: 'operation',\n      stage: 'timeout',\n      outcome: 'failure',\n      billing_op_id: opId,\n      operation_type: operation.type,\n      tier: operation.tier,\n      cycle: operation.cycle,\n      checkout_type: operation.checkoutType,\n      payment_intent_source: operation.paymentIntentSource,\n      failure_category: 'poll_timeout',\n      duration_ms: now - operation.operationStartedAt\n    })\n    if (\n      operation.type === 'subscription' &&\n      operation.businessAttemptStartedAt !== undefined\n    ) {\n      trackLegacyBillingEvent({\n        operation: 'subscription_checkout',\n        stage: 'failed',\n        outcome: 'failure',\n        tier: operation.tier,\n        cycle: operation.cycle,\n        checkout_type: operation.checkoutType,\n        payment_intent_source: operation.paymentIntentSource,\n        billing_op_id: opId,\n        failure_category: 'poll_timeout',\n        duration_ms: now - operation.businessAttemptStartedAt\n      })\n    } else if (\n      operation.type === 'topup' &&\n      operation.businessAttemptStartedAt !== undefined\n    ) {\n      trackLegacyBillingEvent({\n        operation: 'topup',\n        stage: 'failed',\n        outcome: 'failure',\n        billing_op_id: opId,\n        payment_intent_source: operation.paymentIntentSource,\n        failure_category: 'poll_timeout',\n        duration_ms: now - operation.businessAttemptStartedAt\n      })\n    }\n    if (operation.downgradeToPersonal) {\n      trackLegacyBillingEvent({\n        operation: 'downgrade_to_personal',\n        stage: 'failed',\n        outcome: 'failure',\n        member_removal_count: operation.downgradeToPersonal.memberRemovalCount,\n        member_removal_failures:\n          operation.downgradeToPersonal.memberRemovalFailures,\n        target_tier: operation.downgradeToPersonal.targetTier,\n        failure_category: 'poll_timeout',\n        duration_ms: now - operation.downgradeToPersonal.startedAt\n      })\n    }\n\n    if (isPaymentOperation(operation.type)) {\n      toast.error(message)\n    }\n\n    resolveTerminal(opId)\n  }\n\n  /**\n   * No caught JS error here — only the backend's free-form `error_message`, if\n   * any. `cancel` and zero-payment operations (e.g. downgrade-to-personal,\n   * which removes members / changes tier but never touches a card) can't be a\n   * provider decline, so they're always an api rejection. For payment-bearing\n   * `subscription`/`topup` polls, a message naming a connectivity/system\n   * failure isn't a decline either; only fall back to `provider_decline` when\n   * the backend gave no more specific signal.\n   */\n  function categorizePollFailure(\n    type: OperationType,\n    errorMessage: string | null,\n    isZeroPaymentOperation: boolean\n  ): BillingTelemetryFailure['failure_category'] {\n    if (!isPaymentOperation(type) || isZeroPaymentOperation)\n      return 'api_rejected'\n\n    if (errorMessage && /network|connection|unreachable/i.test(errorMessage)) {\n      return 'network'\n    }\n\n    return 'provider_decline'\n  }\n\n  function failureMessage(type: OperationType) {\n    if (type === 'retention') return t('subscription.retentionOffer.failed')\n    if (type === 'subscription') return t('billingOperation.subscriptionFailed')\n    if (type === 'topup') return t('billingOperation.topupFailed')\n    return t('billingOperation.cancelFailed')\n  }\n\n  function billingFailureDetail(\n    type: OperationType,\n    errorMessage: string | null,\n    recovery?: FailureRecovery\n  ) {\n    switch (errorMessage) {\n      case 'insufficient_funds':\n        return t('billingOperation.insufficientFundsDetail')\n      case 'expired_card':\n        return t('billingOperation.expiredCardDetail')\n      case 'incorrect_cvc':\n      case 'invalid_cvc':\n        return t('billingOperation.incorrectCvcDetail')\n      case 'authentication_failed':\n      case 'authentication_required':\n      case 'payment_intent_authentication_failure':\n      case 'payment_not_completed':\n      case 'payment_method_customer_decline':\n      case 'payment_intent_payment_attempt_expired':\n        return t('billingOperation.authenticationFailedDetail')\n      case 'subscribe_method_not_chargeable_off_session':\n        // `recovery` is withheld from operations that never charge a card.\n        if (recovery) {\n          return t('billingOperation.methodNotChargeableOffSessionDetail')\n        }\n        break\n      case 'processing_error':\n      case 'issuer_not_available':\n      case 'try_again_later':\n        return t('billingOperation.processingErrorDetail')\n      case 'card_declined':\n      case 'generic_decline':\n      case 'approve_with_id':\n      case 'call_issuer':\n      case 'do_not_honor':\n      case 'do_not_try_again':\n      case 'not_permitted':\n      case 'restricted_card':\n      case 'security_violation':\n      case 'service_not_allowed':\n      case 'transaction_not_allowed':\n      case 'initial_subscription_rejected':\n      case 'subscribe_invoice_payment_failed':\n      case 'topup_payment_declined':\n      case 'topup_invoice_payment_failed':\n      case 'upgrade_payment_declined':\n      case 'upgrade_invoice_payment_failed':\n      case 'team_credit_raise_payment_declined':\n      case 'reset_now_payment_declined':\n      case 'reset_now_invoice_payment_failed':\n        return t('billingOperation.paymentDeclinedDetail')\n    }\n    // Reached only when no coded reason named something more actionable. A\n    // terminal operation is served no action_url, so this copy must promise no\n    // button — and no retry unless the server says another attempt can work.\n    if (recovery?.action === 'authenticate_payment') {\n      return t(\n        recovery.retryable === false\n          ? 'billingOperation.authenticatePaymentBlockedDetail'\n          : 'billingOperation.authenticatePaymentDetail'\n      )\n    }\n    if (type === 'subscription')\n      return t('billingOperation.subscriptionFailedDetail')\n    if (type === 'topup' && errorMessage) return t('credits.topUp.unknownError')\n    return errorMessage\n  }\n\n  function timeoutMessage(type: OperationType) {\n    if (type === 'retention')\n      return t('subscription.retentionOffer.unconfirmed')\n    if (type === 'subscription')\n      return t('billingOperation.subscriptionTimeout')\n    if (type === 'topup') return t('billingOperation.topupTimeout')\n    return t('billingOperation.cancelTimeout')\n  }\n\n  function resolveTerminal(opId: string) {\n    const resolve = terminalResolvers.get(opId)\n    const operation = operations.value.get(opId)\n    if (resolve && operation) {\n      resolve(operation)\n    }\n    terminalResolvers.delete(opId)\n    terminalPromises.delete(opId)\n  }\n\n  function updateOperationStatus(\n    opId: string,\n    status: OperationStatus,\n    errorMessage: string | null\n  ) {\n    const operation = operations.value.get(opId)\n    if (!operation) return\n\n    const updated = {\n      ...operation,\n      status,\n      errorMessage,\n      actionUrl: null,\n      authenticationState: null,\n      canRetryAuthentication: false,\n      isAuthenticating: false\n    }\n    operations.value = new Map(operations.value).set(opId, updated)\n  }\n\n  function cleanup(opId: string) {\n    const timeoutId = timeouts.get(opId)\n    if (timeoutId) {\n      clearTimeout(timeoutId)\n      timeouts.delete(opId)\n    }\n    intervals.delete(opId)\n    waitingWithoutActionSince.delete(opId)\n    autoHandledPaymentActions.delete(opId)\n    paymentIntentClientSecrets.delete(opId)\n    progressToastsAwaitingFirstRead.delete(opId)\n\n    const progressToast = progressToasts.get(opId)\n    if (progressToast) {\n      toast.dismiss(progressToast.id)\n      progressToasts.delete(opId)\n    }\n  }\n\n  function clearOperation(opId: string) {\n    cleanup(opId)\n    const newMap = new Map(operations.value)\n    newMap.delete(opId)\n    operations.value = newMap\n    terminalResolvers.delete(opId)\n    terminalPromises.delete(opId)\n  }\n\n  // Unlike clearOperation, this keeps the operation live: polling continues\n  // and a late success or failure still resolves normally. It only removes\n  // the operation from the selectors a dialog reads, since whether the\n  // customer wants to see it is a view concern — whether it is over is not.\n  // A server-side cancel (BE-10064/BE-11559) would let a dismissal actually\n  // end the operation instead of merely hiding it; call that here once it\n  // exists.\n  function dismissOperation(opId: string) {\n    updateOperation(opId, { dismissed: true })\n  }\n\n  return {\n    operations,\n    hasPendingOperations,\n    isSettingUp,\n    isAddingCredits,\n    subscriptionActionOperation,\n    topupActionOperation,\n    getOperation,\n    startOperation,\n    retryPaymentAuthentication,\n    pollPendingOperations,\n    clearOperation,\n    dismissOperation\n  }\n})\n","import { computed } from 'vue'\n\nimport type { BillingClient } from '@comfyorg/account-core/billing'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport type { CreateTopupResponse } from '@/platform/workspace/api/workspaceApi'\nimport { workspaceApi } from '@/platform/workspace/api/workspaceApi'\nimport { useBillingSdkStore } from '@/platform/workspace/billing/sdk/billingSdkStore'\nimport { useBillingOperationStore } from '@/platform/workspace/stores/billingOperationStore'\n\n/**\n * The top-up purchase and the operation the dialog reads, from one rail.\n * The rail is fixed when the dialog opens: a flag flip mid-operation must not\n * issue on one rail and observe on the other, or move a live operation\n * between two observers.\n */\nexport function useTopupOperation() {\n  const { flags } = useFeatureFlags()\n  const sdkStore = flags.billingSdkTopupRailEnabled\n    ? useBillingSdkStore()\n    : null\n  const operationStore = useBillingOperationStore()\n  const billingContext = useBillingContext()\n  const billingClient: BillingClient = sdkStore ? 'sdk' : 'legacy'\n\n  const isAddingCredits = computed(() =>\n    sdkStore ? sdkStore.isAddingCredits : operationStore.isAddingCredits\n  )\n  const topupOperation = computed(() =>\n    sdkStore\n      ? sdkStore.topupActionOperation\n      : operationStore.topupActionOperation\n  )\n\n  function topup(amountCents: number): Promise<CreateTopupResponse | void> {\n    if (sdkStore) return sdkStore.createTopup(amountCents)\n    return billingContext.topup(amountCents)\n  }\n\n  /** The Stripe-hosted Checkout URL for a one-off purchase of `amountCents`. */\n  async function createHostedCheckout(\n    amountCents: number,\n    returnUrl: string\n  ): Promise<string> {\n    if (sdkStore) {\n      return sdkStore.createHostedTopupCheckout(amountCents, returnUrl)\n    }\n    const { checkout_url } = await workspaceApi.createTopupCheckout(\n      amountCents,\n      returnUrl\n    )\n    return checkout_url\n  }\n\n  function retryPaymentAuthentication(operationId: string): Promise<boolean> {\n    if (sdkStore) return sdkStore.retryPaymentAuthentication(operationId)\n    return operationStore.retryPaymentAuthentication(operationId)\n  }\n\n  function dismissOperation(operationId: string): void {\n    if (sdkStore) sdkStore.dismissOperation(operationId)\n    else operationStore.dismissOperation(operationId)\n  }\n\n  /**\n   * Adopt a top-up the purchase left pending, so the caller is told when it\n   * settles. On the SDK rail the lifecycle adopted it when the command was\n   * issued, so there is nothing to register and a second registration would be\n   * a second poller on one operation.\n   */\n  async function adoptPendingOperation(\n    operationId: string,\n    metadata: {\n      attemptStartedAt: number\n      paymentIntentSource?: PaymentIntentSource\n    }\n  ): Promise<void> {\n    if (sdkStore) return\n    await operationStore.startOperation(operationId, 'topup', {\n      ...metadata,\n      autoHandleRequiresAction: true\n    })\n  }\n\n  return {\n    billingClient,\n    isAddingCredits,\n    topupOperation,\n    topup,\n    createHostedCheckout,\n    retryPaymentAuthentication,\n    dismissOperation,\n    adoptPendingOperation\n  }\n}\n","import type {\n  CheckoutExit,\n  CheckoutJourneyPhase,\n  CheckoutJourneyPhaseEvent\n} from '@comfyorg/account-core/billing'\nimport { useEventListener } from '@vueuse/core'\nimport { onScopeDispose } from 'vue'\n\nimport { useTelemetry } from '@/platform/telemetry'\nimport {\n  getActiveCheckoutJourney,\n  toCheckoutJourneyContext\n} from '@/platform/workspace/utils/checkoutJourney'\nimport type { CheckoutJourneyRecord } from '@/platform/workspace/utils/checkoutJourney'\n\ntype CloudCheckoutExit = Extract<CheckoutExit, 'dialog_close' | 'page_exit'>\n\n/**\n * The last progress phase this tab reported on a journey, and whether an exit\n * or a handoff already accounts for it. Only new progress reopens it.\n */\nlet progress: {\n  journeyId: string\n  lastPhase: Exclude<CheckoutJourneyPhase, 'abandoned' | 'ended'>\n  accounted: boolean\n} | null = null\n\nexport function trackCheckoutJourneyPhase(\n  record: CheckoutJourneyRecord,\n  phase: CheckoutJourneyPhaseEvent\n): void {\n  if (phase.phase !== 'abandoned' && phase.phase !== 'ended') {\n    progress = {\n      journeyId: record.journey_id,\n      lastPhase: phase.phase,\n      accounted: false\n    }\n  }\n  useTelemetry()?.trackCheckoutJourneyEvent({\n    ...toCheckoutJourneyContext(record),\n    ...phase\n  })\n}\n\nfunction unaccountedProgress(journey: CheckoutJourneyRecord) {\n  return progress?.journeyId === journey.journey_id && !progress.accounted\n    ? progress\n    : null\n}\n\n/** The journey continues on the hosted checkout, so closing this dialog is not an exit. */\nexport function handOffCheckoutJourney(): void {\n  const journey = getActiveCheckoutJourney()\n  const open = journey && unaccountedProgress(journey)\n  if (open) open.accounted = true\n}\n\n/**\n * Where the customer left a journey no operation is bound to. An observation,\n * not a verdict: once an operation exists its own events own the end.\n */\nexport function reportCheckoutJourneyExit(exit: CloudCheckoutExit): void {\n  const journey = getActiveCheckoutJourney()\n  if (!journey || journey.billing_op_id !== undefined) return\n  const open = unaccountedProgress(journey)\n  if (!open) return\n  open.accounted = true\n  trackCheckoutJourneyPhase(journey, {\n    phase: 'abandoned',\n    last_phase: open.lastPhase,\n    exit\n  })\n}\n\n/** For a checkout dialog: its close, or the page going away while it is open, is an exit. */\nexport function useCheckoutJourneyExit(): void {\n  useEventListener(window, 'pagehide', () =>\n    reportCheckoutJourneyExit('page_exit')\n  )\n  onScopeDispose(() => reportCheckoutJourneyExit('dialog_close'))\n}\n","<template>\n  <div\n    class=\"flex min-h-[500px] w-[min(512px,95vw)] flex-col rounded-2xl border border-border-default bg-base-background shadow-[1px_1px_8px_0_rgba(0,0,0,0.4)]\"\n  >\n    <!-- Header -->\n    <div class=\"flex items-center justify-between p-8\">\n      <div class=\"flex items-center gap-2\">\n        <button\n          v-if=\"step === 'confirm'\"\n          class=\"cursor-pointer rounded-sm border-none bg-transparent p-0 text-muted-foreground transition-colors hover:text-base-foreground disabled:pointer-events-none disabled:opacity-40\"\n          :disabled=\"paymentLocked\"\n          :aria-label=\"$t('g.back')\"\n          @click=\"showAmountStep\"\n        >\n          <i class=\"icon-[lucide--arrow-left] size-5\" />\n        </button>\n        <h2\n          v-if=\"step === 'amount' || step === 'confirm'\"\n          class=\"m-0 text-base font-bold text-base-foreground\"\n        >\n          {{\n            step === 'confirm'\n              ? $t('credits.topUp.confirmTitle')\n              : isInsufficientCredits\n                ? $t('credits.topUp.addMoreCreditsToRun')\n                : $t('credits.topUp.addMoreCredits')\n          }}\n        </h2>\n      </div>\n      <button\n        class=\"cursor-pointer rounded-sm border-none bg-transparent p-0 text-muted-foreground transition-colors hover:text-base-foreground focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none\"\n        :aria-label=\"$t('g.close')\"\n        @click=\"() => handleClose(!topupIsParkedWithoutLink)\"\n      >\n        <i class=\"icon-[lucide--x] size-6\" />\n      </button>\n    </div>\n    <p\n      v-if=\"isInsufficientCredits && step === 'amount'\"\n      class=\"m-0 px-8 text-sm text-muted-foreground\"\n    >\n      {{ $t('credits.topUp.insufficientWorkflowMessage') }}\n    </p>\n\n    <template v-if=\"step === 'confirm'\">\n      <p class=\"m-0 px-8 text-sm text-muted-foreground\">\n        {{ $t('credits.topUp.confirmSubtitle') }}\n      </p>\n      <div class=\"flex flex-col gap-3 px-8 pt-6\">\n        <span\n          class=\"flex items-center gap-2 py-2 text-2xl font-semibold text-base-foreground tabular-nums\"\n        >\n          <i class=\"icon-[lucide--coins] size-5 text-gold-500\" />\n          {{ formatNumber(creditsModel) }}\n        </span>\n        <div\n          class=\"flex items-center justify-between border-t border-border-default pt-4\"\n        >\n          <span class=\"text-base font-semibold text-base-foreground\">\n            {{ $t('subscription.preview.totalDueToday') }}\n          </span>\n          <span\n            class=\"text-base font-semibold text-base-foreground tabular-nums\"\n          >\n            {{ displayTotal }}\n          </span>\n        </div>\n      </div>\n      <p\n        v-if=\"checkoutRecovery === 'refused'\"\n        class=\"m-0 px-8 pt-4 text-sm text-muted-foreground\"\n      >\n        {{ $t('credits.topUp.noPaymentMethodCheckoutHint') }}\n      </p>\n      <p\n        v-else-if=\"checkoutRecovery === 'failed'\"\n        role=\"alert\"\n        class=\"m-0 px-8 pt-4 text-sm text-destructive-background\"\n      >\n        {{ $t('credits.topUp.checkoutOpenFailed') }}\n      </p>\n    </template>\n\n    <div\n      v-if=\"step === 'checkoutBlocked'\"\n      class=\"flex flex-col items-center gap-3 px-8 text-center\"\n    >\n      <h2\n        class=\"m-0 text-center text-xl font-semibold text-base-foreground lg:text-2xl\"\n      >\n        {{ $t('credits.topUp.checkoutBlockedTitle') }}\n      </h2>\n      <p class=\"m-0 text-sm text-balance text-muted-foreground\">\n        {{ $t('credits.topUp.checkoutBlockedBody') }}\n      </p>\n    </div>\n\n    <template v-if=\"step === 'verifying'\">\n      <div class=\"flex flex-col items-center gap-3 px-8 text-center\">\n        <i\n          class=\"icon-[lucide--shield-alert] size-10 text-warning-background\"\n        />\n        <h2\n          class=\"m-0 text-center text-xl font-semibold text-base-foreground lg:text-2xl\"\n        >\n          {{ $t('credits.topUp.verifyTitle') }}\n        </h2>\n        <p class=\"m-0 text-sm text-balance text-muted-foreground\">\n          {{ verifyingBody }}\n        </p>\n        <span\n          v-if=\"topupReconciliationOperationId\"\n          class=\"font-mono text-sm text-base-foreground\"\n        >\n          {{ topupReconciliationOperationId }}\n        </span>\n      </div>\n    </template>\n\n    <!-- Preset amount buttons -->\n    <div v-if=\"step === 'amount'\" class=\"px-8\">\n      <h3 class=\"m-0 text-sm font-normal text-muted-foreground\">\n        {{ $t('credits.topUp.selectAmount') }}\n      </h3>\n      <div class=\"flex gap-2 pt-3\">\n        <Button\n          v-for=\"amount in TOPUP_AMOUNT_PRESETS_USD\"\n          :key=\"amount\"\n          :autofocus=\"amount === 50\"\n          variant=\"secondary\"\n          size=\"lg\"\n          :class=\"\n            cn(\n              'h-10 w-full text-base font-medium focus-visible:ring-border-default',\n              selectedPreset === amount && 'bg-secondary-background-selected'\n            )\n          \"\n          @click=\"handlePresetClick(amount)\"\n        >\n          ${{ amount }}\n        </Button>\n      </div>\n    </div>\n    <!-- Amount (USD) / Credits -->\n    <div v-if=\"step === 'amount'\" class=\"flex gap-2 px-8 pt-8\">\n      <!-- You Pay -->\n      <div\n        class=\"flex min-w-0 flex-1 flex-col gap-3\"\n        data-testid=\"top-up-pay-amount\"\n      >\n        <div class=\"text-sm text-muted-foreground\">\n          {{ $t('credits.topUp.youPay') }}\n        </div>\n        <NumberField\n          :model-value=\"payAmount\"\n          :min=\"0\"\n          :max=\"MAX_AMOUNT\"\n          :step=\"getStepAmount(payAmount)\"\n          :format-options=\"{ maximumFractionDigits: 0 }\"\n          @update:model-value=\"handlePayAmountChange\"\n        >\n          <NumberFieldDecrement />\n          <span class=\"shrink-0 text-base font-semibold text-base-foreground\"\n            >$</span\n          >\n          <NumberFieldInput\n            :aria-label=\"$t('credits.topUp.youPay')\"\n            class=\"text-lg font-medium\"\n          />\n          <NumberFieldIncrement />\n        </NumberField>\n      </div>\n\n      <!-- You Get -->\n      <div class=\"flex min-w-0 flex-1 flex-col gap-3\">\n        <div class=\"text-sm text-muted-foreground\">\n          {{ $t('credits.topUp.youGet') }}\n        </div>\n        <NumberField\n          v-model=\"creditsModel\"\n          :min=\"0\"\n          :max=\"usdToCredits(MAX_AMOUNT)\"\n          :step=\"getCreditsStepAmount(creditsModel)\"\n          :format-options=\"{ maximumFractionDigits: 0 }\"\n        >\n          <NumberFieldDecrement />\n          <i class=\"icon-[lucide--coins] size-4 shrink-0 text-gold-500\" />\n          <NumberFieldInput\n            :aria-label=\"$t('credits.topUp.youGet')\"\n            class=\"text-lg font-medium\"\n          />\n          <NumberFieldIncrement />\n        </NumberField>\n      </div>\n    </div>\n\n    <!-- Warnings -->\n\n    <p\n      v-if=\"isBelowMin && step === 'amount'\"\n      class=\"m-0 flex items-center justify-center gap-1 px-8 pt-4 text-center text-sm text-red-500\"\n    >\n      <i class=\"icon-[lucide--coins] size-4\" />\n      {{\n        $t('credits.topUp.minRequired', {\n          credits: formatNumber(usdToCredits(MIN_AMOUNT))\n        })\n      }}\n    </p>\n    <p\n      v-if=\"showCeilingWarning && step === 'amount'\"\n      class=\"m-0 flex items-center justify-center gap-1 px-8 pt-4 text-center text-sm text-gold-500\"\n    >\n      <i class=\"icon-[lucide--coins] size-4\" />\n      {{\n        $t('credits.topUp.maxAllowed', {\n          credits: formatNumber(usdToCredits(MAX_AMOUNT))\n        })\n      }}\n      <span>{{ $t('credits.topUp.needMore') }}</span>\n      <a\n        href=\"https://comfy.org/cloud/enterprise/\"\n        target=\"_blank\"\n        class=\"ml-1 text-inherit\"\n        >{{ $t('credits.topUp.contactUs') }}</a\n      >\n    </p>\n\n    <div class=\"mt-auto flex flex-col gap-8 p-8\">\n      <div v-if=\"step === 'verifying'\">\n        <Button\n          v-if=\"topupCanResumeAuthentication\"\n          variant=\"primary\"\n          size=\"lg\"\n          class=\"h-10 w-full justify-center\"\n          :loading=\"topupIsAuthenticating\"\n          :disabled=\"!canTopUp\"\n          @click=\"resumeTopupAuthentication\"\n        >\n          {{ $t('subscription.preview.completeVerification') }}\n        </Button>\n        <Button\n          v-else-if=\"topupIsFailedRetryable\"\n          variant=\"primary\"\n          size=\"lg\"\n          class=\"h-10 w-full justify-center\"\n          @click=\"startOverTopup\"\n        >\n          {{ $t('credits.topUp.startOver') }}\n        </Button>\n        <Button\n          v-else-if=\"topupIsParkedWithoutLink\"\n          variant=\"secondary\"\n          size=\"lg\"\n          class=\"h-10 w-full justify-center\"\n          @click=\"() => handleClose(false)\"\n        >\n          {{ $t('g.ok') }}\n        </Button>\n        <Button\n          v-else-if=\"!topupReconciliationOperationId\"\n          variant=\"primary\"\n          size=\"lg\"\n          class=\"h-10 w-full justify-center\"\n          :disabled=\"!topupActionUrl || !canTopUp\"\n          :loading=\"!topupActionUrl\"\n          :aria-label=\"$t('subscription.preview.completeVerification')\"\n          @click=\"openTopupVerification\"\n        >\n          {{ $t('subscription.preview.completeVerification') }}\n        </Button>\n      </div>\n      <Button\n        v-else-if=\"step === 'checkoutBlocked'\"\n        variant=\"primary\"\n        size=\"lg\"\n        class=\"h-10 w-full justify-center\"\n        @click=\"continueToCheckout\"\n      >\n        {{ $t('credits.topUp.openCheckout') }}\n        <i class=\"icon-[lucide--external-link] size-4\" />\n      </Button>\n      <div v-else class=\"flex flex-col gap-2\">\n        <Button\n          v-if=\"step === 'confirm' && topupActionUrl && canTopUp\"\n          variant=\"primary\"\n          size=\"lg\"\n          class=\"h-10 justify-center\"\n          @click=\"openTopupVerification\"\n        >\n          {{ $t('subscription.preview.completeVerification') }}\n        </Button>\n        <Button\n          v-if=\"step === 'confirm' && checkoutRecovery\"\n          variant=\"primary\"\n          size=\"lg\"\n          class=\"h-10 justify-center\"\n          :disabled=\"!isValidAmount || paymentLocked || !canTopUp\"\n          :loading=\"paymentLocked\"\n          @click=\"continueToCheckout\"\n        >\n          {{ $t('credits.topUp.continueToCheckout') }}\n          <i class=\"icon-[lucide--external-link] size-4\" />\n        </Button>\n        <Button\n          v-else\n          :disabled=\"!isValidAmount || paymentLocked || !canTopUp\"\n          :loading=\"paymentLocked\"\n          :variant=\"\n            step === 'confirm' && topupActionUrl ? 'tertiary' : 'primary'\n          \"\n          size=\"lg\"\n          class=\"h-10 justify-center tabular-nums\"\n          @click=\"handlePrimaryAction\"\n        >\n          {{\n            step === 'confirm'\n              ? $t('credits.topUp.payAmount', { amount: displayTotal })\n              : $t('subscription.addCredits')\n          }}\n        </Button>\n      </div>\n      <div\n        v-if=\"step === 'amount'\"\n        class=\"flex items-center justify-center gap-1\"\n      >\n        <a\n          :href=\"pricingUrl\"\n          target=\"_blank\"\n          class=\"flex items-center gap-1 text-sm text-muted-foreground no-underline transition-colors hover:text-base-foreground\"\n        >\n          {{ $t('credits.topUp.viewPricing') }}\n          <i class=\"icon-[lucide--external-link] size-4\" />\n        </a>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { BillingOperationTerminal } from '@comfyorg/account-core/billing'\nimport {\n  getTopupAmountPreset,\n  TOPUP_AMOUNT_PRESETS_USD\n} from '@comfyorg/account-core/billing'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { computed, onMounted, onUnmounted, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { creditsToUsd, usdToCredits } from '@/base/credits/comfyCredits'\nimport Button from '@/components/ui/button/Button.vue'\nimport NumberField from '@/components/ui/number-field/NumberField.vue'\nimport NumberFieldDecrement from '@/components/ui/number-field/NumberFieldDecrement.vue'\nimport NumberFieldIncrement from '@/components/ui/number-field/NumberFieldIncrement.vue'\nimport NumberFieldInput from '@/components/ui/number-field/NumberFieldInput.vue'\nimport { watchForTopupBalanceUpdate } from '@/composables/billing/topupBalanceRefresh'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { usePendingTopup } from '@/composables/billing/usePendingTopup'\nimport { isCloud } from '@/platform/distribution/types'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport { categorizeBillingApiError } from '@/platform/telemetry/utils/billingFailureCategory'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport type { CreateTopupResponse } from '@/platform/workspace/api/workspaceApi'\nimport { WorkspaceApiError } from '@/platform/workspace/api/workspaceApi'\nimport type { BillingTab } from '@/platform/workspace/billing/billingTab'\nimport { reserveBillingTab } from '@/platform/workspace/billing/billingTab'\nimport { topupCheckoutReturnUrl } from '@/platform/workspace/billing/topupCheckoutReturnUrl'\nimport { isBlockedOnCustomerPhase } from '@/platform/workspace/billing/customerAttention'\nimport { UncreditedTopupResponse } from '@/platform/workspace/billing/sdk/topupOperationView'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useTopupOperation } from '@/platform/workspace/composables/useTopupOperation'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport {\n  bindOperationToCheckoutJourney,\n  clearCheckoutJourney,\n  getActiveCheckoutJourney,\n  resolveCheckoutAssignment,\n  resolveCheckoutJourney,\n  resolveEntrySource\n} from '@/platform/workspace/utils/checkoutJourney'\nimport {\n  trackCheckoutJourneyPhase,\n  useCheckoutJourneyExit\n} from '@/platform/workspace/utils/checkoutJourneyTelemetry'\nimport { api } from '@/scripts/api'\nimport { useAuthStore } from '@/stores/authStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { getErrorMessage } from '@/utils/errorUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { isInsufficientCredits = false, source } = defineProps<{\n  isInsufficientCredits?: boolean\n  source?: PaymentIntentSource\n}>()\n\nconst { n, t } = useI18n()\nconst dialogStore = useDialogStore()\nconst settingsDialog = useSettingsDialog()\nconst telemetry = useTelemetry()\nconst toast = useToast()\nconst { buildDocsUrl, docsPaths } = useExternalLink()\nconst { balance, fetchBalance, fetchStatus } = useBillingContext()\nconst { canTopUp } = useBillingCapabilities()\n\nconst workspaceStore = useTeamWorkspaceStore()\n\nfunction enterTopupJourney(): void {\n  const workspaceId = workspaceStore.activeWorkspaceId\n  const ownerUid = useAuthStore().userId\n  if (!workspaceId || !ownerUid) return\n\n  const entrySource = resolveEntrySource(source, 'settings_billing')\n  const resolved = resolveCheckoutJourney({\n    actorUid: ownerUid,\n    workspaceId,\n    entryFlow: 'topup',\n    entrySource,\n    paymentIntentSource: source,\n    intent: entrySource,\n    assignment: resolveCheckoutAssignment(api.getServerFeatures())\n  })\n  if (resolved.status === 'blocked' || resolved.resumed) return\n\n  trackCheckoutJourneyPhase(resolved.record, { phase: 'entered' })\n}\n\nonMounted(enterTopupJourney)\nuseCheckoutJourneyExit()\nconst {\n  billingClient,\n  isAddingCredits,\n  topupOperation,\n  topup,\n  createHostedCheckout,\n  retryPaymentAuthentication,\n  dismissOperation,\n  adoptPendingOperation\n} = useTopupOperation()\n// Start over invalidates the attempt in flight: on the SDK rail the purchase\n// call resolves only at settlement, so a superseded attempt must not unlock\n// or close the dialog for the attempt that replaced it.\nlet purchaseAttempt = 0\nconst topupActionUrl = computed(() => topupOperation.value?.actionUrl ?? null)\nconst topupAuthenticationError = computed(\n  () => topupOperation.value?.errorMessage ?? null\n)\nconst topupCanResumeAuthentication = computed(\n  () => topupOperation.value?.canRetryAuthentication ?? false\n)\nconst topupIsAuthenticating = computed(\n  () => topupOperation.value?.isAuthenticating ?? false\n)\nconst topupIsFailedRetryable = computed(\n  () => topupOperation.value?.authenticationState === 'failed_retryable'\n)\n// Parked on the customer with no link to send them to. The operation stays open\n// server-side, and that also refuses a replacement purchase, so this state\n// explains the wait rather than offering a restart that would be rejected.\n// Leaving this screen keeps the pending-top-up marker: the copy sends the\n// customer off to pay elsewhere, and the marker outlives the wait, so it is\n// what refreshes the balance when they come back to a settled purchase.\n// Latent on this rail today — only the legacy hosted-checkout path sets the\n// marker, so usually there is none here to keep. Preserving it is still right,\n// and it starts paying off if this rail ever sets one when it parks.\nconst topupIsParkedWithoutLink = computed(\n  () =>\n    !topupActionUrl.value &&\n    isBlockedOnCustomerPhase(topupOperation.value?.phase)\n)\nconst topupReconciliationOperationId = computed(() =>\n  topupOperation.value?.status === 'reconciliation_needed'\n    ? topupOperation.value.opId\n    : null\n)\nconst verifyingBody = computed(() => {\n  if (topupReconciliationOperationId.value) {\n    return t('billingOperation.reconciliationDetail')\n  }\n  if (topupAuthenticationError.value) return topupAuthenticationError.value\n  if (topupIsParkedWithoutLink.value) {\n    return t('credits.topUp.awaitingBankApprovalBody')\n  }\n  return t('credits.topUp.verifyBody')\n})\n\n// Constants\nconst MIN_AMOUNT = 5\nconst MAX_AMOUNT = 10000\n\n// State\nconst selectedPreset = ref<number | null>(50)\nconst payAmount = ref(50)\nconst loading = ref(false)\nconst paymentSubmitted = ref(false)\nconst checkoutRecovery = ref<'refused' | 'failed' | null>(null)\nconst step = ref<'amount' | 'confirm' | 'verifying' | 'checkoutBlocked'>(\n  topupOperation.value && canTopUp.value ? 'verifying' : 'amount'\n)\n\n// Computed\nconst pricingUrl = computed(() =>\n  buildDocsUrl(docsPaths.partnerNodesPricing, { includeLocale: true })\n)\n\nconst creditsModel = computed({\n  get: () => usdToCredits(payAmount.value),\n  set: (newCredits: number) => {\n    payAmount.value = Math.round(creditsToUsd(newCredits))\n    selectedPreset.value = null\n  }\n})\n\nconst isValidAmount = computed(\n  () => payAmount.value >= MIN_AMOUNT && payAmount.value <= MAX_AMOUNT\n)\n\nconst isBelowMin = computed(() => payAmount.value < MIN_AMOUNT)\nconst showCeilingWarning = computed(() => payAmount.value >= MAX_AMOUNT)\n\nconst displayTotal = computed(() =>\n  n(payAmount.value, {\n    style: 'currency',\n    currency: 'USD',\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2\n  })\n)\n\nconst paymentLocked = computed(\n  () =>\n    loading.value ||\n    paymentSubmitted.value ||\n    isAddingCredits.value ||\n    !!topupOperation.value\n)\n\nwatch(\n  [isAddingCredits, topupOperation, canTopUp],\n  ([addingCredits, operation, allowed]) => {\n    if (addingCredits || operation) loading.value = false\n    if (step.value === 'verifying' && !addingCredits && !operation) {\n      step.value = 'amount'\n      return\n    }\n    if (operation && allowed) {\n      step.value = 'verifying'\n    }\n  }\n)\n\n// Utility functions\nfunction formatNumber(num: number): string {\n  return num.toLocaleString('en-US')\n}\n\n// Step amount functions\nfunction getStepAmount(currentAmount: number): number {\n  if (currentAmount < 100) return 5\n  if (currentAmount < 1000) return 50\n  return 100\n}\n\nfunction getCreditsStepAmount(currentCredits: number): number {\n  const usdAmount = creditsToUsd(currentCredits)\n  return usdToCredits(getStepAmount(usdAmount))\n}\n\n// Event handlers\nfunction handlePayAmountChange(value: number) {\n  payAmount.value = value\n  selectedPreset.value = null\n}\n\nfunction handlePresetClick(amount: number) {\n  payAmount.value = amount\n  selectedPreset.value = amount\n}\n\nfunction handlePrimaryAction() {\n  if (step.value === 'amount') {\n    telemetry?.trackBillingEvent({\n      operation: 'topup',\n      stage: 'intent',\n      outcome: 'pending',\n      payment_intent_source: source\n    })\n    step.value = 'confirm'\n    return\n  }\n  void handleBuy()\n}\n\nfunction openTopupVerification() {\n  if (!topupActionUrl.value) return\n  window.open(topupActionUrl.value, '_blank', 'noopener,noreferrer')\n}\n\nfunction resumeTopupAuthentication() {\n  const operation = topupOperation.value\n  if (!operation || !canTopUp.value) return\n  void retryPaymentAuthentication(operation.opId)\n}\n\nfunction showAmountStep() {\n  checkoutRecovery.value = null\n  step.value = 'amount'\n}\n\nfunction startOverTopup() {\n  purchaseAttempt += 1\n  const operation = topupOperation.value\n  if (operation) dismissOperation(operation.opId)\n  paymentSubmitted.value = false\n  showAmountStep()\n}\n\nfunction handleClose(clearTracking = true) {\n  if (clearTracking) {\n    usePendingTopup().clearPendingTopup()\n  }\n  dialogStore.closeDialog({ key: 'top-up-credits' })\n}\n\nasync function handleBuy() {\n  if (paymentLocked.value || !isValidAmount.value || !canTopUp.value) {\n    return\n  }\n\n  purchaseAttempt += 1\n  const attempt = purchaseAttempt\n  const isCurrentAttempt = () => attempt === purchaseAttempt\n  checkoutRecovery.value = null\n  loading.value = true\n  paymentSubmitted.value = true\n  const attemptStartedAt = Date.now()\n  const amountCents = payAmount.value * 100\n  try {\n    telemetry?.trackApiCreditTopupButtonPurchaseClicked(payAmount.value)\n    telemetry?.trackBillingEvent({\n      operation: 'topup',\n      stage: 'started',\n      outcome: 'pending',\n      payment_intent_source: source,\n      amount_cents: amountCents,\n      amount_preset: getTopupAmountPreset(selectedPreset.value)\n    })\n    telemetry?.trackBillingEvent({\n      operation: 'operation',\n      stage: 'started',\n      outcome: 'pending',\n      operation_type: 'topup',\n      billing_client: billingClient\n    })\n\n    const submittingJourney = getActiveCheckoutJourney()\n    if (submittingJourney) {\n      trackCheckoutJourneyPhase(submittingJourney, { phase: 'submitted' })\n    }\n\n    const response = await topup(amountCents)\n    if (!response) {\n      if (isCurrentAttempt()) paymentSubmitted.value = false\n      reportTerminal(attemptStartedAt, {\n        stage: 'failed',\n        outcome: 'failure',\n        failure_category: 'unknown'\n      })\n      return\n    }\n\n    // Only correlate the response to the journey that submitted it: the user\n    // may have closed this dialog and started another journey while the\n    // request was in flight, and that later journey must not be bound here.\n    const submittingJourneyStillActive =\n      submittingJourney !== null &&\n      getActiveCheckoutJourney()?.journey_id === submittingJourney.journey_id\n    if (submittingJourneyStillActive) {\n      const linkedJourney = bindOperationToCheckoutJourney(\n        response.billing_op_id\n      )\n      if (linkedJourney) {\n        trackCheckoutJourneyPhase(linkedJourney, {\n          phase: 'operation_linked',\n          billing_op_id: response.billing_op_id\n        })\n      }\n    }\n\n    reportResponseTerminal(response, attemptStartedAt)\n\n    if (response.status === 'completed') {\n      if (\n        getActiveCheckoutJourney()?.billing_op_id === response.billing_op_id\n      ) {\n        clearCheckoutJourney()\n      }\n      toast.success(t('credits.topUp.purchaseSuccess'), { duration: 5000 })\n      await Promise.allSettled([fetchBalance(), fetchStatus()])\n      if (!isCurrentAttempt()) return\n      handleClose(false)\n      settingsDialog.show(isCloud ? 'workspace' : 'credits')\n    } else if (response.status === 'pending') {\n      void adoptPendingOperation(response.billing_op_id, {\n        attemptStartedAt,\n        paymentIntentSource: source\n      })\n        .then(() => {\n          if (isCurrentAttempt()) paymentSubmitted.value = false\n        })\n        .catch(() => {\n          reportPurchaseError(\n            attemptStartedAt,\n            response.billing_op_id,\n            undefined,\n            isCurrentAttempt()\n          )\n        })\n    } else {\n      if (isCurrentAttempt()) paymentSubmitted.value = false\n      toast.error(t('credits.topUp.purchaseError'), {\n        description: t('credits.topUp.unknownError')\n      })\n    }\n  } catch (error) {\n    reportPurchaseError(attemptStartedAt, undefined, error, isCurrentAttempt())\n  } finally {\n    if (isCurrentAttempt()) loading.value = false\n  }\n}\n\nfunction reportPurchaseError(\n  attemptStartedAt: number,\n  billingOpId?: string,\n  error?: unknown,\n  currentAttempt = true\n) {\n  if (currentAttempt) paymentSubmitted.value = false\n  console.error('Purchase failed', ...(error === undefined ? [] : [error]))\n\n  reportTerminal(\n    attemptStartedAt,\n    {\n      stage: 'failed',\n      outcome: 'failure',\n      failure_category:\n        error === undefined ? 'unknown' : categorizeBillingApiError(error)\n    },\n    billingOpId\n  )\n  if (isNoPaymentMethodRefusal(error)) {\n    if (currentAttempt) checkoutRecovery.value = 'refused'\n    return\n  }\n  toast.error(t('credits.topUp.purchaseError'), {\n    description: purchaseErrorDetail(error)\n  })\n}\n\nfunction isNoPaymentMethodRefusal(error: unknown): boolean {\n  return (\n    error instanceof WorkspaceApiError && error.code === 'NO_PAYMENT_METHOD'\n  )\n}\n\nlet unmounted = false\nonUnmounted(() => {\n  unmounted = true\n})\n\nfunction handOffToCheckout(checkoutTab: BillingTab, checkoutUrl: string) {\n  checkoutTab.navigate(checkoutUrl)\n  usePendingTopup().startPendingTopup()\n  watchForTopupBalanceUpdate({\n    current: () => balance.value?.amountMicros ?? null,\n    fetch: async () => {\n      const [balanceRead] = await Promise.allSettled([\n        fetchBalance(),\n        fetchStatus()\n      ])\n      if (balanceRead.status === 'rejected') throw balanceRead.reason\n      return balance.value?.amountMicros ?? null\n    }\n  })\n  handleClose(false)\n}\n\nasync function continueToCheckout() {\n  if (!(canTopUp.value && isValidAmount.value && !paymentLocked.value)) {\n    return\n  }\n  const returnUrl = topupCheckoutReturnUrl()\n  if (!returnUrl) {\n    checkoutRecovery.value = 'failed'\n    return\n  }\n  const checkoutTab = reserveBillingTab()\n  if (!checkoutTab) {\n    step.value = 'checkoutBlocked'\n    return\n  }\n  loading.value = true\n  try {\n    const checkoutUrl = await createHostedCheckout(\n      payAmount.value * 100,\n      returnUrl\n    )\n    if (unmounted) {\n      checkoutTab.close()\n      return\n    }\n    handOffToCheckout(checkoutTab, checkoutUrl)\n  } catch (error) {\n    checkoutTab.close()\n    console.error('Hosted top-up checkout failed to open', error)\n    if (unmounted) return\n    step.value = 'confirm'\n    checkoutRecovery.value = 'failed'\n  } finally {\n    loading.value = false\n  }\n}\n\n/**\n * The terminal a response's status implies. A synchronous `failed` is a\n * declined charge, not a pre-attempt rejection; a `pending` one is the\n * poller's to report once it settles.\n */\nconst RESPONSE_TERMINALS: Record<\n  CreateTopupResponse['status'],\n  BillingOperationTerminal | undefined\n> = {\n  completed: { stage: 'succeeded', outcome: 'success' },\n  failed: {\n    stage: 'failed',\n    outcome: 'failure',\n    failure_category: 'provider_decline'\n  },\n  pending: undefined\n}\n\nfunction reportResponseTerminal(\n  response: CreateTopupResponse,\n  attemptStartedAt: number\n) {\n  const terminal =\n    response instanceof UncreditedTopupResponse\n      ? response.terminal\n      : RESPONSE_TERMINALS[response.status]\n  if (terminal) {\n    reportTerminal(attemptStartedAt, terminal, response.billing_op_id)\n  }\n}\n\nfunction reportTerminal(\n  attemptStartedAt: number,\n  terminal: BillingOperationTerminal,\n  billingOpId?: string\n) {\n  const attempt = {\n    ...(billingOpId ? { billing_op_id: billingOpId } : {}),\n    duration_ms: Date.now() - attemptStartedAt\n  }\n  // No timeout stage on the top-up funnel; the poller reports it as failed too.\n  telemetry?.trackBillingEvent(\n    terminal.stage === 'succeeded'\n      ? {\n          operation: 'topup',\n          stage: 'succeeded',\n          outcome: 'success',\n          payment_intent_source: source,\n          ...attempt\n        }\n      : {\n          operation: 'topup',\n          stage: 'failed',\n          outcome: 'failure',\n          payment_intent_source: source,\n          failure_category: terminal.failure_category,\n          ...attempt\n        }\n  )\n  telemetry?.trackBillingEvent({\n    operation: 'operation',\n    operation_type: 'topup',\n    billing_client: billingClient,\n    ...terminal,\n    ...attempt\n  })\n}\n\nfunction purchaseErrorDetail(error?: unknown): string {\n  const code = error instanceof WorkspaceApiError ? error.code : undefined\n  // Only one billing operation is open at a time, so this refusal means the\n  // previous purchase has not settled or expired yet — not that anything failed.\n  if (code === 'SUBSCRIPTION_CHANGE_IN_PROGRESS') {\n    return t('credits.topUp.changeInProgressError')\n  }\n  return t('credits.topUp.purchaseErrorDetail', {\n    error: getErrorMessage(error) ?? t('credits.topUp.unknownError')\n  })\n}\n</script>\n","import { watch } from 'vue'\n\nimport ConfirmationDialogContent from '@/components/dialog/content/ConfirmationDialogContent.vue'\nimport TopUpCreditsDialogContentLegacy from '@/components/dialog/content/TopUpCreditsDialogContentLegacy.vue'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport type {\n  DowngradeToPersonalResult,\n  SubscriptionDialogOptions,\n  TopUpCreditsDialogOptions\n} from '@/composables/billing/types'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { t } from '@/i18n'\nimport type { CancellationFlowDialogOptions } from '@/platform/cloud/subscription/launchCancellationFlow'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport InsufficientCreditsMemberDialog from '@/platform/workspace/components/InsufficientCreditsMemberDialog.vue'\nimport TopUpCreditsDialogContentWorkspace from '@/platform/workspace/components/TopUpCreditsDialogContentWorkspace.vue'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { getErrorMessage } from '@/utils/errorUtil'\n\nfunction topUpFallbackReason(\n  options?: TopUpCreditsDialogOptions\n): PaymentIntentSource {\n  if (options?.isInsufficientCredits) return 'out_of_credits'\n  return options?.source ?? 'top_up_blocked'\n}\n\nexport function useBillingDialogs() {\n  const dialogStore = useDialogStore()\n\n  async function showTopUpCreditsDialog(options?: TopUpCreditsDialogOptions) {\n    useTelemetry()?.trackBillingEvent({\n      operation: 'entry',\n      stage: 'add_credits_clicked',\n      outcome: 'pending',\n      payment_intent_source:\n        options?.source ??\n        (options?.isInsufficientCredits ? 'out_of_credits' : undefined)\n    })\n    const { type } = useBillingContext()\n    const { canTopUp, canSubscribeSelfServe, isReady, initialize } =\n      useBillingCapabilities()\n    // A capability read still in flight has to be awaited here, or a top-up\n    // triggered during that window is silently dropped with no recovery UI.\n    if (!isReady.value) await initialize()\n    if (!isReady.value) return\n    if (!canTopUp.value && canSubscribeSelfServe.value) {\n      await showSubscriptionRequiredDialog({\n        reason: topUpFallbackReason(options),\n        paymentIntentSource: options?.source\n      })\n      return\n    }\n\n    if (!canTopUp.value && type.value === 'workspace') {\n      return dialogStore.showDialog({\n        key: 'insufficient-credits-member',\n        component: InsufficientCreditsMemberDialog,\n        props: {\n          onClose: () =>\n            dialogStore.closeDialog({ key: 'insufficient-credits-member' })\n        },\n        dialogComponentProps: {\n          headless: true\n        }\n      })\n    }\n    if (!canTopUp.value) return\n\n    // Unknown never selects the legacy content, which buys credits directly.\n    const isWorkspaceRail = type.value !== 'legacy'\n\n    return dialogStore.showDialog({\n      key: 'top-up-credits',\n      component: isWorkspaceRail\n        ? TopUpCreditsDialogContentWorkspace\n        : TopUpCreditsDialogContentLegacy,\n      props: options,\n      dialogComponentProps: {\n        headless: true\n      }\n    })\n  }\n\n  async function showSubscriptionRequiredDialog(\n    options?: SubscriptionDialogOptions\n  ) {\n    if (!isCloud) return\n\n    // A caller (e.g. the agent panel's paywall card) can fire this before the\n    // bootstrap /features fetch resolves, most likely right after a fresh\n    // load. window.__CONFIG__ is then still empty and the flag check below\n    // would silently swallow the click. Await one fresh fetch before\n    // deciding, rather than trusting a config snapshot that was never taken.\n    if (!window.__CONFIG__?.subscription_required) {\n      const { remoteConfigState } =\n        await import('@/platform/remoteConfig/remoteConfig')\n      if (remoteConfigState.value === 'unloaded') {\n        const { refreshRemoteConfig } =\n          await import('@/platform/remoteConfig/refreshRemoteConfig')\n        await refreshRemoteConfig()\n      }\n    }\n\n    if (!window.__CONFIG__?.subscription_required) {\n      // This gate closing is never expected to be reachable from a cloud\n      // surface with subscriptions enabled. Report it instead of returning\n      // silently, so a caller's \"Subscribe\" button failing to do anything\n      // shows up in telemetry rather than only in a user's bug report.\n      const { reportError } = await import('@/platform/telemetry/reportError')\n      reportError(\n        new Error(\n          'showSubscriptionRequiredDialog: subscription_required gate closed'\n        ),\n        {\n          surface: 'billing',\n          errorType: 'error_opening_subscription_dialog_gate_closed'\n        }\n      )\n      return\n    }\n\n    const { useSubscriptionDialog } =\n      await import('@/platform/cloud/subscription/composables/useSubscriptionDialog')\n    const { show } = useSubscriptionDialog()\n    show(options)\n  }\n\n  function showBillingComingSoonDialog() {\n    return dialogStore.showDialog({\n      key: 'billing-coming-soon',\n      title: t('subscription.billingComingSoon.title'),\n      component: ConfirmationDialogContent,\n      props: {\n        message: t('subscription.billingComingSoon.message'),\n        type: 'info',\n        onConfirm: () => {}\n      },\n      dialogComponentProps: {\n        size: 'sm'\n      }\n    })\n  }\n\n  async function showCancelSubscriptionDialog(\n    cancelAt?: string,\n    flowAlreadyOpened?: boolean,\n    isScopeCurrent?: () => boolean,\n    flowAlreadyConfirmed?: boolean\n  ) {\n    const { default: component } =\n      await import('@/components/dialog/content/subscription/CancelSubscriptionDialogContent.vue')\n    if (isScopeCurrent && !isScopeCurrent()) return false\n    const guardedProps = {\n      ...(flowAlreadyOpened !== undefined ? { flowAlreadyOpened } : {}),\n      ...(flowAlreadyConfirmed !== undefined ? { flowAlreadyConfirmed } : {}),\n      ...(cancelAt !== undefined ? { cancelAt } : {}),\n      ...(isScopeCurrent ? { isScopeCurrent } : {})\n    }\n    dialogStore.updateDialog({\n      key: 'cancel-subscription',\n      contentProps: guardedProps\n    })\n    return dialogStore.showDialog({\n      key: 'cancel-subscription',\n      component,\n      props: guardedProps,\n      dialogComponentProps: {\n        headless: true\n      }\n    })\n  }\n\n  async function showCancellationFlowDialog(\n    options: CancellationFlowDialogOptions\n  ) {\n    const { default: component } =\n      await import('@/platform/cloud/subscription/components/CancellationFlowDialogContent.vue')\n    if (!options.isScopeCurrent()) return false\n    return dialogStore.showDialog({\n      key: 'cancel-subscription',\n      component,\n      props: { ...options },\n      dialogComponentProps: {\n        headless: true,\n        closable: false,\n        dismissOnPointerDownOutside: false\n      }\n    })\n  }\n\n  async function showCancelSubscriptionFlow(cancelAt?: string) {\n    const launchWorkspaceId = useTeamWorkspaceStore().activeWorkspaceId\n    const cancellationFlow =\n      await import('@/platform/cloud/subscription/launchCancellationFlow')\n    return cancellationFlow.launchCancellationFlow({\n      cancelAt,\n      launchWorkspaceId,\n      showFlow: showCancellationFlowDialog\n    })\n  }\n\n  /**\n   * Downgrade a team plan to a personal plan. Skips the type-\"I understand\"\n   * confirm dialog only when there's nothing to confirm: no other members to\n   * remove and no reactivation charge to disclose. Failures on that fast\n   * path surface as an error toast.\n   */\n  async function showDowngradeToPersonalDialog(options: {\n    planName: string\n    planSlug: string\n    paymentIntentSource?: PaymentIntentSource\n  }): Promise<DowngradeToPersonalResult | null> {\n    const {\n      useDowngradeToPersonal,\n      ReactivationConfirmationRequiredError,\n      ReactivationAmountChangedError\n    } = await import('@/platform/workspace/composables/useDowngradeToPersonal')\n    const {\n      hasOtherMembers,\n      refreshMembers,\n      previewDowngrade,\n      downgradeToPersonal\n    } = useDowngradeToPersonal({\n      paymentIntentSource: options.paymentIntentSource\n    })\n\n    let requiresReactivation = false\n    let chargeCents = 0\n    try {\n      await refreshMembers()\n      const preview = await previewDowngrade(options.planSlug)\n      requiresReactivation = preview.requiresReactivationConfirmation\n      chargeCents = preview.preview.cost_today_cents\n      if (!hasOtherMembers.value && !requiresReactivation) {\n        return await downgradeToPersonal(options.planSlug)\n      }\n    } catch (error) {\n      useToast().error(t('subscription.downgrade.failed'), {\n        description: getErrorMessage(error) ?? t('g.unknownError')\n      })\n      return null\n    }\n\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/DowngradeRemoveMembersDialogContent.vue')\n    const dialogKey = 'downgrade-remove-members'\n    dialogStore.closeDialog({ key: dialogKey })\n    return new Promise((resolve) => {\n      const stopWatching = watch(\n        () => dialogStore.isDialogOpen(dialogKey),\n        (isOpen) => {\n          if (!isOpen) resolveResult(null)\n        },\n        { flush: 'sync' }\n      )\n      function resolveResult(result: DowngradeToPersonalResult | null) {\n        stopWatching()\n        resolve(result)\n      }\n\n      dialogStore.showDialog({\n        key: dialogKey,\n        component,\n        props: {\n          planName: options.planName,\n          planSlug: options.planSlug,\n          requiresRemoval: hasOtherMembers.value,\n          requiresReactivation,\n          chargeCents,\n          onConfirm: async (planSlug: string, confirmReactivation: boolean) => {\n            try {\n              const result = await downgradeToPersonal(\n                planSlug,\n                confirmReactivation,\n                chargeCents\n              )\n              resolveResult(result)\n            } catch (error) {\n              // A fresh preview inside downgradeToPersonal() found the\n              // dialog's captured state (open-time cancellation/charge) is\n              // stale and refused to bill it. Push the corrected values into\n              // the still-open dialog so a retry sends what these errors'\n              // own preview says is actually true, instead of repeating the\n              // same rejected request forever.\n              if (\n                error instanceof ReactivationConfirmationRequiredError ||\n                error instanceof ReactivationAmountChangedError\n              ) {\n                requiresReactivation = true\n                chargeCents = error.preview.cost_today_cents\n                dialogStore.updateDialog({\n                  key: dialogKey,\n                  contentProps: { requiresReactivation, chargeCents }\n                })\n              }\n              throw error\n            }\n          }\n        },\n        dialogComponentProps: {\n          headless: true,\n          closable: false,\n          dismissOnPointerDownOutside: false,\n          onClose: () => resolveResult(null)\n        }\n      })\n    })\n  }\n\n  return {\n    showTopUpCreditsDialog,\n    showSubscriptionRequiredDialog,\n    showBillingComingSoonDialog,\n    showCancelSubscriptionDialog,\n    showCancelSubscriptionFlow,\n    showDowngradeToPersonalDialog\n  }\n}\n","import type { SubscriptionCheckoutType } from '@comfyorg/account-core/billing'\nimport type { SubscriptionDuration } from '@comfyorg/ingest-types'\nimport {\n  getTierPrice,\n  toTierKey\n} from '@/platform/cloud/subscription/constants/tierPricing'\nimport type {\n  IngestSubscriptionTier,\n  TierKey\n} from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { BillingCycle } from '@/platform/cloud/subscription/utils/subscriptionTierRank'\nimport type {\n  BeginCheckoutMetadata,\n  PaymentIntentSource,\n  ResubscribeClickMetadata,\n  SubscriptionSuccessMetadata\n} from '@/platform/telemetry/types'\n\nconst PENDING_SUBSCRIPTION_CHECKOUT_MAX_AGE_MS = 6 * 60 * 60 * 1000\nconst PENDING_SUBSCRIPTION_CHECKOUT_MAX_FUTURE_SKEW_MS = 5 * 60 * 1000\nconst VALID_TIER_KEYS: ReadonlySet<string> = new Set([\n  'free',\n  'standard',\n  'creator',\n  'pro',\n  'founder'\n])\nconst VALID_PAYMENT_INTENT_SOURCES = {\n  subscription_required: true,\n  out_of_credits: true,\n  top_up_blocked: true,\n  deep_link: true,\n  subscribe_to_run: true,\n  subscribe_now_button: true,\n  upgrade_to_add_credits: true,\n  settings_billing_panel: true,\n  avatar_menu_plans: true,\n  team_members_panel: true,\n  invite_member_upsell: true,\n  upload_model_upgrade: true,\n  team_upgrade_resume: true,\n  free_tier_quota: true,\n  agent_paywall: true\n} satisfies Record<PaymentIntentSource, true>\n\nexport const PENDING_SUBSCRIPTION_CHECKOUT_STORAGE_KEY =\n  'comfy.subscription.pending_checkout_attempt'\nexport const PENDING_SUBSCRIPTION_CHECKOUT_EVENT =\n  'comfy:subscription-checkout-attempt-changed'\nconst PENDING_SUBSCRIPTION_CHECKOUT_TERMINAL_STORAGE_KEY =\n  'comfy.subscription.pending_checkout_terminal'\n\nexport type PendingCheckoutTerminal =\n  | 'completion_missing'\n  | 'recovery_unreachable'\n\ninterface PendingCheckoutTerminalClaim {\n  attempt_id: string\n  terminal: PendingCheckoutTerminal\n}\n\ninterface SubscriptionStatusSnapshot {\n  is_active?: boolean\n  subscription_tier?: IngestSubscriptionTier | null\n  subscription_duration?: SubscriptionDuration | null\n  cancel_at?: string | null\n}\n\nexport interface PendingSubscriptionCheckoutAttempt {\n  attempt_id: string\n  started_at_ms: number\n  tier: TierKey\n  cycle: BillingCycle\n  checkout_type: SubscriptionCheckoutType\n  previous_tier?: TierKey\n  previous_cycle?: BillingCycle\n  /** Cancellation marker observed before a resubscribe checkout opened. */\n  previous_cancel_at?: string | null\n  payment_intent_source?: PaymentIntentSource\n  /** Set when this attempt was initiated from the resubscribe flow, not a plain subscribe. */\n  operation?: 'resubscribe'\n  /** Click-time source for a resubscribe attempt; carried through to the terminal event. */\n  resubscribe_source?: ResubscribeClickMetadata['source']\n  /** User and workspace that opened checkout, used to reject another session's attempt. */\n  owner_id?: string\n  workspace_id?: string | null\n  /** Set when this attempt already emitted `billing.subscription_checkout.started`. */\n  start_reported?: true\n}\n\nexport interface PendingSubscriptionCheckoutAttemptInput {\n  tier: TierKey\n  cycle: BillingCycle\n  checkout_type: SubscriptionCheckoutType\n  previous_tier?: TierKey\n  previous_cycle?: BillingCycle\n  previous_cancel_at?: string | null\n  payment_intent_source?: PaymentIntentSource\n  operation?: 'resubscribe'\n  resubscribe_source?: ResubscribeClickMetadata['source']\n  owner_id?: string\n  workspace_id?: string | null\n  start_reported?: true\n}\n\nconst dispatchPendingCheckoutChangeEvent = () => {\n  if (typeof window === 'undefined') {\n    return\n  }\n\n  window.dispatchEvent(new Event(PENDING_SUBSCRIPTION_CHECKOUT_EVENT))\n}\n\nconst createAttemptId = (): string => {\n  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {\n    return crypto.randomUUID()\n  }\n\n  return `attempt-${Date.now()}`\n}\n\ntype CheckoutStorage = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>\n\nconst getStorage = (): CheckoutStorage | null => {\n  let storage: unknown\n\n  try {\n    storage = globalThis.localStorage\n  } catch {\n    return null\n  }\n\n  return isCheckoutStorage(storage) ? storage : null\n}\n\nfunction isCheckoutStorage(value: unknown): value is CheckoutStorage {\n  return (\n    !!value &&\n    typeof value === 'object' &&\n    'getItem' in value &&\n    typeof value.getItem === 'function' &&\n    'setItem' in value &&\n    typeof value.setItem === 'function' &&\n    'removeItem' in value &&\n    typeof value.removeItem === 'function'\n  )\n}\n\nfunction isUnknownRecord(value: unknown): value is Record<string, unknown> {\n  return !!value && typeof value === 'object'\n}\n\nconst getAnnualCheckoutValue = (tier: Exclude<TierKey, 'free' | 'founder'>) =>\n  getTierPrice(tier, true) * 12\n\nconst getCheckoutValue = (tier: TierKey, cycle: BillingCycle): number => {\n  if (tier === 'free' || tier === 'founder') {\n    return getTierPrice(tier, cycle === 'yearly')\n  }\n\n  return cycle === 'yearly'\n    ? getAnnualCheckoutValue(tier)\n    : getTierPrice(tier, false)\n}\n\nconst getTierFromStatus = (\n  status: SubscriptionStatusSnapshot\n): TierKey | null => {\n  const subscriptionTier = status.subscription_tier\n  if (!subscriptionTier) {\n    return null\n  }\n\n  return toTierKey(subscriptionTier)\n}\n\nconst getCycleFromStatus = (\n  status: SubscriptionStatusSnapshot\n): BillingCycle | null => {\n  if (status.subscription_duration === 'ANNUAL') {\n    return 'yearly'\n  }\n\n  if (status.subscription_duration === 'MONTHLY') {\n    return 'monthly'\n  }\n\n  return null\n}\n\nconst isExpired = (attempt: PendingSubscriptionCheckoutAttempt): boolean =>\n  Date.now() - attempt.started_at_ms > PENDING_SUBSCRIPTION_CHECKOUT_MAX_AGE_MS\n\nconst isCheckoutAttemptCore = (\n  value: Record<string, unknown>\n): value is Record<string, unknown> & {\n  attempt_id: string\n  started_at_ms: number\n  tier: TierKey\n  cycle: BillingCycle\n  checkout_type: SubscriptionCheckoutType\n} =>\n  typeof value.attempt_id === 'string' &&\n  typeof value.started_at_ms === 'number' &&\n  Number.isFinite(value.started_at_ms) &&\n  value.started_at_ms <=\n    Date.now() + PENDING_SUBSCRIPTION_CHECKOUT_MAX_FUTURE_SKEW_MS &&\n  isTierKey(value.tier) &&\n  (value.cycle === 'monthly' || value.cycle === 'yearly') &&\n  (value.checkout_type === 'new' || value.checkout_type === 'change')\n\nconst optionalCheckoutAttemptFields = (\n  candidate: Record<string, unknown>\n): Partial<PendingSubscriptionCheckoutAttempt> => ({\n  ...(isTierKey(candidate.previous_tier)\n    ? { previous_tier: candidate.previous_tier }\n    : {}),\n  ...(candidate.previous_cycle === 'monthly' ||\n  candidate.previous_cycle === 'yearly'\n    ? { previous_cycle: candidate.previous_cycle }\n    : {}),\n  ...(typeof candidate.previous_cancel_at === 'string' ||\n  candidate.previous_cancel_at === null\n    ? { previous_cancel_at: candidate.previous_cancel_at }\n    : {}),\n  ...(isPaymentIntentSource(candidate.payment_intent_source)\n    ? { payment_intent_source: candidate.payment_intent_source }\n    : {}),\n  ...(candidate.operation === 'resubscribe'\n    ? { operation: 'resubscribe' }\n    : {}),\n  ...(candidate.resubscribe_source === 'pricing_dialog' ||\n  candidate.resubscribe_source === 'settings_billing_panel'\n    ? { resubscribe_source: candidate.resubscribe_source }\n    : {}),\n  ...(typeof candidate.owner_id === 'string'\n    ? { owner_id: candidate.owner_id }\n    : {}),\n  ...(typeof candidate.workspace_id === 'string' ||\n  candidate.workspace_id === null\n    ? { workspace_id: candidate.workspace_id }\n    : {}),\n  ...(candidate.start_reported === true ? { start_reported: true } : {})\n})\n\nconst normalizeAttempt = (\n  value: unknown\n): PendingSubscriptionCheckoutAttempt | null => {\n  if (!isUnknownRecord(value) || !isCheckoutAttemptCore(value)) return null\n\n  return {\n    attempt_id: value.attempt_id,\n    started_at_ms: Math.min(value.started_at_ms, Date.now()),\n    tier: value.tier,\n    cycle: value.cycle,\n    checkout_type: value.checkout_type,\n    ...optionalCheckoutAttemptFields(value)\n  }\n}\n\nconst isTierKey = (value: unknown): value is TierKey =>\n  typeof value === 'string' && VALID_TIER_KEYS.has(value)\n\nconst isPaymentIntentSource = (value: unknown): value is PaymentIntentSource =>\n  typeof value === 'string' &&\n  Object.hasOwn(VALID_PAYMENT_INTENT_SOURCES, value)\n\nexport const clearPendingSubscriptionCheckoutAttempt = (): void => {\n  const storage = getStorage()\n  if (!storage) {\n    return\n  }\n\n  try {\n    storage.removeItem(PENDING_SUBSCRIPTION_CHECKOUT_STORAGE_KEY)\n    storage.removeItem(PENDING_SUBSCRIPTION_CHECKOUT_TERMINAL_STORAGE_KEY)\n  } catch {\n    return\n  }\n  dispatchPendingCheckoutChangeEvent()\n}\n\nconst persistClampedStartTime = (\n  storage: CheckoutStorage,\n  attempt: PendingSubscriptionCheckoutAttempt\n) => {\n  try {\n    storage.setItem(\n      PENDING_SUBSCRIPTION_CHECKOUT_STORAGE_KEY,\n      JSON.stringify(attempt)\n    )\n  } catch {\n    return\n  }\n}\n\nexport const getPendingSubscriptionCheckoutAttempt =\n  (): PendingSubscriptionCheckoutAttempt | null => {\n    const storage = getStorage()\n    if (!storage) {\n      return null\n    }\n\n    let rawAttempt: string | null\n\n    try {\n      rawAttempt = storage.getItem(PENDING_SUBSCRIPTION_CHECKOUT_STORAGE_KEY)\n    } catch {\n      return null\n    }\n\n    if (!rawAttempt) {\n      return null\n    }\n\n    try {\n      const parsed = JSON.parse(rawAttempt)\n      const attempt = normalizeAttempt(parsed)\n\n      if (!attempt || isExpired(attempt)) {\n        clearPendingSubscriptionCheckoutAttempt()\n        return null\n      }\n\n      if (\n        isUnknownRecord(parsed) &&\n        parsed.started_at_ms !== attempt.started_at_ms\n      ) {\n        persistClampedStartTime(storage, attempt)\n      }\n\n      return attempt\n    } catch {\n      clearPendingSubscriptionCheckoutAttempt()\n      return null\n    }\n  }\n\nconst isPendingCheckoutTerminal = (\n  value: unknown\n): value is PendingCheckoutTerminal =>\n  value === 'completion_missing' || value === 'recovery_unreachable'\n\nconst parsePendingCheckoutTerminalClaim = (\n  rawClaim: string\n): PendingCheckoutTerminalClaim | null => {\n  try {\n    const value: unknown = JSON.parse(rawClaim)\n    if (\n      !isUnknownRecord(value) ||\n      typeof value.attempt_id !== 'string' ||\n      !isPendingCheckoutTerminal(value.terminal)\n    ) {\n      return null\n    }\n    return { attempt_id: value.attempt_id, terminal: value.terminal }\n  } catch {\n    return null\n  }\n}\n\nexport const getPendingCheckoutTerminal = (\n  attemptId: string\n): PendingCheckoutTerminal | null => {\n  try {\n    const rawClaim = getStorage()?.getItem(\n      PENDING_SUBSCRIPTION_CHECKOUT_TERMINAL_STORAGE_KEY\n    )\n    if (!rawClaim) return null\n    const claim = parsePendingCheckoutTerminalClaim(rawClaim)\n    return claim?.attempt_id === attemptId ? claim.terminal : null\n  } catch {\n    return null\n  }\n}\n\nexport const claimPendingCheckoutTerminal = (\n  attemptId: string,\n  terminal: PendingCheckoutTerminal\n): PendingSubscriptionCheckoutAttempt | null => {\n  const attempt = getPendingSubscriptionCheckoutAttempt()\n  if (\n    attempt?.attempt_id !== attemptId ||\n    getPendingCheckoutTerminal(attemptId)\n  ) {\n    return null\n  }\n\n  try {\n    getStorage()?.setItem(\n      PENDING_SUBSCRIPTION_CHECKOUT_TERMINAL_STORAGE_KEY,\n      JSON.stringify({ attempt_id: attemptId, terminal })\n    )\n  } catch {\n    return null\n  }\n\n  return getPendingCheckoutTerminal(attemptId) === terminal ? attempt : null\n}\n\nexport const hasPendingSubscriptionCheckoutAttempt = (): boolean =>\n  getPendingSubscriptionCheckoutAttempt() !== null\n\nexport const createPendingSubscriptionCheckoutAttempt = (\n  input: PendingSubscriptionCheckoutAttemptInput\n): PendingSubscriptionCheckoutAttempt => {\n  return {\n    attempt_id: createAttemptId(),\n    started_at_ms: Date.now(),\n    tier: input.tier,\n    cycle: input.cycle,\n    checkout_type: input.checkout_type,\n    ...(input.previous_tier ? { previous_tier: input.previous_tier } : {}),\n    ...(input.previous_cycle ? { previous_cycle: input.previous_cycle } : {}),\n    ...(input.previous_cancel_at !== undefined\n      ? { previous_cancel_at: input.previous_cancel_at }\n      : {}),\n    ...(input.payment_intent_source\n      ? { payment_intent_source: input.payment_intent_source }\n      : {}),\n    ...(input.operation ? { operation: input.operation } : {}),\n    ...(input.resubscribe_source\n      ? { resubscribe_source: input.resubscribe_source }\n      : {}),\n    ...(input.owner_id ? { owner_id: input.owner_id } : {}),\n    ...(input.workspace_id !== undefined\n      ? { workspace_id: input.workspace_id }\n      : {}),\n    ...(input.start_reported ? { start_reported: true } : {})\n  }\n}\n\nexport const persistPendingSubscriptionCheckoutAttempt = (\n  attempt: PendingSubscriptionCheckoutAttempt\n): PendingSubscriptionCheckoutAttempt => {\n  const storage = getStorage()\n  if (!storage) {\n    return attempt\n  }\n\n  try {\n    storage.setItem(\n      PENDING_SUBSCRIPTION_CHECKOUT_STORAGE_KEY,\n      JSON.stringify(attempt)\n    )\n  } catch {\n    return attempt\n  }\n  dispatchPendingCheckoutChangeEvent()\n\n  return attempt\n}\n\nexport const recordPendingSubscriptionCheckoutAttempt = (\n  input: PendingSubscriptionCheckoutAttemptInput\n): PendingSubscriptionCheckoutAttempt =>\n  persistPendingSubscriptionCheckoutAttempt(\n    createPendingSubscriptionCheckoutAttempt(input)\n  )\n\nexport const withPendingCheckoutAttemptId = (\n  metadata: BeginCheckoutMetadata,\n  attempt: PendingSubscriptionCheckoutAttempt\n): BeginCheckoutMetadata => ({\n  ...metadata,\n  checkout_attempt_id: attempt.attempt_id\n})\n\nconst didAttemptSucceed = (\n  attempt: PendingSubscriptionCheckoutAttempt,\n  status: SubscriptionStatusSnapshot\n): boolean => {\n  if (!status.is_active) {\n    return false\n  }\n\n  if (attempt.operation === 'resubscribe') {\n    return (\n      attempt.previous_cancel_at !== undefined &&\n      (status.cancel_at ?? null) !== attempt.previous_cancel_at &&\n      getTierFromStatus(status) === attempt.tier &&\n      getCycleFromStatus(status) === attempt.cycle\n    )\n  }\n\n  return (\n    getTierFromStatus(status) === attempt.tier &&\n    getCycleFromStatus(status) === attempt.cycle\n  )\n}\n\nexport const consumePendingSubscriptionCheckoutSuccess = (\n  status: SubscriptionStatusSnapshot\n):\n  | (SubscriptionSuccessMetadata &\n      Pick<\n        PendingSubscriptionCheckoutAttempt,\n        'start_reported' | 'started_at_ms'\n      >)\n  | null => {\n  const attempt = getPendingSubscriptionCheckoutAttempt()\n  if (!attempt || !didAttemptSucceed(attempt, status)) {\n    return null\n  }\n\n  const wasReportedTerminal = getPendingCheckoutTerminal(attempt.attempt_id)\n  clearPendingSubscriptionCheckoutAttempt()\n\n  const value = getCheckoutValue(attempt.tier, attempt.cycle)\n\n  return {\n    checkout_attempt_id: attempt.attempt_id,\n    tier: attempt.tier,\n    cycle: attempt.cycle,\n    checkout_type: attempt.checkout_type,\n    ...(attempt.previous_tier ? { previous_tier: attempt.previous_tier } : {}),\n    ...(attempt.payment_intent_source\n      ? { payment_intent_source: attempt.payment_intent_source }\n      : {}),\n    ...(attempt.operation ? { operation: attempt.operation } : {}),\n    ...(attempt.resubscribe_source\n      ? { resubscribe_source: attempt.resubscribe_source }\n      : {}),\n    ...(wasReportedTerminal\n      ? { recovery_outcome: 'late_success' as const }\n      : {}),\n    ...(attempt.start_reported ? { start_reported: true as const } : {}),\n    started_at_ms: attempt.started_at_ms,\n    value,\n    currency: 'USD',\n    ecommerce: {\n      value,\n      currency: 'USD',\n      items: [\n        {\n          item_name: attempt.tier,\n          item_category: 'subscription',\n          item_variant: attempt.cycle,\n          price: value,\n          quantity: 1\n        }\n      ]\n    }\n  }\n}\n","import { getComfyApiBaseUrl } from '@/config/comfyApi'\nimport { t } from '@/i18n'\nimport type { TierKey } from '@/platform/cloud/subscription/constants/tierPricing'\nimport type {\n  PendingSubscriptionCheckoutAttempt,\n  PendingSubscriptionCheckoutAttemptInput\n} from '@/platform/cloud/subscription/utils/subscriptionCheckoutTracker'\nimport {\n  createPendingSubscriptionCheckoutAttempt,\n  persistPendingSubscriptionCheckoutAttempt,\n  withPendingCheckoutAttemptId\n} from '@/platform/cloud/subscription/utils/subscriptionCheckoutTracker'\nimport { webSessionResourceHeader } from '@/platform/auth/session/webSessionFetch'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport type {\n  CheckoutAttributionMetadata,\n  PaymentIntentSource\n} from '@/platform/telemetry/types'\nimport { parseErrorResponse } from '@/platform/remote/comfyui/errors'\nimport {\n  BillingFailureError,\n  PaymentPopupBlockedError,\n  describeBillingFailure\n} from '@/platform/telemetry/utils/billingFailureCategory'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { AuthStoreError, useAuthStore } from '@/stores/authStore'\n\nimport type { BillingCycle } from './subscriptionTierRank'\nimport { loadCheckoutAttributionModule } from './checkoutAttributionLoader'\nimport { openBillingUrl } from '@/platform/workspace/billing/billingTab'\n\ntype CheckoutTier = TierKey | `${TierKey}-yearly`\n\nconst getCheckoutTier = (\n  tierKey: TierKey,\n  billingCycle: BillingCycle\n): CheckoutTier => (billingCycle === 'yearly' ? `${tierKey}-yearly` : tierKey)\n\ntype CheckoutAttributionStage = 'module_load' | 'collect'\n\ntype CheckoutAttributionOutcome =\n  | { ok: true; attribution: CheckoutAttributionMetadata }\n  | { ok: false; error: unknown; stage: CheckoutAttributionStage }\n\nconst getCheckoutAttributionForCloud =\n  async (): Promise<CheckoutAttributionOutcome> => {\n    if (__DISTRIBUTION__ !== 'cloud') {\n      return { ok: true, attribution: {} }\n    }\n\n    let attributionModule\n    try {\n      attributionModule = await loadCheckoutAttributionModule()\n    } catch (error) {\n      return { ok: false, error, stage: 'module_load' }\n    }\n\n    const getCheckoutAttribution = attributionModule.getCheckoutAttribution\n\n    if (typeof getCheckoutAttribution !== 'function') {\n      return {\n        ok: false,\n        error: new TypeError('Checkout attribution module is unavailable'),\n        stage: 'module_load'\n      }\n    }\n\n    try {\n      return {\n        ok: true,\n        attribution: await getCheckoutAttribution()\n      }\n    } catch (error) {\n      return { ok: false, error, stage: 'collect' }\n    }\n  }\n\nasync function getCheckoutAttributionPayload(): Promise<CheckoutAttributionMetadata> {\n  const attribution = await getCheckoutAttributionForCloud()\n  if (attribution.ok) return attribution.attribution\n\n  reportError(attribution.error, {\n    surface: 'billing',\n    errorType: 'cloud_checkout_attribution_fallback',\n    tags: {\n      failure_kind: 'degraded',\n      feature_area: 'billing',\n      operation: 'load',\n      outcome: 'degraded',\n      attribution_stage: attribution.stage\n    },\n    level: 'warning'\n  })\n  return {}\n}\n\nconst checkoutAuthHeader = async (authStore: ReturnType<typeof useAuthStore>) =>\n  (await webSessionResourceHeader()) ??\n  (await authStore.getFirebaseAuthHeader())\n\ninterface PerformSubscriptionCheckoutOptions {\n  paymentIntentSource?: PaymentIntentSource\n}\n\n/**\n * Core subscription checkout logic shared between PricingTable and\n * SubscriptionRedirectView. Handles:\n * - Ensuring the user is authenticated\n * - Calling the backend checkout endpoint\n * - Normalizing error responses\n * - Opening the checkout URL in a new tab when available\n * - Reporting checkout-initiation failures via `trackBillingEvent`\n *\n * Callers are responsible for:\n * - Guarding on cloud-only behavior (isCloud)\n * - Managing loading state\n * - Wrapping with error handling (e.g. useErrorHandling)\n */\nexport async function performSubscriptionCheckout(\n  tierKey: TierKey,\n  currentBillingCycle: BillingCycle,\n  options: PerformSubscriptionCheckoutOptions = {}\n): Promise<void> {\n  if (!isCloud) return\n\n  await runReportedCheckoutAttempt(\n    {\n      tier: tierKey,\n      cycle: currentBillingCycle,\n      checkout_type: 'new',\n      payment_intent_source: options.paymentIntentSource,\n      owner_id: useAuthStore().userId ?? undefined,\n      workspace_id: useTeamWorkspaceStore().activeWorkspaceId\n    },\n    (pendingAttempt) =>\n      initiateSubscriptionCheckout(pendingAttempt, options.paymentIntentSource)\n  )\n}\n\nexport const missingCheckoutUrlError = () =>\n  new BillingFailureError(\n    t('toastMessages.failedToInitiateSubscription', {\n      error: 'No checkout URL returned'\n    }),\n    { failure_category: 'unknown', error_code: 'missing_checkout_response' }\n  )\n\nexport type ReportedCheckoutAttemptInput = Omit<\n  PendingSubscriptionCheckoutAttemptInput,\n  'start_reported'\n>\n\n/**\n * Reports `started` for one legacy checkout attempt and `failed` when `launch`\n * rejects. Its success is reported later by the pending-checkout recovery,\n * which closes only attempts marked `start_reported`.\n */\nexport async function runReportedCheckoutAttempt(\n  input: ReportedCheckoutAttemptInput,\n  launch: (attempt: PendingSubscriptionCheckoutAttempt) => Promise<void>\n): Promise<void> {\n  const telemetry = useTelemetry()\n  const attempt = createPendingSubscriptionCheckoutAttempt({\n    ...input,\n    start_reported: true\n  })\n  const attemptEvent = {\n    operation: 'subscription_checkout',\n    checkout_attempt_id: attempt.attempt_id,\n    tier: attempt.tier,\n    cycle: attempt.cycle,\n    checkout_type: attempt.checkout_type,\n    payment_intent_source: attempt.payment_intent_source\n  } as const\n  telemetry?.trackBillingEvent({\n    ...attemptEvent,\n    stage: 'started',\n    outcome: 'pending'\n  })\n\n  try {\n    await launch(attempt)\n  } catch (error) {\n    telemetry?.trackBillingEvent({\n      ...attemptEvent,\n      stage: 'failed',\n      outcome: 'failure',\n      ...describeBillingFailure(error),\n      duration_ms: Date.now() - attempt.started_at_ms\n    })\n    throw error\n  }\n}\n\nasync function initiateSubscriptionCheckout(\n  pendingAttempt: PendingSubscriptionCheckoutAttempt,\n  paymentIntentSource: PaymentIntentSource | undefined\n): Promise<void> {\n  const { tier: tierKey, cycle: currentBillingCycle } = pendingAttempt\n\n  const authStore = useAuthStore()\n  const telemetry = useTelemetry()\n  const authHeader = await checkoutAuthHeader(authStore)\n\n  if (!authHeader) {\n    throw new AuthStoreError(t('toastMessages.userNotAuthenticated'))\n  }\n\n  const checkoutTier = getCheckoutTier(tierKey, currentBillingCycle)\n  const checkoutAttribution = await getCheckoutAttributionPayload()\n  const checkoutPayload = { ...checkoutAttribution }\n\n  const response = await authStore.fetchWithCustomerRecovery(\n    `${getComfyApiBaseUrl()}/customers/cloud-subscription-checkout/${checkoutTier}`,\n    {\n      method: 'POST',\n      headers: { ...authHeader, 'Content-Type': 'application/json' },\n      body: JSON.stringify(checkoutPayload)\n    }\n  )\n\n  if (!response.ok) {\n    const { message } = await parseErrorResponse(response)\n\n    throw new AuthStoreError(\n      t('toastMessages.failedToInitiateSubscription', {\n        error: message\n      }),\n      response.status\n    )\n  }\n\n  const data = await response.json()\n\n  completeSubscriptionCheckout(data.checkout_url, {\n    tierKey,\n    currentBillingCycle,\n    paymentIntentSource,\n    pendingAttempt,\n    checkoutAttribution,\n    telemetry\n  })\n}\n\ninterface CheckoutCompletionContext {\n  tierKey: TierKey\n  currentBillingCycle: BillingCycle\n  paymentIntentSource?: PaymentIntentSource\n  pendingAttempt: PendingSubscriptionCheckoutAttempt\n  checkoutAttribution: CheckoutAttributionMetadata\n  telemetry: ReturnType<typeof useTelemetry>\n}\n\nfunction trackBeginCheckout(context: CheckoutCompletionContext) {\n  const { pendingAttempt, paymentIntentSource } = context\n  const userId = pendingAttempt.owner_id\n  if (!userId) return\n\n  context.telemetry?.trackBeginCheckout(\n    withPendingCheckoutAttemptId(\n      {\n        user_id: userId,\n        tier: context.tierKey,\n        cycle: context.currentBillingCycle,\n        checkout_type: 'new',\n        ...(paymentIntentSource\n          ? { payment_intent_source: paymentIntentSource }\n          : {}),\n        ...context.checkoutAttribution\n      },\n      pendingAttempt\n    )\n  )\n}\n\nfunction completeSubscriptionCheckout(\n  checkoutUrl: string | undefined,\n  context: CheckoutCompletionContext\n) {\n  if (!checkoutUrl) throw missingCheckoutUrlError()\n\n  trackBeginCheckout(context)\n\n  if (!openBillingUrl(checkoutUrl)) {\n    throw new PaymentPopupBlockedError(\n      t('subscription.preview.paymentPopupBlocked')\n    )\n  }\n  persistPendingSubscriptionCheckoutAttempt(context.pendingAttempt)\n}\n","import { onScopeDispose, ref } from 'vue'\nimport type { ComputedRef, Ref } from 'vue'\nimport { defaultWindow, useEventListener, useTimeoutFn } from '@vueuse/core'\n\nimport type { TelemetryDispatcher } from '@/platform/telemetry/types'\nimport type { BillingStatusResponse } from '@/platform/workspace/api/workspaceApi'\n\nconst MAX_CANCELLATION_ATTEMPTS = 4\nconst CANCELLATION_BASE_DELAY_MS = 5000\nconst CANCELLATION_BACKOFF_MULTIPLIER = 3 // 5s, 15s, 45s, 135s intervals\n\ntype CancellationWatcherOptions = {\n  fetchStatus: () => Promise<BillingStatusResponse | null | void>\n  canAccessSubscriptionFeatures: ComputedRef<boolean>\n  subscriptionStatus: Ref<BillingStatusResponse | null>\n  telemetry: Pick<\n    TelemetryDispatcher,\n    'trackMonthlySubscriptionCancelled'\n  > | null\n  shouldWatchCancellation: () => boolean\n}\n\nexport function useSubscriptionCancellationWatcher({\n  fetchStatus,\n  canAccessSubscriptionFeatures,\n  subscriptionStatus,\n  telemetry,\n  shouldWatchCancellation\n}: CancellationWatcherOptions) {\n  const watcherActive = ref(false)\n  const cancellationAttempts = ref(0)\n  const cancellationTracked = ref(false)\n  const cancellationCheckInFlight = ref(false)\n  const nextDelay = ref(CANCELLATION_BASE_DELAY_MS)\n  let detachFocusListener: (() => void) | null = null\n\n  const { start: startTimer, stop: stopTimer } = useTimeoutFn(\n    () => {\n      void checkForCancellation()\n    },\n    nextDelay,\n    { immediate: false }\n  )\n\n  const stopCancellationWatcher = () => {\n    watcherActive.value = false\n    stopTimer()\n    cancellationAttempts.value = 0\n    cancellationCheckInFlight.value = false\n    if (detachFocusListener) {\n      detachFocusListener()\n      detachFocusListener = null\n    }\n  }\n\n  const scheduleNextCancellationCheck = () => {\n    if (!watcherActive.value) return\n\n    if (cancellationAttempts.value >= MAX_CANCELLATION_ATTEMPTS) {\n      stopCancellationWatcher()\n      return\n    }\n\n    nextDelay.value =\n      CANCELLATION_BASE_DELAY_MS *\n      CANCELLATION_BACKOFF_MULTIPLIER ** cancellationAttempts.value\n    cancellationAttempts.value += 1\n    startTimer()\n  }\n\n  const checkForCancellation = async (triggeredFromFocus = false) => {\n    if (!watcherActive.value || cancellationCheckInFlight.value) return\n\n    cancellationCheckInFlight.value = true\n    try {\n      await fetchStatus()\n\n      if (!canAccessSubscriptionFeatures.value) {\n        if (!cancellationTracked.value) {\n          cancellationTracked.value = true\n          try {\n            telemetry?.trackMonthlySubscriptionCancelled()\n          } catch (telemetryError) {\n            console.error(\n              '[Subscription] Failed to track cancellation telemetry:',\n              telemetryError\n            )\n          }\n        }\n        stopCancellationWatcher()\n        return\n      }\n\n      if (!triggeredFromFocus) {\n        scheduleNextCancellationCheck()\n      }\n    } catch (error) {\n      console.error('[Subscription] Error checking cancellation status:', error)\n      scheduleNextCancellationCheck()\n    } finally {\n      cancellationCheckInFlight.value = false\n    }\n  }\n\n  const startCancellationWatcher = () => {\n    if (!shouldWatchCancellation() || !subscriptionStatus.value?.is_active) {\n      return\n    }\n\n    stopCancellationWatcher()\n    watcherActive.value = true\n    cancellationTracked.value = false\n    cancellationAttempts.value = 0\n    if (!detachFocusListener && defaultWindow) {\n      detachFocusListener = useEventListener(defaultWindow, 'focus', () => {\n        if (!watcherActive.value) return\n        void checkForCancellation(true)\n      })\n    }\n    scheduleNextCancellationCheck()\n  }\n\n  onScopeDispose(() => {\n    stopCancellationWatcher()\n  })\n\n  return {\n    startCancellationWatcher,\n    stopCancellationWatcher\n  }\n}\n","import { computed, onScopeDispose, ref, watch } from 'vue'\nimport {\n  createSharedComposable,\n  defaultDocument,\n  defaultWindow,\n  useEventListener\n} from '@vueuse/core'\n\nimport type { BillingPortalTarget } from '@comfyorg/account-core/billing'\n\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useAuthActions } from '@/composables/auth/useAuthActions'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { getComfyApiBaseUrl } from '@/config/comfyApi'\nimport { t } from '@/i18n'\nimport { webSessionResourceHeader } from '@/platform/auth/session/webSessionFetch'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError as reportTelemetryError } from '@/platform/telemetry/reportError'\nimport { createBillingPortalReporter } from '@/platform/telemetry/utils/billingPortalTelemetry'\nimport type { SubscriptionDialogOptions } from '@/composables/billing/types'\nimport type {\n  CheckoutAttributionMetadata,\n  ResubscribeClickMetadata,\n  SubscriptionSuccessMetadata\n} from '@/platform/telemetry/types'\nimport type { BillingStatusResponse } from '@/platform/workspace/api/workspaceApi'\nimport {\n  WorkspaceApiError,\n  workspaceApi\n} from '@/platform/workspace/api/workspaceApi'\nimport { readOnRail } from '@/platform/workspace/composables/readOnRail'\nimport { useBillingReadRail } from '@/platform/workspace/composables/useBillingReadRail'\nimport {\n  PaymentPopupBlockedError,\n  categorizeBillingApiError\n} from '@/platform/telemetry/utils/billingFailureCategory'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { platformLink } from '@/platform/workspace/utils/platformLink'\nimport { AuthStoreError, useAuthStore } from '@/stores/authStore'\nimport { useBillingDialogs } from '@/composables/billing/useBillingDialogs'\nimport { toTierKey } from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { BillingCycle } from '@/platform/cloud/subscription/utils/subscriptionTierRank'\nimport type { operations } from '@/types/comfyRegistryTypes'\nimport { parseErrorResponse } from '@/platform/remote/comfyui/errors'\nimport {\n  PENDING_SUBSCRIPTION_CHECKOUT_EVENT,\n  PENDING_SUBSCRIPTION_CHECKOUT_STORAGE_KEY,\n  clearPendingSubscriptionCheckoutAttempt,\n  consumePendingSubscriptionCheckoutSuccess,\n  getPendingSubscriptionCheckoutAttempt,\n  claimPendingCheckoutTerminal,\n  getPendingCheckoutTerminal,\n  hasPendingSubscriptionCheckoutAttempt,\n  persistPendingSubscriptionCheckoutAttempt\n} from '@/platform/cloud/subscription/utils/subscriptionCheckoutTracker'\nimport type { ReportedCheckoutAttemptInput } from '@/platform/cloud/subscription/utils/subscriptionCheckoutUtil'\nimport {\n  missingCheckoutUrlError,\n  runReportedCheckoutAttempt\n} from '@/platform/cloud/subscription/utils/subscriptionCheckoutUtil'\nimport { useSubscriptionCancellationWatcher } from './useSubscriptionCancellationWatcher'\nimport { openBillingUrl } from '@/platform/workspace/billing/billingTab'\n\ntype CloudSubscriptionCheckoutResponse = NonNullable<\n  operations['createCloudSubscriptionCheckout']['responses']['201']['content']['application/json']\n>\n\nconst PENDING_SUBSCRIPTION_CHECKOUT_RETRY_DELAYS_MS = [3000, 10000, 30000]\n\nconst PENDING_CHECKOUT_COMPLETION_DEADLINE_MS = 10 * 60 * 1000\nconst PENDING_CHECKOUT_DEADLINE_REFRESH_TIMEOUT_MS = 10_000\nconst PENDING_CHECKOUT_DEADLINE_RETRY_DELAYS_MS = [\n  1000,\n  5000,\n  30000,\n  2 * 60 * 1000,\n  5 * 60 * 1000,\n  10 * 60 * 1000\n] as const\n\ntype CheckoutScopeOwnership = 'unresolved' | 'matched' | 'mismatched'\n\nfunction compareCheckoutScopeStamp(\n  stampedId: string | null | undefined,\n  currentId: string | null | undefined\n): CheckoutScopeOwnership {\n  if (typeof stampedId !== 'string') return 'matched'\n  if (!currentId) return 'unresolved'\n  return stampedId === currentId ? 'matched' : 'mismatched'\n}\n\nasync function withTimeout<T>(promise: Promise<T>, timeoutMs: number) {\n  let timeoutId: ReturnType<typeof setTimeout> | undefined\n  try {\n    return await Promise.race([\n      promise,\n      new Promise<never>((_, reject) => {\n        timeoutId = setTimeout(\n          () => reject(new Error('Billing status deadline refresh timed out')),\n          timeoutMs\n        )\n      })\n    ])\n  } finally {\n    clearTimeout(timeoutId)\n  }\n}\n\nfunction useSubscriptionInternal() {\n  const subscriptionStatus = ref<BillingStatusResponse | null>(null)\n  const telemetry = useTelemetry()\n  const isInitialized = ref(false)\n\n  const canAccessSubscriptionFeatures = computed(() => {\n    if (!isCloud || !window.__CONFIG__?.subscription_required) return true\n\n    return subscriptionStatus.value?.is_active ?? false\n  })\n  const { reportError, accessBillingPortalDirect } = useAuthActions()\n  const { showSubscriptionRequiredDialog } = useBillingDialogs()\n\n  const authStore = useAuthStore()\n  const workspaceStore = useTeamWorkspaceStore()\n  const { getFirebaseAuthHeader, fetchWithCustomerRecovery } = authStore\n  const { wrapWithErrorHandlingAsync } = useErrorHandling()\n\n  const { isLoggedIn } = useCurrentUser()\n\n  // Web-session billing reads need the workspace the gate selects after sign-in.\n  const awaitingSessionWorkspace = computed(\n    () => !!authStore.sessionUser && !workspaceStore.activeWorkspaceId\n  )\n\n  const isCancelled = computed(() => {\n    return !!subscriptionStatus.value?.cancel_at\n  })\n\n  const formattedRenewalDate = computed(() => {\n    if (!subscriptionStatus.value?.renewal_date) return ''\n\n    const renewalDate = new Date(subscriptionStatus.value.renewal_date)\n\n    return renewalDate.toLocaleDateString('en-US', {\n      month: 'short',\n      day: 'numeric',\n      year: 'numeric'\n    })\n  })\n\n  const formattedEndDate = computed(() => {\n    if (!subscriptionStatus.value?.cancel_at) return ''\n\n    const endDate = new Date(subscriptionStatus.value.cancel_at)\n\n    return endDate.toLocaleDateString('en-US', {\n      month: 'short',\n      day: 'numeric',\n      year: 'numeric'\n    })\n  })\n\n  const subscriptionTier = computed(\n    () => subscriptionStatus.value?.subscription_tier ?? null\n  )\n\n  const isFreeTier = computed(() => subscriptionTier.value === 'FREE')\n\n  const subscriptionDuration = computed(\n    () => subscriptionStatus.value?.subscription_duration ?? null\n  )\n\n  const isYearlySubscription = computed(\n    () => subscriptionDuration.value === 'ANNUAL'\n  )\n\n  const subscriptionTierName = computed(() => {\n    const tier = subscriptionTier.value\n    if (!tier) return ''\n    // TEAM and ENTERPRISE map to no catalog key (see toTierKey); reuse their\n    // existing copy instead of mislabeling them as Standard.\n    if (tier === 'TEAM') return t('subscription.teamPlanName')\n    if (tier === 'ENTERPRISE') return t('subscription.tiers.enterprise.name')\n    const key = toTierKey(tier)\n    const baseName = key\n      ? t(`subscription.tiers.${key}.name`)\n      : t('subscription.unknownTierName')\n    return isYearlySubscription.value\n      ? t('subscription.tierNameYearly', { name: baseName })\n      : baseName\n  })\n\n  function buildApiUrl(path: string): string {\n    return `${getComfyApiBaseUrl()}${path}`\n  }\n\n  const getCheckoutAttributionForCloud =\n    async (): Promise<CheckoutAttributionMetadata> => {\n      if (__DISTRIBUTION__ !== 'cloud') {\n        return {}\n      }\n\n      const { getCheckoutAttribution } =\n        await import('@/platform/telemetry/utils/checkoutAttribution')\n\n      return getCheckoutAttribution()\n    }\n\n  interface PendingCheckoutSchedule {\n    timeoutId: number | null\n    retryRung: number\n    deadlineRung: number\n  }\n\n  const IDLE_PENDING_CHECKOUT_SCHEDULE: PendingCheckoutSchedule = {\n    timeoutId: null,\n    retryRung: 0,\n    deadlineRung: 0\n  }\n\n  let pendingCheckoutSchedule = IDLE_PENDING_CHECKOUT_SCHEDULE\n  let activePendingCheckoutRead: {\n    attemptId: string\n    promise: Promise<BillingStatusResponse | null>\n  } | null = null\n  let lastPendingCheckoutStatus: BillingStatusResponse | null = null\n  let isDisposed = false\n\n  const stopPendingCheckoutRecovery = () => {\n    if (pendingCheckoutSchedule.timeoutId !== null && defaultWindow) {\n      defaultWindow.clearTimeout(pendingCheckoutSchedule.timeoutId)\n    }\n    pendingCheckoutSchedule = IDLE_PENDING_CHECKOUT_SCHEDULE\n  }\n\n  const armPendingCheckoutTimer = (delayMs: number, onFire: () => void) => {\n    if (!defaultWindow) return\n    const timeoutId = defaultWindow.setTimeout(() => {\n      pendingCheckoutSchedule = { ...pendingCheckoutSchedule, timeoutId: null }\n      onFire()\n    }, delayMs)\n    pendingCheckoutSchedule = { ...pendingCheckoutSchedule, timeoutId }\n  }\n\n  onScopeDispose(() => {\n    isDisposed = true\n    stopPendingCheckoutRecovery()\n  })\n\n  /**\n   * The retry ladder is exhausted by the time the deadline matters, so without\n   * this the report would wait on the next `pageshow`/`visibilitychange` and\n   * never fire for a user who simply leaves the tab open.\n   */\n  const armMissingCheckoutCompletionWakeUp = (remainingMs: number) => {\n    if (isDisposed || pendingCheckoutSchedule.timeoutId !== null) return\n\n    armPendingCheckoutTimer(Math.max(remainingMs, 0), () => {\n      void recoverPendingSubscriptionCheckout('deadline')\n    })\n  }\n\n  const getCurrentPendingCheckoutAttempt = (attemptId: string) => {\n    const attempt = getPendingSubscriptionCheckoutAttempt()\n    return attempt?.attempt_id === attemptId ? attempt : null\n  }\n\n  const getReportableMissingCheckout = (attemptId: string) => {\n    const attempt = getCurrentPendingCheckoutAttempt(attemptId)\n    if (!attempt || getPendingCheckoutTerminal(attempt.attempt_id)) {\n      return null\n    }\n\n    const attemptAgeMs = Date.now() - attempt.started_at_ms\n    if (attemptAgeMs < PENDING_CHECKOUT_COMPLETION_DEADLINE_MS) {\n      armMissingCheckoutCompletionWakeUp(\n        PENDING_CHECKOUT_COMPLETION_DEADLINE_MS - attemptAgeMs\n      )\n      return null\n    }\n\n    // Any authoritative snapshot that did not consume the attempt proves its\n    // target tier and cycle were not observed, including plan-change checkouts\n    // whose previous subscription remains active.\n    if (lastPendingCheckoutStatus === null) return null\n\n    return { attempt, attemptAgeMs }\n  }\n\n  const reportMissingCheckoutCompletion = (attemptId: string): boolean => {\n    const reportable = getReportableMissingCheckout(attemptId)\n    if (!reportable) return false\n    const { attemptAgeMs } = reportable\n    const attempt = claimPendingCheckoutTerminal(\n      attemptId,\n      'completion_missing'\n    )\n    if (!attempt) return false\n\n    reportTelemetryError(\n      new Error('Pending subscription checkout recovery timed out'),\n      {\n        errorType: 'failure_completing_cloud_checkout',\n        surface: 'billing',\n        context: {\n          checkout_attempt_id: attempt.attempt_id,\n          checkout_type: attempt.checkout_type,\n          attempt_age_ms: attemptAgeMs,\n          tier: attempt.tier,\n          cycle: attempt.cycle,\n          ...(attempt.operation\n            ? { checkout_operation: attempt.operation }\n            : {})\n        },\n        level: 'warning'\n      }\n    )\n    telemetry?.trackBillingEvent({\n      operation: 'subscription_checkout',\n      stage: 'timeout',\n      outcome: 'failure',\n      checkout_attempt_id: attempt.attempt_id,\n      failure_category: 'poll_timeout',\n      tier: attempt.tier,\n      cycle: attempt.cycle,\n      checkout_type: attempt.checkout_type,\n      duration_ms: attemptAgeMs\n    })\n    if (attempt.operation === 'resubscribe') {\n      telemetry?.trackBillingEvent({\n        operation: 'resubscribe',\n        stage: 'failed',\n        outcome: 'failure',\n        source: attempt.resubscribe_source ?? 'settings_billing_panel',\n        checkout_attempt_id: attempt.attempt_id,\n        failure_category: 'poll_timeout',\n        ...(attempt.payment_intent_source\n          ? { payment_intent_source: attempt.payment_intent_source }\n          : {})\n      })\n    }\n    return true\n  }\n\n  const canSchedulePendingCheckoutRecovery = (\n    attempt: ReturnType<typeof getPendingSubscriptionCheckoutAttempt>\n  ) =>\n    !(\n      isDisposed ||\n      !defaultWindow ||\n      pendingCheckoutSchedule.timeoutId !== null ||\n      !isLoggedIn.value ||\n      !attempt\n    )\n\n  const schedulePendingCheckoutRecovery = () => {\n    const attempt = getPendingSubscriptionCheckoutAttempt()\n    if (!canSchedulePendingCheckoutRecovery(attempt) || !attempt) return\n\n    const nextDelay = getPendingCheckoutRetryDelay(\n      pendingCheckoutSchedule.retryRung\n    )\n\n    if (nextDelay === undefined) {\n      const isPastDeadline =\n        Date.now() - attempt.started_at_ms >=\n        PENDING_CHECKOUT_COMPLETION_DEADLINE_MS\n      if (\n        !reportMissingCheckoutCompletion(attempt.attempt_id) &&\n        isPastDeadline\n      ) {\n        rearmBoundedDeadlineWakeUp()\n      }\n      return\n    }\n\n    armPendingCheckoutTimer(nextDelay, () => {\n      pendingCheckoutSchedule = {\n        ...pendingCheckoutSchedule,\n        retryRung: pendingCheckoutSchedule.retryRung + 1\n      }\n      void recoverPendingSubscriptionCheckout('retry')\n    })\n  }\n\n  const getPendingAttemptOwnership = (): CheckoutScopeOwnership => {\n    const attempt = getPendingSubscriptionCheckoutAttempt()\n    if (!attempt) return 'matched'\n    const owner = compareCheckoutScopeStamp(attempt.owner_id, authStore.userId)\n    const workspace = compareCheckoutScopeStamp(\n      attempt.workspace_id,\n      workspaceStore.activeWorkspaceId\n    )\n    if (owner === 'mismatched' || workspace === 'mismatched')\n      return 'mismatched'\n    if (owner === 'unresolved' || workspace === 'unresolved')\n      return 'unresolved'\n    return 'matched'\n  }\n\n  const trackSubscriptionCheckoutSuccess = (\n    metadata: SubscriptionSuccessMetadata,\n    startReported: boolean,\n    startedAtMs: number\n  ) => {\n    if (!startReported && metadata.recovery_outcome !== 'late_success') return\n    telemetry?.trackBillingEvent({\n      operation: 'subscription_checkout',\n      stage: 'succeeded',\n      outcome: 'success',\n      checkout_attempt_id: metadata.checkout_attempt_id,\n      tier: metadata.tier,\n      cycle: metadata.cycle,\n      checkout_type: metadata.checkout_type,\n      payment_intent_source: metadata.payment_intent_source,\n      recovery_outcome: metadata.recovery_outcome,\n      duration_ms: Date.now() - startedAtMs\n    })\n  }\n\n  const trackResubscribeSuccess = (metadata: SubscriptionSuccessMetadata) => {\n    if (metadata.operation !== 'resubscribe') return\n    telemetry?.trackBillingEvent({\n      operation: 'resubscribe',\n      stage: 'succeeded',\n      outcome: 'success',\n      source: metadata.resubscribe_source ?? 'settings_billing_panel',\n      checkout_attempt_id: metadata.checkout_attempt_id,\n      payment_intent_source: metadata.payment_intent_source,\n      recovery_outcome: metadata.recovery_outcome\n    })\n  }\n\n  const syncPendingSubscriptionSuccess = (\n    statusData: BillingStatusResponse\n  ) => {\n    const ownership = getPendingAttemptOwnership()\n    if (ownership === 'mismatched') {\n      stopPendingCheckoutRecovery()\n      return\n    }\n    if (ownership === 'unresolved') return\n    const consumed = consumePendingSubscriptionCheckoutSuccess(statusData)\n\n    if (!consumed) {\n      if (hasPendingSubscriptionCheckoutAttempt()) {\n        schedulePendingCheckoutRecovery()\n      } else {\n        stopPendingCheckoutRecovery()\n      }\n      return\n    }\n\n    const {\n      start_reported: startReported,\n      started_at_ms: startedAtMs,\n      ...metadata\n    } = consumed\n\n    telemetry?.trackMonthlySubscriptionSucceeded({\n      ...(authStore.userId ? { user_id: authStore.userId } : {}),\n      ...metadata\n    })\n\n    trackSubscriptionCheckoutSuccess(\n      metadata,\n      startReported === true,\n      startedAtMs\n    )\n\n    // The recovery flow is shared with plain (non-resubscribe) legacy subscribes,\n    // which all funnel through the same subscribeDirect(). Only emit the canonical\n    // resubscribe terminal when the attempt that just resolved was itself tagged\n    // as a resubscribe at click time — otherwise a plain new subscribe would be\n    // mislabeled as a resubscribe success. Without this, the legacy rail's\n    // `billing.resubscribe.started` (emitted at checkout-tab-open) never gets a\n    // matching terminal, so resubscribe conversion permanently reads ~0%.\n    trackResubscribeSuccess(metadata)\n\n    stopPendingCheckoutRecovery()\n  }\n\n  const buildAuthHeaders = async (): Promise<Record<string, string>> => {\n    const authHeader =\n      (await webSessionResourceHeader()) ?? (await getFirebaseAuthHeader())\n    if (!authHeader) {\n      throw new AuthStoreError(t('toastMessages.userNotAuthenticated'))\n    }\n\n    return {\n      ...authHeader,\n      'Content-Type': 'application/json'\n    }\n  }\n\n  const fetchStatus = wrapWithErrorHandlingAsync(\n    fetchSubscriptionStatus,\n    reportError\n  )\n\n  interface SubscribeDirectOptions {\n    /** Set when this call originates from the resubscribe flow, not a plain subscribe. */\n    operation?: 'resubscribe'\n    /** Click-time source for a resubscribe attempt; carried through to the terminal event. */\n    source?: ResubscribeClickMetadata['source']\n  }\n\n  const getPreviousCycle = (): BillingCycle | undefined => {\n    if (subscriptionDuration.value === 'ANNUAL') return 'yearly'\n    if (subscriptionDuration.value === 'MONTHLY') return 'monthly'\n  }\n\n  const resubscribeAttemptDetails = (\n    options: SubscribeDirectOptions | undefined\n  ) => {\n    if (options?.operation !== 'resubscribe') return {}\n    const previousCancelAt = subscriptionStatus.value\n      ? (subscriptionStatus.value.cancel_at ?? null)\n      : undefined\n\n    return {\n      operation: options.operation,\n      resubscribe_source: options.source,\n      ...(previousCancelAt !== undefined\n        ? { previous_cancel_at: previousCancelAt }\n        : {})\n    }\n  }\n\n  const standardCheckoutAttemptInput = (\n    options: SubscribeDirectOptions | undefined\n  ): ReportedCheckoutAttemptInput => {\n    const previousTier = subscriptionTier.value\n      ? toTierKey(subscriptionTier.value)\n      : null\n\n    return {\n      tier: 'standard',\n      cycle: 'monthly',\n      checkout_type: canAccessSubscriptionFeatures.value ? 'change' : 'new',\n      previous_tier: previousTier ?? undefined,\n      previous_cycle: getPreviousCycle(),\n      ...resubscribeAttemptDetails(options),\n      owner_id: authStore.userId ?? undefined,\n      workspace_id: workspaceStore.activeWorkspaceId\n    }\n  }\n\n  /** Unwrapped `subscribe`, for callers that need rejections to propagate (e.g. telemetry). */\n  const subscribeDirect = (options?: SubscribeDirectOptions): Promise<void> =>\n    runReportedCheckoutAttempt(\n      standardCheckoutAttemptInput(options),\n      async (attempt) => {\n        const response = await initiateSubscriptionCheckout()\n\n        if (!response.checkout_url) throw missingCheckoutUrlError()\n\n        if (!openBillingUrl(response.checkout_url)) {\n          throw new PaymentPopupBlockedError(\n            t('subscription.preview.paymentPopupBlocked')\n          )\n        }\n\n        persistPendingSubscriptionCheckoutAttempt(attempt)\n      }\n    )\n\n  const subscribe = wrapWithErrorHandlingAsync(subscribeDirect, reportError)\n\n  const showSubscriptionDialog = (options?: SubscriptionDialogOptions) => {\n    void showSubscriptionRequiredDialog(options)\n  }\n\n  /**\n   * Whether cloud subscription mode is enabled (cloud distribution with subscription_required config).\n   */\n  const isSubscriptionEnabled = (): boolean =>\n    Boolean(isCloud && window.__CONFIG__?.subscription_required)\n\n  const { startCancellationWatcher, stopCancellationWatcher } =\n    useSubscriptionCancellationWatcher({\n      fetchStatus,\n      canAccessSubscriptionFeatures: canAccessSubscriptionFeatures,\n      subscriptionStatus,\n      telemetry,\n      shouldWatchCancellation: isSubscriptionEnabled\n    })\n\n  const openBillingPortal = async (\n    target: BillingPortalTarget,\n    options?: { cancelSubscription?: boolean }\n  ) => {\n    const portal = createBillingPortalReporter(telemetry, target)\n    let opened: boolean\n    try {\n      opened = await accessBillingPortalDirect(undefined, options)\n    } catch (error) {\n      portal.failed(error, 'legacy')\n      throw error\n    }\n    if (opened) portal.opened('legacy')\n    else portal.blocked('legacy')\n    return opened\n  }\n\n  const manageSubscription = async (options?: {\n    cancelSubscription?: boolean\n  }) => {\n    if (!(await openBillingPortal('manage_subscription', options))) {\n      throw new PaymentPopupBlockedError(t('subscription.billingTabBlocked'))\n    }\n    startCancellationWatcher()\n  }\n\n  const requireActiveSubscription = async (): Promise<void> => {\n    await fetchSubscriptionStatus()\n\n    if (!canAccessSubscriptionFeatures.value) {\n      showSubscriptionDialog({ reason: 'subscription_required' })\n    }\n  }\n\n  const handleViewUsageHistory = () => {\n    window.open(platformLink('/profile/usage'), '_blank')\n  }\n\n  const handleLearnMore = () => {\n    window.open('https://docs.comfy.org', '_blank')\n  }\n\n  const handleInvoiceHistory = wrapWithErrorHandlingAsync(async () => {\n    await openBillingPortal('invoices')\n  }, reportError)\n\n  type PendingCheckoutRecoverySource =\n    | 'bootstrap'\n    | 'pageshow'\n    | 'visibilitychange'\n    | 'retry'\n    | 'deadline'\n\n  const canRecoverPendingCheckout = () =>\n    isCloud &&\n    isLoggedIn.value &&\n    !awaitingSessionWorkspace.value &&\n    hasOwnedPendingCheckoutAttempt()\n\n  const hasOwnedPendingCheckoutAttempt = () => {\n    const attempt = getPendingSubscriptionCheckoutAttempt()\n    if (!attempt) return false\n    return getPendingAttemptOwnership() === 'matched'\n  }\n\n  const handlePendingCheckoutRecoveryError = (\n    source: PendingCheckoutRecoverySource,\n    attemptId: string,\n    error: unknown\n  ) => {\n    console.error(\n      `[Subscription] Failed to recover pending checkout on ${source}:`,\n      error\n    )\n    const attempt = getCurrentPendingCheckoutAttempt(attemptId)\n    if (!attempt) return\n    const isPastDeadline =\n      Date.now() - attempt.started_at_ms >=\n      PENDING_CHECKOUT_COMPLETION_DEADLINE_MS\n    if (source === 'deadline' || isPastDeadline) {\n      reportRecoveryUnreachable(attemptId, error)\n      rearmBoundedDeadlineWakeUp()\n    } else {\n      schedulePendingCheckoutRecovery()\n    }\n  }\n\n  const reportRecoveryUnreachable = (attemptId: string, error?: unknown) => {\n    if (isDisposed) return\n    const attempt = claimPendingCheckoutTerminal(\n      attemptId,\n      'recovery_unreachable'\n    )\n    if (!attempt) return\n    reportTelemetryError(\n      new Error(\n        'Pending subscription checkout recovery could not reach billing'\n      ),\n      {\n        errorType: 'failure_recovering_cloud_checkout',\n        surface: 'billing',\n        context: {\n          checkout_attempt_id: attempt.attempt_id,\n          checkout_type: attempt.checkout_type,\n          attempt_age_ms: Date.now() - attempt.started_at_ms,\n          tier: attempt.tier,\n          cycle: attempt.cycle\n        },\n        level: 'warning'\n      }\n    )\n    telemetry?.trackBillingEvent({\n      operation: 'subscription_checkout',\n      stage: 'failed',\n      outcome: 'failure',\n      checkout_attempt_id: attempt.attempt_id,\n      failure_category: categorizeBillingApiError(error),\n      tier: attempt.tier,\n      cycle: attempt.cycle,\n      checkout_type: attempt.checkout_type,\n      duration_ms: Date.now() - attempt.started_at_ms\n    })\n    if (attempt.operation === 'resubscribe') {\n      telemetry?.trackBillingEvent({\n        operation: 'resubscribe',\n        stage: 'failed',\n        outcome: 'failure',\n        source: attempt.resubscribe_source ?? 'settings_billing_panel',\n        checkout_attempt_id: attempt.attempt_id,\n        failure_category: categorizeBillingApiError(error)\n      })\n    }\n  }\n\n  const waitForActiveRecoveryAtDeadline = async (\n    source: PendingCheckoutRecoverySource,\n    attemptId: string\n  ): Promise<boolean> => {\n    if (activePendingCheckoutRead?.attemptId !== attemptId) return false\n    if (source !== 'deadline') return true\n\n    try {\n      const status = await withTimeout(\n        activePendingCheckoutRead.promise,\n        PENDING_CHECKOUT_DEADLINE_REFRESH_TIMEOUT_MS\n      )\n      return status !== null\n    } catch (error) {\n      console.error(\n        '[Subscription] Pending checkout recovery was still running at the deadline:',\n        error\n      )\n      reportRecoveryUnreachable(attemptId, error)\n      rearmBoundedDeadlineWakeUp()\n      return false\n    }\n  }\n\n  const fetchPendingCheckoutStatus = async (attemptId: string) => {\n    lastPendingCheckoutStatus = null\n    const statusFetch = fetchSubscriptionStatus()\n    activePendingCheckoutRead = { attemptId, promise: statusFetch }\n    try {\n      return await withTimeout(\n        statusFetch,\n        PENDING_CHECKOUT_DEADLINE_REFRESH_TIMEOUT_MS\n      )\n    } catch (error) {\n      clearInFlightStatusFetch(statusFetch)\n      throw error\n    }\n  }\n\n  const rearmBoundedDeadlineWakeUp = () => {\n    const attempt = getPendingSubscriptionCheckoutAttempt()\n    if (!attempt) return\n    const { deadlineRung } = pendingCheckoutSchedule\n    if (deadlineRung >= PENDING_CHECKOUT_DEADLINE_RETRY_DELAYS_MS.length) return\n    const delay = PENDING_CHECKOUT_DEADLINE_RETRY_DELAYS_MS[deadlineRung]\n    pendingCheckoutSchedule = {\n      ...pendingCheckoutSchedule,\n      deadlineRung: deadlineRung + 1\n    }\n    armMissingCheckoutCompletionWakeUp(delay)\n  }\n\n  const retryUnavailableDeadline = (source: PendingCheckoutRecoverySource) => {\n    if (source !== 'deadline') return\n\n    const attempt = getPendingSubscriptionCheckoutAttempt()\n    if (attempt) rearmBoundedDeadlineWakeUp()\n  }\n\n  const handleEmptyPendingCheckoutStatus = (\n    source: PendingCheckoutRecoverySource\n  ) => {\n    if (source === 'deadline') {\n      rearmBoundedDeadlineWakeUp()\n    } else {\n      schedulePendingCheckoutRecovery()\n    }\n  }\n\n  const recoverPendingSubscriptionCheckout = async (\n    source: PendingCheckoutRecoverySource\n  ) => {\n    if (!canRecoverPendingCheckout()) {\n      retryUnavailableDeadline(source)\n      return\n    }\n    const attempt = getPendingSubscriptionCheckoutAttempt()\n    if (!attempt) return\n    const attemptId = attempt.attempt_id\n    if (activePendingCheckoutRead?.attemptId === attemptId) {\n      await joinActivePendingCheckoutRecovery(source, attemptId)\n      return\n    }\n\n    if (!(await runPendingCheckoutRecovery(source, attemptId))) return\n\n    if (source === 'deadline') reportMissingCheckoutCompletion(attemptId)\n  }\n\n  const joinActivePendingCheckoutRecovery = async (\n    source: PendingCheckoutRecoverySource,\n    attemptId: string\n  ) => {\n    const didObserveStatus = await waitForActiveRecoveryAtDeadline(\n      source,\n      attemptId\n    )\n    if (isDisposed || source !== 'deadline') return\n    if (didObserveStatus) reportMissingCheckoutCompletion(attemptId)\n    else retryUnavailableDeadline(source)\n  }\n\n  const runPendingCheckoutRecovery = async (\n    source: PendingCheckoutRecoverySource,\n    attemptId: string\n  ): Promise<boolean> => {\n    try {\n      const status = await fetchPendingCheckoutStatus(attemptId)\n      if (isDisposed) return false\n      if (status === null) {\n        handleEmptyPendingCheckoutStatus(source)\n        return false\n      }\n      return true\n    } catch (error) {\n      handlePendingCheckoutRecoveryError(source, attemptId, error)\n      return false\n    } finally {\n      if (activePendingCheckoutRead?.attemptId === attemptId) {\n        activePendingCheckoutRead = null\n      }\n    }\n  }\n\n  // Coalesce concurrent callers so an auth/session-rotation burst mints one fetch.\n  let inFlightStatusRead: {\n    promise: Promise<BillingStatusResponse | null>\n    ownerId: string | null\n    workspaceId: string | null\n    pendingAttemptId: string | null\n  } | null = null\n  let nextStatusFetchSequence = 0\n  let statusScopeGeneration = 0\n  let observedStatusScope = `${authStore.userId ?? ''}\\0${workspaceStore.activeWorkspaceId ?? ''}`\n\n  const observeStatusScope = (\n    ownerId: string | null,\n    workspaceId: string | null\n  ) => {\n    const scope = `${ownerId ?? ''}\\0${workspaceId ?? ''}`\n    if (scope === observedStatusScope) return\n    observedStatusScope = scope\n    statusScopeGeneration += 1\n    // The invoice link is a bearer payment URL: never carry it across scopes.\n    if (subscriptionStatus.value?.renewal_invoice) {\n      subscriptionStatus.value = {\n        ...subscriptionStatus.value,\n        renewal_invoice: undefined\n      }\n    }\n  }\n\n  watch(\n    () =>\n      [\n        authStore.userId,\n        workspaceStore.activeWorkspaceId,\n        awaitingSessionWorkspace.value\n      ] as const,\n    ([ownerId, workspaceId], [, , wasAwaitingWorkspace]) => {\n      observeStatusScope(ownerId ?? null, workspaceId)\n      // The bootstrap watcher reads for the session's first workspace.\n      if (wasAwaitingWorkspace) return\n      if (\n        workspaceId &&\n        hasPendingSubscriptionCheckoutAttempt() &&\n        getPendingAttemptOwnership() === 'matched'\n      ) {\n        void recoverPendingSubscriptionCheckout('retry')\n      }\n    }\n  )\n\n  const clearInFlightStatusFetch = (\n    fetchPromise: Promise<BillingStatusResponse | null>\n  ) => {\n    if (inFlightStatusRead?.promise === fetchPromise) inFlightStatusRead = null\n  }\n\n  function fetchSubscriptionStatus(): Promise<BillingStatusResponse | null> {\n    const ownerId = authStore.userId ?? null\n    const workspaceId = workspaceStore.activeWorkspaceId\n    const pendingAttemptId =\n      getPendingSubscriptionCheckoutAttempt()?.attempt_id ?? null\n    observeStatusScope(ownerId, workspaceId)\n    if (\n      inFlightStatusRead?.ownerId === ownerId &&\n      inFlightStatusRead.workspaceId === workspaceId &&\n      inFlightStatusRead.pendingAttemptId === pendingAttemptId\n    ) {\n      return inFlightStatusRead.promise\n    }\n\n    const sequence = ++nextStatusFetchSequence\n    const scopeGeneration = statusScopeGeneration\n    const fetchPromise = performFetchSubscriptionStatus(\n      ownerId,\n      workspaceId,\n      sequence,\n      scopeGeneration\n    )\n    inFlightStatusRead = {\n      promise: fetchPromise,\n      ownerId,\n      workspaceId,\n      pendingAttemptId\n    }\n    void fetchPromise\n      .catch(() => undefined)\n      .finally(() => {\n        clearInFlightStatusFetch(fetchPromise)\n      })\n    return fetchPromise\n  }\n\n  /**\n   * The status read on whichever rail is on, in the failure shape the legacy\n   * client threw in. The rail is taken before the read and held for it: a flag\n   * flip mid-read must not start on one client and publish through the other.\n   */\n  async function readSubscriptionStatus(): Promise<\n    BillingStatusResponse | undefined\n  > {\n    const rail = useBillingReadRail()\n    try {\n      const status = rail\n        ? await readOnRail(rail.readStatus, 'getBillingStatus')\n        : await workspaceApi.getBillingStatus()\n      return status\n    } catch (error) {\n      const status =\n        error instanceof WorkspaceApiError || error instanceof AuthStoreError\n          ? error.status\n          : undefined\n      throw new AuthStoreError(\n        t('toastMessages.failedToFetchSubscription', {\n          error: error instanceof Error ? error.message : String(error)\n        }),\n        status\n      )\n    }\n  }\n\n  async function performFetchSubscriptionStatus(\n    ownerId: string | null,\n    workspaceId: string | null,\n    sequence: number,\n    scopeGeneration: number\n  ): Promise<BillingStatusResponse | null> {\n    if (!isCloud) return null\n\n    const statusData = await readSubscriptionStatus()\n    if (\n      !isPublishableStatusRead(\n        statusData,\n        ownerId,\n        workspaceId,\n        sequence,\n        scopeGeneration\n      )\n    )\n      return null\n    publishSubscriptionStatus(statusData, workspaceId)\n\n    return statusData\n  }\n\n  function isPublishableStatusRead(\n    statusData: BillingStatusResponse | undefined,\n    ownerId: string | null,\n    workspaceId: string | null,\n    sequence: number,\n    scopeGeneration: number\n  ): statusData is BillingStatusResponse {\n    return (\n      !isDisposed &&\n      statusData !== undefined &&\n      scopeGeneration === statusScopeGeneration &&\n      sequence === nextStatusFetchSequence &&\n      (authStore.userId ?? null) === ownerId &&\n      workspaceStore.activeWorkspaceId === workspaceId\n    )\n  }\n\n  function publishSubscriptionStatus(\n    statusData: BillingStatusResponse,\n    workspaceId: string | null\n  ): void {\n    // Only a current, publishable read proves billing is reachable.\n    lastPendingCheckoutStatus = statusData\n    subscriptionStatus.value = statusData\n    if (workspaceId && statusData.billing_rail) {\n      workspaceStore.setWorkspaceBillingRail(\n        workspaceId,\n        statusData.billing_rail\n      )\n    }\n    syncPendingSubscriptionSuccess(statusData)\n  }\n\n  const handlePendingSubscriptionCheckoutChange = () => {\n    if (!hasPendingSubscriptionCheckoutAttempt()) {\n      stopPendingCheckoutRecovery()\n      return\n    }\n\n    stopPendingCheckoutRecovery()\n    void recoverPendingSubscriptionCheckout('retry')\n  }\n\n  useEventListener(defaultWindow, PENDING_SUBSCRIPTION_CHECKOUT_EVENT, () => {\n    handlePendingSubscriptionCheckoutChange()\n  })\n\n  useEventListener(defaultWindow, 'storage', (event: StorageEvent) => {\n    if (event.key === PENDING_SUBSCRIPTION_CHECKOUT_STORAGE_KEY) {\n      handlePendingSubscriptionCheckoutChange()\n    }\n  })\n\n  useEventListener(defaultWindow, 'pageshow', () => {\n    void recoverPendingSubscriptionCheckout('pageshow')\n  })\n\n  useEventListener(defaultDocument, 'visibilitychange', () => {\n    if (defaultDocument?.visibilityState === 'visible') {\n      void recoverPendingSubscriptionCheckout('visibilitychange')\n    }\n  })\n\n  watch(\n    () =>\n      [\n        authStore.isInitialized,\n        isLoggedIn.value,\n        authStore.userId,\n        awaitingSessionWorkspace.value\n      ] as const,\n    async ([authInitialized, loggedIn, , awaitingWorkspace]) => {\n      if (!authInitialized) {\n        return\n      }\n\n      if (loggedIn && isCloud) {\n        if (awaitingWorkspace) return\n        try {\n          if (hasOwnedPendingCheckoutAttempt()) {\n            await recoverPendingSubscriptionCheckout('bootstrap')\n          } else {\n            await fetchSubscriptionStatus()\n          }\n        } catch (error) {\n          // Network errors are expected during navigation/component unmount\n          // and when offline - log for debugging but don't surface to user\n          console.error('Failed to fetch subscription status:', error)\n        } finally {\n          isInitialized.value = true\n        }\n      } else {\n        subscriptionStatus.value = null\n        clearPendingSubscriptionCheckoutAttempt()\n        stopPendingCheckoutRecovery()\n        stopCancellationWatcher()\n        isInitialized.value = true\n      }\n    },\n    { immediate: true }\n  )\n\n  const initiateSubscriptionCheckout =\n    async (): Promise<CloudSubscriptionCheckoutResponse> => {\n      const headers = await buildAuthHeaders()\n      const checkoutAttribution = await getCheckoutAttributionForCloud()\n\n      const response = await fetchWithCustomerRecovery(\n        buildApiUrl('/customers/cloud-subscription-checkout'),\n        {\n          method: 'POST',\n          headers,\n          body: JSON.stringify(checkoutAttribution)\n        }\n      )\n\n      if (!response.ok) {\n        const { message, code } = await parseErrorResponse(response)\n        throw new AuthStoreError(\n          t('toastMessages.failedToInitiateSubscription', {\n            error: message\n          }),\n          response.status,\n          code\n        )\n      }\n\n      return response.json()\n    }\n\n  return {\n    // State\n    canAccessSubscriptionFeatures: canAccessSubscriptionFeatures,\n    isInitialized,\n    isCancelled,\n    formattedRenewalDate,\n    formattedEndDate,\n    subscriptionTier,\n    isFreeTier,\n    subscriptionDuration,\n    isYearlySubscription,\n    subscriptionTierName,\n    subscriptionStatus,\n\n    // Utilities\n    isSubscriptionEnabled,\n\n    // Actions\n    subscribe,\n    subscribeDirect,\n    fetchStatus,\n    fetchStatusDirect: fetchSubscriptionStatus,\n    showSubscriptionDialog,\n    manageSubscription,\n    requireActiveSubscription,\n    handleViewUsageHistory,\n    handleLearnMore,\n    handleInvoiceHistory\n  }\n}\n\nfunction getPendingCheckoutRetryDelay(attempt: number): number | undefined {\n  return PENDING_SUBSCRIPTION_CHECKOUT_RETRY_DELAYS_MS[attempt]\n}\n\nexport const useSubscription = createSharedComposable(useSubscriptionInternal)\n","import { computed, ref } from 'vue'\n\nimport { t } from '@/i18n'\nimport { useAuthActions } from '@/composables/auth/useAuthActions'\nimport { useSubscription } from '@/platform/cloud/subscription/composables/useSubscription'\nimport { isWorkspaceBillingRequiredError } from '@/platform/remote/comfyui/errors'\nimport type {\n  BillingStatus,\n  BillingSubscriptionStatus,\n  PreviewSubscribeOptions,\n  PreviewSubscribeResponse,\n  SubscribeOptions,\n  SubscribeResponse\n} from '@/platform/workspace/api/workspaceApi'\nimport { useAuthStore } from '@/stores/authStore'\n\nimport type {\n  BalanceInfo,\n  BillingActions,\n  BillingState,\n  SubscriptionDialogOptions,\n  SubscriptionInfo\n} from './types'\n\ntype LegacyBalance = NonNullable<ReturnType<typeof useAuthStore>['balance']>\ntype RuntimeLegacyBalance = Omit<\n  LegacyBalance,\n  'amount_micros' | 'effective_balance_micros'\n> & {\n  amount_micros?: number\n  effective_balance_micros?: number\n}\n\n/**\n * Adapter for legacy user-scoped billing via /customers/* endpoints.\n * Used for personal workspaces.\n * @internal - Use useBillingContext() instead of importing directly.\n */\nexport function useLegacyBilling(): BillingState & BillingActions {\n  const {\n    canAccessSubscriptionFeatures: legacyCanAccessSubscriptionFeatures,\n    subscriptionTier,\n    subscriptionDuration,\n    subscriptionStatus: legacySubscriptionStatus,\n    isCancelled,\n    fetchStatus: legacyFetchStatus,\n    fetchStatusDirect: legacyFetchStatusDirect,\n    manageSubscription: legacyManageSubscription,\n    subscribeDirect: legacySubscribeDirect,\n    showSubscriptionDialog: legacyShowSubscriptionDialog\n  } = useSubscription()\n\n  const authStore = useAuthStore()\n  const authActions = useAuthActions()\n\n  const isInitialized = ref(false)\n  const isLoading = ref(false)\n  const error = ref<string | null>(null)\n\n  // The backend refuses legacy calls for a workspace that moved to workspace\n  // billing. Refresh the status so the next click routes correctly and ask the\n  // user to retry; the call is not repeated here.\n  async function toPresentableFailure(err: unknown): Promise<unknown> {\n    if (!isWorkspaceBillingRequiredError(err)) return err\n    try {\n      await legacyFetchStatusDirect()\n    } catch {\n      // The refusal is the failure to report, not the refresh.\n    }\n    return new Error(t('billingOperation.subscriptionFailedDetail'), {\n      cause: err\n    })\n  }\n\n  async function reportFailures(action: () => Promise<unknown>): Promise<void> {\n    try {\n      await action()\n    } catch (err) {\n      authActions.reportError(await toPresentableFailure(err))\n    }\n  }\n\n  // For actions whose caller shows the outcome, so a failure must not resolve.\n  async function rejectFailures(action: () => Promise<unknown>): Promise<void> {\n    try {\n      await action()\n    } catch (err) {\n      throw await toPresentableFailure(err)\n    }\n  }\n\n  const canAccessSubscriptionFeatures = computed(\n    () => legacyCanAccessSubscriptionFeatures.value\n  )\n  const isFreeTier = computed(() => subscriptionTier.value === 'FREE')\n  const maxSeats = computed(() => null)\n  const occupiedSeats = computed(() => null)\n\n  const hasFunds = computed(() => (authStore.balance?.amount_micros ?? 0) > 0)\n  const subscription = computed<SubscriptionInfo | null>(() => {\n    // A past-due legacy status has no tier and is inactive, yet must still\n    // reach the payment-recovery banner.\n    if (\n      !legacyCanAccessSubscriptionFeatures.value &&\n      !subscriptionTier.value &&\n      !legacySubscriptionStatus.value?.renewal_invoice\n    ) {\n      return null\n    }\n\n    return {\n      isActive: legacyCanAccessSubscriptionFeatures.value,\n      tier: subscriptionTier.value,\n      duration: subscriptionDuration.value,\n      planSlug: null, // Legacy doesn't use plan slugs\n      scheduledChange: null, // Legacy rail cannot schedule plan changes\n      renewalDate: legacySubscriptionStatus.value?.renewal_date ?? null,\n      endDate: legacySubscriptionStatus.value?.cancel_at ?? null,\n      isCancelled: isCancelled.value,\n      hasFunds: hasFunds.value,\n      agentHasFunds: hasFunds.value\n    }\n  })\n\n  const balance = computed<BalanceInfo | null>(() => {\n    const legacyBalance: RuntimeLegacyBalance | null = authStore.balance\n    if (!legacyBalance) return null\n\n    return {\n      amountMicros: legacyBalance.amount_micros || 0,\n      currency: legacyBalance.currency || 'usd',\n      effectiveBalanceMicros:\n        legacyBalance.effective_balance_micros ??\n        legacyBalance.amount_micros ??\n        0,\n      prepaidBalanceMicros: legacyBalance.prepaid_balance_micros ?? 0,\n      cloudCreditBalanceMicros: legacyBalance.cloud_credit_balance_micros ?? 0\n    }\n  })\n\n  const billingStatus = computed<BillingStatus | null>(\n    () => legacySubscriptionStatus.value?.billing_status ?? null\n  )\n  const subscriptionStatus = computed<BillingSubscriptionStatus | null>(() => {\n    if (legacySubscriptionStatus.value?.subscription_status) {\n      return legacySubscriptionStatus.value.subscription_status\n    }\n    if (isCancelled.value) return 'canceled'\n    if (legacyCanAccessSubscriptionFeatures.value) return 'active'\n    return null\n  })\n  const tier = computed(() => subscriptionTier.value)\n  const renewalDate = computed(\n    () => legacySubscriptionStatus.value?.renewal_date ?? null\n  )\n\n  // Legacy billing doesn't have workspace-style plans\n  const plans = computed(() => [])\n  const currentPlanSlug = computed(() => null)\n  const teamCreditStops = computed(() => null)\n  const currentTeamCreditStop = computed(\n    () => legacySubscriptionStatus.value?.team_credit_stop ?? null\n  )\n\n  async function initialize(): Promise<void> {\n    if (isInitialized.value) return\n\n    isLoading.value = true\n    error.value = null\n    try {\n      await Promise.all([fetchStatus(), fetchBalance()])\n      // Re-fetch balance if free tier credits were just lazily granted\n      if (isFreeTier.value && balance.value?.amountMicros === 0) {\n        await fetchBalance()\n      }\n      isInitialized.value = true\n    } catch (err) {\n      error.value =\n        err instanceof Error ? err.message : 'Failed to initialize billing'\n      throw err\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  async function fetchStatus(): Promise<void> {\n    isLoading.value = true\n    error.value = null\n    try {\n      await legacyFetchStatus()\n    } catch (err) {\n      error.value =\n        err instanceof Error ? err.message : 'Failed to fetch subscription'\n      throw err\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  async function fetchBalance(): Promise<void> {\n    isLoading.value = true\n    error.value = null\n    try {\n      await authStore.fetchBalance()\n    } catch (err) {\n      error.value =\n        err instanceof Error ? err.message : 'Failed to fetch balance'\n      throw err\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  async function subscribe(\n    _planSlug: string,\n    _options?: SubscribeOptions\n  ): Promise<SubscribeResponse | void> {\n    // Legacy billing uses Stripe checkout flow via useSubscription\n    await reportFailures(() => legacySubscribeDirect())\n  }\n\n  async function previewSubscribe(\n    _planSlug: string,\n    _options?: PreviewSubscribeOptions\n  ): Promise<PreviewSubscribeResponse | null> {\n    // Legacy billing doesn't support preview - returns null\n    return null\n  }\n\n  async function manageSubscription(): Promise<void> {\n    await reportFailures(() => legacyManageSubscription())\n  }\n\n  async function cancelSubscription(): Promise<void> {\n    await rejectFailures(() =>\n      legacyManageSubscription({ cancelSubscription: true })\n    )\n  }\n\n  async function resubscribe(options?: {\n    source?: 'pricing_dialog' | 'settings_billing_panel'\n  }): Promise<void> {\n    // Legacy has no resubscribe endpoint; resubscribing is a fresh checkout.\n    // Unwrapped so failures propagate to resubscribe telemetry instead of being swallowed.\n    // Tag the attempt as a resubscribe so the pending-checkout recovery in\n    // useSubscription.ts can later emit the canonical resubscribe terminal\n    // instead of leaving it indistinguishable from a plain subscribe.\n    await rejectFailures(() =>\n      legacySubscribeDirect({\n        operation: 'resubscribe',\n        source: options?.source\n      })\n    )\n  }\n\n  async function topup(amountCents: number): Promise<void> {\n    // Facade standardizes on cents; legacy /customers/credit takes dollars.\n    await reportFailures(() =>\n      authActions.purchaseCreditsDirect(amountCents / 100)\n    )\n  }\n\n  async function fetchPlans(): Promise<void> {\n    // Legacy billing doesn't have workspace-style plans\n    // Plans are hardcoded in the UI for legacy subscriptions\n  }\n\n  async function requireActiveSubscription(): Promise<void> {\n    await fetchStatus()\n    if (!canAccessSubscriptionFeatures.value) {\n      legacyShowSubscriptionDialog({ reason: 'subscription_required' })\n    }\n  }\n\n  function showSubscriptionDialog(options?: SubscriptionDialogOptions): void {\n    legacyShowSubscriptionDialog(options)\n  }\n\n  return {\n    // State\n    isInitialized,\n    subscription,\n    balance,\n    plans,\n    currentPlanSlug,\n    teamCreditStops,\n    currentTeamCreditStop,\n    maxSeats,\n    occupiedSeats,\n    isLoading,\n    error,\n    canAccessSubscriptionFeatures,\n    isFreeTier,\n    billingStatus,\n    subscriptionStatus,\n    tier,\n    renewalDate,\n    renewalInvoice: computed(\n      () => legacySubscriptionStatus.value?.renewal_invoice ?? null\n    ),\n\n    // Actions\n    initialize,\n    fetchStatus,\n    fetchBalance,\n    subscribe,\n    previewSubscribe,\n    manageSubscription,\n    cancelSubscription,\n    resubscribe,\n    topup,\n    fetchPlans,\n    requireActiveSubscription,\n    showSubscriptionDialog\n  }\n}\n","import { computed, effectScope, ref, watch } from 'vue'\n\nimport type {\n  BillingPlansResponse,\n  Plan,\n  TeamCreditStops\n} from '@/platform/workspace/api/workspaceApi'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { workspaceApi } from '@/platform/workspace/api/workspaceApi'\nimport { readOnRail } from '@/platform/workspace/composables/readOnRail'\nimport { useBillingReadRail } from '@/platform/workspace/composables/useBillingReadRail'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { t } from '@/i18n'\n\nconst plans = ref<Plan[]>([])\nconst currentPlanSlug = ref<string | null>(null)\nconst teamCreditStops = ref<TeamCreditStops | null>(null)\nconst isLoading = ref(false)\nconst error = ref<string | null>(null)\nlet fetchPromise: Promise<void> | null = null\nlet fetchPromiseScopeKey: string | null = null\nlet adoptedScopeKey: string | null = null\nlet errorScopeKey: string | null = null\nlet isScopeWatcherInitialized = false\nconst MAX_SCOPE_REISSUES = 4\n\nfunction billingScopeKey(): string {\n  const identity = useCurrentUser().resolvedUserInfo.value?.id ?? 'anonymous'\n  const workspace = useTeamWorkspaceStore().activeWorkspaceId ?? 'personal'\n  return `${identity}:${workspace}`\n}\n\nfunction clearCatalog(): void {\n  plans.value = []\n  currentPlanSlug.value = null\n  teamCreditStops.value = null\n  adoptedScopeKey = null\n  error.value = null\n  errorScopeKey = null\n}\n\nfunction isAnonymousScope(scopeKey: string): boolean {\n  return scopeKey.startsWith('anonymous:')\n}\n\nfunction hasCatalogForScope(scopeKey: string): boolean {\n  return adoptedScopeKey === scopeKey && plans.value.length > 0\n}\n\nfunction reportCatalogFallback(err: unknown, hasCachedPlans: boolean): void {\n  const hasTeamCreditStops = (teamCreditStops.value?.stops.length ?? 0) > 0\n  reportError(err, {\n    surface: 'billing',\n    errorType: 'cloud_billing_plan_catalog_fallback',\n    tags: {\n      failure_kind: 'degraded',\n      feature_area: 'billing',\n      has_cached_plans: hasCachedPlans,\n      has_team_credit_stops: hasTeamCreditStops,\n      operation: 'load',\n      outcome: hasCachedPlans ? 'recovered' : 'failed'\n    },\n    level: 'warning'\n  })\n}\n\nfunction ensureScopeWatcher(): void {\n  if (isScopeWatcherInitialized) return\n  isScopeWatcherInitialized = true\n  effectScope(true).run(() =>\n    watch(billingScopeKey, (scopeKey) => {\n      if (adoptedScopeKey !== null && adoptedScopeKey !== scopeKey)\n        clearCatalog()\n      else if (errorScopeKey !== null && errorScopeKey !== scopeKey) {\n        error.value = null\n        errorScopeKey = null\n      }\n    })\n  )\n}\n\nexport function useBillingPlans() {\n  ensureScopeWatcher()\n  function adopt(response: BillingPlansResponse, scopeKey: string): void {\n    if (!Array.isArray(response.plans)) {\n      throw new TypeError('Billing plans response did not contain a plan list')\n    }\n    if (\n      response.team_credit_stops != null &&\n      !Array.isArray(response.team_credit_stops.stops)\n    ) {\n      throw new TypeError(\n        'Billing plans response did not contain a team credit stop list'\n      )\n    }\n    plans.value = response.plans\n    currentPlanSlug.value = response.current_plan_slug ?? null\n    teamCreditStops.value = response.team_credit_stops ?? null\n    adoptedScopeKey = scopeKey\n  }\n\n  function fetchPlans(reissueCount = 0): Promise<void> {\n    const scopeKey = billingScopeKey()\n    if (fetchPromise && fetchPromiseScopeKey === scopeKey) return fetchPromise\n    if (adoptedScopeKey !== null && adoptedScopeKey !== scopeKey) {\n      clearCatalog()\n    } else if (errorScopeKey !== null && errorScopeKey !== scopeKey) {\n      error.value = null\n      errorScopeKey = null\n    }\n    const rail = useBillingReadRail()\n    // A superseded read publishes nothing, so whatever the last read left\n    // behind has to survive this one: the catalog stays, and so does the\n    // error, or a failed read followed by a superseded one would leave an\n    // empty catalog with nothing on screen to explain it.\n    const priorError = error.value\n    isLoading.value = true\n    error.value = null\n\n    const reissueForCurrentScope = (): Promise<void> | undefined => {\n      const currentScope = billingScopeKey()\n      if (errorScopeKey === currentScope) error.value = priorError\n      if (isAnonymousScope(currentScope)) return\n      if (currentScope === scopeKey) return\n      if (reissueCount >= MAX_SCOPE_REISSUES) {\n        const exhaustion = new Error(t('subscription.plansLoadFailed'), {\n          cause: { reissueCount, scopeKey: currentScope }\n        })\n        error.value ??= t('subscription.plansLoadFailed')\n        errorScopeKey = currentScope\n        reportCatalogFallback(exhaustion, hasCatalogForScope(currentScope))\n        return\n      }\n      if (fetchPromise === request) {\n        fetchPromise = null\n        fetchPromiseScopeKey = null\n      }\n      return fetchPlans(reissueCount + 1)\n    }\n\n    const request: Promise<void> = (\n      rail\n        ? readOnRail(rail.readPlans, 'getBillingPlans')\n        : workspaceApi.getBillingPlans()\n    )\n      .then((response) => {\n        if (fetchPromise !== request) return fetchPromise ?? undefined\n        // Undefined is a read the scope moved on under; the catalog it would\n        // have published belongs to an actor this host has left.\n        if (response === undefined) return reissueForCurrentScope()\n        else if (billingScopeKey() === scopeKey) adopt(response, scopeKey)\n        else return reissueForCurrentScope()\n      })\n      .catch((err: unknown) => {\n        if (fetchPromise !== request) return fetchPromise ?? undefined\n        if (billingScopeKey() !== scopeKey) {\n          return reissueForCurrentScope()\n        }\n        error.value =\n          err instanceof Error ? err.message : 'Failed to fetch plans'\n        errorScopeKey = scopeKey\n        reportCatalogFallback(err, hasCatalogForScope(scopeKey))\n      })\n      .finally(() => {\n        if (fetchPromise !== request) return\n        isLoading.value = false\n        fetchPromise = null\n        fetchPromiseScopeKey = null\n      })\n\n    fetchPromise = request\n    fetchPromiseScopeKey = scopeKey\n    return request\n  }\n\n  const monthlyPlans = computed(() =>\n    plans.value.filter((p) => p.duration === 'MONTHLY')\n  )\n\n  const annualPlans = computed(() =>\n    plans.value.filter((p) => p.duration === 'ANNUAL')\n  )\n\n  function getPlanBySlug(slug: string) {\n    return plans.value.find((p) => p.slug === slug)\n  }\n\n  function getPlansForTier(tier: Plan['tier']) {\n    return plans.value.filter((p) => p.tier === tier)\n  }\n\n  const isCurrentPlan = (slug: string) => currentPlanSlug.value === slug\n\n  return {\n    plans,\n    currentPlanSlug,\n    teamCreditStops,\n    isLoading,\n    error,\n    monthlyPlans,\n    annualPlans,\n    fetchPlans,\n    getPlanBySlug,\n    getPlansForTier,\n    isCurrentPlan\n  }\n}\n","import type { WorkspaceRole } from '@/platform/workspace/api/workspaceApi'\nimport { useDialogStore } from '@/stores/dialogStore'\n\n// Workspace dialogs - dynamically imported to avoid bundling when feature flag is off\nexport function useWorkspaceDialogs() {\n  const dialogStore = useDialogStore()\n\n  async function showDeleteWorkspaceDialog(options?: {\n    workspaceId?: string\n    workspaceName?: string\n  }) {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/DeleteWorkspaceDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'delete-workspace',\n      component,\n      props: options,\n      dialogComponentProps: { headless: true }\n    })\n  }\n\n  async function showCreateWorkspaceDialog(\n    onConfirm?: (name: string) => void | Promise<void>\n  ) {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/CreateWorkspaceDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'create-workspace',\n      component,\n      props: { onConfirm },\n      dialogComponentProps: {\n        headless: true\n      }\n    })\n  }\n\n  /**\n   * Show the team workspaces dialog for creating or switching workspaces.\n   * Optionally calls `onConfirm` after a workspace is successfully created.\n   */\n  async function showTeamWorkspacesDialog(\n    onConfirm?: (name: string) => void | Promise<void>\n  ) {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/TeamWorkspacesDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'team-workspaces',\n      component,\n      props: { onConfirm },\n      dialogComponentProps: {\n        headless: true\n      }\n    })\n  }\n\n  async function showLeaveWorkspaceDialog() {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/LeaveWorkspaceDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'leave-workspace',\n      component,\n      dialogComponentProps: { headless: true }\n    })\n  }\n\n  async function showEditWorkspaceDialog() {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/EditWorkspaceDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'edit-workspace',\n      component,\n      dialogComponentProps: {\n        headless: true\n      }\n    })\n  }\n\n  async function showRemoveMemberDialog(memberId: string) {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/RemoveMemberDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'remove-member',\n      component,\n      props: { memberId },\n      dialogComponentProps: { headless: true }\n    })\n  }\n\n  async function showChangeMemberRoleDialog(props: {\n    memberId: string\n    memberName: string\n    targetRole: WorkspaceRole\n  }) {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/ChangeMemberRoleDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'change-member-role',\n      component,\n      props,\n      dialogComponentProps: { headless: true }\n    })\n  }\n\n  async function showSetMemberCreditLimitDialog(props: {\n    memberId: string\n    memberName: string\n    creditsUsed?: number\n    currentLimit?: number | null\n  }) {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/SetMemberCreditLimitDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'set-member-credit-limit',\n      component,\n      props,\n      dialogComponentProps: { headless: true }\n    })\n  }\n\n  async function showInviteMemberDialog() {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/InviteMemberDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'invite-member',\n      component,\n      dialogComponentProps: {\n        headless: true\n      }\n    })\n  }\n\n  async function showInviteMemberUpsellDialog() {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/InviteMemberUpsellDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'invite-member-upsell',\n      component,\n      dialogComponentProps: {\n        headless: true\n      }\n    })\n  }\n\n  async function showInviteLinkInvalidDialog() {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/InviteLinkInvalidDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'invite-link-invalid',\n      component,\n      dialogComponentProps: {\n        headless: true\n      }\n    })\n  }\n\n  async function showInviteWrongAccountDialog(props: { inviteToken: string }) {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/InviteWrongAccountDialogContent.vue')\n    // showDialog keeps an existing entry's props; close first so a repeat 403\n    // carries the fresh token instead of replaying the previous one.\n    dialogStore.closeDialog({ key: 'invite-wrong-account' })\n    return dialogStore.showDialog({\n      key: 'invite-wrong-account',\n      component,\n      props,\n      dialogComponentProps: {\n        headless: true\n      }\n    })\n  }\n\n  async function showRevokeInviteDialog(inviteId: string) {\n    const { default: component } =\n      await import('@/platform/workspace/components/dialogs/RevokeInviteDialogContent.vue')\n    return dialogStore.showDialog({\n      key: 'revoke-invite',\n      component,\n      props: { inviteId },\n      dialogComponentProps: { headless: true }\n    })\n  }\n  return {\n    showDeleteWorkspaceDialog,\n    showCreateWorkspaceDialog,\n    showTeamWorkspacesDialog,\n    showLeaveWorkspaceDialog,\n    showEditWorkspaceDialog,\n    showRemoveMemberDialog,\n    showChangeMemberRoleDialog,\n    showSetMemberCreditLimitDialog,\n    showRevokeInviteDialog,\n    showInviteMemberDialog,\n    showInviteMemberUpsellDialog,\n    showInviteLinkInvalidDialog,\n    showInviteWrongAccountDialog\n  }\n}\n","import { computed, watch } from 'vue'\nimport { createSharedComposable } from '@vueuse/core'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useBillingRouting } from '@/composables/billing/useBillingRouting'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\n\nimport type { WorkspaceRole, WorkspaceType } from '../api/workspaceApi'\nimport { useTeamWorkspaceStore } from '../stores/teamWorkspaceStore'\n\n/** Permission flags for workspace actions */\ninterface WorkspacePermissions {\n  canViewOtherMembers: boolean\n  canViewPendingInvites: boolean\n  canLeaveWorkspace: boolean\n  canAccessWorkspaceMenu: boolean\n  canManageSubscription: boolean\n  canManageSubscriptionLifecycle: boolean\n  canDowngradeToPersonal: boolean\n}\n\n/** UI configuration for workspace role */\ninterface WorkspaceUIConfig {\n  showMembersList: boolean\n  showPendingTab: boolean\n  showSearch: boolean\n  showRoleColumn: boolean\n  showCreditsColumn: boolean\n  membersGridCols: string\n  pendingGridCols: string\n  headerGridCols: string\n  showEditWorkspaceMenuItem: boolean\n  workspaceMenuAction: 'delete' | null\n  workspaceMenuDisabledTooltip: string | null\n}\n\nfunction getPermissions(\n  type: WorkspaceType,\n  role: WorkspaceRole,\n  isOriginalOwner: boolean,\n  isOriginalOwnerResolved: boolean,\n  hasActiveWorkspace: boolean,\n  isTeamPlan: boolean\n): WorkspacePermissions {\n  const canManageBilling = hasActiveWorkspace && role === 'owner'\n  const canLeaveWorkspace =\n    hasActiveWorkspace &&\n    (type === 'personal'\n      ? isTeamPlan &&\n        !isOriginalOwner &&\n        (role === 'member' || isOriginalOwnerResolved)\n      : true)\n  const billingPermissions = {\n    canManageSubscription: canManageBilling,\n    canManageSubscriptionLifecycle: canManageBilling,\n    canDowngradeToPersonal: canManageBilling && isTeamPlan && isOriginalOwner\n  }\n\n  if (role === 'member') {\n    return {\n      canViewOtherMembers: true,\n      canViewPendingInvites: false,\n      canLeaveWorkspace,\n      canAccessWorkspaceMenu: canLeaveWorkspace,\n      ...billingPermissions\n    }\n  }\n\n  if (type === 'personal') {\n    return {\n      canViewOtherMembers: false,\n      canViewPendingInvites: false,\n      canLeaveWorkspace,\n      canAccessWorkspaceMenu: canLeaveWorkspace,\n      ...billingPermissions\n    }\n  }\n\n  return {\n    canViewOtherMembers: true,\n    canViewPendingInvites: true,\n    canLeaveWorkspace,\n    canAccessWorkspaceMenu: true,\n    ...billingPermissions\n  }\n}\n\nfunction getUIConfig(\n  type: WorkspaceType,\n  role: WorkspaceRole\n): WorkspaceUIConfig {\n  if (role === 'member') {\n    return {\n      showMembersList: true,\n      showPendingTab: false,\n      showSearch: true,\n      showRoleColumn: true,\n      showCreditsColumn: false,\n      membersGridCols: 'grid-cols-[1fr_auto]',\n      pendingGridCols: 'grid-cols-[50%_20%_20%_10%]',\n      headerGridCols: 'grid-cols-[1fr_auto]',\n      showEditWorkspaceMenuItem: false,\n      workspaceMenuAction: null,\n      workspaceMenuDisabledTooltip: null\n    }\n  }\n\n  if (type === 'personal') {\n    return {\n      showMembersList: false,\n      showPendingTab: false,\n      showSearch: false,\n      showRoleColumn: false,\n      showCreditsColumn: false,\n      membersGridCols: 'grid-cols-1',\n      pendingGridCols: 'grid-cols-[50%_20%_20%_10%]',\n      headerGridCols: 'grid-cols-1',\n      showEditWorkspaceMenuItem: true,\n      workspaceMenuAction: null,\n      workspaceMenuDisabledTooltip: null\n    }\n  }\n\n  return {\n    showMembersList: true,\n    showPendingTab: true,\n    showSearch: true,\n    showRoleColumn: true,\n    showCreditsColumn: false,\n    membersGridCols: 'grid-cols-[50%_40%_10%]',\n    pendingGridCols: 'grid-cols-[50%_20%_20%_10%]',\n    headerGridCols: 'grid-cols-[50%_40%_10%]',\n    showEditWorkspaceMenuItem: true,\n    workspaceMenuAction: 'delete',\n    workspaceMenuDisabledTooltip:\n      'workspacePanel.menu.deleteWorkspaceDisabledTooltip'\n  }\n}\n\n/**\n * Internal implementation of UI configuration composable.\n */\nfunction useWorkspaceUIInternal() {\n  const store = useTeamWorkspaceStore()\n  const { canAccessSubscriptionFeatures, isTeamPlan, subscription } =\n    useBillingContext()\n  const { flags } = useFeatureFlags()\n\n  const isInPersonalWorkspace = computed(() => store.isInPersonalWorkspace)\n  const isWorkspaceSubscribed = computed(() => store.isWorkspaceSubscribed)\n\n  const workspaceType = computed<WorkspaceType>(\n    () => store.activeWorkspace?.type ?? 'personal'\n  )\n\n  const workspaceRole = computed<WorkspaceRole>(\n    () => store.activeWorkspace?.role ?? 'owner'\n  )\n\n  watch(\n    [() => store.activeWorkspace?.id, () => store.activeWorkspace?.role],\n    () => {\n      if (store.activeWorkspace?.role === 'owner') {\n        void store.ensureMembersLoaded()\n      }\n    },\n    { immediate: true }\n  )\n\n  const { shouldUseWorkspaceBilling } = useBillingRouting()\n  const { canReactivate, canSubscribeSelfServe, snapshotAuthoritative } =\n    useBillingCapabilities()\n\n  const permissions = computed<WorkspacePermissions>(() =>\n    getPermissions(\n      workspaceType.value,\n      workspaceRole.value,\n      store.isCurrentUserOriginalOwner,\n      store.originalOwnerId !== null,\n      store.activeWorkspace !== null,\n      isTeamPlan.value\n    )\n  )\n\n  // legacy_stripe workspaces have no capability projection row, so the\n  // server-resolved can_reactivate is false for them and cannot gate the\n  // action; that rail stays on the membership check.\n  //\n  // Every reactivation surface reads this — the affordances and the handlers\n  // that execute them. They must not diverge: an affordance shown on a\n  // condition the handler does not share offers an action that silently fails,\n  // and the reverse hides a working one.\n  const canReactivatePlan = computed(() =>\n    isCloud && shouldUseWorkspaceBilling.value\n      ? canReactivate.value\n      : permissions.value.canManageSubscriptionLifecycle\n  )\n\n  // Whether the self-serve pricing catalog applies to this workspace at all.\n  // The server resolves can_subscribe_self_serve false for sales-managed tiers\n  // (Enterprise, unrecognized), so every pricing-table entry point — menu\n  // items, settings links, and the ?pricing= deep link — reads this one value.\n  // Same rail split as canReactivatePlan: legacy_stripe has no capability\n  // projection row and stays on the membership check.\n  //\n  // Opening the catalog is navigation, not a billing write — every checkout\n  // endpoint enforces its own policy — so an absent snapshot falls back to\n  // membership rather than stranding a self-serve owner with no route to a\n  // plan. This mirrors canTopUp, which already fails open for owners.\n  const canOpenPricingSurface = computed(() => {\n    if (!isCloud || !shouldUseWorkspaceBilling.value)\n      return permissions.value.canManageSubscription\n    return snapshotAuthoritative.value\n      ? canSubscribeSelfServe.value\n      : permissions.value.canManageSubscription\n  })\n\n  const uiConfig = computed<WorkspaceUIConfig>(() => {\n    const base = getUIConfig(workspaceType.value, workspaceRole.value)\n    const showCreditsColumn =\n      flags.memberCreditLimitsEnabled &&\n      workspaceType.value === 'team' &&\n      workspaceRole.value === 'owner'\n    if (!showCreditsColumn) return base\n\n    return {\n      ...base,\n      showCreditsColumn: true,\n      membersGridCols: 'grid-cols-[38%_18%_30%_14%]',\n      headerGridCols: 'grid-cols-[38%_18%_30%_14%]'\n    }\n  })\n\n  const isOriginalOwner = computed(() => store.isCurrentUserOriginalOwner)\n\n  const isSubscriptionCancelled = computed(\n    () => subscription.value?.isCancelled ?? false\n  )\n\n  const isTeamPlanCancelled = computed(\n    () => isTeamPlan.value && isSubscriptionCancelled.value\n  )\n\n  // The server refuses deleting a workspace until its plan has ended, and a\n  // cancelled plan stays active until cancel_at. Both settings panels read\n  // this so their menus can't desync on a billing-flag change.\n  const isDeleteDisabled = computed(() => canAccessSubscriptionFeatures.value)\n\n  const deleteDisabledTooltipKey = computed(() =>\n    isDeleteDisabled.value ? uiConfig.value.workspaceMenuDisabledTooltip : null\n  )\n\n  return {\n    // Permissions and config\n    permissions,\n    canReactivatePlan,\n    canOpenPricingSurface,\n    uiConfig,\n    workspaceType,\n    workspaceRole,\n    isInPersonalWorkspace,\n    isWorkspaceSubscribed,\n    canAccessSubscriptionFeatures,\n    isOriginalOwner,\n    isSubscriptionCancelled,\n    isTeamPlanCancelled,\n    isDeleteDisabled,\n    deleteDisabledTooltipKey\n  }\n}\n\n/**\n * UI configuration composable derived from workspace state.\n * Controls what UI elements are visible/enabled based on role and workspace type.\n * Uses createSharedComposable to ensure tab state is shared across components.\n */\nexport const useWorkspaceUI = createSharedComposable(useWorkspaceUIInternal)\n","import type {\n  BillingCycle,\n  SubscriptionCheckoutTier\n} from '@comfyorg/account-core/billing'\n\nimport { toTierKey } from '@/platform/cloud/subscription/constants/tierPricing'\nimport type {\n  SubscriptionDuration,\n  SubscriptionTier\n} from '@/platform/workspace/api/workspaceApi'\n\n/** The plan a customer is on, in the telemetry vocabulary; absent when it names none. */\nexport function toCurrentTier(\n  tier: SubscriptionTier | null | undefined\n): SubscriptionCheckoutTier | undefined {\n  if (tier === 'TEAM') return 'team'\n  return (tier && toTierKey(tier)) || undefined\n}\n\nexport function toBillingCycle(\n  duration: SubscriptionDuration | null | undefined\n): BillingCycle | undefined {\n  if (!duration) return undefined\n  return duration === 'ANNUAL' ? 'yearly' : 'monthly'\n}\n","import type { TierKey } from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { BillingCycle } from '@/platform/cloud/subscription/utils/subscriptionTierRank'\nimport type { BillingOpStatusResponse } from '@/platform/workspace/api/workspaceApi'\n\nconst STORAGE_KEY = 'comfy:pending-subscription-checkout'\nconst MAX_AGE_MS = 24 * 60 * 60_000\n\ntype CheckoutTierKey = Exclude<TierKey, 'free' | 'founder'>\n\ntype PendingSubscriptionSelection =\n  | {\n      planMode: 'personal'\n      tierKey: CheckoutTierKey\n      billingCycle: BillingCycle\n    }\n  | {\n      planMode: 'team'\n      teamCreditStopId: string\n      billingCycle: BillingCycle\n    }\n\nexport interface PendingSubscriptionCheckout {\n  operationId: string\n  workspaceId: string\n  ownerUid: string\n  selection: PendingSubscriptionSelection\n  attemptedAt: number\n}\n\nconst CHECKOUT_TIERS: readonly CheckoutTierKey[] = [\n  'standard',\n  'creator',\n  'pro'\n]\n\nfunction isNonEmptyString(value: unknown): value is string {\n  return typeof value === 'string' && value.length > 0\n}\n\nfunction isBillingCycle(value: unknown): value is BillingCycle {\n  return value === 'monthly' || value === 'yearly'\n}\n\nfunction isSelection(value: unknown): value is PendingSubscriptionSelection {\n  if (!value || typeof value !== 'object') return false\n  if (!('planMode' in value) || !('billingCycle' in value)) return false\n  if (!isBillingCycle(value.billingCycle)) return false\n\n  if (value.planMode === 'personal') {\n    return (\n      'tierKey' in value &&\n      CHECKOUT_TIERS.some((tierKey) => tierKey === value.tierKey)\n    )\n  }\n\n  return (\n    value.planMode === 'team' &&\n    'teamCreditStopId' in value &&\n    isNonEmptyString(value.teamCreditStopId)\n  )\n}\n\nfunction isPendingCheckout(\n  value: unknown,\n  now: number\n): value is PendingSubscriptionCheckout {\n  if (!value || typeof value !== 'object') return false\n  if (\n    !('operationId' in value) ||\n    !isNonEmptyString(value.operationId) ||\n    !('workspaceId' in value) ||\n    !isNonEmptyString(value.workspaceId) ||\n    !('ownerUid' in value) ||\n    !isNonEmptyString(value.ownerUid) ||\n    !('attemptedAt' in value) ||\n    typeof value.attemptedAt !== 'number' ||\n    !Number.isFinite(value.attemptedAt) ||\n    value.attemptedAt > now ||\n    now - value.attemptedAt > MAX_AGE_MS ||\n    !('selection' in value)\n  ) {\n    return false\n  }\n  return isSelection(value.selection)\n}\n\nexport function savePendingSubscriptionCheckout(\n  checkout: PendingSubscriptionCheckout\n): void {\n  try {\n    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(checkout))\n  } catch {\n    return\n  }\n}\n\nexport function getPendingSubscriptionCheckout(\n  now = Date.now()\n): PendingSubscriptionCheckout | null {\n  try {\n    const stored = sessionStorage.getItem(STORAGE_KEY)\n    if (!stored) return null\n    const checkout: unknown = JSON.parse(stored)\n    if (isPendingCheckout(checkout, now)) return checkout\n    sessionStorage.removeItem(STORAGE_KEY)\n  } catch {\n    try {\n      sessionStorage.removeItem(STORAGE_KEY)\n    } catch {\n      return null\n    }\n  }\n  return null\n}\n\nexport function clearPendingSubscriptionCheckout(operationId?: string): void {\n  try {\n    if (operationId) {\n      const checkout = getPendingSubscriptionCheckout()\n      if (checkout?.operationId !== operationId) return\n    }\n    sessionStorage.removeItem(STORAGE_KEY)\n  } catch {\n    return\n  }\n}\n\nexport type PollableOperationStatus =\n  | BillingOpStatusResponse['status']\n  | 'timeout'\n\n// A client-side `timeout` is this tab giving up, not the server finishing: an\n// operation awaiting bank authentication stays pending for hours. Dropping the\n// pointer there is the defect. `reconciliation_needed` does belong here — the\n// contract calls it terminal for polling, and the store stops and resolves on\n// it, so retaining the pointer would re-poll a settled operation every reload.\nconst CLEARS_PENDING_POINTER: Record<PollableOperationStatus, boolean> = {\n  pending: false,\n  timeout: false,\n  succeeded: true,\n  failed: true,\n  reconciliation_needed: true\n}\n\nexport function clearPendingSubscriptionCheckoutIfTerminal(\n  operationId: string,\n  status: PollableOperationStatus\n): void {\n  if (!CLEARS_PENDING_POINTER[status]) return\n  clearPendingSubscriptionCheckout(operationId)\n}\n","import { defineAsyncComponent } from 'vue'\nimport { useDialogService } from '@/services/dialogService'\nimport { useWorkspaceDialogs } from '@/platform/workspace/composables/useWorkspaceDialogs'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useBillingRouting } from '@/composables/billing/useBillingRouting'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport {\n  getStopDiscountedMonthlyUsd,\n  mapApiTeamCreditStops\n} from '@comfyorg/account-ui/billing/catalog'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport type {\n  SubscriptionCheckoutSelection,\n  SubscriptionDialogOptions\n} from '@/composables/billing/types'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { toCurrentTier } from '@/platform/cloud/subscription/utils/billingPlanTelemetry'\nimport { useBillingSdkStore } from '@/platform/workspace/billing/sdk/billingSdkStore'\nimport { useBillingOperationStore } from '@/platform/workspace/stores/billingOperationStore'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { getWorkspaceTelemetryContext } from '@/platform/workspace/telemetry/workspaceTelemetryContext'\nimport { useAuthStore } from '@/stores/authStore'\nimport {\n  clearPendingSubscriptionCheckout,\n  clearPendingSubscriptionCheckoutIfTerminal,\n  getPendingSubscriptionCheckout\n} from '@/platform/workspace/utils/pendingSubscriptionCheckout'\nimport type { PendingSubscriptionCheckout } from '@/platform/workspace/utils/pendingSubscriptionCheckout'\n\nconst DIALOG_KEY = 'subscription-required'\nconst RESUME_PRICING_KEY = 'comfy:resume-team-pricing'\n\nfunction paymentIntentSourceOf(\n  options?: SubscriptionDialogOptions\n): PaymentIntentSource | undefined {\n  return options?.paymentIntentSource ?? options?.reason\n}\n\nfunction getInitialPlanMode(\n  explicitMode: SubscriptionDialogOptions['planMode'],\n  isTeamPlan: boolean,\n  hasCurrentPlan: boolean,\n  isPersonalWorkspace: boolean\n): NonNullable<SubscriptionDialogOptions['planMode']> {\n  if (explicitMode) return explicitMode\n  if (isTeamPlan) return 'team'\n  if (hasCurrentPlan) return 'personal'\n  return isPersonalWorkspace ? 'personal' : 'team'\n}\n\nexport const useSubscriptionDialog = () => {\n  const { shouldUseWorkspaceBilling, shouldUseUnifiedPricing } =\n    useBillingRouting()\n  const dialogService = useDialogService()\n  const dialogStore = useDialogStore()\n  const workspaceStore = useTeamWorkspaceStore()\n  const { flags } = useFeatureFlags()\n\n  function hide() {\n    dialogStore.closeDialog({ key: DIALOG_KEY })\n  }\n\n  // Fired here — the choke point every paywall/pricing dialog variant passes\n  // through — so both the legacy and workspace billing paths emit it.\n  function trackModalOpened(reason?: PaymentIntentSource) {\n    // Resolved lazily to avoid the useBillingContext import cycle (see below).\n    const { tier } = useBillingContext()\n    useTelemetry()?.trackSubscription('modal_opened', {\n      current_tier: tier.value?.toLowerCase(),\n      reason,\n      ...getWorkspaceTelemetryContext()\n    })\n  }\n\n  function trackPaywallShown(paymentIntentSource?: PaymentIntentSource) {\n    const { tier } = useBillingContext()\n    useTelemetry()?.trackBillingEvent({\n      operation: 'entry',\n      stage: 'paywall_shown',\n      outcome: 'pending',\n      payment_intent_source: paymentIntentSource,\n      current_tier: toCurrentTier(tier.value)\n    })\n  }\n\n  function showInactiveMemberDialog(\n    paymentIntentSource?: PaymentIntentSource\n  ): boolean {\n    if (!shouldUseWorkspaceBilling.value) return false\n\n    const { permissions } = useWorkspaceUI()\n    if (permissions.value.canManageSubscription) return false\n\n    trackPaywallShown(paymentIntentSource)\n    dialogService.showLayoutDialog({\n      key: DIALOG_KEY,\n      component: defineAsyncComponent(\n        () =>\n          import('@/platform/workspace/components/SubscriptionInactiveMemberDialog.vue')\n      ),\n      props: { onClose: hide }\n    })\n    return true\n  }\n\n  function showPricingTable(options?: SubscriptionDialogOptions) {\n    if (!isCloud) return\n    const paymentIntentSource = paymentIntentSourceOf(options)\n    if (showInactiveMemberDialog(paymentIntentSource)) return\n\n    trackModalOpened(options?.reason)\n    trackPaywallShown(paymentIntentSource)\n\n    const legacyPricingDialogProps = {\n      dismissOnPointerDownOutside: false\n    } as const\n\n    // Jun-5 model: a single unified pricing table (personal/team plan toggle on\n    // one workspace). The billing rail still selects the checkout and top-up\n    // backend, but does not select the pricing table.\n    if (shouldUseUnifiedPricing.value) {\n      // Existing per-member (legacy) team subscribers keep the old tier-based\n      // team table; the unified credit-slider table is for everyone else.\n      // Resolved lazily (not at composable setup): these three composables form\n      // an import cycle (useBillingContext -> useWorkspaceBilling ->\n      // useSubscriptionDialog), so a setup-time read would deref the shared\n      // context before its state is constructed.\n      const { currentPlanSlug, isLegacyTeamPlan, isTeamPlan } =\n        useBillingContext()\n      if (isLegacyTeamPlan.value) {\n        const personalInitialCheckout =\n          options?.initialCheckout?.planMode === 'personal'\n            ? options.initialCheckout\n            : undefined\n        dialogService.showLayoutDialog({\n          key: DIALOG_KEY,\n          component: defineAsyncComponent(\n            () =>\n              import('@/platform/workspace/components/SubscriptionRequiredDialogContentWorkspace.vue')\n          ),\n          props: {\n            onClose: hide,\n            reason: options?.reason,\n            paymentIntentSource,\n            ...(personalInitialCheckout\n              ? {\n                  initialCheckout: personalInitialCheckout,\n                  isPersonal: true\n                }\n              : {})\n          },\n          dialogComponentProps: legacyPricingDialogProps\n        })\n        return\n      }\n\n      dialogService.showLayoutDialog({\n        key: DIALOG_KEY,\n        component: defineAsyncComponent(\n          () =>\n            import('@/platform/workspace/components/SubscriptionRequiredDialogContentUnified.vue')\n        ),\n        props: {\n          onClose: hide,\n          reason: options?.reason,\n          paymentIntentSource,\n          embeddedCheckoutEnabled: flags.embeddedCheckoutEnabled,\n          initialCheckout: options?.initialCheckout,\n          initialPlanMode: getInitialPlanMode(\n            options?.planMode,\n            isTeamPlan.value,\n            currentPlanSlug.value !== null,\n            workspaceStore.isInPersonalWorkspace\n          )\n        },\n        dialogComponentProps: {\n          // A scrim click mid-checkout would silently discard typed card\n          // details and any pending 3DS state; the X is the only close.\n          dismissOnPointerDownOutside: false\n        }\n      })\n      return\n    }\n\n    dialogService.showLayoutDialog({\n      key: DIALOG_KEY,\n      component: defineAsyncComponent(\n        () =>\n          import('@/platform/cloud/subscription/components/SubscriptionRequiredDialogContent.vue')\n      ),\n      props: {\n        onClose: hide,\n        reason: options?.reason,\n        paymentIntentSource,\n        onChooseTeam: () => startTeamWorkspaceUpgradeFlow()\n      },\n      dialogComponentProps: legacyPricingDialogProps\n    })\n  }\n\n  function show(options?: SubscriptionDialogOptions) {\n    if (isCloud && showInactiveMemberDialog(paymentIntentSourceOf(options))) {\n      return\n    }\n\n    showPricingTable(options)\n  }\n\n  /**\n   * Start the two-stage team workspace upgrade flow:\n   * 1. Close the current pricing dialog\n   * 2. Open the create workspace dialog\n   * 3. On successful creation, persist a resume intent so the team pricing\n   *    dialog reopens automatically after the page reload\n   *\n   * Uses sessionStorage (not a store) because the intent must survive\n   * a full page reload triggered by workspace switching.\n   */\n  function startTeamWorkspaceUpgradeFlow() {\n    hide()\n    useWorkspaceDialogs()\n      .showTeamWorkspacesDialog(() => {\n        try {\n          sessionStorage.setItem(RESUME_PRICING_KEY, '1')\n        } catch {\n          // sessionStorage may be unavailable\n        }\n      })\n      .catch((error) => {\n        console.error(\n          '[useSubscriptionDialog] Failed to open team workspaces dialog:',\n          error\n        )\n        showPricingTable()\n      })\n  }\n\n  async function restoreCheckoutSelection(\n    pending: PendingSubscriptionCheckout\n  ): Promise<SubscriptionCheckoutSelection | null> {\n    const selection = pending.selection\n    if (selection.planMode === 'personal') return selection\n\n    const {\n      fetchPlans,\n      fetchStatus,\n      teamCreditStops,\n      currentTeamCreditStop,\n      subscription,\n      subscriptionStatus\n    } = useBillingContext()\n    await Promise.all([fetchPlans(), fetchStatus()])\n    const stop = mapApiTeamCreditStops(teamCreditStops.value?.stops ?? []).find(\n      ({ id }) => id === selection.teamCreditStopId\n    )\n    if (!stop?.id) return null\n\n    return {\n      planMode: 'team',\n      stop: {\n        id: stop.id,\n        usd: stop.usd,\n        credits: stop.credits,\n        discountedUsd: getStopDiscountedMonthlyUsd(stop, selection.billingCycle)\n      },\n      billingCycle: selection.billingCycle,\n      isChange:\n        currentTeamCreditStop.value !== null &&\n        subscriptionStatus.value !== 'ended' &&\n        (currentTeamCreditStop.value.id !== stop.id ||\n          (subscription.value?.duration === 'MONTHLY'\n            ? 'monthly'\n            : 'yearly') !== selection.billingCycle)\n    }\n  }\n\n  async function resumePendingCheckout(\n    pending: PendingSubscriptionCheckout\n  ): Promise<void> {\n    if (\n      pending.workspaceId !== workspaceStore.activeWorkspaceId ||\n      pending.ownerUid !== useAuthStore().userId\n    ) {\n      clearPendingSubscriptionCheckout(pending.operationId)\n      return\n    }\n\n    // The host pointer stays as it is: it carries the tier/cycle selection the\n    // pricing dialog restores below, which the SDK's scope-keyed pointer\n    // deliberately does not. Only who drives the operation moves.\n    const operation = flags.billingSdkSubscriptionRailEnabled\n      ? await useBillingSdkStore().recoverPendingOperation(pending.operationId)\n      : await useBillingOperationStore().startOperation(\n          pending.operationId,\n          'subscription',\n          {\n            tier:\n              pending.selection.planMode === 'personal'\n                ? pending.selection.tierKey\n                : 'team',\n            cycle: pending.selection.billingCycle,\n            attemptStartedAt: pending.attemptedAt\n          }\n        )\n    // Nothing to adopt: the server names no pending operation for this scope,\n    // so the parked pointer is stale and the customer is not mid-checkout.\n    if (!operation) {\n      clearPendingSubscriptionCheckout(pending.operationId)\n      return\n    }\n    clearPendingSubscriptionCheckoutIfTerminal(\n      pending.operationId,\n      operation.status\n    )\n    if (operation.status !== 'failed') return\n\n    const initialCheckout = await restoreCheckoutSelection(pending)\n    showPricingTable({\n      planMode: pending.selection.planMode,\n      ...(initialCheckout && { initialCheckout })\n    })\n  }\n\n  function resumePendingPricingFlow(): Promise<void> | void {\n    const pendingCheckout = getPendingSubscriptionCheckout()\n    if (pendingCheckout) return resumePendingCheckout(pendingCheckout)\n\n    try {\n      const pending = sessionStorage.getItem(RESUME_PRICING_KEY)\n      if (!pending) return\n      sessionStorage.removeItem(RESUME_PRICING_KEY)\n\n      if (!workspaceStore.isInPersonalWorkspace) {\n        showPricingTable({\n          reason: 'team_upgrade_resume',\n          planMode: 'team'\n        })\n      }\n    } catch {\n      // sessionStorage may be unavailable\n    }\n  }\n\n  return {\n    show,\n    showPricingTable,\n    hide,\n    startTeamWorkspaceUpgradeFlow,\n    resumePendingPricingFlow\n  }\n}\n","/**\n * The one place that opens a hosted billing tab. Every entry point — the\n * avatar menu's Plans and pricing, the workspace settings' Billing &\n * invoices, and a future in-app subscribe CTA — routes through here so the\n * workspace the host is showing is always the one billing-web operates on,\n * and a return to the app always refreshes the same state.\n */\nimport type { BillingIntent } from '@comfyorg/billing-contract'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport { reserveBillingTab } from '@/platform/workspace/billing/billingTab'\nimport { hostedBillingRoute } from '@/platform/workspace/billing/hostedBillingRoutes'\nimport { registerRefreshOnReturn } from '@/platform/workspace/billing/refreshOnReturn'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { createJourneyId } from '@/platform/workspace/utils/checkoutJourney'\n\nexport interface OpenHostedBillingTabOptions {\n  readonly plan?: string\n  readonly teamCreditStopId?: string\n  /** Why the customer asked, when the click knew. */\n  readonly source?: PaymentIntentSource\n  /** The cloud journey this hands off; one is minted when the entry has none. */\n  readonly journeyId?: string\n}\n\nlet stopReturnRefresh: (() => void) | null = null\nlet stopOperationWatch: (() => void) | null = null\n\nexport function disarmHostedBillingReturnRefresh(): void {\n  stopReturnRefresh?.()\n  stopReturnRefresh = null\n  stopOperationWatch?.()\n  stopOperationWatch = null\n}\n\nconst OPERATION_INTENTS: ReadonlySet<BillingIntent> = new Set([\n  'checkout',\n  'subscription'\n])\nconst OPERATION_POLL_MS = 4_000\nconst OPERATION_WATCH_MS = 15 * 60_000\n\n/**\n * A payment billing-web takes never pushes back to this tab, but a status read\n * resumes the operation the server reports pending, and that operation then\n * polls itself and shows the same progress and outcome toasts the embedded\n * checkout shows. This reads until one is found, for the workspace the tab\n * was opened for only. A read still in flight skips the tick, and a failed\n * read waits for the next one.\n */\nfunction watchForHostedOperation(\n  readOperation: () => Promise<boolean>,\n  workspaceId: string | undefined\n) {\n  const workspaceStore = useTeamWorkspaceStore()\n  const startedAt = Date.now()\n  let reading = false\n  const timer = setInterval(() => {\n    if (\n      Date.now() - startedAt >= OPERATION_WATCH_MS ||\n      (workspaceStore.activeWorkspaceId ?? undefined) !== workspaceId\n    ) {\n      clearInterval(timer)\n      return\n    }\n    if (reading) return\n    reading = true\n    void readOperation()\n      .then((found) => {\n        if (found) clearInterval(timer)\n      })\n      .catch(() => undefined)\n      .finally(() => {\n        reading = false\n      })\n  }, OPERATION_POLL_MS)\n  return () => clearInterval(timer)\n}\n\nfunction armReturnRefresh(\n  intent: BillingIntent,\n  workspaceId: string | undefined\n): void {\n  disarmHostedBillingReturnRefresh()\n  // Resolved inside the call, not at module scope: useBillingContext ->\n  // useWorkspaceBilling -> this module would otherwise dereference the\n  // shared context before its state is constructed.\n  const { fetchStatus, fetchBalance, readCheckoutOperation } =\n    useBillingContext()\n  stopReturnRefresh = registerRefreshOnReturn(() =>\n    Promise.allSettled([\n      fetchStatus(),\n      fetchBalance(),\n      useBillingCapabilities().refresh()\n    ])\n  )\n  if (OPERATION_INTENTS.has(intent)) {\n    stopOperationWatch = watchForHostedOperation(\n      readCheckoutOperation,\n      workspaceId\n    )\n  }\n}\n\nexport type HostedBillingTabOutcome = 'opened' | 'unavailable' | 'blocked'\n\n/**\n * Opens `intent` in a hosted billing tab carrying the active workspace, and\n * arms the same-state refresh for when the customer comes back. Reports\n * `unavailable` when the destination isn't billing_web and `blocked` when the\n * browser refused the tab.\n */\nexport function openHostedBillingTabOutcome(\n  intent: BillingIntent,\n  options: OpenHostedBillingTabOptions = {}\n): HostedBillingTabOutcome {\n  const { flags } = useFeatureFlags()\n  const workspaceId = useTeamWorkspaceStore().activeWorkspaceId ?? undefined\n  const correlationId = options.journeyId ?? createJourneyId()\n  const route = hostedBillingRoute(flags.hostedBillingDestination, intent, {\n    plan: options.plan,\n    teamCreditStopId: options.teamCreditStopId,\n    workspaceId,\n    correlationId,\n    source: options.source\n  })\n  if (route.kind !== 'billing_web') return 'unavailable'\n  const tab = reserveBillingTab()\n  tab?.navigate(route.url.href)\n  const result = tab ? 'opened' : 'blocked'\n  useTelemetry()?.trackBillingEvent({\n    operation: 'web_handoff',\n    stage: 'opened',\n    outcome: 'pending',\n    intent,\n    result,\n    payment_intent_source: options.source,\n    correlation_id: correlationId\n  })\n  if (result === 'opened') armReturnRefresh(intent, workspaceId)\n  return result\n}\n\n/**\n * {@link openHostedBillingTabOutcome} for callers whose fallback is the same\n * whether the destination isn't billing_web or the tab was blocked.\n */\nexport function openHostedBillingTab(\n  intent: BillingIntent,\n  options: OpenHostedBillingTabOptions = {}\n): boolean {\n  return openHostedBillingTabOutcome(intent, options) === 'opened'\n}\n","import { computed } from 'vue'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useBillingSdkStore } from '@/platform/workspace/billing/sdk/billingSdkStore'\nimport type { SubscriptionRail } from '@/platform/workspace/billing/sdk/subscriptionOperationView'\nimport { useBillingOperationStore } from '@/platform/workspace/stores/billingOperationStore'\n\n/**\n * Which rail cancel, resubscribe and the payment portal run on. Null is the\n * legacy path.\n *\n * Read once at the start of an action and held for the whole of it, for the\n * same reason as `useTopupOperation`: a flag flip mid-flow must not issue on\n * one rail and observe the result on the other.\n */\nexport function useSubscriptionRail(): SubscriptionRail | null {\n  const { flags } = useFeatureFlags()\n  return flags.billingSdkSubscriptionRailEnabled ? useBillingSdkStore() : null\n}\n\n/**\n * The pending subscription operation as the billing surfaces read it, from\n * whichever rail owns it. The reads are the commands' other half: an operation\n * issued on the SDK rail is driven by the lifecycle, so a surface reading the\n * legacy store describes one nothing is writing.\n */\nexport function useSubscriptionOperationView() {\n  const { flags } = useFeatureFlags()\n  const sdkStore = flags.billingSdkSubscriptionRailEnabled\n    ? useBillingSdkStore()\n    : null\n  const operationStore = useBillingOperationStore()\n\n  const isSettingUp = computed(() =>\n    sdkStore ? sdkStore.isSettingUp : operationStore.isSettingUp\n  )\n\n  const subscriptionActionUrl = computed(\n    () =>\n      (sdkStore ?? operationStore).subscriptionActionOperation?.actionUrl ??\n      null\n  )\n\n  return { isSettingUp, subscriptionActionUrl }\n}\n","/**\n * The host's subscribe options as the generated request body, field for field,\n * including the two the workspace client drops when they arrive empty: JSON\n * keeps `''`, so an empty credential would reach the server as present but\n * meaningless.\n *\n * `SubscribeOptions` carries nothing the generated body lacks. `SubscribeInput`\n * also has `checkout_attempt_id` and `idempotency_key`, which no host caller\n * sets: the SDK mints the key itself, and the checkout attempt is carried on\n * the quote rather than the subscribe.\n *\n * Shared so the two call sites that issue a subscribe on the rail — the\n * workspace billing adapter and the team deep-link checkout — send one body.\n */\nimport type { SubscribeInput } from '@comfyorg/account-core/billing'\n\nimport type { SubscribeOptions } from '@/platform/workspace/api/workspaceApi'\n\nexport function subscribeInputFrom(\n  planSlug: string,\n  options: SubscribeOptions = {}\n): SubscribeInput {\n  return {\n    plan_slug: planSlug,\n    confirmation_token: options.confirmationToken || undefined,\n    saved_payment_method_id: options.savedPaymentMethodId || undefined,\n    promotion_code: options.promotionCode,\n    quote_id: options.quoteId,\n    quote_version: options.quoteVersion,\n    return_url: options.returnUrl,\n    cancel_url: options.cancelUrl,\n    team_credit_stop_id: options.teamCreditStopId,\n    billing_cycle: options.billingCycle,\n    confirm_reactivation: options.confirmReactivation,\n    proration_at: options.prorationAt\n  }\n}\n","import {\n  computed,\n  getCurrentScope,\n  onScopeDispose,\n  ref,\n  shallowRef,\n  watch\n} from 'vue'\n\nimport type {\n  BillingClient,\n  BillingTelemetryFailure,\n  PreviewSubscribeInput\n} from '@comfyorg/account-core/billing'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { t } from '@/i18n'\nimport { useBillingPlans } from '@/platform/cloud/subscription/composables/useBillingPlans'\nimport { useSubscriptionDialog } from '@/platform/cloud/subscription/composables/useSubscriptionDialog'\nimport type { SubscriptionDialogOptions } from '@/composables/billing/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { categorizeBillingApiError } from '@/platform/telemetry/utils/billingFailureCategory'\nimport { createBillingPortalReporter } from '@/platform/telemetry/utils/billingPortalTelemetry'\nimport type {\n  BillingBalanceResponse,\n  BillingStatusResponse,\n  CreateTopupResponse,\n  PreviewSubscribeOptions,\n  PreviewSubscribeResponse,\n  SubscribeOptions\n} from '@/platform/workspace/api/workspaceApi'\nimport {\n  WorkspaceApiError,\n  workspaceApi\n} from '@/platform/workspace/api/workspaceApi'\nimport { reserveBillingTab } from '@/platform/workspace/billing/billingTab'\nimport { openHostedBillingTabOutcome } from '@/platform/workspace/billing/openHostedBillingTab'\nimport { registerRefreshOnReturn } from '@/platform/workspace/billing/refreshOnReturn'\nimport { useBillingSdkStore } from '@/platform/workspace/billing/sdk/billingSdkStore'\nimport type {\n  SettledSubscribeResponse,\n  SubscriptionRailOutcome\n} from '@/platform/workspace/billing/sdk/subscriptionOperationView'\nimport { SettledOperationError } from '@/platform/workspace/billing/sdk/subscriptionOperationView'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { readOnRail } from '@/platform/workspace/composables/readOnRail'\nimport type { BillingReadRail } from '@/platform/workspace/composables/useBillingReadRail'\nimport { useBillingReadRail } from '@/platform/workspace/composables/useBillingReadRail'\nimport { useSubscriptionRail } from '@/platform/workspace/composables/useSubscriptionRail'\nimport { useBillingOperationStore } from '@/platform/workspace/stores/billingOperationStore'\nimport { subscribeInputFrom } from '@/platform/workspace/billing/subscribeInput'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\n\nimport type {\n  BalanceInfo,\n  BillingActions,\n  BillingState,\n  SubscriptionInfo\n} from '../../../composables/billing/types'\n\nexport class CancellationScopeChangedError extends Error {\n  constructor(message: string) {\n    super(message)\n    this.name = 'CancellationScopeChangedError'\n  }\n}\n\nfunction assertCancellationScopeCurrent(isScopeCurrent: () => boolean): void {\n  if (isScopeCurrent()) return\n  throw new CancellationScopeChangedError(\n    t('subscription.cancelDialog.workspaceChanged')\n  )\n}\n\n/**\n * Which client path resumes a recovered operation. Exhaustive on purpose: the\n * two-way check this replaces sent anything that was not `topup` down the\n * subscription path, which covers the customer's real plan with a \"setting up\n * your subscription\" spinner until the operation settles.\n */\nfunction resumeModeFor(\n  type: BillingStatusResponse['pending_billing_op_type']\n): 'subscription' | 'topup' {\n  switch (type) {\n    case 'topup':\n      return 'topup'\n    case 'subscription':\n      return 'subscription'\n    // A server predating the field only ever had subscriptions to hand back.\n    case undefined:\n      return 'subscription'\n    default: {\n      const unexpected: never = type\n      // JSON.stringify, not String: the latter throws on a value with no\n      // callable toString/valueOf, and throwing out of the branch that exists\n      // to absorb a bad value would abort recovery entirely. The value came\n      // from a parsed response, so it cannot be circular.\n      reportError(\n        new Error(\n          `Unknown pending billing op type: ${JSON.stringify(unexpected)}`\n        ),\n        {\n          surface: 'workspace',\n          errorType: 'billing_unknown_resume_mode'\n        }\n      )\n      // Reachable only against a newer server. Dropping recovery strands a\n      // customer who cannot reach the payment page; a wrong panel clears on\n      // reload, so recovery wins.\n      return 'subscription'\n    }\n  }\n}\n\n/**\n * Whether a rejection means the subscription already holds the state the caller\n * asked for. The request did nothing, but the user's intent is satisfied, so\n * surfacing it as a failure would report a problem that does not exist — most\n * visibly when a request succeeds and its response is lost, and the retry is\n * then refused.\n *\n * The 4xx check keeps a server fault that happens to echo one of these codes\n * from being swallowed as success.\n */\nfunction isAlreadyInRequestedState(err: unknown, code: string): boolean {\n  return (\n    err instanceof WorkspaceApiError &&\n    err.code === code &&\n    err.status !== undefined &&\n    err.status >= 400 &&\n    err.status < 500\n  )\n}\n\n/**\n * Refreshes local state after a no-op, without letting the refresh overturn the\n * outcome. The desired state already holds on the server, so a failed read must\n * not turn it back into a reported failure — which is exactly what would happen\n * on the flaky network that caused the no-op in the first place.\n */\nasync function resyncQuietly(refresh: () => Promise<unknown>): Promise<void> {\n  try {\n    await refresh()\n  } catch {\n    // Intentionally ignored: the next read corrects the view.\n  }\n}\n\n/** The SDK rail refusing an action, distinct from any value it could return. */\nconst DECLINED = Symbol('subscription rail declined')\n\nfunction previewSubscribeInputFrom(\n  planSlug: string,\n  options: PreviewSubscribeOptions = {}\n): PreviewSubscribeInput {\n  return {\n    planSlug,\n    ...(options.promotionCode === undefined\n      ? {}\n      : { promotionCode: options.promotionCode }),\n    ...(options.teamCreditStopId === undefined\n      ? {}\n      : { teamCreditStopId: options.teamCreditStopId })\n  }\n}\n\ninterface SeatCapacity {\n  maxSeats: number\n  occupiedSeats: number\n}\n\nfunction seatCapacityFrom(status: BillingStatusResponse): SeatCapacity | null {\n  if (\n    typeof status.max_seats === 'number' &&\n    Number.isInteger(status.max_seats) &&\n    status.max_seats >= 0 &&\n    typeof status.occupied_seats === 'number' &&\n    Number.isInteger(status.occupied_seats) &&\n    status.occupied_seats >= 0\n  ) {\n    return {\n      maxSeats: status.max_seats,\n      occupiedSeats: status.occupied_seats\n    }\n  }\n  return null\n}\n\n/**\n * Adapter for workspace-scoped billing via /billing/* endpoints.\n * Used for team workspaces.\n * @internal - Use useBillingContext() instead of importing directly.\n */\nexport type WorkspaceBilling = BillingState &\n  BillingActions & {\n    /**\n     * Reads status and resolves true once the operation it reports pending\n     * has been adopted, so its own polling shows progress and outcome.\n     */\n    readAndAdoptPendingOperation: () => Promise<boolean>\n  }\n\nexport function useWorkspaceBilling(): WorkspaceBilling {\n  const billingPlans = useBillingPlans()\n  const billingOperationStore = useBillingOperationStore()\n  const workspaceStore = useTeamWorkspaceStore()\n  const telemetry = useTelemetry()\n  const { flags } = useFeatureFlags()\n\n  const isInitialized = ref(false)\n  const isLoading = ref(false)\n  const error = ref<string | null>(null)\n\n  const statusData = shallowRef<BillingStatusResponse | null>(null)\n  let adoption: Promise<boolean> = Promise.resolve(false)\n  const seatCapacity = shallowRef<SeatCapacity | null>(null)\n  const balanceData = shallowRef<BillingBalanceResponse | null>(null)\n  // Prevent older status and balance responses from overwriting newer state.\n  const latestBillingReadIds = { status: 0, balance: 0 }\n\n  const canAccessSubscriptionFeatures = computed(\n    () => statusData.value?.is_active ?? false\n  )\n  const isFreeTier = computed(\n    () => statusData.value?.subscription_tier === 'FREE'\n  )\n\n  const subscription = computed<SubscriptionInfo | null>(() => {\n    const status = statusData.value\n    if (!status) return null\n\n    return {\n      isActive: status.is_active,\n      tier: status.subscription_tier ?? null,\n      duration: status.subscription_duration ?? null,\n      planSlug: status.plan_slug ?? null,\n      scheduledChange: status.scheduled_change ?? null,\n      renewalDate: status.renewal_date ?? null,\n      endDate: status.cancel_at ?? null,\n      isCancelled: status.subscription_status === 'canceled',\n      hasFunds: status.has_funds,\n      agentHasFunds:\n        status.scoped_effective_has_funds?.agent ?? status.has_funds,\n      agentScopedHasFunds: status.scoped_has_funds?.agent\n    }\n  })\n\n  const balance = computed<BalanceInfo | null>(() => {\n    const data = balanceData.value\n    if (!data) return null\n\n    return {\n      amountMicros: data.amount_micros,\n      currency: data.currency,\n      effectiveBalanceMicros:\n        data.effective_balance_micros ?? data.amount_micros,\n      prepaidBalanceMicros: data.prepaid_balance_micros ?? 0,\n      cloudCreditBalanceMicros: data.cloud_credit_balance_micros ?? 0\n    }\n  })\n\n  const billingStatus = computed(() => statusData.value?.billing_status ?? null)\n  const subscriptionStatus = computed(\n    () => statusData.value?.subscription_status ?? null\n  )\n  const tier = computed(() => statusData.value?.subscription_tier ?? null)\n  const renewalDate = computed(() => statusData.value?.renewal_date ?? null)\n  const renewalInvoice = computed(\n    () => statusData.value?.renewal_invoice ?? null\n  )\n\n  const plans = computed(() => billingPlans.plans.value)\n  const currentPlanSlug = computed(\n    () => statusData.value?.plan_slug ?? billingPlans.currentPlanSlug.value\n  )\n  const teamCreditStops = computed(() => billingPlans.teamCreditStops.value)\n  const currentTeamCreditStop = computed(\n    () => statusData.value?.team_credit_stop ?? null\n  )\n  const maxSeats = computed(() => seatCapacity.value?.maxSeats ?? null)\n  const occupiedSeats = computed(\n    () => seatCapacity.value?.occupiedSeats ?? null\n  )\n\n  watch(\n    () => workspaceStore.activeWorkspace?.id,\n    () => {\n      seatCapacity.value = null\n    }\n  )\n\n  async function initialize(): Promise<void> {\n    if (isInitialized.value) return\n\n    isLoading.value = true\n    error.value = null\n    try {\n      await Promise.all([fetchStatus(), fetchBalance(), fetchPlans()])\n      // Re-fetch balance if free tier credits were just lazily granted\n      if (isFreeTier.value && balance.value?.amountMicros === 0) {\n        await fetchBalance()\n      }\n      isInitialized.value = true\n    } catch (err) {\n      error.value =\n        err instanceof Error ? err.message : 'Failed to initialize billing'\n      throw err\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  /**\n   * Whether the rail that issues this kind of operation is the one that owns a\n   * pending one at load. Adopting on the other rail is what makes a mid-session\n   * flag flip ambiguous: the operation's writes went one way and its poller the\n   * other.\n   *\n   * A server predating `pending_billing_op_type` only ever had subscriptions to\n   * hand back, so it follows the subscription rail — the same reading\n   * `resumeModeFor` takes of an absent field.\n   */\n  function railOwnsResume(\n    type: BillingStatusResponse['pending_billing_op_type']\n  ): boolean {\n    return type === 'topup'\n      ? flags.billingSdkTopupRailEnabled\n      : flags.billingSdkSubscriptionRailEnabled\n  }\n\n  async function resumePendingOperation(\n    status: BillingStatusResponse\n  ): Promise<boolean> {\n    if (!status.pending_billing_op_id) return false\n    if (billingOperationStore.getOperation(status.pending_billing_op_id)) {\n      return true\n    }\n    if (railOwnsResume(status.pending_billing_op_type)) {\n      return useBillingSdkStore()\n        .recover()\n        .catch(() => false)\n    }\n    void billingOperationStore.startOperation(\n      status.pending_billing_op_id,\n      resumeModeFor(status.pending_billing_op_type),\n      { resumed: true },\n      status.action_url\n    )\n    return true\n  }\n\n  function isStaleStatusRead(\n    requestId: number,\n    workspaceId: string | undefined\n  ): boolean {\n    return (\n      requestId !== latestBillingReadIds.status ||\n      workspaceId !== workspaceStore.activeWorkspace?.id\n    )\n  }\n\n  async function readAndAdoptPendingOperation(): Promise<boolean> {\n    await fetchStatus()\n    return adoption\n  }\n\n  async function fetchStatus(): Promise<void> {\n    adoption = Promise.resolve(false)\n    const requestId = ++latestBillingReadIds.status\n    const workspaceId = workspaceStore.activeWorkspace?.id\n    const rail: BillingReadRail | null = useBillingReadRail()\n    isLoading.value = true\n    error.value = null\n    try {\n      const status = rail\n        ? await readOnRail(rail.readStatus, 'getBillingStatus')\n        : await workspaceApi.getBillingStatus()\n      if (status === undefined || isStaleStatusRead(requestId, workspaceId))\n        return\n\n      seatCapacity.value = seatCapacityFrom(status)\n      statusData.value = status\n      if (workspaceId && status.billing_rail) {\n        workspaceStore.setWorkspaceBillingRail(workspaceId, status.billing_rail)\n      }\n      adoption = resumePendingOperation(status)\n    } catch (err) {\n      if (requestId === latestBillingReadIds.status) {\n        error.value =\n          err instanceof Error ? err.message : 'Failed to fetch billing status'\n      }\n      throw err\n    } finally {\n      if (requestId === latestBillingReadIds.status) isLoading.value = false\n    }\n  }\n\n  async function fetchBalance(): Promise<void> {\n    const requestId = ++latestBillingReadIds.balance\n    const rail: BillingReadRail | null = useBillingReadRail()\n    isLoading.value = true\n    error.value = null\n    try {\n      const balance = rail\n        ? await readOnRail(rail.readBalance, 'getBillingBalance')\n        : await workspaceApi.getBillingBalance()\n      if (balance !== undefined && requestId === latestBillingReadIds.balance) {\n        balanceData.value = balance\n      }\n    } catch (err) {\n      if (requestId === latestBillingReadIds.balance) {\n        error.value =\n          err instanceof Error ? err.message : 'Failed to fetch balance'\n      }\n      throw err\n    } finally {\n      if (requestId === latestBillingReadIds.balance) isLoading.value = false\n    }\n  }\n\n  async function retryBillingRead(\n    fetchBillingResource: () => Promise<void>,\n    billingResource: keyof typeof latestBillingReadIds\n  ): Promise<{ failed: boolean; requestId: number }> {\n    const firstAttempt = fetchBillingResource()\n    const firstRequestId = latestBillingReadIds[billingResource]\n    try {\n      await firstAttempt\n      return { failed: false, requestId: firstRequestId }\n    } catch {\n      if (firstRequestId !== latestBillingReadIds[billingResource]) {\n        return { failed: false, requestId: firstRequestId }\n      }\n    }\n\n    const retry = fetchBillingResource()\n    const retryRequestId = latestBillingReadIds[billingResource]\n    try {\n      await retry\n      return { failed: false, requestId: retryRequestId }\n    } catch {\n      return {\n        failed: retryRequestId === latestBillingReadIds[billingResource],\n        requestId: retryRequestId\n      }\n    }\n  }\n\n  async function reconcileBillingStateAfterSubscribe(): Promise<void> {\n    const [statusResult, balanceResult] = await Promise.all([\n      retryBillingRead(fetchStatus, 'status'),\n      retryBillingRead(fetchBalance, 'balance')\n    ])\n    const statusFailed =\n      statusResult.failed &&\n      statusResult.requestId === latestBillingReadIds.status\n    const balanceFailed =\n      balanceResult.failed &&\n      balanceResult.requestId === latestBillingReadIds.balance\n\n    if (statusFailed || balanceFailed) {\n      error.value = 'Subscription succeeded, but billing state refresh failed'\n    }\n  }\n\n  async function subscribe(\n    planSlug: string,\n    options?: SubscribeOptions\n  ): Promise<SettledSubscribeResponse> {\n    const rail = useSubscriptionRail()\n    const attemptStartedAt = options?.attemptStartedAt\n    if (rail?.subscriptionRouteAvailable) {\n      const response = await onSubscriptionRail(() =>\n        rail.subscribe(subscribeInputFrom(planSlug, options), {\n          callerStarted: attemptStartedAt !== undefined\n        })\n      )\n      // The SDK waited for the operation, so the refresh the legacy path fires\n      // and forgets has already run on the rail.\n      if (response !== DECLINED) return response\n      if (attemptStartedAt !== undefined) {\n        // The caller started this attempt on the rail; the legacy call is its own attempt.\n        telemetry?.trackBillingEvent({\n          operation: 'operation',\n          stage: 'failed',\n          outcome: 'failure',\n          operation_type: 'subscription',\n          billing_client: 'sdk',\n          failure_category: 'api_rejected',\n          duration_ms: Date.now() - attemptStartedAt\n        })\n        telemetry?.trackBillingEvent({\n          operation: 'operation',\n          stage: 'started',\n          outcome: 'pending',\n          operation_type: 'subscription',\n          billing_client: 'legacy'\n        })\n      }\n    }\n\n    isLoading.value = true\n    error.value = null\n    try {\n      const response = await workspaceApi.subscribe(planSlug, options)\n      isLoading.value = false\n      void reconcileBillingStateAfterSubscribe()\n      return response\n    } catch (err) {\n      error.value = err instanceof Error ? err.message : 'Failed to subscribe'\n      isLoading.value = false\n      throw err\n    }\n  }\n\n  async function previewSubscribe(\n    planSlug: string,\n    options?: PreviewSubscribeOptions\n  ): Promise<PreviewSubscribeResponse | null> {\n    const rail = useSubscriptionRail()\n    if (rail) {\n      const quote = await onSubscriptionRail(() =>\n        rail.previewSubscribe(previewSubscribeInputFrom(planSlug, options))\n      )\n      if (quote !== DECLINED) return quote\n    }\n\n    isLoading.value = true\n    error.value = null\n    try {\n      return await workspaceApi.previewSubscribe(planSlug, options)\n    } catch (err) {\n      error.value =\n        err instanceof Error ? err.message : 'Failed to preview subscription'\n      throw err\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  // A cancellation or card change made in the portal window never pushes\n  // back to this one — status has no return refetch and capability reads\n  // are paced — so the next return to the app re-reads everything the\n  // portal could have changed.\n  let stopPortalReturnRefresh: (() => void) | null = null\n  function refreshOnPortalReturn() {\n    stopPortalReturnRefresh?.()\n    stopPortalReturnRefresh = registerRefreshOnReturn(() =>\n      Promise.allSettled([\n        fetchStatus(),\n        fetchBalance(),\n        useBillingCapabilities().refresh()\n      ])\n    )\n  }\n\n  if (getCurrentScope()) {\n    onScopeDispose(() => {\n      stopPortalReturnRefresh?.()\n    })\n  }\n\n  /**\n   * Runs one action on the SDK rail and reports into this adapter's own\n   * state. `DECLINED` means the routes are not deployed on this backend, so\n   * the caller runs its legacy path.\n   */\n  async function onSubscriptionRail<T>(\n    run: () => Promise<SubscriptionRailOutcome<T>>\n  ): Promise<T | typeof DECLINED> {\n    isLoading.value = true\n    error.value = null\n    try {\n      const outcome = await run()\n      if (outcome.status === 'unavailable') return DECLINED\n      if (outcome.status === 'error') {\n        error.value = outcome.error.message\n        throw outcome.error\n      }\n      return outcome.value\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  function reportBillingTabBlocked(): void {\n    useToast().warning(t('g.warning'), {\n      description: t('subscription.billingTabBlocked')\n    })\n  }\n\n  /** The rail's portal URL, or the legacy client's when the rail declines. */\n  async function requestPortalUrl(): Promise<{\n    url: string | undefined\n    billingClient: BillingClient\n  }> {\n    const rail = useSubscriptionRail()\n    if (rail) {\n      const url = await onSubscriptionRail(() =>\n        rail.openPaymentPortal(window.location.href)\n      )\n      if (url !== DECLINED) return { url, billingClient: 'sdk' }\n    }\n\n    isLoading.value = true\n    error.value = null\n    try {\n      const returnUrl = window.location.href\n      const response = await workspaceApi.getPaymentPortalUrl(returnUrl)\n      return { url: response.url || undefined, billingClient: 'legacy' }\n    } catch (err) {\n      error.value =\n        err instanceof Error ? err.message : 'Failed to open billing portal'\n      throw err\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  // Layer C first; the rail, and then the legacy client, only when the one\n  // before them doesn't serve this workspace. The portal tab is reserved\n  // before the first request: one opened after it resolves has lost the\n  // click's activation, and a refused reservation mints no portal session.\n  async function manageSubscription(): Promise<void> {\n    error.value = null\n    const hosted = openHostedBillingTabOutcome('payment-methods')\n    if (hosted === 'opened') return\n    if (hosted === 'blocked') return reportBillingTabBlocked()\n\n    const portal = createBillingPortalReporter(telemetry, 'manage_subscription')\n    const portalTab = reserveBillingTab()\n    if (!portalTab) {\n      portal.blocked()\n      return reportBillingTabBlocked()\n    }\n    try {\n      const { url, billingClient } = await requestPortalUrl()\n      if (!url) {\n        portal.failed(undefined, billingClient)\n        return portalTab.close()\n      }\n      portalTab.navigate(url)\n      portal.opened(billingClient)\n      refreshOnPortalReturn()\n    } catch (err) {\n      portalTab.close()\n      portal.failed(err)\n      throw err\n    }\n  }\n\n  async function cancelSubscription(\n    isScopeCurrent: () => boolean = () => true\n  ): Promise<void> {\n    assertCancellationScopeCurrent(isScopeCurrent)\n    const attemptStartedAt = Date.now()\n    const rail = useSubscriptionRail()\n    const trackCancelStarted = (billingClient: BillingClient) =>\n      telemetry?.trackBillingEvent({\n        operation: 'operation',\n        stage: 'started',\n        outcome: 'pending',\n        operation_type: 'cancel',\n        billing_client: billingClient\n      })\n    const trackCancelSucceeded = (billingClient: BillingClient) =>\n      telemetry?.trackBillingEvent({\n        operation: 'operation',\n        stage: 'succeeded',\n        outcome: 'success',\n        operation_type: 'cancel',\n        billing_client: billingClient,\n        duration_ms: Date.now() - attemptStartedAt\n      })\n    const trackCancelFailed = (\n      failureCategory: BillingTelemetryFailure['failure_category'],\n      billingClient: BillingClient\n    ) =>\n      telemetry?.trackBillingEvent({\n        operation: 'operation',\n        stage: 'failed',\n        outcome: 'failure',\n        operation_type: 'cancel',\n        billing_client: billingClient,\n        failure_category: failureCategory,\n        duration_ms: Date.now() - attemptStartedAt\n      })\n\n    // A rail that already learned its routes are missing goes straight to the\n    // legacy call, so it never starts an SDK attempt.\n    if (rail?.subscriptionRouteAvailable) {\n      trackCancelStarted('sdk')\n      const settled = await onSubscriptionRail(() =>\n        rail.cancelSubscription()\n      ).catch((err: unknown) => {\n        if (!(err instanceof SettledOperationError)) {\n          trackCancelFailed(categorizeBillingApiError(err), 'sdk')\n        }\n        throw err\n      })\n      if (settled !== DECLINED) {\n        if (!settled.operationObserved) trackCancelSucceeded('sdk')\n        return\n      }\n      // The backend refused the SDK request; the legacy call is its own attempt.\n      trackCancelFailed('api_rejected', 'sdk')\n    }\n\n    assertCancellationScopeCurrent(isScopeCurrent)\n    trackCancelStarted('legacy')\n\n    isLoading.value = true\n    error.value = null\n    // Once set, the poller (billingOperationStore) owns failure telemetry; until then, this must report it.\n    let billingOpId: string | undefined\n    try {\n      const response = await workspaceApi.cancelSubscription()\n      billingOpId = response.billing_op_id\n      const operation = await billingOperationStore.startOperation(\n        billingOpId,\n        'cancel',\n        { attemptStartedAt }\n      )\n\n      if (operation.status !== 'succeeded') {\n        throw new Error(\n          operation.errorMessage ?? 'Failed to cancel subscription'\n        )\n      }\n    } catch (err) {\n      if (isAlreadyInRequestedState(err, 'ALREADY_CANCELED')) {\n        await resyncQuietly(fetchStatus)\n        // fetchStatus records its own read failure; the cancellation still\n        // holds, so the operation is not in error.\n        error.value = null\n        trackCancelSucceeded('legacy')\n        return\n      }\n      if (billingOpId === undefined) {\n        trackCancelFailed(categorizeBillingApiError(err), 'legacy')\n      }\n      error.value =\n        err instanceof Error ? err.message : 'Failed to cancel subscription'\n      throw err\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  async function resubscribe(_options?: {\n    source?: 'pricing_dialog' | 'settings_billing_panel'\n  }): Promise<void> {\n    // Workspace's resubscribe() call is itself the terminal reactivation, so\n    // the click-time source isn't needed here the way the legacy adapter\n    // needs it for its pending-checkout-recovery terminal event.\n    const rail = useSubscriptionRail()\n    if (\n      rail &&\n      (await onSubscriptionRail(() => rail.resubscribe())) !== DECLINED\n    ) {\n      return\n    }\n\n    isLoading.value = true\n    error.value = null\n    try {\n      const response = await workspaceApi.resubscribe()\n      await Promise.allSettled([fetchStatus(), fetchBalance()])\n      // A pending resubscribe (e.g. SCA/3DS re-authentication) isn't done\n      // yet: wait for the tracked billing op to actually resolve instead of\n      // reporting success the instant the request was accepted. fetchStatus\n      // above may have already started tracking this op via\n      // pending_billing_op_id; startOperation dedupes by opId either way.\n      if (response.status === 'pending') {\n        const operation = await billingOperationStore.startOperation(\n          response.billing_op_id,\n          'subscription'\n        )\n        if (operation.status !== 'succeeded') {\n          throw new Error(operation.errorMessage ?? 'Failed to resubscribe')\n        }\n        await Promise.allSettled([fetchStatus(), fetchBalance()])\n      }\n    } catch (err) {\n      if (isAlreadyInRequestedState(err, 'NOT_SCHEDULED_FOR_CANCELLATION')) {\n        // Mirrors the success path, which refreshes balance too. allSettled,\n        // not all: a rejection from one read must not release this branch while\n        // the other is still in flight, or that one writes its failure into\n        // error after the clear below.\n        await resyncQuietly(() =>\n          Promise.allSettled([fetchStatus(), fetchBalance()])\n        )\n        error.value = null\n        return\n      }\n      error.value = err instanceof Error ? err.message : 'Failed to resubscribe'\n      throw err\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  async function topup(\n    amountCents: number\n  ): Promise<CreateTopupResponse | undefined> {\n    isLoading.value = true\n    error.value = null\n    try {\n      return await workspaceApi.createTopup(amountCents)\n    } catch (err) {\n      error.value =\n        err instanceof Error ? err.message : 'Failed to top up credits'\n      throw err\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  async function fetchPlans(): Promise<void> {\n    isLoading.value = true\n    error.value = null\n    try {\n      await billingPlans.fetchPlans()\n      if (billingPlans.error.value) {\n        error.value = billingPlans.error.value\n      }\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  const subscriptionDialog = useSubscriptionDialog()\n\n  async function requireActiveSubscription(): Promise<void> {\n    await fetchStatus()\n    if (!canAccessSubscriptionFeatures.value) {\n      subscriptionDialog.show({ reason: 'subscription_required' })\n    }\n  }\n\n  function showSubscriptionDialog(options?: SubscriptionDialogOptions): void {\n    subscriptionDialog.show(options)\n  }\n\n  return {\n    // State\n    isInitialized,\n    subscription,\n    balance,\n    plans,\n    currentPlanSlug,\n    teamCreditStops,\n    currentTeamCreditStop,\n    maxSeats,\n    occupiedSeats,\n    isLoading,\n    error,\n    canAccessSubscriptionFeatures,\n    isFreeTier,\n    billingStatus,\n    subscriptionStatus,\n    tier,\n    renewalDate,\n    renewalInvoice,\n    readAndAdoptPendingOperation,\n\n    // Actions\n    initialize,\n    fetchStatus,\n    fetchBalance,\n    subscribe,\n    previewSubscribe,\n    manageSubscription,\n    cancelSubscription,\n    resubscribe,\n    topup,\n    fetchPlans,\n    requireActiveSubscription,\n    showSubscriptionDialog\n  }\n}\n","import { useErrorHandling } from '@/composables/useErrorHandling'\nimport { t } from '@/i18n'\nimport { isAuthenticatedConfigLoaded } from '@/platform/remoteConfig/remoteConfig'\nimport { computed, ref, shallowRef, toValue, watch } from 'vue'\nimport { createSharedComposable, until } from '@vueuse/core'\n\nimport {\n  KEY_TO_TIER,\n  getTierFeatures\n} from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { TierKey } from '@/platform/cloud/subscription/constants/tierPricing'\nimport { useFreeTierQuota } from '@/platform/cloud/subscription/composables/useFreeTierQuota'\nimport { isCloud } from '@/platform/distribution/types'\nimport type {\n  PreviewSubscribeOptions,\n  SubscribeOptions\n} from '@/platform/workspace/api/workspaceApi'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\n\nimport type {\n  BalanceInfo,\n  BillingActions,\n  BillingContext,\n  CancelRail,\n  BillingState,\n  SubscriptionDialogOptions,\n  SubscriptionInfo\n} from './types'\nimport { useBillingRouting } from './useBillingRouting'\nimport { useLegacyBilling } from './useLegacyBilling'\nimport type { WorkspaceBilling } from '@/platform/workspace/composables/useWorkspaceBilling'\nimport { useWorkspaceBilling } from '@/platform/workspace/composables/useWorkspaceBilling'\n\n// Legacy per-member team plans use a hyphenated `team-{tier}-{cycle}` slug; the\n// new credit-slider plan uses an underscore `team_per_credit_{cycle}` slug and\n// carries a team_credit_stop. The hyphen prefix alone separates the two, so a\n// new sub is never misrouted even before its credit stop is populated.\nconst LEGACY_TEAM_PLAN_SLUG_PREFIX = 'team-'\nconst PER_CREDIT_TEAM_PLAN_SLUG_PREFIX = 'team_per_credit_'\n\nconst ROUTING_WAIT_TIMEOUT_MS = 10_000\n\nclass BillingRoutingUnavailableError extends Error {}\n\nclass BillingWorkspaceChangedError extends Error {}\n\nfunction isTeamPlanSlug(planSlug: string | null | undefined): boolean {\n  const normalizedSlug = planSlug?.toLowerCase()\n  return (\n    normalizedSlug?.startsWith(LEGACY_TEAM_PLAN_SLUG_PREFIX) === true ||\n    normalizedSlug?.startsWith(PER_CREDIT_TEAM_PLAN_SLUG_PREFIX) === true\n  )\n}\n\n/**\n * Unified billing context that selects billing state and account actions by\n * billing rail. When unified pricing is enabled, its catalog and checkout\n * actions use workspace billing independently so legacy Stripe workspaces can\n * migrate plans while balance, top-up, and subscription management stay legacy.\n *\n * - Workspace not loaded yet (`unknown`): no billing call is made until it is\n * - OSS/Desktop: workspace billing once the Cloud-backed workspace loads\n * - Unified pricing: plan catalog and checkout via /api/billing/*\n * - Other state and actions: legacy or workspace billing selected by rail\n *\n * The context automatically initializes when the workspace changes and provides\n * a unified interface for subscription status, balance, and billing actions.\n *\n * @example\n * ```typescript\n * import { formatCreditsFromCents } from '@/base/credits/comfyCredits'\n *\n * const {\n *   type,\n *   subscription,\n *   balance,\n *   isInitialized,\n *   initialize,\n *   subscribe\n * } = useBillingContext()\n *\n * // Wait for initialization\n * await initialize()\n *\n * // Check subscription status\n * if (subscription.value?.isActive) {\n *   console.log(`Tier: ${subscription.value.tier}`)\n * }\n *\n * // Check balance (the *Micros fields are cents - see BalanceInfo)\n * if (balance.value) {\n *   const credits = formatCreditsFromCents({ cents: balance.value.amountMicros })\n *   console.log(`Balance: ${credits} credits`)\n * }\n * ```\n */\nfunction useBillingContextInternal(): BillingContext {\n  const store = useTeamWorkspaceStore()\n  const { type, shouldUseUnifiedPricing } = useBillingRouting()\n\n  const legacyBillingRef = shallowRef<(BillingState & BillingActions) | null>(\n    null\n  )\n  const workspaceBillingRef = shallowRef<WorkspaceBilling | null>(null)\n\n  const getLegacyBilling = () => {\n    if (!legacyBillingRef.value) {\n      legacyBillingRef.value = useLegacyBilling()\n    }\n    return legacyBillingRef.value\n  }\n\n  const getWorkspaceBilling = () => {\n    if (!workspaceBillingRef.value) {\n      workspaceBillingRef.value = useWorkspaceBilling()\n    }\n    return workspaceBillingRef.value\n  }\n\n  const isInitialized = ref(false)\n  const isLoading = ref(false)\n  const error = ref<string | null>(null)\n\n  const activeContext = computed(() =>\n    type.value === 'workspace' ? getWorkspaceBilling() : getLegacyBilling()\n  )\n  const checkoutContext = computed(() =>\n    shouldUseUnifiedPricing.value ? getWorkspaceBilling() : activeContext.value\n  )\n\n  // Proxy state from active context\n  const subscription = computed<SubscriptionInfo | null>(() =>\n    toValue(activeContext.value.subscription)\n  )\n\n  const balance = computed<BalanceInfo | null>(() =>\n    toValue(activeContext.value.balance)\n  )\n\n  const plans = computed(() => toValue(checkoutContext.value.plans))\n\n  const currentPlanSlug = computed(() =>\n    toValue(checkoutContext.value.currentPlanSlug)\n  )\n\n  const teamCreditStops = computed(() =>\n    toValue(checkoutContext.value.teamCreditStops)\n  )\n\n  const currentTeamCreditStop = computed(() =>\n    toValue(activeContext.value.currentTeamCreditStop)\n  )\n\n  const maxSeats = computed(() => toValue(activeContext.value.maxSeats))\n  const occupiedSeats = computed(() =>\n    toValue(activeContext.value.occupiedSeats)\n  )\n\n  const canAccessSubscriptionFeatures = computed(() =>\n    toValue(activeContext.value.canAccessSubscriptionFeatures)\n  )\n\n  const isFreeTier = computed(() => subscription.value?.tier === 'FREE')\n\n  const freeTierQuota = useFreeTierQuota()\n\n  const canRunWorkflows = computed(\n    () =>\n      canAccessSubscriptionFeatures.value &&\n      (!isFreeTier.value ||\n        !isCloud ||\n        !isAuthenticatedConfigLoaded.value ||\n        freeTierQuota.freeTierExecutionPermitted.value)\n  )\n\n  const showsSubscribeToRunPrompt = computed(\n    () => isInitialized.value && !canRunWorkflows.value\n  )\n\n  const isLegacyTeamPlan = computed(\n    () =>\n      type.value === 'workspace' &&\n      canAccessSubscriptionFeatures.value &&\n      !isFreeTier.value &&\n      currentTeamCreditStop.value === null &&\n      (currentPlanSlug.value\n        ?.toLowerCase()\n        .startsWith(LEGACY_TEAM_PLAN_SLUG_PREFIX) ??\n        false)\n  )\n\n  // Plan identity, independent of subscription health: the per-credit Team plan\n  // carries a credit stop, the retired seat-based ones a `team-` slug. Kept off\n  // canAccessSubscriptionFeatures on purpose — paused and payment_failed\n  // both force is_active=false, which is exactly when callers still need\n  // to know this is a team plan.\n  const isTeamPlan = computed(\n    () =>\n      type.value === 'workspace' &&\n      (currentTeamCreditStop.value !== null ||\n        isTeamPlanSlug(currentPlanSlug.value))\n  )\n\n  const billingStatus = computed(() =>\n    toValue(activeContext.value.billingStatus)\n  )\n  const subscriptionStatus = computed(() =>\n    toValue(activeContext.value.subscriptionStatus)\n  )\n  const tier = computed(() => toValue(activeContext.value.tier))\n  const renewalDate = computed(() => toValue(activeContext.value.renewalDate))\n  const renewalInvoice = computed(() =>\n    toValue(activeContext.value.renewalInvoice)\n  )\n\n  function getMaxSeats(tierKey: TierKey): number {\n    if (type.value !== 'workspace') return 1\n\n    const apiTier = KEY_TO_TIER[tierKey]\n    const plan = plans.value.find(\n      (p) => p.tier === apiTier && p.duration === 'MONTHLY'\n    )\n    return plan?.max_seats ?? getTierFeatures(tierKey).maxMembers\n  }\n\n  // Sync subscription info to workspace store for display in workspace switcher.\n  // Subscribed means active AND not cancelled, so the delete button enables\n  // after cancellation, even before the period ends. A null subscription means\n  // \"not loaded yet\" (adapters are discarded on every workspace/type switch);\n  // skip it so the transient reinit gap can't clobber the list-derived baseline\n  // (personal workspaces and subscribed teams already read subscribed there).\n  watch(\n    subscription,\n    (sub) => {\n      if (!sub) return\n\n      store.updateActiveWorkspace({\n        isSubscribed: sub.isActive && !sub.isCancelled,\n        subscriptionPlan: sub.planSlug\n      })\n    },\n    { immediate: true }\n  )\n\n  // Discarding the adapter instances forces a fresh fetch and lets an in-flight\n  // init detect that it was superseded (its captured adapter is no longer the\n  // active one), so a stale response can't resolve into a ready state for the\n  // wrong workspace.\n  function resetBillingState() {\n    legacyBillingRef.value = null\n    workspaceBillingRef.value = null\n    isInitialized.value = false\n    isLoading.value = false\n    error.value = null\n  }\n\n  // Reset and reinitialize when the active workspace or billing backend changes.\n  watch(\n    [() => store.activeWorkspace?.id, () => type.value],\n    async ([newWorkspaceId]) => {\n      resetBillingState()\n      if (!newWorkspaceId) return\n\n      try {\n        await initialize()\n      } catch (err) {\n        console.error('Failed to initialize billing context:', err)\n      }\n    },\n    { immediate: true }\n  )\n\n  // Rejects on timeout. Resolves false when the user switched workspace during\n  // the wait, so the caller stops silently.\n  async function waitForRouting(): Promise<boolean> {\n    if (type.value !== 'unknown') return true\n    const workspaceId = store.activeWorkspace?.id\n    try {\n      await until(type).not.toBe('unknown', {\n        timeout: ROUTING_WAIT_TIMEOUT_MS,\n        throwOnTimeout: true\n      })\n    } catch {\n      throw new BillingRoutingUnavailableError(\n        t('auth.webSession.token.unavailable')\n      )\n    }\n    const currentId = store.activeWorkspace?.id\n    return !workspaceId || currentId === workspaceId\n  }\n\n  // For actions whose caller shows the outcome: a workspace switch during the\n  // wait is a failure the caller reports, not a silent drop.\n  async function waitForRoutingInSameWorkspace(): Promise<void> {\n    if (await waitForRouting()) return\n    throw new BillingWorkspaceChangedError(\n      t('subscription.cancelDialog.workspaceChanged')\n    )\n  }\n\n  // For actions whose caller shows no outcome: reports a timeout once, as\n  // legacy actions did on failure, and resolves false so the caller stops.\n  async function whenRoutingKnown(): Promise<boolean> {\n    try {\n      return await waitForRouting()\n    } catch (err) {\n      useErrorHandling().toastErrorHandler(err)\n      return false\n    }\n  }\n\n  async function initialize(): Promise<void> {\n    if (isInitialized.value) return\n    if (!(await whenRoutingKnown())) return\n\n    const adapter = activeContext.value\n    isLoading.value = true\n    error.value = null\n    try {\n      await adapter.initialize()\n      if (activeContext.value !== adapter) return\n      isInitialized.value = true\n    } catch (err) {\n      if (activeContext.value !== adapter) return\n      error.value =\n        err instanceof Error ? err.message : 'Failed to initialize billing'\n      throw err\n    } finally {\n      if (activeContext.value === adapter) isLoading.value = false\n    }\n  }\n\n  // Passive reads do nothing while unknown; the watcher above re-initializes\n  // once the workspace type loads.\n  async function fetchStatus(): Promise<void> {\n    if (type.value === 'unknown') return\n    return activeContext.value.fetchStatus()\n  }\n\n  async function fetchBalance(): Promise<void> {\n    if (type.value === 'unknown') return\n    return activeContext.value.fetchBalance()\n  }\n\n  // Reconcile and the checkout-operation read run once after a Stripe redirect\n  // and are never retried, so they wait instead of skipping.\n  async function reconcileSubscriptionSuccess(): Promise<void> {\n    if (!(await whenRoutingKnown())) return\n    const checkout = checkoutContext.value\n    await checkout.fetchStatus()\n\n    const account = activeContext.value\n    if (account !== checkout) await account.fetchStatus()\n    await account.fetchBalance()\n  }\n\n  /**\n   * Reads the