Context.value.topup(amountCents)\n  }\n\n  async function fetchPlans() {\n    if (type.value === 'unknown') return\n    return checkoutContext.value.fetchPlans()\n  }\n\n  async function requireActiveSubscription() {\n    if (!(await whenRoutingKnown())) return\n    return activeContext.value.requireActiveSubscription()\n  }\n\n  function showSubscriptionDialog(options?: SubscriptionDialogOptions) {\n    if (type.value !== 'unknown') {\n      return activeContext.value.showSubscriptionDialog(options)\n    }\n    void whenRoutingKnown().then((known) => {\n      if (known) activeContext.value.showSubscriptionDialog(options)\n    })\n  }\n\n  return {\n    type,\n    isInitialized,\n    subscription,\n    balance,\n    plans,\n    currentPlanSlug,\n    teamCreditStops,\n    currentTeamCreditStop,\n    maxSeats,\n    occupiedSeats,\n    isLoading,\n    error,\n    showsSubscribeToRunPrompt,\n    canAccessSubscriptionFeatures,\n    canRunWorkflows,\n    isFreeTier,\n    isLegacyTeamPlan,\n    isTeamPlan,\n    billingStatus,\n    subscriptionStatus,\n    tier,\n    renewalDate,\n    renewalInvoice,\n    getMaxSeats,\n\n    initialize,\n    fetchStatus,\n    fetchBalance,\n    reconcileSubscriptionSuccess,\n    readCheckoutOperation,\n    subscribe,\n    previewSubscribe,\n    manageSubscription,\n    cancelSubscription,\n    resubscribe,\n    topup,\n    fetchPlans,\n    requireActiveSubscription,\n    showSubscriptionDialog\n  }\n}\n\nexport const useBillingContext = createSharedComposable(\n  useBillingContextInternal\n)\n"],"file":"useBillingContext-Cvibmzb6.js"}"""

